# A frozen NOP must reset its inherited DLL directory in a *child*, never in
# the running player. The child remains in the conversion's Windows Job Object.
if __name__ == "__main__" and len(sys.argv) == 3 and sys.argv[1] == "--nop-conversion-tool":
    try:
        manifest = Path(sys.argv[2])
        if manifest.stat().st_size > 128 * 1024:
            raise ValueError("Conversion command exceeds the size limit")
        command = json.loads(manifest.read_text(encoding="utf-8"))
        if (not isinstance(command, list) or not command or len(command) > 512
                or any(not isinstance(arg, str) or "\0" in arg for arg in command)
                or not Path(command[0]).is_absolute() or not Path(command[0]).is_file()):
            raise ValueError("Invalid conversion command")
        if os.name == "nt":
            reset = ctypes.WinDLL("kernel32", use_last_error=True).SetDllDirectoryW
            reset.argtypes, reset.restype = [ctypes.c_wchar_p], ctypes.c_int
            if not reset(None):
                raise ctypes.WinError(ctypes.get_last_error())
        child = subprocess.Popen(command, stdin=subprocess.DEVNULL)
        fd = os.open(str(manifest.with_suffix(".pid")), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w", encoding="ascii") as pid_file:
            pid_file.write(str(child.pid))
        sys.exit(child.wait())
    except Exception as exc:
        message = ("NOP conversion launch failed: " + str(exc) + "\n").encode("utf-8", "replace")
        try:
            os.write(2, message)
        except OSError:
            if os.name == "nt":
                api = ctypes.WinDLL("kernel32")
                api.GetStdHandle.argtypes, api.GetStdHandle.restype = [ctypes.c_int32], ctypes.c_void_p
                api.WriteFile.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint32, ctypes.c_void_p, ctypes.c_void_p]
                written = ctypes.c_uint32()
                buffer = ctypes.create_string_buffer(message)
                api.WriteFile(api.GetStdHandle(-12), buffer, len(message), ctypes.byref(written), None)
        sys.exit(126)


