def redact_diagnostic(value):
    """Keep authentication material and URL query strings out of diagnostics."""
    text = str(value)
    text = re.sub(r"(?i)(Bearer\s+)[^\s,;\"']+", r"\1[redacted]", text)
    text = re.sub(r"(?i)((?:set-cookie|cookie|authorization)[\"']?\s*[:=]\s*)[^\r\n]+", r"\1[redacted]", text)
    text = re.sub(r"(?i)((?:access[_ -]?token|refresh[_ -]?token|client[_ -]?secret|code[_ -]?verifier|request_?token|\btoken)[\"']?\s*[:=]\s*[\"']?)[^\s,;\"'{}]+", r"\1[redacted]", text)
    def clean_url(match):
        raw = match.group(0)
        try:
            parsed = urllib.parse.urlsplit(raw)
            host = parsed.hostname or ""
            if parsed.port:
                host += ":" + str(parsed.port)
            return urllib.parse.urlunsplit((parsed.scheme, host, parsed.path, "…" if parsed.query else "", ""))
        except ValueError:
            return "[URL]"
    return re.sub(r"https?://[^\s<>\"']+", clean_url, text)[:5000]


def _private_write(path: Path, data: bytes):
    """Atomic replacement; temporary and resulting files are owner-readable only."""
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    fd, name = tempfile.mkstemp(prefix=".nop-", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(name, path)
        if os.name != "nt":
            os.chmod(path, 0o600)
    finally:
        Path(name).unlink(missing_ok=True)


def _dpapi(data: bytes, decrypt=False) -> bytes:
    """Windows user-bound protection. No plaintext persistent fallback."""
    if os.name != "nt":
        raise OSError("Windows DPAPI is unavailable")
    from ctypes import wintypes
    class Blob(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]
    buffer = (ctypes.c_ubyte * len(data)).from_buffer_copy(data)
    incoming = Blob(len(data), buffer)
    outgoing = Blob()
    crypt = ctypes.WinDLL("crypt32", use_last_error=True)
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel.LocalFree.argtypes = [ctypes.c_void_p]
    kernel.LocalFree.restype = ctypes.c_void_p
    if decrypt:
        function = crypt.CryptUnprotectData
        function.argtypes = [ctypes.POINTER(Blob), ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
                             ctypes.c_void_p, wintypes.DWORD, ctypes.POINTER(Blob)]
        args = (ctypes.byref(incoming), None, None, None, None, 1, ctypes.byref(outgoing))
    else:
        function = crypt.CryptProtectData
        function.argtypes = [ctypes.POINTER(Blob), wintypes.LPCWSTR, ctypes.c_void_p, ctypes.c_void_p,
                             ctypes.c_void_p, wintypes.DWORD, ctypes.POINTER(Blob)]
        args = (ctypes.byref(incoming), "NOP Spotify", None, None, None, 1, ctypes.byref(outgoing))
    function.restype = wintypes.BOOL
    try:
        if not function(*args):
            raise ctypes.WinError(ctypes.get_last_error())
        return ctypes.string_at(outgoing.pbData, outgoing.cbData)
    finally:
        ctypes.memset(buffer, 0, len(buffer))
        if outgoing.pbData:
            ctypes.memset(outgoing.pbData, 0, outgoing.cbData)
            kernel.LocalFree(ctypes.cast(outgoing.pbData, ctypes.c_void_p))


def _pack_private(data: bytes) -> bytes:
    return b"DPAPI\0" + _dpapi(data) if os.name == "nt" else b"PRIVATE\0" + data


def _unpack_private(data: bytes) -> bytes:
    if data.startswith(b"DPAPI\0"):
        return _dpapi(data[6:], decrypt=True)
    if data.startswith(b"PRIVATE\0") and os.name != "nt":
        return data[8:]
    raise ValueError("Unsupported private payload")


def stop_owned_process(proc):
    """Stop only a process group created by NOP; call from a worker, not the GUI."""
    if proc is None or proc.poll() is not None:
        return
    if os.name == "nt":
        subprocess.run(["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                       stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                       creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0), timeout=8, check=False)
    else:
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError:
            return
    try:
        proc.wait(timeout=1)
    except subprocess.TimeoutExpired:
        if os.name != "nt":
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        else:
            proc.kill()
        proc.wait(timeout=3)


def _retire_audio(owner, attribute, thread):
    if getattr(owner, attribute, None) is thread:
        setattr(owner, attribute, None)
    thread.deleteLater()


def _submit_lut(owner, work):
    if getattr(owner, "_closing_lut", False):
        return
    if not hasattr(owner, "_lut_executor"):
        owner._lut_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="NOP LUT")
        owner._lut_future = None
        owner._lut_jobs = set()
        owner._lut_lock = threading.RLock()
    previous = owner._lut_future
    if previous is not None:
        previous.cancel()
    future = owner._lut_executor.submit(work)
    owner._lut_future = future
    with owner._lut_lock:
        owner._lut_jobs.add(future)
    def completed(job):
        with owner._lut_lock:
            owner._lut_jobs.discard(job)
    future.add_done_callback(completed)


def _finish_lut(owner):
    owner._closing_lut = True
    executor = getattr(owner, "_lut_executor", None)
    if executor is not None:
        executor.shutdown(wait=True, cancel_futures=True)
        owner._lut_executor = None
        owner._lut_future = None


def start_window_move(widget):
    window = widget.window()
    window._startup_center_active = False  # пользователь сам двигает окно - автоцентрирование не нужно
    handle = window.windowHandle() if window.isWindow() else None
    return bool(handle is not None and handle.isTopLevel() and handle.startSystemMove())


class DownloadCancelled(Exception):
    pass


def _download_process_main(directory):
    """Private IPC works with console and PyInstaller windowed executables alike."""
    directory = Path(directory)
    parameters = json.loads(_unpack_private((directory / "request.dat").read_bytes()))
    set_language(parameters.pop("__language", "ru"))  # сообщения рабочего процесса — на языке интерфейса
    parameters["folder"] = Path(parameters["folder"])
    worker = Downloader(**parameters)
    worker._child_mode = True
    worker._job_temp_dir = directory / "media"
    worker._job_temp_dir.mkdir()
    write_lock = threading.Lock()
    stopped = threading.Event()
    # Tokens in this stream are DPAPI protected on Windows; IPC files are private and ephemeral.
    events_path = directory / "events.jsonl"
    with events_path.open("a", encoding="utf-8") as events:
        def emit(kind, *args):
            if kind == "tokens":
                args = [base64.b64encode(_pack_private(json.dumps(args[0]).encode())).decode("ascii")]
            line = json.dumps({"kind": kind, "args": args}, ensure_ascii=False) + "\n"
            with write_lock:
                events.write(line)
                events.flush()
        for signal_name, kind in (("status", "status"), ("stats", "stats"), ("queue_items", "queue"),
                                  ("item_update", "item"), ("item_detail", "detail"),
                                  ("attempt_update", "attempt"),
                                  ("spotify_tokens_updated", "tokens")):
            getattr(worker, signal_name).connect(lambda *a, k=kind: emit(k, *a), Qt.ConnectionType.DirectConnection)
        def controls():
            with (directory / "control.jsonl").open(encoding="utf-8") as handle:
                while not stopped.is_set():
                    line = handle.readline(65536)
                    if not line:
                        stopped.wait(.05)
                        continue
                    try:
                        command = json.loads(line)
                        action = command.get("action")
                        if action == "stop":
                            worker.request_stop()
                        elif action == "pause":
                            worker.set_paused(bool(command.get("paused")))
                        elif action == "cancel":
                            worker.cancel_item(str(command.get("id")))
                        elif action == "move":
                            worker.reorder_pending_item(str(command.get("id")), int(command.get("delta", 0)))
                    except (ValueError, TypeError):
                        continue
        thread = threading.Thread(target=controls, name="NOP download controls", daemon=True)
        thread.start()
        try:
            worker._run_job()
        finally:
            stopped.set()
            thread.join(1)
            emit("summary", {"finished_videos": worker.finished_videos, "total_videos": worker.total_videos,
                             "total_bytes": worker.total_bytes, "error_text": redact_diagnostic(worker.error_text),
                             "failed_entries": worker._failed_entries, "cancelled": worker._stop_event.is_set()})


def _guard_optional_zstd():
    """urllib3 (inside yt-dlp) uses backports.zstd when it is importable. A broken or partial copy of that module
    (for example one without ZstdError) used to abort start-up with "module 'backports.zstd' has no attribute
    'ZstdError'". Such a module is treated as not installed, so urllib3 simply runs without zstd."""
    try:
        import importlib
        module = importlib.import_module("backports.zstd")
    except ImportError:
        return
    except Exception:  # noqa: BLE001 - a broken native module: hide it as well
        module = None
    if module is None or not all(hasattr(module, name) for name in ("ZstdError", "ZstdDecompressor")):
        sys.modules["backports.zstd"] = None
        package = sys.modules.get("backports")
        if package is not None and hasattr(package, "zstd"):
            try:
                delattr(package, "zstd")
            except AttributeError:
                pass


_guard_optional_zstd()
