def startup_media_file(arguments):
    """The shell passes an individual quoted audio OR video path as %1."""
    for argument in arguments:
        path = Path(str(argument).strip('"'))
        if path.suffix.lower() in MEDIA_EXTS and path.is_file():
            return path
    return None


