def audio_selectors(aq: str) -> list[str]:
    if aq == "best":
        return ["bestaudio"]
    if aq == "min":
        return ["worstaudio"]
    return [f"bestaudio[abr<=?{aq}]", "worstaudio"]


def build_format(mode: str, vq: str, aq: str, vcodec: str = "any") -> str:
    """Audio preference is independent of the image profile and video codec."""
    audio = audio_selectors(aq)
    if mode == "audio": return "/".join(audio + ["best"])
    return "bestvideo/best" if mode == "video" else "/".join("bestvideo+"+a for a in audio)+"/best"


def make_tag(mode: str, vq: str, aq: str) -> str:
    """Метка профиля в имени файла. Пустая - обычная загрузка (совместимо со старыми файлами)."""
    if mode == "audio":
        return f"a-{aq}"
    if mode == "video":
        return f"v-{vq}"
    return "" if (vq == "min" and aq == "best") else f"av-{vq}-{aq}"

