EQ_PRESET_FREQUENCIES = (31, 63, 125, 250, 500, 1000, 2000, 4000, 8000, 16000)


def resample_eq_values(values, target_frequencies, source_frequencies=None):
    """Переносит профиль EQ на произвольное число полос по логарифму частоты.

    Пресеты приложения исторически десятиполосные, но пользователь может добавлять
    полосы. Возвращаемый список всегда имеет длину target_frequencies.
    """
    target = []
    for value in (target_frequencies or []):
        try:
            target.append(max(20, min(20000, int(value))))
        except (TypeError, ValueError):
            continue
    if not target:
        return []
    clean_values = []
    for value in (values or []):
        try:
            clean_values.append(max(-12.0, min(12.0, float(value))))
        except (TypeError, ValueError):
            clean_values.append(0.0)
    if not clean_values:
        return [0.0] * len(target)

    source = []
    if source_frequencies is not None:
        for value in source_frequencies:
            try:
                source.append(max(20, min(20000, int(value))))
            except (TypeError, ValueError):
                pass
    if len(source) != len(clean_values):
        if len(clean_values) == len(EQ_PRESET_FREQUENCIES):
            source = list(EQ_PRESET_FREQUENCIES)
        elif len(clean_values) == 1:
            source = [target[0]]
        else:
            # Для старых пользовательских пресетов без сохранённых частот считаем,
            # что полосы равномерно распределены по логарифмической шкале.
            lo, hi = math.log(31), math.log(16000)
            source = [int(round(math.exp(lo + (hi - lo) * i / (len(clean_values) - 1))))
                      for i in range(len(clean_values))]
    pairs = sorted((freq, gain) for freq, gain in zip(source, clean_values))
    if len(pairs) == 1:
        return [round(pairs[0][1], 2)] * len(target)

    result = []
    for freq in target:
        if freq <= pairs[0][0]:
            gain = pairs[0][1]
        elif freq >= pairs[-1][0]:
            gain = pairs[-1][1]
        else:
            gain = pairs[0][1]
            for (f0, g0), (f1, g1) in zip(pairs, pairs[1:]):
                if f0 <= freq <= f1:
                    # Частоты воспринимаются логарифмически, поэтому интерполяция
                    # по log(f) лучше подходит для аудиополос, чем по линейной шкале.
                    ratio = (math.log(freq) - math.log(f0)) / (math.log(f1) - math.log(f0))
                    gain = g0 + (g1 - g0) * ratio
                    break
        result.append(round(max(-12.0, min(12.0, gain)), 2))
    return result

