# ---------- настройки в файле ----------
def load_config() -> dict:
    global CONFIG_WARNING, _CONFIG_READ_FAILED
    _CONFIG_READ_FAILED = False
    cfg = copy.deepcopy(DEFAULT_CONFIG)
    try:
        if CONFIG_PATH.stat().st_size > 4 * 1024 * 1024:
            raise ValueError("Settings file is too large")
        loaded = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
        if isinstance(loaded, dict):
            cfg.update(loaded)
    except FileNotFoundError:
        pass
    except (OSError, ValueError, TypeError) as exc:
        _CONFIG_READ_FAILED = True
        CONFIG_WARNING = "Settings could not be read; the original file will not be overwritten: " + redact_diagnostic(exc)
    if _CREDENTIALS_PATH.is_file():
        try:
            if _CREDENTIALS_PATH.stat().st_size > 128 * 1024:
                raise ValueError("Credential file is too large")
            tokens = json.loads(_unpack_private(_CREDENTIALS_PATH.read_bytes()))
            if tokens.get("client_id") == cfg.get("spotify_client_id"):
                for key in _TOKEN_KEYS:
                    cfg[key] = str(tokens.get(key, ""))
        except (OSError, ValueError, TypeError) as exc:
            CONFIG_WARNING = "Spotify credentials could not be opened: " + redact_diagnostic(exc)
    cfg.pop("show_modes", None)
    _remember_shared_baseline(cfg)
    return cfg


# Settings that several NOP windows (separate processes) may change. A window that did
# not change such a value itself must not overwrite another window's newer choice.
SHARED_CONFIG_KEYS = ("open_mode",)
_SHARED_BASELINE: dict = {}


def _remember_shared_baseline(cfg: dict):
    for key in SHARED_CONFIG_KEYS:
        _SHARED_BASELINE[key] = cfg.get(key)


def save_config(cfg: dict):
    global CONFIG_WARNING
    if _CONFIG_READ_FAILED:
        return False
    with _CONFIG_LOCK:
        try:
            on_disk = json.loads(CONFIG_PATH.read_text(encoding="utf-8")) if CONFIG_PATH.stat().st_size < 4 * 1024 * 1024 else {}
        except (OSError, ValueError, TypeError):
            on_disk = {}
        if isinstance(on_disk, dict):
            for key in SHARED_CONFIG_KEYS:
                if key in _SHARED_BASELINE and cfg.get(key) == _SHARED_BASELINE.get(key) and key in on_disk:
                    cfg[key] = on_disk[key]  # untouched here, changed elsewhere: adopt the newer value
        _remember_shared_baseline(cfg)
        plain = {key: value for key, value in cfg.items() if key not in _TOKEN_KEYS}
        protected = True
        try:
            if any(cfg.get(key) for key in _TOKEN_KEYS):
                if os.name == "nt":
                    try:
                        payload = {key: str(cfg.get(key, "")) for key in _TOKEN_KEYS}
                        payload["client_id"] = str(cfg.get("spotify_client_id", ""))
                        _private_write(_CREDENTIALS_PATH, _pack_private(json.dumps(payload).encode("utf-8")))
                    except (OSError, ValueError) as exc:
                        protected = False
                        CONFIG_WARNING = "Spotify tokens remain session-only: " + redact_diagnostic(exc)
                        _CREDENTIALS_PATH.unlink(missing_ok=True)
                else:
                    CONFIG_WARNING = "Spotify tokens are session-only on this OS; persistent protection requires Windows DPAPI."
            else:
                _CREDENTIALS_PATH.unlink(missing_ok=True)
            _private_write(CONFIG_PATH, json.dumps(plain, ensure_ascii=False, indent=2).encode("utf-8"))
            return protected
        except (OSError, ValueError, TypeError) as exc:
            CONFIG_WARNING = "Settings could not be saved safely: " + redact_diagnostic(exc)
            return False


def normalize_channel(text: str) -> str:
    """Принимает ссылку на канал, @имя или просто имя; приводит к ссылке на вкладку 'Видео'."""
    s = text.strip()
    if not s:
        return DEFAULT_CHANNEL
    if s.startswith("@"):
        s = f"https://www.youtube.com/{s}"
    elif not s.startswith("http"):
        s = "https://www.youtube.com/@" + s.lstrip("/@")
    tabs = ("/videos", "/streams", "/shorts", "/playlists", "/featured")
    if "/@" in s and not s.rstrip("/").endswith(tabs):
        s = s.rstrip("/") + "/videos"
    return s


def normalize_video(text: str) -> str:
    """Ссылка на одно видео или 11-символьный id. Пустая строка - если не похоже."""
    s = text.strip()
    if re.fullmatch(r"[\w-]{11}", s):
        return f"https://www.youtube.com/watch?v={s}"
    return canonical_youtube_url(s, "single") if s.startswith(("http://", "https://")) else ""


def normalize_playlist(text: str) -> str:
    """Ссылка на плейлист или его id (PL…, OL…, UU… и т.п.). Пустая строка - если не похоже."""
    s = text.strip()
    if re.fullmatch(r"(?:PL|OL|FL|UU|LL|RD)[\w-]{10,}", s):
        return f"https://www.youtube.com/playlist?list={s}"
    return canonical_youtube_url(s, "playlist") if s.startswith(("http://", "https://")) else ""


def canonical_youtube_url(value: str, kind: str = "single") -> str:
    """Remove playback/tracking parameters without losing video or playlist IDs."""
    try:
        parsed = urllib.parse.urlsplit(value)
        host = (parsed.hostname or "").lower().rstrip(".")
        if (parsed.scheme not in ("http", "https") or parsed.username is not None
                or parsed.password is not None or parsed.port not in (None, 80, 443)):
            return value
        youtube = host == "youtube.com" or host.endswith(".youtube.com")
        nocookie = host == "youtube-nocookie.com" or host.endswith(".youtube-nocookie.com")
        short = host == "youtu.be" or host == "www.youtu.be"
        if not (youtube or nocookie or short):
            return value
        query = urllib.parse.parse_qs(parsed.query)
        playlist = query.get("list", [""])[0]
        if (kind == "playlist" or parsed.path.rstrip("/") == "/playlist") and re.fullmatch(r"[A-Za-z0-9_-]+", playlist):
            return "https://www.youtube.com/playlist?" + urllib.parse.urlencode({"list": playlist})
        parts = parsed.path.strip("/").split("/")
        video = query.get("v", [""])[0] if parsed.path.rstrip("/") == "/watch" else ""
        if short and len(parts) == 1:
            video = parts[0]
        elif len(parts) == 2 and parts[0] in {"shorts", "embed", "live", "v"}:
            video = parts[1]
        if re.fullmatch(r"[A-Za-z0-9_-]{11}", video):
            return "https://www.youtube.com/watch?" + urllib.parse.urlencode({"v": video})
    except ValueError:
        pass  # Validation remains the responsibility of download_url().
    return value


def spotify_url_kind(url: str) -> tuple[str, str]:
    """Возвращает тип и ID публичной ссылки Spotify: track, album или playlist."""
    try:
        parsed = urllib.parse.urlparse((url or "").strip())
    except ValueError:
        return "", ""
    host = (parsed.hostname or "").casefold()
    if host not in {"open.spotify.com", "spotify.com", "www.spotify.com", "spotify.link"}:
        return "", ""
    parts = [p for p in parsed.path.split("/") if p]
    for i, part in enumerate(parts[:-1]):
        if part.casefold() in {"track", "album", "playlist"}:
            spotify_id = parts[i + 1].split("?", 1)[0]
            if re.fullmatch(r"[A-Za-z0-9]{10,32}", spotify_id):
                return part.casefold(), spotify_id
    return "", ""


def scan_folder(folder: Path, recursive: bool) -> list[Path]:
    """Медиафайлы папки, новые сверху. Недокачанные куски yt-dlp (.f123.mp4, .part) пропускаются."""
    files: list[Path] = []
    try:
        it = folder.rglob("*") if recursive else folder.glob("*")
        for p in it:
            if any(part.startswith(".nop-convert-") for part in p.parts):
                continue  # In-progress private exports must not enter the media library.
            if is_complete_media(p):
                files.append(p)
                if len(files) >= MAX_SCAN_FILES:
                    break
    except OSError:
        pass

    def mtime(p: Path) -> float:
        try:
            return p.stat().st_mtime
        except OSError:
            return 0.0

    return sorted(files, key=mtime, reverse=True)


# ---------- иконки (рисуем сами, чтобы не зависеть от шрифтов) ----------
# Все иконки - в одном стиле, как «настройки загрузки» и «закрепить» в версии 7:
# плотные залитые формы, толстые скруглённые линии, без тонких контуров.
ACCENT = "#ff426d"        # акцентный цвет (включённые панели, главная кнопка)
ICON_COLOR = "#e9edf5"    # обычные иконки
ICON_MUTED = "#8e98ab"    # второстепенные иконки
ICON_STROKE = 7.0         # толщина «линейных» иконок на сетке 64x64
ICON_HI = "#ffffff"       # иконка включённой кнопки-режима
ON_ACCENT = "#ffffff"     # иконка/текст на акцентной (залитой) кнопке
ACCENT_LIGHT = "#ff8da7"  # светлый акцент для текста и ссылок
SPECIAL = "#ffb02e"       # цвет блока «Настройки / О приложении»
ON_SPECIAL = "#0d0f14"    # иконка на залитой кнопке этого блока
_ICON_REG: dict = {}      # cacheKey иконки -> (вид, роль цвета, размер): нужно для смены темы


def make_icon(kind: str, color: str | None = None, size: int = 64) -> QIcon:
    if _THEME.get("name") in {"jet_black_orchid", "wine_ash_turquoise"}:
        if color is None or (str(color).lower() == _THEME["bg"].lower() and not kind.startswith("fs_")):
            color = "#ffffff"  # Ordinary glyphs stay white; selected file icons retain their contrast role.
    color = color or ICON_COLOR
    pm = QPixmap(size, size)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.scale(size / 64.0, size / 64.0)
    qc = QColor(color)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(qc)

    def poly(*pts):
        p.drawPolygon(QPolygonF([QPointF(x, y) for x, y in pts]))

    def rect(x, y, w, h, r=3):
        p.drawRoundedRect(QRectF(x, y, w, h), r, r)

    def disc(cx, cy, r):
        p.drawEllipse(QPointF(cx, cy), r, r)

    def clear(fn):
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)
        fn()
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)

    def stroked(width=ICON_STROKE):
        p.setPen(QPen(qc, width, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.setBrush(Qt.BrushStyle.NoBrush)

    def filled():
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(qc)

    def line(x1, y1, x2, y2):
        p.drawLine(QPointF(x1, y1), QPointF(x2, y2))

    def path(pts):
        p.drawPolyline(QPolygonF([QPointF(x, y) for x, y in pts]))

    if kind.startswith("fs_"):
        # File-picker glyphs share one 5-unit stroke and the same 64px grid.
        stroked(5)
        symbol = kind[3:]
        if symbol in ("back", "forward", "up", "down"):
            path({"back": [(40, 12), (20, 32), (40, 52)],
                  "forward": [(24, 12), (44, 32), (24, 52)],
                  "up": [(12, 40), (32, 20), (52, 40)],
                  "down": [(12, 24), (32, 44), (52, 24)]}[symbol])
        elif symbol in ("computer", "desktop", "network"):
            rect(8, 8, 48, 34, 5)
            line(32, 42, 32, 54)
            line(20, 55, 44, 55)
        elif symbol == "drive":
            rect(8, 15, 48, 36, 6)
            line(8, 37, 56, 37)
            filled(); disc(46, 44, 2)
        elif symbol in ("folder", "folder_add"):
            path([(7, 22), (7, 13), (26, 13), (33, 22), (56, 22), (56, 51), (7, 51), (7, 22), (56, 22)])
            if symbol == "folder_add":
                line(32, 29, 32, 43); line(25, 36, 39, 36)
        elif symbol in ("list", "details"):
            if symbol == "details":
                rect(8, 10, 48, 44, 3)
                line(8, 23, 56, 23); line(8, 38, 56, 38); line(24, 10, 24, 54)
            else:
                for yy in (16, 32, 48):
                    line(23, yy, 55, yy); line(9, yy, 12, yy)
        else:
            path([(14, 7), (39, 7), (51, 20), (51, 57), (14, 57), (14, 7)])
            path([(38, 8), (38, 21), (50, 21)])
            if symbol == "audio":
                line(35, 29, 35, 45); line(35, 29, 43, 27)
                filled(); disc(29, 46, 5)
            elif symbol == "video":
                filled(); poly((25, 28), (25, 47), (41, 38))
            elif symbol == "image":
                path([(20, 47), (29, 35), (36, 43), (42, 36), (46, 47)])
                filled(); disc(24, 29, 3)
            elif symbol == "archive":
                for yy in (29, 37, 45):line(30, yy, 35, yy)
            elif symbol == "text":
                for yy in (30, 39, 48):line(22, yy, 42, yy)
    elif kind == "play":
        poly((20, 12), (20, 52), (52, 32))
    elif kind == "pause":
        rect(16, 12, 12, 40)
        rect(36, 12, 12, 40)
    elif kind == "next":
        poly((12, 14), (12, 50), (40, 32))
        rect(44, 14, 8, 36)
    elif kind == "prev":
        poly((52, 14), (52, 50), (24, 32))
        rect(12, 14, 8, 36)
    elif kind == "plus":
        rect(10, 28, 44, 8)
        rect(28, 10, 8, 44)
    elif kind == "minus":
        rect(10, 28, 44, 8)
    elif kind == "download":
        rect(28, 8, 8, 28)
        poly((14, 30), (50, 30), (32, 52))
        rect(12, 55, 40, 6)
    elif kind == "pin":
        rect(18, 6, 28, 10)
        poly((24, 16), (40, 16), (46, 36), (18, 36))
        rect(14, 36, 36, 6)
        rect(29, 42, 6, 18, 2)
    elif kind == "panel":
        rect(8, 12, 48, 8)
        rect(8, 28, 48, 8)
        rect(8, 44, 48, 8)
    elif kind == "folder":
        rect(6, 20, 52, 34, 5)
        rect(6, 12, 22, 12)
    elif kind == "film":
        stroked(5)
        p.drawRoundedRect(QRectF(8, 12, 48, 40), 4, 4)
        path([(24, 13), (24, 51)])
        path([(40, 13), (40, 51)])
        for yy in (21, 32, 43):
            line(10, yy, 22, yy)
            line(42, yy, 54, yy)
    elif kind == "palette":
        disc(32, 32, 26)
        clear(lambda: [disc(cx, cy, 5) for cx, cy in ((24, 24), (40, 22), (44, 38), (26, 42))])
    elif kind == "frame":
        stroked(7)
        p.drawRoundedRect(QRectF(10, 12, 44, 40), 5, 5)
        filled()
        rect(32, 32, 22, 20)
    elif kind == "list":
        for y in (12, 27, 42):
            rect(8, y, 10, 10, 2)
            rect(24, y + 2, 32, 6)
    elif kind == "seek":
        rect(6, 29, 52, 6)
        disc(26, 32, 11)
    elif kind == "sliders":
        rect(6, 16, 52, 6)
        disc(40, 19, 9)
        rect(6, 42, 52, 6)
        disc(22, 45, 9)
    elif kind == "eq":
        for x, ky in ((14, 42), (32, 22), (50, 34)):
            rect(x - 3, 6, 6, 52, 3)
            disc(x, ky, 8)
    elif kind == "activity":
        stroked()
        path([(6, 33), (18, 33), (26, 12), (38, 52), (46, 33), (58, 33)])
    elif kind in ("volume", "mute"):
        poly((6, 25), (17, 25), (30, 13), (30, 51), (17, 39), (6, 39))
        stroked(6)
        if kind == "volume":
            p.drawArc(QRectF(20, 21, 22, 22), -50 * 16, 100 * 16)
            p.drawArc(QRectF(9, 9, 46, 46), -50 * 16, 100 * 16)
        else:
            line(41, 25, 56, 40)
            line(56, 25, 41, 40)
    elif kind == "save":
        rect(8, 8, 48, 48, 7)
        clear(lambda: (rect(19, 8, 24, 15, 2), rect(16, 35, 32, 21, 3)))
        rect(20, 40, 24, 16, 2)
    elif kind == "trash":
        rect(9, 15, 46, 8, 4)
        rect(23, 8, 18, 9, 3)
        rect(15, 26, 34, 30, 5)
        clear(lambda: (rect(25, 32, 5, 18, 2), rect(34, 32, 5, 18, 2)))
    elif kind == "stop":
        rect(12, 12, 40, 40, 6)
    elif kind in ("repeat_one", "shuffle_tracks", "sequential_tracks", "convert"):
        stroked()
        if kind == "repeat_one":
            p.drawArc(QRectF(11, 12, 42, 42), 35 * 16, 145 * 16)
            p.drawArc(QRectF(11, 12, 42, 42), 215 * 16, 145 * 16)
            filled()
            poly((52, 8), (52, 26), (36, 20))
            poly((12, 56), (12, 38), (28, 44))
            stroked(5)
            path([(27, 29), (33, 24), (33, 41)])
        elif kind == "shuffle_tracks":
            path([(7, 18), (17, 18), (43, 46), (50, 46)])
            path([(7, 46), (17, 46), (43, 18), (50, 18)])
            filled()
            poly((50, 9), (60, 18), (50, 27))
            poly((50, 37), (60, 46), (50, 55))
        elif kind == "sequential_tracks":
            line(10, 16, 36, 16)
            line(10, 32, 36, 32)
            line(10, 48, 36, 48)
            filled()
            poly((38, 20), (56, 32), (38, 44))
        else:  # convert
            path([(10, 28), (10, 18), (42, 18)])
            path([(54, 36), (54, 46), (22, 46)])
            filled()
            poly((40, 8), (56, 18), (40, 28))
            poly((24, 36), (8, 46), (24, 56))
    elif kind == "headphones":
        stroked(7)
        p.drawArc(QRectF(10, 10, 44, 44), 0, 180 * 16)
        filled()
        rect(8, 32, 14, 22, 5)
        rect(42, 32, 14, 22, 5)
    elif kind == "layout_all":
        rect(8, 8, 22, 22, 4)
        rect(34, 8, 22, 22, 4)
        rect(8, 34, 22, 22, 4)
        rect(34, 34, 22, 22, 4)
    elif kind == "speed":
        stroked(7)
        p.drawArc(QRectF(8, 10, 48, 48), 210 * 16, -240 * 16)
        line(32, 34, 44, 21)
        filled()
        disc(32, 34, 6)
    elif kind == "settings":
        filled()
        for i in range(8):
            p.save()
            p.translate(32, 32)
            p.rotate(i * 45)
            rect(-5, -30, 10, 15, 2)
            p.restore()
        disc(32, 32, 21)
        clear(lambda: disc(32, 32, 8.5))
    elif kind == "info":
        disc(32, 32, 27)
        clear(lambda: (disc(32, 18.5, 4.5), rect(28, 28, 8, 20, 3)))
    elif kind == "heart":
        disc(21, 24, 14)
        disc(43, 24, 14)
        poly((8.5, 30), (55.5, 30), (32, 56))
    elif kind in ("chev_r", "chev_l", "chev_d", "chev_u"):
        pts = {"chev_r": [(24, 10), (44, 32), (24, 54)],
               "chev_l": [(40, 10), (20, 32), (40, 54)],
               "chev_d": [(10, 22), (32, 44), (54, 22)],
               "chev_u": [(10, 42), (32, 20), (54, 42)]}[kind]
        stroked(9)
        path(pts)
    p.end()
    icon = QIcon(pm)
    _ICON_REG[icon.cacheKey()] = (kind, _icon_role(color), size)
    return icon


def _icon_role(color: str) -> str:
    c = str(color).lower()
    for role, value in (("special", SPECIAL), ("onspecial", ON_SPECIAL), ("icon", ICON_COLOR),
                        ("muted", ICON_MUTED), ("accent", ACCENT), ("onacc", ON_ACCENT), ("hi", ICON_HI)):
        if c == str(value).lower():
            return role
    return "raw:" + c


def _role_color(role: str) -> str:
    if _THEME["name"] in {"jet_black_orchid", "wine_ash_turquoise"} and role in {"icon", "hi", "onacc", "onspecial"}:
        return "#ffffff"
    if role.startswith("raw:"):
        return role[4:]
    return {"special": SPECIAL, "onspecial": ICON_HI, "icon": ICON_COLOR, "muted": ICON_MUTED,
            "accent": ACCENT, "onacc": ICON_HI, "hi": ICON_HI}.get(role, ICON_COLOR)


def ensure_arrow_png() -> str:
    """Рисует стрелку для выпадающих списков (в стилях Qt она иначе пропадает)."""
    arrow = DATA_DIR / "arrow_down.png"
    pm = QPixmap(20, 12)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#9a9a9a"))
    p.drawPolygon(QPolygonF([QPointF(4, 3), QPointF(16, 3), QPointF(10, 10)]))
    p.end()
    pm.save(str(arrow), "PNG")
    return arrow.as_posix()


