def make_application_icon() -> QIcon:
    """Load the embedded N/Omni mark at native Windows icon sizes."""
    icon = QIcon()
    for encoded in _NOP_APP_ICON_PNGS:
        pixmap = QPixmap()
        pixmap.loadFromData(base64.b64decode(encoded), "PNG")
        icon.addPixmap(pixmap)
    return icon


