ASSET_DIRS = [APP_DIR / "assets", DATA_DIR / "assets"]
if getattr(sys, "_MEIPASS", None):
    ASSET_DIRS.append(Path(sys._MEIPASS) / "assets")


def find_asset(stem: str) -> Path | None:
    for folder in ASSET_DIRS:
        for ext in (".png", ".jpg", ".jpeg", ".webp"):
            candidate = folder / (stem + ext)
            if candidate.is_file():
                return candidate
    return None


def support_url(value: str) -> str:
    """Return a configured web link, or hide it when empty/malformed."""
    url = str(value or "").strip()
    if not url or any(ch.isspace() for ch in url):
        return ""
    try:
        parsed = urllib.parse.urlsplit(url)
        if (parsed.scheme.lower() not in {"http", "https"} or not parsed.hostname
                or parsed.username is not None or parsed.password is not None):
            return ""
        parsed.port  # Reject malformed/out-of-range ports before showing the link.
    except ValueError:
        return ""
    return url


# ---------- темы оформления ----------
# Тема 1 - исходная. В темах 2 и 3 тёмный цвет задаёт фон, светлый используется для акцентов и иконок.
# Цвета текста во всех темах остаются из исходной таблицы STYLE.
THEMES = {
    "classic": {"ru": "1 · Классическая", "dark": "#0d0f14", "light": "#e9edf5", "swatch": "#ff426d", "special": "#ffb02e"},
    "cosmic": {"ru": "2 · Cosmic + Vanilla", "dark": "#23212C", "light": "#F1FEC8", "swatch": "#F1FEC8", "special": "#ff9e64"},
    "lavender": {"ru": "3 · Lavender + Violet", "dark": "#36255C", "light": "#D2C3F6", "swatch": "#D2C3F6", "special": "#ffd166"},
    "jet_black_orchid": {"ru": "4 · Jet Black / Orchid", "dark": "#1D1D1D", "light": "#E5BDDF", "swatch": "#E5BDDF", "special": "#F2B78C"},
    "wine_ash_turquoise": {"ru": "5 · Wine Ash / Turquoise", "dark": "#32292F", "light": "#99E1D9", "swatch": "#99E1D9", "special": "#E7C77F"},
}
_HEX_RE = re.compile(r"#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b")
_ORIG_BG = "#0d0f14"
_ORIG_FG = "#e9edf5"
_THEME: dict = {"name": "classic", "light": False, "identity": True, "amap": {}, "keep": set(), "ph": {}}


def _rgb(h):
    if not isinstance(h, str):
        return tuple(h)
    h = h.lstrip("#")
    if len(h) == 3:
        h = "".join(ch * 2 for ch in h)
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)


def _hx(c) -> str:
    return "#%02x%02x%02x" % tuple(max(0, min(255, int(round(v)))) for v in c)


def _mixc(a, b, t: float) -> str:
    ra, rb = _rgb(a), _rgb(b)
    return _hx(tuple(x + (y - x) * t for x, y in zip(ra, rb)))


def _lum(c) -> float:
    r, g, b = _rgb(c)
    return 0.299 * r + 0.587 * g + 0.114 * b


def set_theme(name: str, light: bool = False) -> None:
    """Применяет цветовую тему; текстовые цвета остаются как в classic.

    Аргумент light сохранён ради совместимости со старыми вызовами и настройками,
    но прежний светлый вариант больше не используется.
    """
    global ACCENT, ACCENT_LIGHT, ICON_COLOR, ICON_MUTED, ICON_HI, ON_ACCENT, SPECIAL, ON_SPECIAL, _THEME
    if name not in THEMES:
        name = "classic"
    th = THEMES[name]
    classic = name == "classic"
    light = False  # безопасно игнорируем старое сохранённое theme_light=True
    bg = th["dark"]
    tone = _ORIG_FG if classic else th["light"]
    accent = "#ff426d" if classic else tone
    on_accent = "#ffffff" if classic else bg
    special = th["special"]
    ACCENT = accent
    # Ссылки/текстовые акценты остаются тем же читаемым оттенком во всех темах.
    ACCENT_LIGHT = "#ff8da7" if name in {"classic", "cosmic", "lavender"} else tone
    ICON_COLOR = tone
    ICON_MUTED = "#8e98ab" if classic else _mixc(bg, tone, 0.68 if name in {"jet_black_orchid", "wine_ash_turquoise"} else 0.55)
    ICON_HI = "#ffffff" if classic else tone
    ON_ACCENT = on_accent
    SPECIAL = special
    ON_SPECIAL = bg

    def shift(c, k):
        return _mixc(c, "#ffffff" if _lum(c) < 150 else bg, k)

    amap = {}
    if not classic:
        amap = {
            "#ff426d": accent, "#ff5c80": shift(accent, 0.12), "#ff6486": shift(accent, 0.16),
            "#ff8da7": ACCENT_LIGHT,
            "#3a2431": _mixc(bg, accent, 0.19), "#3b2637": _mixc(bg, accent, 0.19),
            "#4a2a3b": _mixc(bg, accent, 0.27), "#4a2935": _mixc(bg, accent, 0.22),
            "#5a2a38": _mixc(bg, accent, 0.30), "#a17c87": _mixc(accent, bg, 0.55),
        }
    _THEME = {
        "name": name, "light": False, "identity": classic, "bg": bg,
        "fg": _ORIG_FG, "tone": tone, "amap": amap,
        "keep": {"#7bd88f", "#2f5a3e", "#000000"},
        "ph": {
            "%ACCENT%": accent, "%ONACC%": on_accent, "%ONSPECIAL%": bg, "%SPECIAL%": special, "%PANELBG%": bg,
            "%SPBG%": _mixc(bg, special, 0.28), "%SPHOVER%": _mixc(bg, special, 0.42),
            "%SPLINE%": _mixc(bg, special, 0.55),
            "%SELECTBG%": _mixc(bg, accent, .18), "%SELECTFG%": ICON_HI,
            "%ACCENTDIM%": _mixc(bg, accent, .55),
        },
    }


def themed(css: str) -> str:
    """Перекрашивает поверхности и рамки, не меняя CSS-цвета текста classic."""
    th = _THEME
    # SPECIAL/SPBG/SPHOVER/SPLINE already retain each theme's warm accent.
    # All non-classic themes share the original quietOutline/information states
    # in STYLE; appending separate 4/5 overrides here would defeat that cascade.
    placeholders = {}
    for index, (key, value) in enumerate(th["ph"].items()):
        token = f"__NOP_THEME_{index}__"
        placeholders[token] = value
        css = css.replace(key, token)  # Semantic colors must not be interpolated twice.
    if not th["identity"]:
        # Цвета текста — отдельная семантическая группа. Раньше общий HEX_RE
        # смешивал их с фоновым тоном темы, из-за чего менялся цвет шрифта.
        protected_text_colors = []
        text_color_decl = re.compile(
            r"(?P<prefix>(?:^|[;{]\s*)(?:selection-color|color)\s*:\s*)"
            r"(?P<value>[^;}]*)", re.IGNORECASE
        )

        def protect_text_color(match):
            token = f"__YAMI_TEXT_COLOR_{len(protected_text_colors)}__"
            value = match.group("value")
            if th["name"] in {"jet_black_orchid", "wine_ash_turquoise"}:
                value = value.replace("#ff8da7", ACCENT_LIGHT).replace("#ff426d", ACCENT)
            protected_text_colors.append(value)
            return match.group("prefix") + token

        css = text_color_decl.sub(protect_text_color, css)
        lb, lf = _lum(_ORIG_BG), _lum(_ORIG_FG)

        def repl(m):
            h = m.group(0).lower()
            if len(h) == 4:
                h = "#" + "".join(ch * 2 for ch in h[1:])
            if h in th["keep"]:
                return m.group(0)
            if h in th["amap"]:
                return th["amap"][h]
            t = (_lum(h) - lb) / (lf - lb)
            return _mixc(th["bg"], th["tone"], max(0.0, min(1.0, t)))

        css = _HEX_RE.sub(repl, css)
        for index, value in enumerate(protected_text_colors):
            css = css.replace(f"__YAMI_TEXT_COLOR_{index}__", value)
    for token, value in placeholders.items():
        css = css.replace(token, value)
    return css


set_theme("classic")


