def set_language(code: str) -> None:
    global LANG
    LANG = "en" if code == "en" else "ru"
    app = QApplication.instance()
    if app is not None:
        previous = getattr(app, "_cnp_qt_translator", None)
        if previous is not None:
            app.removeTranslator(previous)
            previous.deleteLater()
        app._cnp_qt_translator = CnpQtTranslator(app) if LANG == "ru" else None
        if app._cnp_qt_translator is not None:
            app.installTranslator(app._cnp_qt_translator)
        QLocale.setDefault(QLocale("ru_RU" if LANG == "ru" else "en_US"))


def T(text: str) -> str:
    if LANG != "en" or not text:
        return text
    hit = EN_TEXT.get(text)
    if hit is not None:
        return hit
    hit = _UI_PAIRS.get(text)
    if hit is not None:
        return hit
    return _translate_dynamic(text)


def T_html(text: str) -> str:
    if LANG != "en":
        return text
    for ru in sorted(EN_HTML, key=len, reverse=True):
        if ru in text:
            text = text.replace(ru, EN_HTML[ru])
    return text


