class WrapCheck(QWidget):
    """Флажок с переносимой подписью (обычный QCheckBox длинный текст не переносит)."""
    toggled = pyqtSignal(bool)

    def __init__(self, text: str, checked: bool = False, parent=None):
        super().__init__(parent)
        self.setObjectName("clear")
        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(8)
        self.box = QCheckBox()
        self.box.setChecked(bool(checked))
        self.box.setCursor(Qt.CursorShape.PointingHandCursor)
        self.box.toggled.connect(self.toggled)
        self.label = QLabel(text)
        self.label.setWordWrap(True)
        self.label.setCursor(Qt.CursorShape.PointingHandCursor)
        self.label.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.label.mousePressEvent = lambda _e: self.box.toggle() if self.box.isEnabled() else None
        lay.addWidget(self.box, 0, Qt.AlignmentFlag.AlignTop)
        lay.addWidget(self.label, 1)

    def isChecked(self) -> bool:
        return self.box.isChecked()

    def setChecked(self, on: bool):
        self.box.setChecked(bool(on))


def fmt_time(ms: int) -> str:
    s = max(int(ms), 0) // 1000
    h, rem = divmod(s, 3600)
    m, s = divmod(rem, 60)
    return f"{h}:{m:02d}:{s:02d}" if h else f"{m}:{s:02d}"


NAME_RE = re.compile(r"^(?P<title>.*?)\s*\[(?P<id>[\w-]{11})\](?: ~(?P<tag>\S+))?$")


def parse_name(stem: str):
    """'Название [id] ~метка' -> (название, id, метка). None, если это не файл от yt-dlp."""
    m = NAME_RE.match(stem)
    return (m["title"], m["id"], m["tag"] or "") if m else None


def display_name(p: Path) -> str:
    """Имя трека без служебного [id]; у копий «только аудио / только видео» добавляется пометка."""
    parsed = parse_name(p.stem)
    if not parsed:
        return p.stem
    title, _, tag = parsed
    clip = " · " + ui_text("фрагмент", "clip") if any(part.startswith("cut") for part in tag.split("_")) else ""
    if tag.startswith("a-"):
        return f"{title} · " + ui_text("аудио", "audio") + clip
    if tag.startswith("v-"):
        return f"{title} · " + ui_text("видео", "video") + clip
    return title + clip


def is_complete_media(path: Path) -> bool:
    if not path.is_file() or path.suffix.lower() not in MEDIA_EXTS:
        return False
    if re.search(r"\.f\d+$|\[[^\[\]]+\](?: ~[^.]+)?\.temp$", path.stem):
        return False
    try:
        return path.stat().st_size > 0
    except OSError:
        return False


def downloaded_ids(folder: Path, clip_tag: str = "") -> set[str]:
    """ID видео, которые уже есть в папке, независимо от профиля/качества.

    Фрагмент (метка «cut…») и целое видео — разные файлы: целое видео не блокирует загрузку
    фрагмента, а фрагмент не считается скачанным целым видео."""
    ids = set()
    try:
        for p in folder.iterdir():
            if is_complete_media(p):
                parsed = parse_name(p.stem)
                if parsed:
                    file_clip = next((part for part in parsed[2].split("_") if part.startswith("cut")), "")
                    if file_clip == clip_tag:
                        ids.add(parsed[1])
                elif not clip_tag:
                    # Запасной поиск ID для файлов с немного изменённым названием.
                    m = re.search(r"\[([\w-]{11})\]", p.stem)
                    if m:
                        ids.add(m.group(1))
    except OSError:
        pass
    return ids


class WheelSafeComboBox(QComboBox):
    """Колёсико прокручивает родительскую панель, но не меняет значение и hover-рамку."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._wheel_suppresses_hover = False

    def wheelEvent(self, event):
        # Даже при открытом/закрытом combo колёсико не меняет значение.
        # Передаём событие родительской QScrollArea и временно убираем hover-акцент.
        self._wheel_suppresses_hover = True
        self.setProperty("wheelScrolled", True)
        self.style().unpolish(self)
        self.style().polish(self)
        self.update()
        event.ignore()

    def mouseMoveEvent(self, event):
        if self._wheel_suppresses_hover:
            self._wheel_suppresses_hover = False
            self.setProperty("wheelScrolled", False)
            self.style().unpolish(self)
            self.style().polish(self)
            self.update()
        super().mouseMoveEvent(event)

    def leaveEvent(self, event):
        self._wheel_suppresses_hover = False
        self.setProperty("wheelScrolled", False)
        self.style().unpolish(self)
        self.style().polish(self)
        super().leaveEvent(event)


class NoWheelSlider(QSlider):
    """Колёсико мыши НЕ меняет значение ползунка: событие уходит родительской панели (она прокручивается)."""

    def wheelEvent(self, event):
        event.ignore()


