class ClickSlider(NoWheelSlider):
    """Ползунок: клик в любое место сразу переносит бегунок туда, потом можно тянуть.
    Работает и для горизонтальных, и для вертикальных (у вертикальных максимум сверху).
    Колёсико не действует (см. NoWheelSlider) - ни на одном ползунке программы."""

    def _apply(self, e):
        if self.orientation() == Qt.Orientation.Vertical:
            v = QStyle.sliderValueFromPosition(
                self.minimum(), self.maximum(), int(e.position().y()), max(self.height(), 1), True
            )
        else:
            v = QStyle.sliderValueFromPosition(
                self.minimum(), self.maximum(), int(e.position().x()), max(self.width(), 1)
            )
        self.setValue(v)
        self.sliderMoved.emit(v)

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            self.setSliderDown(True)
            self._apply(e)
            e.accept()
        else:
            super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        if self.isSliderDown():
            self._apply(e)
            e.accept()
        else:
            super().mouseMoveEvent(e)

    def mouseReleaseEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton and self.isSliderDown():
            self.setSliderDown(False)
            e.accept()
        else:
            super().mouseReleaseEvent(e)


def fmt_size(n: float) -> str:
    units = ("B", "KB", "MB", "GB") if LANG == "en" else ("Б", "КБ", "МБ", "ГБ")
    for unit in units:
        if n < 1024 or unit == units[-1]:
            return f"{n:.1f} {unit}"
        n /= 1024
    return f"{n:.1f} {units[-1]}"


def fmt_speed(n: float) -> str:
    return f"{fmt_size(n)}/" + ("s" if LANG == "en" else "с")


def flatten(entries):
    """Разворачивает вложенные плейлисты (если дали ссылку на корень канала)."""
    for e in entries or []:
        if not e:
            continue
        if e.get("entries"):
            yield from flatten(e["entries"])
        elif e.get("id"):
            yield e


class ElidedLabel(QLabel):
    """Однострочная подпись: длинный текст обрезается многоточием (полный - во всплывающей подсказке),
    а не «убегает» за границу панели и не растягивает её."""

    def __init__(self, text: str = "", parent=None):
        super().__init__(parent)
        self._full = ""
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.setMinimumWidth(0)
        self.setText(text)

    def setText(self, text: str):
        self._full = _dyn(str(text))
        self.setToolTip(self._full)
        self._refresh()

    def text(self) -> str:
        return self._full

    def setFixedWidth(self, width: int):
        # Политика Ignored заставляла компоновку выделять подписи фиксированной ширины 0 px,
        # и ползунки налезали на текст. При явной ширине подпись занимает ровно её.
        super().setFixedWidth(width)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Preferred)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._refresh()

    def _refresh(self):
        shown = self.fontMetrics().elidedText(
            self._full, Qt.TextElideMode.ElideRight, max(self.width() - 2, 0)
        )
        if shown != QLabel.text(self):
            QLabel.setText(self, shown)


class FitScrollArea(QScrollArea):
    """Прокрутка, у которой желаемый размер = размер содержимого.
    У обычного QScrollArea sizeHint ограничен ~24 высотами строки, из-за чего содержимое
    обрезалось и приходилось задавать высоту панели «на глаз»."""

    MAX_SCREEN_FRACTION = 0.6   # выше этой доли экрана панель не растёт - появляется прокрутка

    def sizeHint(self):
        content = self.widget()
        if content is None:
            return super().sizeHint()
        hint = content.sizeHint()
        screen = self.screen() or QApplication.primaryScreen()
        cap = int(screen.availableGeometry().height() * self.MAX_SCREEN_FRACTION) if screen else hint.height()
        f = 2 * self.frameWidth()
        return QSize(hint.width() + f, min(hint.height(), cap) + f)


class LowerScrollArea(QScrollArea):
    """Нижняя часть окна (настройки загрузки и эквалайзер).
    Желаемая высота = высота содержимого, но не больше cap: выше - вертикальная прокрутка,
    и окно с любым числом открытых панелей остаётся в пределах экрана."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.cap = 10 ** 6
        self.setWidgetResizable(True)
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)

    def sizeHint(self):
        content = self.widget()
        if content is None:
            return super().sizeHint()
        hint = content.sizeHint()
        h = min(hint.height(), self.cap)
        w = hint.width()
        if hint.height() > self.cap:
            w += self.verticalScrollBar().sizeHint().width() + 4
        return QSize(w, h)

    def minimumSizeHint(self):
        return QSize(0, min(self.sizeHint().height(), 120))


class HFitScrollArea(QScrollArea):
    """Горизонтальная прокрутка: ширина = ширина содержимого, но не больше MAX_WIDTH
    (если полос эквалайзера очень много - появляется полоса прокрутки, окно не раздувается)."""

    MAX_WIDTH = 520

    def sizeHint(self):
        content = self.widget()
        if content is None:
            return super().sizeHint()
        hint = content.sizeHint()
        bar = self.horizontalScrollBar().sizeHint().height() if hint.width() > self.MAX_WIDTH else 0
        f = 2 * self.frameWidth()
        return QSize(min(hint.width(), self.MAX_WIDTH) + f, hint.height() + bar + f)

    def minimumSizeHint(self):
        return QSize(120, self.sizeHint().height())


class RowScrollArea(QScrollArea):
    """Панель с вертикальной прокруткой, которая НЕ растягивает окно по высоте.
    Желаемая высота ограничена PREFERRED_HEIGHT, остальное прокручивается; если строка выше
    (крупное видео, полный экран) - панель занимает всё доступное место."""

    PREFERRED_HEIGHT = 340

    def sizeHint(self):
        content = self.widget()
        if content is None:
            return super().sizeHint()
        hint = content.sizeHint()
        f = 2 * self.frameWidth()
        return QSize(hint.width() + f, min(hint.height(), self.PREFERRED_HEIGHT) + f)


class PresetListWidget(QListWidget):
    """Список пресетов с удобной прокруткой: плавное колесо и тачпад, передача прокрутки панели
    на краях списка, выбор стрелками/PgUp/PgDn/Home/End и набором буквы с применением пресета."""
    picked = pyqtSignal(object)
    WHEEL_ROWS = 3

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setVerticalScrollMode(QListWidget.ScrollMode.ScrollPerPixel)
        self.verticalScrollBar().setSingleStep(22)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setUniformItemSizes(False)
        self.setMouseTracking(True)
        self._by_key = False
        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.setInterval(140)  # не пересчитываем цвет на каждый шаг при быстром листании
        self._timer.timeout.connect(self._emit_current)
        self.currentItemChanged.connect(self._current_changed)

    def wheelEvent(self, event):
        bar = self.verticalScrollBar()
        pixels = event.pixelDelta().y()
        delta = pixels if pixels else round(event.angleDelta().y() / 120 * bar.singleStep() * self.WHEEL_ROWS)
        if not delta or bar.maximum() <= bar.minimum():
            event.ignore()  # список короче окна: пусть прокручивается вся панель
            return
        if (delta > 0 and bar.value() <= bar.minimum()) or (delta < 0 and bar.value() >= bar.maximum()):
            event.ignore()  # край списка: прокрутка уходит на панель, а не «залипает»
            return
        bar.setValue(bar.value() - delta)
        event.accept()

    def keyPressEvent(self, event):
        self._by_key = True
        try:
            super().keyPressEvent(event)
        finally:
            self._by_key = False

    def _current_changed(self, current, _previous):
        if self._by_key and current is not None and current.data(Qt.ItemDataRole.UserRole):
            self._timer.start()

    def _emit_current(self):
        item = self.currentItem()
        if item is not None and item.data(Qt.ItemDataRole.UserRole):
            self.scrollToItem(item, QListWidget.ScrollHint.EnsureVisible)
            self.picked.emit(item)


class SpotifyAuthThread(QThread):
    """OAuth PKCE для официального Spotify Web API без встраивания client secret в приложение."""
    status = pyqtSignal(str)
    result = pyqtSignal(dict)

    REDIRECT_URI = "http://127.0.0.1:8765/callback"
    AUTH_TIMEOUT_SECONDS = 180

    def __init__(self, client_id: str, parent=None):
        super().__init__(parent)
        self.client_id = (client_id or "").strip()
        self._stop_event = threading.Event()

    def run(self):
        server = None
        try:
            if not self.client_id:
                raise RuntimeError("Сначала укажи Spotify Client ID.")
            verifier = secrets.token_urlsafe(64)[:96]
            challenge = base64.urlsafe_b64encode(hashlib.sha256(verifier.encode("ascii")).digest()).decode("ascii").rstrip("=")
            state = secrets.token_urlsafe(18)

            class CallbackHandler(BaseHTTPRequestHandler):
                def do_GET(handler_self):
                    parsed = urllib.parse.urlparse(handler_self.path)
                    try:
                        query = urllib.parse.parse_qs(parsed.query, max_num_fields=16)
                    except ValueError:
                        handler_self.send_error(400)
                        return
                    if parsed.path != "/callback":
                        handler_self.send_response(404)
                        handler_self.end_headers()
                        return
                    if not secrets.compare_digest(query.get("state", [""])[0], handler_self.server.expected_state):
                        # A forged local callback must not cancel the legitimate attempt.
                        status_code = 400
                        page = "Проверка состояния OAuth не прошла. Вернитесь к своей вкладке Spotify."
                    elif query.get("error"):
                        handler_self.server.auth_error = str(query.get("error_description", query["error"])[0])
                        status_code = 400
                        page = "Spotify отказал в авторизации. Можно закрыть эту вкладку и вернуться в NOP."
                    elif query.get("code"):
                        handler_self.server.authorization_code = query["code"][0]
                        status_code = 200
                        page = "Spotify подключён к NOP. Эту вкладку можно закрыть."
                    else:
                        handler_self.server.auth_error = "Spotify не вернул код авторизации."
                        status_code = 400
                        page = "Не получен код авторизации. Можно закрыть эту вкладку."
                    body = ("<!doctype html><meta charset='utf-8'><title>NOP</title>"
                            "<body style='font:16px sans-serif;background:#111;color:#eee;padding:3em'>"
                            f"<h2>{html_lib.escape(page)}</h2></body>").encode("utf-8")
                    handler_self.send_response(status_code)
                    handler_self.send_header("Cache-Control", "no-store")
                    handler_self.send_header("Referrer-Policy", "no-referrer")
                    handler_self.send_header("Content-Type", "text/html; charset=utf-8")
                    handler_self.send_header("Content-Length", str(len(body)))
                    handler_self.end_headers()
                    try:
                        handler_self.wfile.write(body)
                    except OSError:
                        pass

                def log_message(handler_self, format_string, *args):
                    return

            class CallbackServer(HTTPServer):
                def get_request(server_self):
                    connection, address = super().get_request()
                    connection.settimeout(2)
                    return connection, address
            server = CallbackServer(("127.0.0.1", 8765), CallbackHandler)
            server.timeout = .2
            server.expected_state = state
            server.authorization_code = ""
            server.auth_error = ""
            auth_params = {
                "client_id": self.client_id,
                "response_type": "code",
                "redirect_uri": self.REDIRECT_URI,
                "scope": "playlist-read-private playlist-read-collaborative",
                "state": state,
                "code_challenge_method": "S256",
                "code_challenge": challenge,
            }
            auth_url = "https://accounts.spotify.com/authorize?" + urllib.parse.urlencode(auth_params)
            self.status.emit("Открыл страницу Spotify — заверши авторизацию в браузере…")
            if not webbrowser.open(auth_url):
                self.status.emit("Если браузер не открылся, открой ссылку авторизации вручную.")
            deadline = time.monotonic() + self.AUTH_TIMEOUT_SECONDS
            while (not server.authorization_code and not server.auth_error
                   and not self._stop_event.is_set() and time.monotonic() < deadline):
                server.handle_request()
            if self._stop_event.is_set():
                return
            if server.auth_error:
                raise RuntimeError(server.auth_error)
            if not server.authorization_code:
                raise RuntimeError("Время авторизации истекло. Нажми «Авторизовать Spotify» ещё раз.")

            token_payload = urllib.parse.urlencode({
                "grant_type": "authorization_code",
                "code": server.authorization_code,
                "redirect_uri": self.REDIRECT_URI,
                "client_id": self.client_id,
                "code_verifier": verifier,
            }).encode("ascii")
            request = urllib.request.Request(
                "https://accounts.spotify.com/api/token",
                data=token_payload,
                headers={"Content-Type": "application/x-www-form-urlencoded"},
                method="POST",
            )
            with urllib.request.urlopen(request, timeout=25) as response:
                token_data = json.loads(response.read(1024 * 1024).decode("utf-8", errors="replace"))
            if not token_data.get("access_token"):
                raise RuntimeError("Spotify не вернул access token.")
            self.result.emit({
                "ok": True,
                "access_token": str(token_data.get("access_token", "")),
                "refresh_token": str(token_data.get("refresh_token", "")),
                "expires_at": time.time() + int(token_data.get("expires_in", 3600)),
                "client_id": self.client_id,
            })
        except Exception as exc:  # noqa: BLE001
            self.result.emit({"ok": False, "error": redact_diagnostic(exc)})
        finally:
            if server is not None:
                try:
                    server.server_close()
                except OSError:
                    pass

    def request_stop(self):
        self._stop_event.set()
        self.requestInterruption()


class AudioSampleRatePP(PostProcessor):
    """Реально пересэмплирует уже загруженный аудиофайл, сохраняя его расширение."""

    ALLOWED_RATES = {"22050", "32000", "44100", "48000", "96000"}

    def __init__(self, downloader, sample_rate: str, include_video: bool = False, container: str = "mkv"):
        super().__init__(downloader)
        self.sample_rate = str(sample_rate) if str(sample_rate) in self.ALLOWED_RATES else "0"
        self.include_video = bool(include_video)
        self.container = str(container or "mkv")

    def run(self, info):
        if self.sample_rate == "0":
            return [], info
        raw_path = info.get("filepath") or info.get("_filename")
        if not raw_path:
            raise yt_dlp.utils.PostProcessingError("Не удалось определить путь аудиофайла для пересэмплирования")
        source_path = Path(raw_path)
        if not source_path.is_file():
            raise yt_dlp.utils.PostProcessingError(f"Аудиофайл не найден для пересэмплирования: {source_path}")

        ffmpeg = shutil.which("ffmpeg")
        if not ffmpeg:
            local_ffmpeg = APP_DIR / ("ffmpeg.exe" if os.name == "nt" else "ffmpeg")
            if local_ffmpeg.is_file():
                ffmpeg = str(local_ffmpeg)
        if not ffmpeg:
            raise yt_dlp.utils.PostProcessingError("Для изменения частоты дискретизации нужен FFmpeg")

        # Если формат уже имеет нужную частоту, не перекодируем его повторно.
        ffprobe = shutil.which("ffprobe")
        if not ffprobe:
            sibling_probe = Path(ffmpeg).with_name("ffprobe.exe" if os.name == "nt" else "ffprobe")
            if sibling_probe.is_file():
                ffprobe = str(sibling_probe)
        if ffprobe:
            try:
                probe = run_download_command(
                    [ffprobe, "-v", "error", "-select_streams", "a:0", "-show_entries",
                     "stream=sample_rate", "-of", "default=noprint_wrappers=1:nokey=1", str(source_path)],
                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=20,
                )
                if probe.returncode == 0 and probe.stdout.strip() == self.sample_rate:
                    return [], info
            except (OSError, subprocess.SubprocessError):
                pass

        temp_path = source_path.with_name(f"{source_path.stem}.sample-rate.tmp{source_path.suffix}")
        try:
            if self.include_video:
                # Перекодируем только аудио, сохраняя видеопоток без потерь.
                audio_codec = "libopus" if source_path.suffix.lower() == ".webm" else "aac"
                ffmpeg_args = [ffmpeg, "-y", "-i", str(source_path), "-map", "0", "-c:v", "copy",
                               "-c:a", audio_codec, "-ar", self.sample_rate, "-map_metadata", "0"]
            else:
                ffmpeg_args = [ffmpeg, "-y", "-i", str(source_path), "-vn", "-map", "0:a:0",
                               "-ar", self.sample_rate, "-map_metadata", "0"]
            ffmpeg_args.append(str(temp_path))
            result = run_download_command(
                ffmpeg_args,
                stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=600,
            )
            if result.returncode != 0 or not temp_path.is_file() or temp_path.stat().st_size <= 0:
                detail = result.stderr.decode("utf-8", errors="replace")[-600:]
                raise yt_dlp.utils.PostProcessingError(
                    "FFmpeg не смог изменить частоту дискретизации: " + (detail or "пустой выходной файл")
                )
            os.replace(temp_path, source_path)
        except yt_dlp.utils.PostProcessingError:
            raise
        except (OSError, subprocess.SubprocessError) as exc:
            raise yt_dlp.utils.PostProcessingError(f"Не удалось пересэмплировать аудио: {exc}") from exc
        finally:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
        info["filepath"] = str(source_path)
        return [], info


DOWNLOAD_SOURCE_NAMES = {"youtube": "YouTube", "tiktok": "TikTok", "instagram": "Instagram",
                         "spotify": "Spotify", "direct": "Загрузка видео"}


def download_url(text: str, source: str, kind: str = "single") -> str:
    """Validate BEFORE normalization: a foreign host must never become a YouTube handle."""
    value = str(text or "").strip()
    if source not in DOWNLOAD_SOURCE_NAMES:
        raise ValueError(ui_text("Неизвестная площадка загрузки.", "Unknown download source."))
    if source == "youtube" and value and "://" not in value and not any(c in value for c in "/:?#"):
        if kind == "single" and re.fullmatch(r"[A-Za-z0-9_-]{11}", value):
            value = normalize_video(value)
        elif kind == "playlist" and re.fullmatch(r"(?:PL|OL|FL|UU|LL|RD)[A-Za-z0-9_-]{10,}", value):
            value = normalize_playlist(value)
        elif kind == "channel" and (re.fullmatch(r"@[\w.-]+", value) or re.fullmatch(r"[\w-]+", value)):
            value = normalize_channel(value)
    try:
        p = urllib.parse.urlsplit(value)
        host = (p.hostname or "").lower().rstrip(".")
        port = p.port
        if (p.scheme.lower() not in ("http", "https") or not host or p.username is not None
                or p.password is not None or re.search(r"[\s\\\x00-\x1f\x7f]", value)
                or (port is not None and not 1 <= port <= 65535)):
            raise ValueError()
        host.encode("idna")
    except (ValueError, UnicodeError):
        raise ValueError(ui_text("Вставьте корректный адрес http:// или https:// без логина и пароля.",
                                "Enter a valid http:// or https:// URL without a username or password.")) from None
    domains = {"youtube": ("youtube.com", "youtu.be", "youtube-nocookie.com"),
               "tiktok": ("tiktok.com",), "instagram": ("instagram.com",),
               "spotify": ("open.spotify.com", "spotify.com")}
    if source != "direct" and not any(host == d or host.endswith("." + d) for d in domains[source]):
        name = DOWNLOAD_SOURCE_NAMES[source]
        raise ValueError(ui_text(f"Выбран {name}: нужна ссылка именно с {name}. Другая площадка не будет использована.",
                                f"{name} is selected: enter a {name} URL. Another platform will not be used."))
    if source == "spotify" and not spotify_url_kind(value)[0]:
        raise ValueError(ui_text("Нужна полная ссылка open.spotify.com на трек, альбом или плейлист.",
                                "Use a full open.spotify.com track, album or playlist URL."))
    value = urllib.parse.urlunsplit((p.scheme.lower(), p.netloc, p.path, p.query, ""))
    return canonical_youtube_url(value, kind) if source == "youtube" else value


class DownloadSourceError(ValueError):
    """Permanent validation failures must not retry three times."""


def check_direct_video_url(url: str, cookies_file: str = "") -> None:
    """Inspect a bounded response, not a filename: GenericIE accepts arbitrary binary files."""
    class MediaRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            download_url(newurl, "direct")
            return super().redirect_request(req, fp, code, msg, headers, newurl)
    handlers = [MediaRedirect()]
    if cookies_file and Path(cookies_file).is_file():
        jar = http.cookiejar.MozillaCookieJar(cookies_file)
        jar.load(ignore_discard=True, ignore_expires=False)
        handlers.append(urllib.request.HTTPCookieProcessor(jar))
    request = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 NOP", "Accept-Encoding": "identity"})
    with urllib.request.build_opener(*handlers).open(request, timeout=20) as response:
        download_url(response.url, "direct")
        head = response.read(512).lstrip()
    # MIME can lie; reject HTML and common non-media downloads even with a video suffix.
    lower = head.lower()
    forbidden = (b"<!doctype html", b"<html", b"<script", b"<?php", b"mz", b"%pdf", b"pk\x03\x04")
    media_header = (len(head) >= 12 and head[4:8] in (b"ftyp", b"moov", b"mdat", b"wide")) or head.startswith(
        (b"\x1aE\xdf\xa3", b"OggS", b"RIFF", b"FLV", b"ID3", b"fLaC", b"#!AMR",
         b"\x00\x00\x01\xba", b"\x00\x00\x01\xb3", b"\x30\x26\xb2\x75\x8e\x66\xcf\x11"))
    media_header = media_header or (len(head) > 188 and head[0] == head[188] == 0x47)
    media_header = media_header or (len(head) >= 2 and head[0] == 0xff and head[1] & 0xe0 == 0xe0)
    manifest = head.startswith(b"#EXTM3U") or bool(re.search(rb"<(?:[\w.-]+:)?MPD\b", head, re.I))
    if not head or lower.startswith(forbidden) or not (media_header or manifest):
        raise DownloadSourceError(ui_text(
            "Адрес не является поддерживаемым прямым видео или потоком. Скопируйте URL самого видео; страницы, blob: и защищённые ссылки не поддерживаются.",
            "This is not a supported direct video or stream. Copy the video's own URL; pages, blob: and protected links are not supported."))


def audio_bitrate_codec(extension):
    codec = {"mp3": "libmp3lame", "mp2": "mp2", "m4a": "aac", "mp4": "aac", "aac": "aac",
             "opus": "libopus", "webm": "libopus", "ogg": "libvorbis", "oga": "libvorbis",
             "wma": "wmav2", "ac3": "ac3", "eac3": "eac3"}.get(str(extension).lower().lstrip("."))
    if not codec:
        raise ValueError(ui_text("Этот аудиоформат не поддерживает заданный битрейт. Выберите Авто или AAC/MP3/Opus.",
                                 "This audio format does not support a target bitrate. Choose Auto or AAC/MP3/Opus."))
    return codec


def validate_audio_bitrate(codec, rate):
    codec = {"AAC": "aac", "MP3": "libmp3lame", "Opus": "libopus", "FLAC": "flac", "PCM": "pcm_s16le"}.get(codec, codec)
    rate = int(rate)
    bounds = {"aac": (16, 512), "libopus": (6, 510), "libmp3lame": (32, 320),
              "libvorbis": (32, 500), "wmav2": (24, 384), "mp2": (32, 384), "ac3": (32, 640), "eac3": (32, 6144)}
    if codec not in bounds:
        raise ValueError(ui_text("Для общего битрейта выберите управляемый аудиокодек, например AAC или Opus.",
                                 "Select a bitrate-controlled audio codec such as AAC or Opus for a total target."))
    low, high = bounds[codec]
    if not low <= rate <= high:
        raise ValueError(ui_text(f"Битрейт {codec}: допустимо {low}–{high} кбит/с на дорожку.",
                                 f"{codec} bitrate must be {low}–{high} kbit/s per track."))
    if codec == "libmp3lame" and rate not in {32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320}:
        raise ValueError(ui_text("Для MP3 выберите стандартный битрейт: 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256 или 320 кбит/с.",
                                 "Use a standard MP3 bitrate: 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256 or 320 kbit/s."))
    return codec


def total_bitrate_plan(total, *, has_video=True, audio_codec="aac", audio_rate=192, audio_count=1, copied_rates=None):
    total = float(total or 0)
    if not math.isfinite(total) or not 0 <= total <= 500000:
        raise ValueError(ui_text("Общий битрейт должен быть от 0 до 500000 кбит/с.", "Total bitrate must be between 0 and 500000 kbit/s."))
    total = round(total)
    if not total:
        return {}
    count = max(0, int(audio_count))
    if not has_video:
        rate = round(total / max(1, count))
        validate_audio_bitrate(audio_codec, rate)
        return {"total": total, "video": 0, "audio": rate, "audio_sum": rate * max(1, count), "overhead": 0}
    if audio_codec == "copy" and count:
        rates = list(copied_rates or [])
        if len(rates) != count or any(r is None or not math.isfinite(float(r)) or float(r) <= 0 for r in rates):
            raise ValueError(ui_text("Неизвестен битрейт копируемых аудиодорожек. Выберите AAC/Opus, уберите аудио или используйте Авто.",
                                     "Copied audio bitrates are unknown. Choose AAC/Opus, omit audio or use Auto."))
        audio_sum = sum(float(r) for r in rates)
    else:
        if count: validate_audio_bitrate(audio_codec, audio_rate)
        audio_sum = count * int(audio_rate)
    overhead = max(4, round(total * .02))
    video = int(total - overhead - audio_sum)
    if video < 64:
        raise ValueError(ui_text("Общий битрейт слишком мал для выбранных аудиодорожек и видео (минимум 64 кбит/с для видео).",
                                 "Total bitrate is too low for the selected audio tracks and video (video needs at least 64 kbit/s)."))
    return {"total": total, "video": video, "audio": int(audio_rate), "audio_sum": audio_sum, "overhead": overhead}


def target_video_codec(container, requested="any", encoder="CPU", audio_codec="aac"):
    wanted = ("vp9" if container == "webm" else "h264") if requested == "any" else requested
    profiles = {"mp4": {"h264", "vp9", "av1"}, "mkv": {"h264", "vp9", "av1"},
                "webm": {"vp9", "av1"}, "mov": {"h264"}, "avi": {"h264"},
                "m4v": {"h264"}, "flv": {"h264"}, "ts": {"h264"}, "m2ts": {"h264"}}
    if container not in profiles or wanted not in profiles[container]:
        raise ValueError(ui_text("Для этого формата/кодека нет профиля общего битрейта. Выберите MP4/MKV/WebM или Авто.",
                                 "No total-bitrate profile is available for this format/codec. Choose MP4/MKV/WebM or Auto."))
    if container == "webm" and (wanted not in {"vp9", "av1"} or audio_codec not in {"libopus", "libvorbis", "copy"}):
        raise ValueError(ui_text("WebM требует VP9/AV1 и Opus/Vorbis. Выберите совместимые кодеки.",
                                 "WebM requires VP9/AV1 and Opus/Vorbis. Select compatible codecs."))
    if container in {"mp4", "mov"} and audio_codec not in {"aac", "libmp3lame", "pcm_s16le", "copy"}:
        raise ValueError(ui_text("Для MP4/MOV выберите AAC, MP3 или совместимую исходную дорожку.",
                                 "For MP4/MOV choose AAC, MP3 or a compatible copied track."))
    if container == "mp4" and audio_codec == "pcm_s16le":
        raise ValueError(ui_text("PCM не поддерживается этим профилем MP4; выберите AAC или MOV/MKV.",
                                 "This MP4 profile does not support PCM; choose AAC or MOV/MKV."))
    if wanted not in {"h264", "vp9", "av1"} or (container in {"avi", "mov"} and wanted != "h264"):
        raise ValueError(ui_text("Видеокодек несовместим с выбранным профилем контейнера.", "The video codec is incompatible with this container profile."))
    if encoder != "CPU":
        if wanted != "h264":
            raise ValueError(ui_text("Для этого кодека выберите CPU; перечисленные GPU-профили кодируют H.264.",
                                     "Choose CPU for this codec; the listed GPU profiles encode H.264."))
        return {"NVIDIA NVENC": "h264_nvenc", "Intel Quick Sync": "h264_qsv", "AMD AMF": "h264_amf"}.get(encoder, "libx264")
    return {"h264": "libx264", "vp9": "libvpx-vp9", "av1": "libaom-av1"}[wanted]


class TotalBitrateControl(QWidget):
    changed = pyqtSignal()

    def __init__(self, value=0, unit="kbps"):
        super().__init__()
        self.setObjectName("clear")
        self.amount = WheelSafeDoubleSpinBox()
        self.amount.setObjectName("totalBitrateAmount")
        self.amount.setMinimumWidth(0)
        self.amount.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.amount.setRange(0, 500000)
        self.amount.setDecimals(0)
        self.units = WheelSafeComboBox()
        self.units.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)
        self.units.addItem("кбит/с", "kbps")
        self.units.addItem("Мбит/с", "mbps")
        self._factor = 1
        self.amount.setValue(float(value or 0))
        self.units.currentIndexChanged.connect(self._change_unit)
        self.amount.valueChanged.connect(lambda _value: self.changed.emit())
        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        layout.addWidget(self.amount, 1)
        layout.addWidget(self.units)
        self.units.setCurrentIndex(max(0, self.units.findData(unit)))
        self.refresh_text()

    def kbps(self):
        return round(self.amount.value() * self._factor)

    def _change_unit(self):
        value = self.kbps()
        self._factor = 1000 if self.units.currentData() == "mbps" else 1
        blocked = self.amount.blockSignals(True)
        self.amount.setDecimals(3 if self._factor == 1000 else 0)
        self.amount.setRange(0, 500000 / self._factor)
        self.amount.setValue(value / self._factor)
        self.amount.blockSignals(blocked)
        self.changed.emit()

    def refresh_text(self):
        self.amount.setLocale(QLocale("en_US" if LANG == "en" else "ru_RU"))
        self.amount.setSpecialValueText(T("Авто"))
        self.units.setItemText(0, T("кбит/с"))
        self.units.setItemText(1, T("Мбит/с"))
        self.setToolTip(ui_text("Целевой средний битрейт. Авто сохраняет обычные настройки. Размер и битрейт контейнера приблизительны.",
                               "Target average bitrate. Auto keeps the usual settings. Container size and bitrate are approximate."))


def video_profile(value):
    """Migrate old resolution keys without interpreting them as bitrate targets."""
    value = str(value or 'min').lower()
    if value in {'min', 'mid', 'max'}: return value
    try:
        height = int(value)
        return 'min' if height <= 480 else 'mid' if height <= 1080 else 'max'
    except ValueError:
        return 'min'


def format_number(value):
    try:
        value = float(value)
        return value if math.isfinite(value) and 0 < value <= 10**18 else None
    except (TypeError, ValueError, OverflowError):
        return None


def codec_family(value):
    value = str(value or '').lower()
    for prefixes, family in ((('avc', 'h264'), 'h264'), (('vp09', 'vp9'), 'vp9'), (('av01', 'av1'), 'av1'),
                             (('hev', 'hvc', 'hevc', 'h265'), 'hevc'), (('mp4v', 'mpeg4'), 'mpeg4'),
                             (('mp4a', 'aac'), 'aac'), (('opus',), 'opus'), (('vorbis',), 'vorbis'),
                             (('mp3',), 'mp3'), (('alac',), 'alac'), (('flac',), 'flac'),
                             (('pcm',), 'pcm'), (('vp8',), 'vp8'), (('eac3',), 'eac3'), (('ac3',), 'ac3')):
        if value.startswith(prefixes): return family
    return value.split('.')[0] or 'unknown'


def source_rate(fmt, stream, duration=None):
    rate = format_number(fmt.get('vbr' if stream == 'video' else 'abr'))
    if rate is not None: return rate
    total = format_number(fmt.get('tbr'))
    other = 'acodec' if stream == 'video' else 'vcodec'
    if total and fmt.get(other) == 'none': return total
    other_rate = format_number(fmt.get('abr' if stream == 'video' else 'vbr'))
    if total and other_rate and total > other_rate: return total - other_rate
    size = format_number(fmt.get('filesize')) or format_number(fmt.get('filesize_approx'))
    if size and duration and fmt.get(other) == 'none': return size * 8 / duration / 1000
    return None


def source_container(requested, video, audio):
    v, a = codec_family((video or {}).get('vcodec')), codec_family((audio or {}).get('acodec'))
    if requested == 'mkv': return 'mkv'
    if video and requested == video.get('ext') and (audio is None or audio is video):
        return requested  # The existing resource already proves this container can carry its streams.
    compatible = {
        'webm': ({'vp8','vp9','av1'}, {'opus','vorbis'}),
        'mp4': ({'h264','hevc','av1','vp9','mpeg4'}, {'aac','mp3','alac','ac3','eac3','opus'}),
        'avi': ({'h264','mpeg4','mpeg2video','mpeg1video','msmpeg4v3','wmv1','wmv2'}, {'mp3','pcm','ac3'}),
        'm4v': ({'h264','mpeg4'}, {'aac','alac'}),
        'mov': ({'h264','hevc','mpeg4'}, {'aac','mp3','alac','ac3','eac3','pcm'}),
        'ts': ({'h264','hevc','mpeg2video','mpeg1video'}, {'aac','mp3','ac3','eac3'}),
        'flv': ({'h264'}, {'aac','mp3'}),
    }
    videos, audios = compatible.get(requested, (set(), set()))
    return requested if (video is None or v in videos) and (audio is None or a in audios) else 'mkv'


def video_resolution(value):
    """Zero means Auto; positive values are the desired shorter side in pixels."""
    try:
        value = int(value)
        return value if 0 < value <= 100000 else 0
    except (TypeError, ValueError, OverflowError):
        return 0


RESOLUTION_STEPS = (4320, 2160, 1440, 1080, 720, 480, 360, 240, 144)
DL_CONTAINERS = (("mkv", "MKV"), ("mp4", "MP4"), ("m4v", "M4V"), ("mov", "MOV"), ("webm", "WebM"),
                 ("avi", "AVI"), ("ts", "TS (MPEG-TS)"), ("flv", "FLV"))
DL_VCODECS = (("any", "Любой / лучший"), ("h264", "H.264 / AVC"), ("hevc", "H.265 / HEVC"), ("vp9", "VP9"),
              ("av1", "AV1"), ("vp8", "VP8"), ("mpeg4", "MPEG-4 Part 2"), ("mpeg2video", "MPEG-2"))


def resolution_choice(value, profile='min'):
    """'max'/'mid'/'min' или высота короткой стороны; старое 0/«авто» берёт прежний профиль."""
    text = str(value if value is not None else '').strip().lower()
    if text in {'min', 'mid', 'max'}: return text
    return video_resolution(text) or video_profile(profile)


def fps_choice(value, fallback='max'):
    """'max'/'mid'/'min' или число кадров/с; без значения - по прежнему профилю."""
    text = str(value if value is not None else '').strip().lower()
    if text in {'min', 'mid', 'max'}: return text
    number = format_number(text)
    if number and number <= 1000: return number
    return video_profile(fallback)


def source_resolution(fmt):
    w, h = format_number(fmt.get('width')), format_number(fmt.get('height'))
    return min(w, h) if w and h else h or w


def available_video_resolutions(formats):
    return sorted({int(source_resolution(f)) for f in formats if isinstance(f, dict) and f.get('url')
        and not f.get('has_drm') and f.get('vcodec') not in {'none', 'images', 'storyboard'}
        and f.get('ext') not in {'mhtml', 'html', 'jpg', 'png'} and source_resolution(f)
        and source_resolution(f) <= 100000})


def select_source_formats(formats, profile='mid', mode='both', audio_quality='best', codec='any', container='mkv', duration=None, resolution='auto', bitrate_mode='auto', bitrate_kbps=0, fps_preference=None):
    """Pure per-item selection; never invent a format or allocate an encoding budget.

    yt-dlp provides formats in ascending source preference order. Resolution
    tiers use the shorter side (including portrait). Middle means the upper
    median available tier; ties use actual FPS, codec and reported stream rate.
    """
    duration = format_number(duration)
    formats = [f for f in formats if isinstance(f, dict) and f.get('url') and not f.get('has_drm')
               and f.get('vcodec') not in {'images', 'storyboard'} and f.get('ext') not in {'mhtml','html','jpg','png'}]
    if not formats: raise DownloadSourceError(ui_text('Нет доступных незашифрованных форматов.', 'No available unencrypted formats.'))
    position = {id(f): i for i, f in enumerate(formats)}
    profile = video_profile(profile)
    warnings = []
    videos = [f for f in formats if f.get('vcodec') != 'none']
    audio = [f for f in formats if f.get('acodec') != 'none']
    pure_audio = [f for f in audio if f.get('vcodec') == 'none']
    audio_pool = pure_audio or audio
    chosen_audio = None
    if mode != 'video' and audio_pool:
        if audio_quality not in {'best','min'}:
            limit = format_number(audio_quality)
            lower = [f for f in audio_pool if limit and source_rate(f,'audio',duration) and source_rate(f,'audio',duration) <= limit]
            if lower: audio_pool = lower
            else: warnings.append('audio_quality')
        def audio_rank(f):
            # Source preference preserves extractor language/codec decisions.
            # For combined-only sources prefer measured audio rate, not video size.
            rate = source_rate(f, 'audio', duration)
            return (rate or 0, position[id(f)]) if not pure_audio else (position[id(f)],)
        if audio_quality == 'min' or 'audio_quality' in warnings:
            known = [f for f in audio_pool if source_rate(f,'audio',duration)]
            chosen_audio = min(known, key=lambda f:(source_rate(f,'audio',duration), -position[id(f)])) if known else audio_pool[0]
        else: chosen_audio = max(audio_pool, key=audio_rank)
    elif mode == 'both': warnings.append('no_audio')
    chosen_video = None
    bitrate_mode, wanted_kbps = (bitrate_mode if mode != 'audio' else 'auto'), None
    requested_resolution = video_resolution(resolution) if mode != 'audio' else 0
    if mode != 'audio':
        if not videos: raise DownloadSourceError(ui_text('Источник не содержит видеопотока.', 'This source contains no video stream.'))
        # Explicit detail takes precedence; profile then chooses FPS/codec/rate
        # within that tier. Keep the historical Auto/codec selection unchanged.
        if requested_resolution:
            tiers = available_video_resolutions(videos)
            if tiers:
                target = min(tiers, key=lambda value: (abs(value-requested_resolution), value))
                videos = [f for f in videos if source_resolution(f) == target]
                if target != requested_resolution: warnings.append('resolution')
            else: warnings.append('resolution')
        if codec != 'any':
            matching = [f for f in videos if codec_family(f.get('vcodec')) == codec]
            if matching: videos = matching
            else: warnings.append('codec')
        known = [f for f in videos if source_resolution(f)]
        tiers = sorted({source_resolution(f) for f in known})
        if tiers:
            target = tiers[0] if profile == 'min' else tiers[-1] if profile == 'max' else tiers[len(tiers)//2]
            videos = [f for f in known if source_resolution(f) == target]
            if len(tiers) < 3 and not requested_resolution: warnings.append('few_tiers')
        else: warnings.append('unknown_resolution')
        fps_values = sorted({format_number(f.get('fps')) for f in videos if format_number(f.get('fps'))})
        if fps_values:
            wanted_fps = fps_choice(fps_preference, profile)
            if isinstance(wanted_fps, str):
                fps = fps_values[0] if wanted_fps == 'min' else fps_values[-1] if wanted_fps == 'max' else fps_values[(len(fps_values)-1)//2]
            else:
                fps = min(fps_values, key=lambda value: (abs(value - wanted_fps), -value))
            videos = [f for f in videos if format_number(f.get('fps')) == fps]
        efficiency = {'av1':5,'vp9':4,'hevc':4,'h264':3,'vp8':2,'mpeg4':1}
        # Total bitrate setting = video stream rate + chosen audio rate. It only ranks candidates left by
        # resolution, FPS and codec. Nothing is re-encoded: a real source stream is chosen.
        bitrate_mode = bitrate_mode if bitrate_mode in {'max', 'mid', 'min', 'manual'} else 'auto'
        wanted_kbps = format_number(bitrate_kbps) if bitrate_mode == 'manual' else None
        if bitrate_mode == 'manual' and not wanted_kbps: bitrate_mode = 'auto'
        measured = [f for f in videos if source_rate(f, 'video', duration)] if bitrate_mode != 'auto' else []
        if bitrate_mode != 'auto' and not measured:
            warnings.append('bitrate_unknown')  # source reports no video bitrate: usual profile selection
        audio_part = 0.0
        if mode == 'both' and chosen_audio is not None:
            audio_part = source_rate(chosen_audio, 'audio', duration) or 0.0
            if bitrate_mode != 'auto' and not audio_part: warnings.append('bitrate_audio_unknown')
        if measured:
            def vrate(f): return source_rate(f, 'video', duration) + audio_part  # общий битрейт кандидата
            rates = sorted({vrate(f) for f in measured})
            if bitrate_mode == 'max': goal = rates[-1]
            elif bitrate_mode == 'min': goal = rates[0]
            elif bitrate_mode == 'mid':
                middle = (rates[0] + rates[-1]) / 2
                goal = min(rates, key=lambda value: (abs(value - middle), -value))
            else:
                goal = min(rates, key=lambda value: (abs(value - wanted_kbps), value))
            pool = [f for f in measured if vrate(f) == goal]
            chosen_video = max(pool, key=lambda f: (efficiency.get(codec_family(f.get('vcodec')), 0), position[id(f)]))
            if bitrate_mode == 'manual' and abs(goal - wanted_kbps) > max(1.0, wanted_kbps * .02):
                warnings.append('bitrate_closest')
            if len(rates) == 1 and bitrate_mode in {'max', 'mid', 'min'}: warnings.append('bitrate_single')
        elif profile == 'min':
            chosen_video = min(videos, key=lambda f:(source_rate(f,'video',duration) is None,
                source_rate(f,'video',duration) or float('inf'), -efficiency.get(codec_family(f.get('vcodec')),0), -position[id(f)]))
        else:
            best_codec = max(efficiency.get(codec_family(f.get('vcodec')),0) for f in videos)
            videos = [f for f in videos if efficiency.get(codec_family(f.get('vcodec')),0) == best_codec]
            rates = sorted({source_rate(f,'video',duration) for f in videos if source_rate(f,'video',duration)})
            if rates:
                rate = rates[-1] if profile == 'max' else rates[len(rates)//2]
                videos = [f for f in videos if source_rate(f,'video',duration) == rate]
            chosen_video = max(videos, key=lambda f:position[id(f)])
    if mode == 'audio' and chosen_audio is None:
        raise DownloadSourceError(ui_text('Источник не содержит аудиопотока.', 'This source contains no audio stream.'))
    selected = []
    if chosen_video is not None: selected.append(chosen_video)
    if chosen_audio is not None and chosen_audio is not chosen_video: selected.append(chosen_audio)
    if chosen_audio is not None and chosen_audio.get('vcodec') != 'none' and chosen_audio is not chosen_video:
        warnings.append('combined_audio')
    if mode == 'audio':
        family = codec_family(chosen_audio.get('acodec'))
        extension = chosen_audio.get('ext') if chosen_audio.get('vcodec') == 'none' else {
            'aac':'m4a','opus':'opus','vorbis':'ogg','mp3':'mp3','flac':'flac','alac':'m4a','pcm':'wav'}.get(family,'mka')
    else:
        extension = source_container(container, chosen_video, chosen_audio)
        if extension != container: warnings.append('container')
    vr = source_rate(chosen_video,'video',duration) if chosen_video else None
    ar = source_rate(chosen_audio,'audio',duration) if chosen_audio else None
    size = None
    if len(selected)==1 and (mode=='both' or selected[0].get('acodec' if mode=='video' else 'vcodec')=='none'):
        size = format_number(selected[0].get('filesize')) or format_number(selected[0].get('filesize_approx'))
    if size is None and all(f.get('vcodec')=='none' or f.get('acodec')=='none' for f in selected):
        sizes = [format_number(f.get('filesize')) or format_number(f.get('filesize_approx')) for f in selected]
        if all(sizes): size = sum(sizes)
    if size is None and duration and (chosen_video is None or vr) and (chosen_audio is None or ar):
        size = duration * ((vr or 0)+(ar or 0)) * 1000 / 8
    summary = {'profile':profile if mode!='audio' else None, 'width':chosen_video.get('width') if chosen_video else None,
        'height':chosen_video.get('height') if chosen_video else None, 'fps':chosen_video.get('fps') if chosen_video else None,
        'video_codec':str((chosen_video or {}).get('vcodec') or '')[:60], 'audio_codec':str((chosen_audio or {}).get('acodec') or '')[:60],
        'video_kbps':vr, 'audio_kbps':ar, 'size':size, 'container':extension, 'requested_container':container,
        'requested_codec':codec, 'warnings':warnings, 'format_ids':[str(f.get('format_id',''))[:120] for f in selected],
        'format_count':len(formats), 'duration':duration, 'requested_resolution':requested_resolution,
        'bitrate_mode':bitrate_mode if mode != 'audio' else 'auto', 'requested_total_kbps':wanted_kbps if mode != 'audio' else None,
        'total_kbps':(vr + (ar or 0)) if vr else None,
        'available_resolutions':available_video_resolutions(formats) if mode!='audio' else []}
    if len(selected)==1:
        result = dict(selected[0])
    else:
        video_copy, audio_copy = dict(chosen_video), dict(chosen_audio)
        # Download combined resources if necessary, but map only the intended
        # stream from each. Never let yt-dlp keep the lower-quality embedded audio.
        video_copy.update(acodec='none', abr=0)
        audio_copy.update(vcodec='none', vbr=0)
        parts = [video_copy, audio_copy]
        result = {'requested_formats':parts, 'format_id':'+'.join(str(f['format_id']) for f in parts),
            'ext':extension, 'protocol':'+'.join(yt_dlp.utils.determine_protocol(f) for f in parts),
            'vcodec':chosen_video.get('vcodec'), 'acodec':chosen_audio.get('acodec'),
            'width':chosen_video.get('width'), 'height':chosen_video.get('height'), 'fps':chosen_video.get('fps'),
            'vbr':vr,'abr':ar,'tbr':(vr+ar if vr and ar else None), 'filesize_approx':size}
    return result, summary, selected


def describe_source_selection(selection):
    lines = []
    clip = selection.get("clip")
    if clip:
        lines.append(ui_text("Фрагмент: ", "Clip: ") + format_clip_time(clip[0]) + " – " +
                     (format_clip_time(clip[1]) if clip[1] is not None else ui_text("до конца", "to the end")))
    profile = selection.get("profile")
    if profile:
        title = {"min":("Минимальное","Minimum"), "mid":("Среднее","Medium"), "max":("Максимальное","Maximum")}.get(profile,(profile,profile)) if not selection.get("requested_resolution") else None
        w, h = format_number(selection.get("width")), format_number(selection.get("height"))
        resolution = f"{w:g}×{h:g}" if w and h else f"{h:g}p" if h else ui_text("разрешение неизвестно", "resolution unknown")
        fps = format_number(selection.get("fps"))
        raw_codec = selection.get("video_codec") or "?"
        codec = {"h264":"H.264", "hevc":"H.265", "av1":"AV1", "vp9":"VP9", "vp8":"VP8", "mpeg4":"MPEG-4"}.get(codec_family(raw_codec), str(raw_codec)[:20])
        lines.append((ui_text(*title)+" · " if title else "")+resolution+(f" · {fps:g} FPS" if fps else "")+" · "+codec)
    rates = []
    for key, ru, en in (("video_kbps","Видео","Video"),("audio_kbps","Звук","Audio")):
        rate = format_number(selection.get(key))
        if key=="video_kbps" and not profile: continue
        rates.append(ui_text(ru,en)+": "+(f"~{rate:.0f} "+ui_text("кбит/с", "kbps") if rate else ui_text("неизвестно","unknown")))
    lines.append(" · ".join(rates))
    size = format_number(selection.get("size"))
    lines.append((ui_text("Размер ≈ ", "Size ≈ ")+QLocale("ru_RU" if LANG=="ru" else "en_US").formattedDataSize(round(size)) if size else ui_text("Размер неизвестен", "Size unknown"))+" · "+str(selection.get("container") or "").upper())
    notes = {
        "codec":("Выбранного кодека нет: ближайший исходный поток.", "Requested codec unavailable: closest source stream."),
        "few_tiers":("У источника меньше трёх уровней: выбран ближайший.", "Fewer than three tiers: closest available quality selected."),
        "unknown_resolution":("Источник не сообщил разрешение.", "The source did not report resolution."),
        "audio_quality":("Заданного качества аудио нет: ближайшее доступное.", "Requested audio quality unavailable: closest available selected."),
        "no_audio":("Звук у источника не найден.", "No source audio stream found."),
        "combined_audio":("Для лучшего звука нужен отдельный совмещённый источник.", "Best audio requires an additional combined source."),
        "container":("Для копирования кодеков выбран MKV вместо ", "MKV preserves codecs instead of "),
        "unavailable":("Поток недоступен: проверен и выбран другой.", "A stream was unavailable: another was checked and selected.")}
    bitrate_title = {"max":("Максимум","Maximum"), "mid":("Среднее","Medium"), "min":("Минимум","Minimum"),
                     "manual":("Вручную","Manual")}.get(selection.get("bitrate_mode"))
    if bitrate_title and selection.get("profile"):
        actual = format_number(selection.get("total_kbps"))
        line = ui_text("Общий битрейт: ", "Total bitrate: ") + ui_text(*bitrate_title)
        if selection.get("bitrate_mode") == "manual" and selection.get("requested_total_kbps"):
            line += ui_text(" · запрошено ", " · requested ") + format_bitrate_kbps(selection["requested_total_kbps"])
        if actual and "bitrate_unknown" not in selection.get("warnings", []):
            line += ui_text(" · фактически ", " · actual ") + "~" + format_bitrate_kbps(actual)
        lines.append(line)
    bitrate_notes = {
        "bitrate_unknown": ("Источник не сообщил битрейт видеопотоков: выбор выполнен по разрешению и FPS.",
                            "The source does not report video stream bitrates: selected by resolution and FPS."),
        "bitrate_audio_unknown": ("Битрейт звука неизвестен: общий битрейт посчитан только по видео.",
                                  "Audio bitrate is unknown: the total was calculated from video only."),
        "bitrate_closest": ("Точного общего битрейта у источника нет: выбран ближайший доступный вариант (значение указано выше). Заданный битрейт не гарантируется.",
                            "The source has no option at that exact total bitrate: the closest available one was selected (see actual value above). The requested bitrate is not guaranteed."),
        "bitrate_single": ("Среди подходящих потоков доступен один общий битрейт.",
                           "Only one total bitrate is available among the matching streams."),
    }
    for key in selection.get("warnings", []):
        if key in bitrate_notes:
            lines.append(ui_text(*bitrate_notes[key]))
    if 'resolution' in selection.get('warnings', []):
        requested = selection.get('requested_resolution')
        lines.append(ui_text(f"Разрешение {requested}p недоступно: выбран ближайший исходный поток.",
                             f"Resolution {requested}p unavailable: closest source stream selected."))
    for key in selection.get("warnings",[]):
        if key in notes:
            lines.append(ui_text(*notes[key])+(str(selection.get("requested_container","")).upper() if key=="container" else ""))
    return lines


# ---------- фрагмент видео: время ЧЧ:ММ:СС ----------
def _group_digits_right(digits: str) -> str:
    parts = []
    while digits:
        parts.append(digits[-2:])
        digits = digits[:-2]
    return ":".join(reversed(parts))


def clip_time_live(text) -> str:
    """Маска при вводе: цифры группируются справа налево как Ч:ММ:СС (123456 -> 12:34:56).

    Двоеточия, которые пользователь поставил сам (например «1:2»), сохраняются до завершения ввода."""
    raw = str(text or "")
    for separator in ("：", ".", ",", ";"):
        raw = raw.replace(separator, ":")
    cleaned = re.sub(r"[^\d:]", "", raw)
    digits = cleaned.replace(":", "")[:6]
    auto = _group_digits_right(digits)
    if ":" in cleaned and cleaned != auto:
        groups = cleaned.split(":")
        if len(groups) <= 3 and all(len(group) <= 2 for group in groups):
            return cleaned
    return auto


def parse_clip_time(text):
    """Секунды из текста времени; None - поле пустое. Неполное время («1:5», «12:34») допускается."""
    value = clip_time_live(text).strip(":")
    if not value:
        return None
    groups = value.split(":")
    if len(groups) > 3 or any(not group.isdigit() for group in groups):
        raise ValueError(ui_text("Время нужно вводить в формате ЧЧ:ММ:СС.", "Enter time as HH:MM:SS."))
    numbers = [int(group) for group in groups]
    seconds = numbers[-1]
    minutes = numbers[-2] if len(numbers) >= 2 else 0
    hours = numbers[-3] if len(numbers) == 3 else 0
    if seconds > 59:
        raise ValueError(ui_text("Секунды должны быть от 00 до 59 (для 90 секунд введите 01:30).",
                                 "Seconds must be 00–59 (enter 01:30 for 90 seconds)."))
    if minutes > 59:
        raise ValueError(ui_text("Минуты должны быть от 00 до 59.", "Minutes must be 00–59."))
    return float(hours * 3600 + minutes * 60 + seconds)


def format_clip_time(seconds) -> str:
    seconds = max(0, int(seconds))
    return f"{seconds // 3600:02d}:{seconds // 60 % 60:02d}:{seconds % 60:02d}"


def canonical_clip_text(text) -> str:
    """Законченное значение поля: «1:30» -> «00:01:30». Пустое поле остаётся пустым."""
    seconds = parse_clip_time(text)
    return "" if seconds is None else format_clip_time(seconds)


def clip_range(start_text, end_text, duration=None):
    """(начало, конец|None) в секундах или None для целого видео. ValueError - некорректный диапазон."""
    start, end = parse_clip_time(start_text), parse_clip_time(end_text)
    if start is None and end is None:
        return None
    start = start or 0.0
    if end is not None and end <= start:
        raise ValueError(ui_text("Конец фрагмента должен быть позже начала.", "The clip end must be later than its start."))
    total = format_number(duration)
    if total:
        if start >= total:
            raise ValueError(ui_text(f"Начало ({format_clip_time(start)}) не меньше длительности видео ({format_clip_time(total)}).",
                                     f"The start ({format_clip_time(start)}) is not before the video duration ({format_clip_time(total)})."))
        if end is not None and end > total + 1:
            raise ValueError(ui_text(f"Конец ({format_clip_time(end)}) выходит за длительность видео ({format_clip_time(total)}).",
                                     f"The end ({format_clip_time(end)}) is beyond the video duration ({format_clip_time(total)})."))
    if start == 0 and (end is None or (total and end >= total - 1)):
        return None  # весь ролик: обычная загрузка без FFmpeg-вырезки
    return float(start), None if end is None else float(end)


def clip_tag(clip) -> str:
    if not clip:
        return ""
    def digits(value):
        return f"{int(value) // 3600:02d}{int(value) // 60 % 60:02d}{int(value) % 60:02d}"
    return "cut" + digits(clip[0]) + "-" + (digits(clip[1]) if clip[1] is not None else "end")


class ClipTimeEdit(QLineEdit):
    """Поле времени ЧЧ:ММ:СС с автоматической расстановкой двоеточий."""
    def __init__(self, placeholder="00:00:00"):
        super().__init__()
        self.setMaxLength(8)
        self.setPlaceholderText(placeholder)
        self.setClearButtonEnabled(True)
        self._previous = ""
        self.textEdited.connect(self._mask)
        self.editingFinished.connect(self._finish)

    def _mask(self, text):
        cursor = self.cursorPosition()
        right_digits = sum(ch.isdigit() for ch in text[cursor:])
        formatted = clip_time_live(text)
        if len(text) < len(self._previous):  # при удалении всегда пересчитываем маску по цифрам
            formatted = _group_digits_right(re.sub(r"\D", "", text)[:6])
        self._previous = formatted
        if formatted != text:
            blocked = self.blockSignals(True)
            self.setText(formatted)
            self.blockSignals(blocked)
            position, seen = len(formatted), 0
            for index in range(len(formatted), -1, -1):
                if seen == right_digits:
                    position = index
                    break
                if index > 0 and formatted[index - 1].isdigit():
                    seen += 1
            self.setCursorPosition(position)
            self.textChanged.emit(formatted)

    def _finish(self):
        try:
            canonical = canonical_clip_text(self.text())
        except ValueError:
            return  # ошибка показывается в строке требований; введённое не стираем
        if canonical != self.text():
            self.setText(canonical)


# ---------- битрейт видео ----------
VIDEO_BITRATE_MODES = [("auto", "Авто"), ("max", "Максимум"), ("mid", "Среднее"),
                       ("min", "Минимум"), ("manual", "Вручную")]
VIDEO_BITRATE_LIMITS = (32, 200000)  # кбит/с


def parse_video_bitrate(text, unit="kbps"):
    """«2500», «2,5 Мбит/с», «8 Mbps» -> (кбит/с, единица). Единицу из текста можно не указывать."""
    raw = str(text or "").strip().lower().replace("\u00a0", " ")
    if not raw:
        raise ValueError(ui_text("Укажите общий битрейт.", "Enter the total bitrate."))
    match = re.fullmatch(r"(\d+(?:[.,]\d+)?)\s*([a-zа-яё/.]*)", raw)
    if not match:
        raise ValueError(ui_text("Введите число, например 2500 или 2,5.", "Enter a number such as 2500 or 2.5."))
    suffix = match.group(2)
    if suffix:
        if suffix[0] in ("m", "м"):
            unit = "mbps"
        elif suffix[0] in ("k", "к"):
            unit = "kbps"
        else:
            raise ValueError(ui_text("Единица: Кбит/с или Мбит/с.", "Unit must be kbit/s or Mbit/s."))
    value = float(match.group(1).replace(",", "."))
    kbps = value * (1000 if unit == "mbps" else 1)
    low, high = VIDEO_BITRATE_LIMITS
    if not math.isfinite(kbps) or not low <= kbps <= high:
        raise ValueError(ui_text(f"Общий битрейт: от {low} Кбит/с до {high // 1000} Мбит/с.",
                                 f"Total bitrate must be {low} kbit/s to {high // 1000} Mbit/s."))
    return int(round(kbps)), unit


def format_bitrate_kbps(kbps) -> str:
    """Человекочитаемый битрейт для сообщений: 2500 кбит/с, 8 Мбит/с."""
    kbps = float(kbps)
    if kbps >= 10000:
        text = f"{kbps / 1000:.1f}".rstrip("0").rstrip(".")
        return text.replace(".", "," if LANG == "ru" else ".") + " " + ui_text("Мбит/с", "Mbit/s")
    return f"{kbps:.0f} " + ui_text("кбит/с", "kbit/s")


class VideoBitrateInput(QWidget):
    """Число + единица (Кбит/с / Мбит/с) с автоматической конвертацией при смене единицы."""
    changed = pyqtSignal()

    def __init__(self, kbps=0, unit="kbps"):
        super().__init__()
        self.setObjectName("clear")
        self.edit = QLineEdit()
        self.edit.setPlaceholderText("2500")
        self.edit.setMinimumWidth(60)
        self.units = WheelSafeComboBox()
        self.units.addItem("кбит/с", "kbps")
        self.units.addItem("Мбит/с", "mbps")
        self.units.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)
        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        layout.addWidget(self.edit, 1)
        layout.addWidget(self.units)
        self._unit = unit if unit in ("kbps", "mbps") else "kbps"
        self.units.setCurrentIndex(max(0, self.units.findData(self._unit)))
        self.set_kbps(kbps, self._unit)
        self.edit.textChanged.connect(self._text_changed)
        self.units.currentIndexChanged.connect(self._unit_changed)

    def _display(self, kbps, unit):
        if not kbps:
            return ""
        if unit == "mbps":
            text = f"{kbps / 1000:.3f}".rstrip("0").rstrip(".")
            return text.replace(".", "," if LANG == "ru" else ".")
        return str(int(round(kbps)))

    def set_kbps(self, kbps, unit=None):
        unit = unit or self.units.currentData()
        blocked = self.units.blockSignals(True)
        self.units.setCurrentIndex(max(0, self.units.findData(unit)))
        self.units.blockSignals(blocked)
        self._unit = unit
        blocked = self.edit.blockSignals(True)
        self.edit.setText(self._display(float(kbps or 0), unit))
        self.edit.blockSignals(blocked)

    def _text_changed(self, _text):
        try:  # единица, набранная вручную («2,5 Мбит/с»), переключает список
            kbps, unit = parse_video_bitrate(self.edit.text(), self.units.currentData())
            if unit != self.units.currentData():
                self.set_kbps(kbps, unit)
        except ValueError:
            pass
        self.changed.emit()

    def _unit_changed(self, _index):
        try:
            kbps, _unit = parse_video_bitrate(self.edit.text(), self._unit)
        except ValueError:
            kbps = 0
        self._unit = self.units.currentData()
        if kbps:
            self.set_kbps(kbps, self._unit)  # 2500 Кбит/с -> 2,5 Мбит/с и обратно
        self.changed.emit()

    def kbps(self):
        try:
            return parse_video_bitrate(self.edit.text(), self.units.currentData())[0]
        except ValueError:
            return 0

    def error(self) -> str:
        try:
            parse_video_bitrate(self.edit.text(), self.units.currentData())
        except ValueError as exc:
            return str(exc)
        return ""

    def refresh_text(self):
        self.units.setItemText(0, T("кбит/с"))
        self.units.setItemText(1, T("Мбит/с"))
        kbps = self.kbps()
        if kbps:
            self.set_kbps(kbps, self.units.currentData())


# ---------- cookies из браузера (штатный cookiesfrombrowser yt-dlp) ----------
COOKIE_BROWSER_NAMES = {
    "chrome": "Google Chrome", "edge": "Microsoft Edge", "firefox": "Mozilla Firefox", "opera": "Opera",
    "brave": "Brave", "vivaldi": "Vivaldi", "chromium": "Chromium", "whale": "Naver Whale", "safari": "Safari",
}


def cookie_browser_choices():
    """[(ключ, название)] браузеров, которые поддерживает установленная версия yt-dlp."""
    try:
        from yt_dlp.cookies import SUPPORTED_BROWSERS
        supported = set(SUPPORTED_BROWSERS)
    except Exception:  # noqa: BLE001
        supported = {"chrome", "edge", "firefox", "opera", "brave", "vivaldi"}
    if sys.platform != "darwin":
        supported.discard("safari")  # Safari поддерживается yt-dlp только в macOS
    preferred = [key for key in ("chrome", "edge", "firefox", "opera", "brave", "vivaldi") if key in supported]
    others = sorted(supported - set(preferred))
    return [(key, COOKIE_BROWSER_NAMES.get(key, key.capitalize())) for key in preferred + others]


def browser_cookies_error(exc, browser) -> str:
    name = COOKIE_BROWSER_NAMES.get(browser, str(browser))
    text = str(exc)
    low = text.lower()
    if isinstance(exc, PermissionError) or any(word in low for word in (
            "could not copy", "cannot copy", "database is locked", "permission", "being used by another process")):
        return ui_text(
            f"Не удалось прочитать cookies браузера {name}: база данных занята. Полностью закройте {name} "
            f"(включая фоновые процессы) и повторите, либо выберите другой браузер или файл cookies.txt.",
            f"Could not read {name} cookies: the cookie database is locked. Fully close {name} "
            f"(including background processes) and try again, or choose another browser or a cookies.txt file.")
    if isinstance(exc, FileNotFoundError) or "could not find" in low or "no such file" in low:
        return ui_text(
            f"Cookies браузера {name} не найдены: браузер не установлен или профиль ещё не использовался. "
            f"Выберите другой браузер или файл cookies.txt.",
            f"{name} cookies were not found: the browser is not installed or its profile has not been used. "
            f"Choose another browser or a cookies.txt file.")
    if any(word in low for word in ("decrypt", "dpapi", "keyring", "keychain", "secretstorage")):
        return ui_text(
            f"Не удалось расшифровать cookies браузера {name}. Запустите NOP от того же пользователя Windows, "
            f"что и браузер, или используйте файл cookies.txt.",
            f"Could not decrypt {name} cookies. Run NOP as the same Windows user as the browser, "
            f"or use a cookies.txt file.")
    detail = redact_diagnostic(text)[:160]
    return ui_text(f"Не удалось получить cookies браузера {name}. {detail}".strip(),
                   f"Could not get cookies from {name}. {detail}".strip())


class _QuietCookieLogger:
    def debug(self, *args, **kwargs): pass
    def info(self, *args, **kwargs): pass
    def warning(self, *args, **kwargs): pass
    def error(self, *args, **kwargs): pass
    def progress_bar(self): return None


def check_browser_cookies(browser):
    """Проверяет доступ к cookies браузера заранее, чтобы показать понятную причину ошибки.

    Cookies читаются только в памяти штатным механизмом yt-dlp; они не записываются на диск и не попадают в журнал."""
    from yt_dlp.cookies import extract_cookies_from_browser
    try:
        jar = extract_cookies_from_browser(browser, logger=_QuietCookieLogger())
    except Exception as exc:  # noqa: BLE001
        raise DownloadSourceError(browser_cookies_error(exc, browser)) from None
    del jar



# ---------- кэш проверки конвертеров ----------
# Проверка возможностей (FFmpeg, LibreOffice, Inkscape, Calibre, Blender) запускает внешние программы и
# занимала время при каждом старте. Результат хранится на диске и действует, пока не изменились сами
# программы (путь, размер, время изменения) и версия NOP. Установщик заполняет кэш один раз после установки.
CAPABILITY_CACHE_PATH = DATA_DIR / "capabilities.json"
CAPABILITY_CACHE_SCHEMA = 1
_CAPABILITY_TOOLS = (
    ("ffmpeg", ("ffmpeg.exe", "ffmpeg")),
    ("office", ("soffice.com", "soffice.exe", "soffice", "libreoffice")),
    ("vector", ("inkscape.com", "inkscape.exe", "inkscape")),
    ("ebook", ("ebook-convert.exe", "ebook-convert")),
    ("ebook_debug", ("calibre-debug.exe", "calibre-debug")),
    ("model", ("blender.exe", "blender")),
)


def conversion_tools_fingerprint() -> dict:
    """Только stat() найденных файлов: внешние программы здесь не запускаются."""
    result = {"app": APP_VERSION}
    for key, names in _CAPABILITY_TOOLS:
        try:
            tool = find_converter_tool(*names)
            if tool:
                st = Path(tool).stat()
                result[key] = [str(Path(tool).resolve()), st.st_size, st.st_mtime_ns]
            else:
                result[key] = None
        except OSError:
            result[key] = None
    return result


def _capabilities_encode(value):
    if isinstance(value, ConversionText):
        return {"__text__": [value.ru, value.en]}
    if isinstance(value, (set, frozenset)):
        return {"__set__": sorted(str(item) for item in value)}
    if isinstance(value, dict):
        return {str(key): _capabilities_encode(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_capabilities_encode(item) for item in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)


def _capabilities_decode(value):
    if isinstance(value, dict):
        if set(value) == {"__set__"}:
            return set(value["__set__"])
        if set(value) == {"__text__"}:
            return ConversionText(*value["__text__"])
        return {key: _capabilities_decode(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_capabilities_decode(item) for item in value]
    return value


def load_conversion_capabilities_cache():
    """Сохранённый результат проверки или None, если его нет либо программы изменились."""
    try:
        if CAPABILITY_CACHE_PATH.stat().st_size > 4 * 1024 * 1024:
            return None
        payload = json.loads(CAPABILITY_CACHE_PATH.read_text(encoding="utf-8"))
        if payload.get("schema") != CAPABILITY_CACHE_SCHEMA or payload.get("fingerprint") != conversion_tools_fingerprint():
            return None
        data = _capabilities_decode(payload["data"])
        if not isinstance(data, dict) or data.get("ffmpeg") is None:
            return None
        return data
    except (OSError, ValueError, TypeError, KeyError, AttributeError):
        return None


def save_conversion_capabilities_cache(capabilities: dict) -> bool:
    """Кэшируем только устойчивый результат: ошибки допустимы лишь для программ, которых нет."""
    fingerprint = conversion_tools_fingerprint()
    for key, message in (capabilities.get("errors") or {}).items():
        tool_key = {"office": "office", "vector": "vector", "ebook": "ebook", "model": "model"}.get(key)
        if tool_key is None or fingerprint.get(tool_key) is not None:
            return False  # сбой, а не отсутствие программы: пусть проверка повторится при следующем запуске
    if capabilities.get("ffmpeg") is None:
        return False
    try:
        payload = {"schema": CAPABILITY_CACHE_SCHEMA, "fingerprint": fingerprint,
                   "data": _capabilities_encode(capabilities)}
        tmp = CAPABILITY_CACHE_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
        os.replace(tmp, CAPABILITY_CACHE_PATH)
        return True
    except OSError:
        return False


def _warm_capabilities_main() -> int:
    """NOP.exe --nop-warm-capabilities: установщик выполняет проверку один раз и заполняет кэш."""
    from PyQt6.QtCore import QCoreApplication
    app = QCoreApplication(sys.argv[:1])
    results = []
    probe = ConversionCapabilityProbe(None)
    probe.ready.connect(results.append)
    probe.run()
    del app
    if results and save_conversion_capabilities_cache(results[0]):
        CAPABILITY_CACHE_PATH.with_name("capabilities-error.json").unlink(missing_ok=True)
        return 0
    try:  # why nothing was cached (tool failure, timeout...): readable by the installer / build script
        errors = {key: str(getattr(value, "en", value)) for key, value in ((results[0].get("errors") or {}) if results else {}).items()}
        CAPABILITY_CACHE_PATH.with_name("capabilities-error.json").write_text(json.dumps(errors, ensure_ascii=False, indent=1), encoding="utf-8")
    except OSError:
        pass
    return 1


def _selftest_main(report_path: str) -> int:
    """NOP.exe --nop-selftest <report.json>: проверка установленной копии без окон."""
    checks = []

    def add(name, ok, detail="", critical=True):
        checks.append({"name": name, "ok": bool(ok), "critical": critical, "detail": str(detail)[:400]})

    for module in ("PyQt6.QtWidgets", "PyQt6.QtMultimedia", "numpy", "PIL", "fitz", "mutagen", "yt_dlp"):
        try:
            __import__(module)
            add("import " + module, True)
        except Exception as exc:  # noqa: BLE001
            add("import " + module, False, exc, critical=module not in {"fitz"})
    try:
        import yt_dlp_ejs  # noqa: F401
        add("yt-dlp EJS", True)
    except Exception as exc:  # noqa: BLE001
        add("yt-dlp EJS", False, exc, critical=False)

    # libmpv: загрузка, версия API и создание контекста без окна и без звука
    try:
        directory, dll = MpvPlayer._find_library(MpvPlayer)
        if dll is None:
            raise RuntimeError("libmpv-2.dll not found")
        if os.name == "nt" and hasattr(os, "add_dll_directory"):
            os.add_dll_directory(str(directory))
        lib = ctypes.CDLL(str(dll))
        lib.mpv_client_api_version.restype = ctypes.c_ulong
        major = int(lib.mpv_client_api_version()) >> 16
        lib.mpv_create.restype = ctypes.c_void_p
        lib.mpv_set_option_string.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p]
        lib.mpv_initialize.argtypes = [ctypes.c_void_p]
        lib.mpv_terminate_destroy.argtypes = [ctypes.c_void_p]
        handle = lib.mpv_create()
        lib.mpv_set_option_string(handle, b"vo", b"null")
        lib.mpv_set_option_string(handle, b"ao", b"null")
        lib.mpv_set_option_string(handle, b"config", b"no")
        code = lib.mpv_initialize(handle)
        lib.mpv_terminate_destroy(handle)
        add("libmpv", major == 2 and code == 0, f"{dll} API {major} init={code}")
    except Exception as exc:  # noqa: BLE001
        add("libmpv", False, exc)

    # FFmpeg: запуск, кодирование и фильтр эквалайзера
    ffmpeg = find_converter_tool("ffmpeg.exe", "ffmpeg")
    ffprobe = find_converter_tool("ffprobe.exe", "ffprobe")
    deno = find_converter_tool("deno.exe", "deno")
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)

    def run(args, timeout=60):
        return subprocess.run(args, stdin=subprocess.DEVNULL, capture_output=True, timeout=timeout, creationflags=flags)

    add("ffmpeg.exe", bool(ffmpeg), ffmpeg or "not found")
    add("ffprobe.exe", bool(ffprobe), ffprobe or "not found")
    add("deno.exe (YouTube)", bool(deno), deno or "not found", critical=False)
    if ffmpeg:
        with tempfile.TemporaryDirectory(prefix="nop-selftest-") as folder:
            wav = Path(folder) / "t.wav"
            mp4 = Path(folder) / "t.mp4"
            try:
                proc = run([ffmpeg, "-hide_banner", "-v", "error", "-f", "lavfi", "-i", "sine=frequency=440:duration=0.5",
                            "-af", "equalizer=f=1000:t=q:w=1:g=3", str(wav)])
                add("FFmpeg: аудио и эквалайзер", proc.returncode == 0 and wav.is_file() and wav.stat().st_size > 1000,
                    proc.stderr.decode("utf-8", "replace")[:200])
                proc = run([ffmpeg, "-hide_banner", "-v", "error", "-f", "lavfi", "-i", "testsrc=duration=0.5:size=320x240:rate=25",
                            "-c:v", "libx264", "-pix_fmt", "yuv420p", str(mp4)])
                add("FFmpeg: перекодирование H.264", proc.returncode == 0 and mp4.is_file() and mp4.stat().st_size > 500,
                    proc.stderr.decode("utf-8", "replace")[:200])
                if ffprobe and mp4.is_file():
                    proc = run([ffprobe, "-v", "error", "-show_entries", "stream=codec_name", "-of", "csv=p=0", str(mp4)])
                    add("ffprobe", proc.returncode == 0 and b"h264" in proc.stdout, proc.stdout.decode("utf-8", "replace")[:100])
            except Exception as exc:  # noqa: BLE001
                add("FFmpeg", False, exc)
    # Conversion engines (documents, spreadsheets, presentations, vector, e-books, 3D). The build sets
    # NOP_SELFTEST_REQUIRE_ENGINES=1 when it bundled them: then a missing or non-working engine fails the check.
    require = os.environ.get("NOP_SELFTEST_REQUIRE_ENGINES") == "1"
    with tempfile.TemporaryDirectory(prefix="nop-engines-") as folder:
        work = Path(folder)

        def engine(name, tool, make_args, verify, timeout=300):
            if not tool:
                add(name, not require, "not found", critical=require)
                return
            try:
                proc = run(make_args(), timeout=timeout)
                good = verify(proc)
                add(name, good, ("" if good else (proc.stderr or proc.stdout).decode("utf-8", "replace")[-300:]), critical=require)
            except Exception as exc:  # noqa: BLE001
                add(name, False, exc, critical=require)

        text = work / "t.txt"
        text.write_text("NOP engine check\n", encoding="utf-8")
        office = conversion_office_tool()
        profile = (work / "lo-profile").as_uri()
        engine("Документы/Таблицы/Презентации (LibreOffice)", office,
               lambda: [office, f"-env:UserInstallation={profile}", "--headless", "--convert-to", "pdf", "--outdir", str(work), str(text)],
               lambda proc: (work / "t.pdf").is_file() and (work / "t.pdf").read_bytes()[:4] == b"%PDF")
        svg = work / "t.svg"
        svg.write_text('<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64"><rect width="64" height="64" fill="#e91e63"/></svg>', encoding="utf-8")
        vector = conversion_vector_tool()
        engine("Векторная графика (Inkscape)", vector,
               lambda: [vector, "--export-type=png", f"--export-filename={work / 't.png'}", str(svg)],
               lambda proc: (work / "t.png").is_file() and (work / "t.png").stat().st_size > 100)
        ebook = find_converter_tool("ebook-convert.exe", "ebook-convert")
        engine("Электронные книги (Calibre)", ebook,
               lambda: [ebook, str(text), str(work / "t.epub")],
               lambda proc: (work / "t.epub").is_file() and (work / "t.epub").stat().st_size > 300)
        blender = find_converter_tool("blender.exe", "blender")
        engine("3D-модели (Blender)", blender,
               lambda: [blender, "--background", "--factory-startup", "--python-expr", "import bpy; print('NOP-BLENDER-OK')"],
               lambda proc: b"NOP-BLENDER-OK" in proc.stdout)
    ok = all(item["ok"] for item in checks if item["critical"])
    try:
        Path(report_path).write_text(json.dumps({"app": APP_VERSION, "ok": ok, "frozen": FROZEN, "checks": checks},
                                                ensure_ascii=False, indent=1), encoding="utf-8")
    except OSError:
        pass
    return 0 if ok else 1


def _resolution_process_main(directory):
    """Extract metadata in an owned process; never download or encode media."""
    directory = Path(directory)
    params = json.loads(_unpack_private((directory / 'request.dat').read_bytes()))
    set_language(params.get('language', 'ru'))
    try:
        url = download_url(params['url'], params['source'], 'single')
        cookies = params.get('cookies_file', '')
        if cookies:
            original = Path(cookies)
            if original.stat().st_size > 16 * 1024 * 1024:
                raise ValueError(ui_text('Файл cookies превышает 16 МиБ.', 'Cookie file exceeds 16 MiB.'))
            copied = directory / 'cookies.txt'
            _private_write(copied, original.read_bytes())
            cookies = str(copied)  # yt-dlp must not rewrite the user's cookies during a preview.
        owner = Downloader(url, 1, directory, single_url=url, source=params['source'], cookies_file=cookies,
                           cookies_browser=params.get('cookies_browser', 'none'),
                           cookies_priority=params.get('cookies_priority', 'browser'))
        if owner._cookie_browser_in_use():
            check_browser_cookies(owner._cookie_browser_in_use())
        opts = owner.ytdlp_auth_options()
        opts.update(quiet=True, no_warnings=True, skip_download=True, noplaylist=True, check_formats=False,
                    cachedir=False, retries=0, extractor_retries=0, format='bestvideo/best')
        with yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(url, download=False)
        if not info or info.get('_type') in {'playlist', 'multi_video'}:
            raise ValueError(ui_text('Укажите ссылку одного видео.', 'Enter a single-video URL.'))
        tiers = available_video_resolutions(info.get('formats') or [info])
        result = {'resolutions': tiers, 'title': str(info.get('title') or '')[:300],
                  'duration': format_number(info.get('duration')),
                  'video_kbps': sorted({round(r) for r in (source_rate(f, 'video', info.get('duration')) for f in (info.get('formats') or [])
                                       if isinstance(f, dict) and f.get('vcodec') not in {None, 'none', 'images', 'storyboard'}) if r})[:64]}
    except Exception as exc:
        result = {'error': redact_diagnostic(exc)}
    _private_write(directory / 'result.json', json.dumps(result, ensure_ascii=False).encode('utf-8'))


class ResolutionProbe(QThread):
    result = pyqtSignal(dict)

    def __init__(self, params, parent):
        super().__init__(parent)
        self.params = dict(params)
        self._stop = threading.Event()

    def request_stop(self):
        self.requestInterruption()
        self._stop.set()

    def run(self):
        proc = None
        try:
            with tempfile.TemporaryDirectory(prefix='nop-resolutions-') as name:
                directory = Path(name)
                if os.name != 'nt': os.chmod(directory, 0o700)
                _private_write(directory / 'request.dat', _pack_private(json.dumps(self.params).encode('utf-8')))
                args = [sys.executable] if FROZEN else [sys.executable, str(Path(__file__).resolve())]
                args += ['--nop-resolution-probe', name]
                options = {'creationflags': getattr(subprocess, 'CREATE_NO_WINDOW', 0)} if os.name=='nt' else {'start_new_session':True}
                proc = subprocess.Popen(args, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, **options)
                deadline = time.monotonic() + 45
                while proc.poll() is None:
                    if self._stop.wait(.05) or time.monotonic() >= deadline:
                        stop_owned_process(proc)
                        if not self.isInterruptionRequested():
                            self.result.emit({'error':ui_text('Источник не ответил за 45 с. Повторите получение разрешений.',
                                                             'Source did not respond within 45 s. Fetch resolutions again.')})
                        return
                if self.isInterruptionRequested(): return
                path = directory / 'result.json'
                if not path.is_file() or path.stat().st_size > 1024*1024:
                    raise RuntimeError(ui_text('Не удалось получить список разрешений.', 'Could not retrieve resolutions.'))
                self.result.emit(json.loads(path.read_text(encoding='utf-8')))
        except Exception as exc:
            if not self.isInterruptionRequested(): self.result.emit({'error':redact_diagnostic(exc)})
        finally:
            if proc is not None and proc.poll() is None: stop_owned_process(proc)


class SourceMetadataPP(PostProcessor):
    def __init__(self, downloader, callback):
        super().__init__(downloader); self.callback = callback
    def run(self, info):
        self.callback(info)
        return [], info


class SourceStreamRemuxPP(PostProcessor):
    """Copy selected streams to the requested compatible container; never encode."""
    def __init__(self, downloader, owner, vid):
        super().__init__(downloader); self.owner, self.vid = owner, str(vid)
    def run(self, info):
        self.owner._checkpoint(self.vid)
        selection = self.owner._item_states.get(self.vid,{}).get('selection',{})
        extension = selection.get('container') or info['ext']
        source = Path(info['filepath'])
        remove_stream = ((self.owner.mode=='video' and info.get('acodec')!='none') or
                         (self.owner.mode=='audio' and info.get('vcodec')!='none'))
        if source.suffix.lower()=='.'+extension and not remove_stream: return [], info
        ffmpeg = shutil.which('ffmpeg') or str(APP_DIR/('ffmpeg.exe' if os.name=='nt' else 'ffmpeg'))
        destination = source.with_suffix('.'+extension)
        temporary = source.with_name(source.stem+'.nop-remux-'+secrets.token_hex(4)+'.'+extension)
        args = [ffmpeg,'-nostdin','-y','-i',str(source)]
        if self.owner.mode=='video': args += ['-map','0:v:0','-an']
        elif self.owner.mode=='audio': args += ['-map','0:a:0','-vn']
        else: args += ['-map','0:v:0','-map','0:a?']
        args += ['-c','copy','-map_metadata','0',str(temporary)]
        self.owner._set_item_detail(self.vid,'processing',percent=None,eta=None)
        result = run_download_command(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=1800)
        self.owner._checkpoint(self.vid)
        if result.returncode or not temporary.is_file():
            raise yt_dlp.utils.PostProcessingError(ui_text('Не удалось сохранить потоки без перекодирования: ',
                'Could not save streams without re-encoding: ')+redact_diagnostic(result.stderr.decode('utf-8',errors='replace')[-800:]))
        os.replace(temporary,destination)
        info.update(filepath=str(destination),ext=extension)
        return [str(source)] if source!=destination else [], info


class DownloadAttempt:
    """One attempt owns one newly created directory and explicitly journaled outputs.

    No filename masks or destination-directory snapshots are used for deletion.
    The journal also lets the supervising process clean up after a forced stop.
    """
    def __init__(self, owner, vid):
        self.owner, self.vid = owner, str(vid)
        owner.folder.mkdir(parents=True, exist_ok=True)
        self.directory = Path(tempfile.mkdtemp(prefix=".nop-task-", dir=str(owner.folder.resolve())))
        self.media = self.directory / "media"
        self.media.mkdir()
        identity = self.directory.stat()
        self.record = {"id": self.vid, "directory": str(self.directory),
                       "device": identity.st_dev, "inode": identity.st_ino,
                       "token": secrets.token_hex(16), "outputs": [], "committed": False}
        self._write()

    def _write(self):
        _private_write(self.directory / "attempt.json", json.dumps(self.record).encode())
        self.owner.attempt_update.emit(copy.deepcopy(self.record))

    def publish(self):
        self.owner._checkpoint(self.vid)
        self.owner._set_item_detail(self.vid, "saving", percent=None, eta=None, speed=0)
        files = sorted(p for p in self.media.iterdir() if not p.is_symlink() and
                       (is_complete_media(p) or (p.is_file() and p.suffix.lower() in {".png", ".jpg", ".jpeg", ".webp"})))
        if not files or not any(is_complete_media(p) for p in files):
            raise RuntimeError(ui_text("Итоговый медиафайл не найден.", "The final media file was not found."))
        # Reserve the whole group (audio + cover, for example) with the same suffix.
        for index in range(1, 10001):
            targets = [self.directory.parent / (p.name if index == 1 else f"{p.stem} ({index}){p.suffix}") for p in files]
            if any(p.exists() or p.is_symlink() for p in targets):
                continue
            try:
                for source, target in zip(files, targets):
                    self.owner._checkpoint(self.vid)
                    identity = source.stat()
                    # Record intent BEFORE the atomic, non-overwriting operation.
                    self.record["outputs"].append({"path": str(target), "device": identity.st_dev, "inode": identity.st_ino})
                    self._write()
                    if os.name == "nt":
                        os.rename(source, target)  # Windows rename fails if the target exists.
                    else:
                        os.link(source, target)  # Same filesystem; fails if the target exists.
                self.owner._checkpoint(self.vid)
                return targets
            except FileExistsError:
                self.record["outputs"].pop()  # The last reservation belongs to the other writer.
                self._write()
                # Another task won a name race. Roll back only our own file identities.
                errors = self._remove_outputs(self.record)
                if errors:
                    raise OSError("; ".join(errors))
                self.record["outputs"] = []
                self._write()
                if os.name == "nt":
                    raise OSError(ui_text("Имя занято другой задачей; повторите загрузку.", "Another task reserved this name; retry the download."))
        raise OSError(ui_text("Не удалось подобрать свободное имя файла.", "Could not reserve an unused filename."))

    def commit(self):
        # cancel_item() uses the same lock: the commit is the task's completion boundary.
        with self.owner.lock:
            self.owner._checkpoint(self.vid)
            self.record["committed"] = True
            self._write()
            self.owner._set_item_detail(self.vid, "done", percent=100, eta=0)

    @staticmethod
    def _remove_outputs(record):
        errors = []
        root = Path(record["directory"]).parent
        for output in record.get("outputs", []):
            path = Path(output["path"])
            if path.parent != root:
                errors.append(f"{path.name}: unsafe output path")
                continue
            for retry in range(5):
                try:
                    current = path.lstat()
                    if not output.get("inode") or not current.st_ino:
                        errors.append(f"{path.name}: " + ui_text("файловая система не подтверждает владельца; удаление пропущено", "filesystem cannot verify ownership; deletion skipped"))
                        break
                    if (current.st_dev, current.st_ino) != (output["device"], output["inode"]) or stat.S_ISLNK(current.st_mode):
                        errors.append(f"{path.name}: " + ui_text("файл был заменён; оставлен без изменений", "file was replaced; left untouched"))
                        break
                    path.unlink()
                    break
                except FileNotFoundError:
                    break
                except OSError as exc:
                    if retry < 4 and isinstance(exc, PermissionError):
                        time.sleep(.1)
                        continue
                    errors.append(f"{path.name}: {redact_diagnostic(exc)}")
                    break
        return errors

    @classmethod
    def cleanup_record(cls, registered):
        directory = Path(registered["directory"])
        try:
            identity = directory.lstat()
            if not registered.get("inode") or (identity.st_dev, identity.st_ino) != (registered["device"], registered["inode"]) or not stat.S_ISDIR(identity.st_mode):
                return [str(directory) + ": " + ui_text("рабочая папка была заменена; оставлена без изменений", "working directory was replaced; left untouched")]
            try:
                raw = (directory / "attempt.json").read_bytes()
            except FileNotFoundError:
                raise ValueError(ui_text("журнал владения отсутствует; папка оставлена без изменений", "ownership journal is missing; directory left untouched")) from None
            if len(raw) > 1024 * 1024:
                raise ValueError("Attempt journal exceeds the size limit")
            record = json.loads(raw)
            if record.get("token") != registered["token"] or record.get("directory") != str(directory):
                raise ValueError("Attempt ownership does not match")
            errors = [] if record.get("committed") else cls._remove_outputs(record)
            if not errors:
                for retry in range(5):
                    try:
                        shutil.rmtree(directory)
                        break
                    except FileNotFoundError:
                        break
                    except PermissionError:
                        if retry == 4:
                            raise
                        time.sleep(.1)
            return errors
        except FileNotFoundError:
            return []
        except (OSError, ValueError, KeyError) as exc:
            return [str(directory) + ": " + redact_diagnostic(exc)]


_DOWNLOAD_PROCESS_CONTEXT = threading.local()


class DownloadPopen(yt_dlp.utils.Popen):
    """Monitor FFmpeg/FFprobe for the current task, retaining yt-dlp's process API."""
    def __init__(self, args, *remaining, **kwargs):
        context = getattr(_DOWNLOAD_PROCESS_CONTEXT, "task", None)
        self._nop_monitor = None
        progress_path = None
        if context and isinstance(args, (list, tuple)):
            owner, vid, attempt = context
            executable = Path(str(args[0])).stem.lower()
            if executable.startswith(("ffmpeg", "ffprobe", "avconv", "avprobe")):
                owner._checkpoint(vid)
                if executable.startswith("ffmpeg") and "-i" in args and not getattr(_DOWNLOAD_PROCESS_CONTEXT, "format_probe", False):
                    owner._ffmpeg_duration(vid, args)
                    progress_path = attempt.directory / ("progress-" + secrets.token_hex(8) + ".log")
                    progress_path.touch()
                    args = [args[0], "-nostdin", "-nostats", "-stats_period", "0.25", "-progress", str(progress_path), *args[1:]]
                super().__init__(args, *remaining, **kwargs)
                self._nop_monitor = threading.Thread(target=self._monitor_task,
                    args=(owner, vid, progress_path), name="NOP FFmpeg progress", daemon=True)
                self._nop_monitor.start()
                return
        super().__init__(args, *remaining, **kwargs)

    def _monitor_task(self, owner, vid, progress_path):
        handle = None
        block = {}
        try:
            if progress_path is not None:
                handle = progress_path.open(encoding="utf-8", errors="replace")
            while True:
                if owner._stop_event.is_set() or owner.is_item_cancelled(vid):
                    if self.poll() is None:
                        if os.name == "nt":
                            stop_owned_process(self)
                        else:
                            # FFmpeg/FFprobe do not spawn worker processes. Stay in the
                            # enclosing job's process group so its forced stop includes us.
                            self.terminate()
                            try:
                                self.wait(timeout=.5)
                            except subprocess.TimeoutExpired:
                                self.kill(timeout=None)
                    return
                if handle is not None:
                    while True:
                        position = handle.tell()
                        line = handle.readline()
                        if not line or not line.endswith("\n"):
                            handle.seek(position)
                            break
                        key, separator, value = line.strip().partition("=")
                        if separator:
                            block[key] = value
                        if key == "progress":
                            owner._ffmpeg_progress(vid, block)
                            block = {}
                if self.poll() is not None:
                    return
                time.sleep(.05)
        except (OSError, ValueError) as exc:
            owner.status.emit(ui_text("Не удалось прочитать прогресс FFmpeg: ", "Could not read FFmpeg progress: ") + redact_diagnostic(exc))
        finally:
            if handle is not None:
                handle.close()

    def __exit__(self, *args):
        try:
            return super().__exit__(*args)
        finally:
            if self._nop_monitor is not None:
                self._nop_monitor.join(10)


class DownloadYoutubeDL(yt_dlp.YoutubeDL):
    def __init__(self, params, owner, vid, attempt):
        self._nop_context = (owner, str(vid), attempt)
        super().__init__(params)

    def __enter__(self):
        self._nop_previous = getattr(_DOWNLOAD_PROCESS_CONTEXT, "task", None)
        _DOWNLOAD_PROCESS_CONTEXT.task = self._nop_context
        return super().__enter__()

    def __exit__(self, *args):
        try:
            return super().__exit__(*args)
        finally:
            _DOWNLOAD_PROCESS_CONTEXT.task = self._nop_previous


# Only subprocesses inside DownloadYoutubeDL's thread-local task are monitored.
# Keeping yt-dlp's command construction preserves all its codec/container options.
_ytdlp_ffmpeg.Popen = DownloadPopen
_ytdlp_external.Popen = DownloadPopen


def run_download_command(args, **kwargs):
    stdout, stderr, code = DownloadPopen.run(args, **kwargs)
    return subprocess.CompletedProcess(args, code, stdout, stderr)


class Downloader(QThread):
    status = pyqtSignal(str)                # текстовый статус
    stats = pyqtSignal(float, int, int)     # скорость (байт/с), готово видео, всего видео
    done = pyqtSignal()
    queue_items = pyqtSignal(list)
    item_update = pyqtSignal(str, float, str)  # id, progress %, status
    spotify_tokens_updated = pyqtSignal(dict)
    item_detail = pyqtSignal(dict)
    attempt_update = pyqtSignal(dict)

    def __init__(self, url: str, count: int, folder: Path, single_url: str | None = None,
                 mode: str = "both", vq: str = "min", aq: str = "best", container: str = "mkv", vcodec: str = "any", cookies_browser: str = "none", cookies_file: str = "", retry_entries: list | None = None, source: str = "youtube",
                 spotify_client_id: str = "", spotify_access_token: str = "", spotify_refresh_token: str = "", spotify_token_expires_at: float = 0,
                 spotify_format: str = "mp3", spotify_bitrate: str = "192", rate_limit: str = "0",
                 dl_sample_rate: str = "0", parallel_videos: int = 2, fragment_threads: int = 4,
                 total_bitrate_kbps: int = 0, allow_bitrate_reencode: bool = False, resolution: str = 'auto',
                 video_bitrate_mode: str = "auto", video_bitrate_kbps: float = 0, clip_start=None, clip_end=None,
                 cookies_priority: str = "browser",
                 overall_bitrate_mode: str = "auto", overall_bitrate_kbps: float = 0, fps=None):
        super().__init__()
        self._job_arguments = {key: str(value) if isinstance(value, Path) else value
                               for key, value in locals().copy().items() if key not in {"self", "__class__"}}
        self._stop_event = threading.Event()
        self._control_lock = threading.Lock()
        self._ipc_directory = None
        self._child_process = None
        self._child_mode = False
        self._item_states = {}
        self._detail_emitted = {}
        self._stream_bytes = {}
        self._stream_totals = {}
        self._stream_estimates = {}
        self._counted_streams = set()
        self.total_bitrate_kbps = 0  # Legacy argument retained for saved job compatibility.
        self.allow_bitrate_reencode = False
        res_pref = resolution_choice(resolution, vq)
        self.video_profile = res_pref if isinstance(res_pref, str) else video_profile(vq)
        self.video_resolution = 0 if isinstance(res_pref, str) else res_pref
        self.fps_preference = fps_choice(fps, self.video_profile)
        self.audio_quality = aq
        self._attempt_records = {}
        self._attempts = {}
        self.parallel_videos = max(1, min(3, int(parallel_videos)))
        self.fragment_threads = max(1, min(8, int(fragment_threads), 16 // self.parallel_videos))
        self.url = url
        self.count = count
        self.folder = Path(folder)
        self.single_url = single_url  # если задан - качаем один элемент
        self.source = source if source in {"youtube", "tiktok", "instagram", "spotify", "direct"} else "youtube"
        self.spotify_client_id = str(spotify_client_id or "").strip()
        self.spotify_access_token = str(spotify_access_token or "").strip()
        self.spotify_refresh_token = str(spotify_refresh_token or "").strip()
        self.spotify_format = spotify_format if spotify_format in {"mp3", "m4a", "flac", "opus"} else "mp3"
        self.spotify_bitrate = spotify_bitrate if spotify_bitrate in {"128", "192", "256", "320", "0"} else "192"
        self.dl_sample_rate = str(dl_sample_rate) if str(dl_sample_rate) in {"0", "22050", "32000", "44100", "48000", "96000"} else "0"
        self.mode = mode if mode in {"both", "video", "audio"} else "both"
        self.rate_limit = str(rate_limit or "0")
        self.cancelled_items: set[str] = set()
        self._pending_queue: list[dict] = []
        self._in_progress_ids: set[str] = set()
        try:
            self.spotify_token_expires_at = float(spotify_token_expires_at or 0)
        except (TypeError, ValueError):
            self.spotify_token_expires_at = 0.0
        self.retry_entries = list(retry_entries or [])
        self.vcodec = vcodec
        self.cookies_browser = cookies_browser if cookies_browser in {key for key, _name in cookie_browser_choices()} else "none"
        self.cookies_priority = "file" if cookies_priority == "file" else "browser"
        self.cookies_file = str(cookies_file or "").strip()
        # video_bitrate_* принимаются только для совместимости со старыми сохранёнными задачами и не используются.
        self.overall_bitrate_mode = overall_bitrate_mode if overall_bitrate_mode in {"max", "mid", "min", "manual"} else "auto"
        try:
            self.overall_bitrate_kbps = max(0.0, float(overall_bitrate_kbps or 0))
        except (TypeError, ValueError):
            self.overall_bitrate_kbps = 0.0
        if self.overall_bitrate_mode == "manual" and not self.overall_bitrate_kbps:
            self.overall_bitrate_mode = "auto"
        self.clip = None
        self._clip_invalid = False
        try:
            if clip_start is not None or clip_end is not None:
                begin = max(0.0, float(clip_start or 0))
                finish = None if clip_end is None else float(clip_end)
                if finish is None or finish > begin:
                    self.clip = None if (begin == 0 and finish is None) else (begin, finish)
                else:
                    self._clip_invalid = True  # конец не позже начала: загрузка не начинается
        except (TypeError, ValueError):
            self._clip_invalid = True
        if self.source == "spotify":
            self.clip = None
        self.fmt = build_format("audio", vq, aq) if self.mode == "audio" else "source-profile:" + self.video_profile
        self.container = container if container in {key for key, _label in DL_CONTAINERS} else "mkv"
        self.tag = "_".join(part for part in (make_tag(self.mode, (f"{self.video_resolution}p" if self.video_resolution else self.video_profile), aq), clip_tag(self.clip)) if part)
        self.tag_suffix = f" ~{self.tag}" if self.tag else ""
        self.lock = threading.RLock()
        self.active: dict[str, tuple[float, float]] = {}  # id -> (процент, скорость)
        self.finished_videos = 0
        self.total_videos = 0
        self.total_bytes = 0
        self.last_render = 0.0
        self.resume_event = threading.Event()
        self.resume_event.set()  # set = working, clear = paused
        self._failed: list[str] = []
        self._failed_entries: list[dict] = []
        self.spotify_export_path = ""
        self.spotify_export_csv_path = ""
        self.spotify_export_count = 0
        self.error_text = ""

    # ---------- вывод в консоль ----------
    def log(self, msg: str):
        msg = redact_diagnostic(msg)
        with self.lock:
            sys.stdout.write(msg + "\n")
            sys.stdout.flush()

    def _spotify_access_token(self) -> str:
        """Возвращает действующий пользовательский OAuth-токен и обновляет его при необходимости."""
        if self.spotify_access_token and self.spotify_token_expires_at > time.time() + 60:
            return self.spotify_access_token
        if not self.spotify_client_id or not self.spotify_refresh_token:
            raise RuntimeError(
                "Для экспорта Spotify-альбома/плейлиста сначала укажи Client ID и нажми «Авторизовать Spotify»."
            )
        payload = urllib.parse.urlencode({
            "grant_type": "refresh_token",
            "refresh_token": self.spotify_refresh_token,
            "client_id": self.spotify_client_id,
        }).encode("ascii")
        request = urllib.request.Request(
            "https://accounts.spotify.com/api/token",
            data=payload,
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=25) as response:
                data = json.loads(response.read(1024 * 1024).decode("utf-8", errors="replace"))
        except urllib.error.HTTPError as exc:
            detail = exc.read(4096).decode("utf-8", errors="replace")
            exc.close()
            raise RuntimeError(f"Не удалось обновить авторизацию Spotify (HTTP {exc.code}): {detail[:300]}") from exc
        token = str(data.get("access_token") or "")
        if not token:
            raise RuntimeError("Spotify не выдал новый access token. Повтори авторизацию.")
        self.spotify_access_token = token
        self.spotify_token_expires_at = time.time() + int(data.get("expires_in", 3600))
        if data.get("refresh_token"):
            self.spotify_refresh_token = str(data["refresh_token"])
        self.spotify_tokens_updated.emit({
            "access_token": self.spotify_access_token,
            "refresh_token": self.spotify_refresh_token,
            "expires_at": self.spotify_token_expires_at,
        })
        return self.spotify_access_token

    @staticmethod
    def _spotify_api_get(url: str, token: str) -> dict:
        parsed = urllib.parse.urlsplit(url)
        if (parsed.scheme != "https" or parsed.hostname != "api.spotify.com" or parsed.port not in (None, 443)
                or parsed.username is not None or parsed.password is not None):
            raise ValueError("Untrusted Spotify API endpoint")
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, headers, newurl):
                raise ValueError("Spotify API redirect rejected")
        request = urllib.request.Request(url, headers={"Authorization": "Bearer " + token, "Accept": "application/json"})
        try:
            with urllib.request.build_opener(NoRedirect()).open(request, timeout=15) as response:
                raw = response.read(8 * 1024 * 1024 + 1)
                if len(raw) > 8 * 1024 * 1024:
                    raise ValueError("Spotify API response is too large")
                data = json.loads(raw)
                if not isinstance(data, dict):
                    raise ValueError("Invalid Spotify API response")
                return data
        except urllib.error.HTTPError as exc:
            status = exc.code
            exc.close()
            raise RuntimeError("Spotify HTTP " + str(status)) from None

    def _spotify_collection_metadata(self, url: str) -> tuple[str, list[dict]]:
        """Читает метаданные альбома/собственного плейлиста через официальный Spotify Web API."""
        kind, spotify_id = spotify_url_kind(url)
        if kind not in {"album", "playlist"}:
            raise ValueError("Для экспорта списка нужна ссылка Spotify на альбом или плейлист.")
        token = self._spotify_access_token()
        base = "https://api.spotify.com/v1"
        if kind == "album":
            meta = self._spotify_api_get(f"{base}/albums/{spotify_id}", token)
            title = str(meta.get("name") or "Spotify album").strip()
            page = meta.get("tracks") or {}
            page_url = page.get("next")
            raw_tracks = list(page.get("items") or [])
            # Некоторые ответы включают первую страницу полностью, но не добавляют URL до вызова /tracks.
            if not raw_tracks and not page_url:
                page_url = f"{base}/albums/{spotify_id}/tracks?limit=50&offset=0"
            while page_url:
                page = self._spotify_api_get(page_url, token)
                raw_tracks.extend(page.get("items") or [])
                page_url = page.get("next")
            source_name = "альбом"
        else:
            meta = self._spotify_api_get(f"{base}/playlists/{spotify_id}?fields=name,external_urls", token)
            title = str(meta.get("name") or "Spotify playlist").strip()
            page_url = f"{base}/playlists/{spotify_id}/items?limit=50&offset=0"
            raw_tracks = []
            while page_url:
                page = self._spotify_api_get(page_url, token)
                raw_items = page.get("items") or []
                for entry in raw_items:
                    item = entry.get("item") or entry.get("track") or entry.get("episode") or {}
                    if item:
                        raw_tracks.append(item)
                page_url = page.get("next")
            source_name = "плейлист"
        tracks = []
        for track in raw_tracks:
            if not isinstance(track, dict) or track.get("type") not in (None, "track"):
                continue
            track_id = str(track.get("id") or "").strip()
            track_name = str(track.get("name") or "").strip()
            if not track_name:
                continue
            artists = ", ".join(
                str(a.get("name") or "").strip()
                for a in (track.get("artists") or [])
                if isinstance(a, dict) and a.get("name")
            )
            external = track.get("external_urls") or {}
            track_url = str(external.get("spotify") or (f"https://open.spotify.com/track/{track_id}" if track_id else ""))
            tracks.append({"name": track_name, "artists": artists, "url": track_url})
        if not tracks:
            if kind == "playlist":
                raise RuntimeError(
                    "Spotify не вернул треки этого плейлиста. После изменений API содержимое часто доступно "
                    "только для плейлистов, которыми владеешь или в которых являешься соавтором."
                )
            raise RuntimeError("Spotify API вернул альбом без списка треков.")
        self.log(f"Spotify: получено {len(tracks)} треков из {source_name} «{title}».")
        return title, tracks

    def _write_spotify_tracklist(self, source_url: str, title: str, tracks: list[dict]) -> tuple[Path, Path]:
        """Сохраняет список Spotify в TXT и CSV, не перезаписывая предыдущие экспорты."""
        safe_title = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", title).strip(" .")[:120] or "Spotify_tracklist"
        self.folder.mkdir(parents=True, exist_ok=True)

        # Ищем общее свободное имя для обоих форматов, чтобы повторный экспорт
        # не затирал список, который пользователь сохранил раньше.
        base = f"{safe_title} - Spotify"
        txt_path = getattr(self, "_job_temp_dir", self.folder) / f"{base}.txt"
        csv_path = getattr(self, "_job_temp_dir", self.folder) / f"{base}.csv"
        suffix = 2
        while txt_path.exists() or csv_path.exists():
            txt_path = getattr(self, "_job_temp_dir", self.folder) / f"{base} ({suffix}).txt"
            csv_path = getattr(self, "_job_temp_dir", self.folder) / f"{base} ({suffix}).csv"
            suffix += 1

        lines = [
            f"Spotify: {title}",
            f"Источник: {source_url}",
            f"Треков: {len(tracks)}",
            "",
        ]
        for index, track in enumerate(tracks, start=1):
            artist = track.get("artists") or "Неизвестный исполнитель"
            name = str(track.get("name") or "Без названия")
            track_url = str(track.get("url") or "")
            lines.append(f"{index:02d}. {name} — {artist}")
            if track_url:
                lines.append(f"    Spotify: {track_url}")
        lines.extend(["", "Список создан из метаданных Spotify. Аудио этим экспортом не скачивается."])
        txt_path.write_text("\n".join(lines) + "\n", encoding="utf-8-sig")

        # Разделитель ; удобнее для Excel с русской/европейской региональной настройкой.
        with csv_path.open("w", newline="", encoding="utf-8-sig") as handle:
            writer = csv.writer(handle, delimiter=";", quoting=csv.QUOTE_MINIMAL)
            writer.writerow(["№", "Название", "Исполнитель(и)", "Ссылка Spotify", "Источник Spotify"])
            for index, track in enumerate(tracks, start=1):
                writer.writerow([
                    index,
                    str(track.get("name") or "Без названия"),
                    str(track.get("artists") or "Неизвестный исполнитель"),
                    str(track.get("url") or ""),
                    source_url,
                ])
        return txt_path, csv_path

    def emit_stats(self):
        speed = sum(s for _, s in self.active.values())
        self.stats.emit(float(speed), self.finished_videos, self.total_videos)

    def render(self):
        """Строка прогресса в консоли + статистика в окно. Вызывать под self.lock."""
        now = time.monotonic()
        if now - self.last_render < 0.3:
            return
        self.last_render = now
        self.emit_stats()
        width = shutil.get_terminal_size((100, 20)).columns
        speed = sum(s for _, s in self.active.values())
        parts = "  ".join(f"{vid[:6]} {pct:3.0f}%" for vid, (pct, _) in self.active.items())
        line = f"[{self.finished_videos}/{self.total_videos}] {fmt_speed(speed):>10}   {parts}"
        sys.stdout.write("\r" + line.ljust(width - 1)[: width - 1])
        sys.stdout.flush()

    def _direct_cookie_file(self):
        return self.cookies_file if self._cookie_file_in_use() and not self._cookie_browser_in_use() else ""

    def _cookie_file_in_use(self):
        return bool(self.cookies_file and Path(self.cookies_file).is_file())

    def _cookie_browser_in_use(self):
        """Браузер, чьи cookies нужно использовать, либо "". Файл cookies.txt остаётся рабочим вариантом:
        при выбранных обоих источниках решает настройка приоритета."""
        if self.cookies_browser == "none" or self.source == "spotify":
            return ""
        if self.cookies_priority == "file" and self._cookie_file_in_use():
            return ""
        return self.cookies_browser

    def ytdlp_auth_options(self, vid=None):
        opts = {
            "logger": self.make_logger(vid),
            "socket_timeout": 12,
            "trim_file_name": 180,
            # YouTube часто требует решить JS challenge. yt-dlp получает solver
            # из официального репозитория; Deno используется как JS runtime.
            "remote_components": ["ejs:github"],
            "js_runtimes": {"deno": {"path": shutil.which("deno") or "deno"}},
        }
        browser = self._cookie_browser_in_use()
        if browser:
            # Штатный механизм yt-dlp: cookies читаются из браузера в память и нигде не сохраняются.
            # cookiefile при этом не передаётся, иначе yt-dlp записал бы извлечённые cookies в файл.
            opts["cookiesfrombrowser"] = (browser,)
        elif self._cookie_file_in_use():
            # Файл cookies.txt читается без обращения к заблокированной базе браузера.
            opts["cookiefile"] = self.cookies_file
        if self.source != "spotify":
            opts["allowed_extractors"] = [{"direct": "generic"}.get(self.source, self.source + ".*")]
            opts["default_search"] = "error"
            opts["allow_unplayable_formats"] = False
            opts["match_filter"] = self._check_download_info
        return opts

    def _check_download_info(self, info, *, incomplete=False):
        key = str(info.get("extractor_key") or info.get("extractor") or "").lower()
        expected = "generic" if self.source == "direct" else self.source
        if key and not key.startswith(expected):
            raise DownloadSourceError(ui_text("Загрузчик попытался сменить выбранную площадку.",
                                             "The downloader attempted to switch the selected platform."))
        page = info.get("webpage_url")
        if page:
            download_url(page, self.source)
        if info.get("has_drm"):
            raise DownloadSourceError(ui_text("Видео защищено DRM и не поддерживается.", "DRM-protected video is not supported."))
        return None

    # ---------- получение списка ----------
    @staticmethod
    def _decode_meta_content(page: str, key: str) -> str:
        """Извлекает content из meta по property/name, независимо от порядка атрибутов."""
        for tag in re.findall(r"<meta\b[^>]*>", page, flags=re.IGNORECASE):
            attrs = {
                name.casefold(): html_lib.unescape(value)
                for name, _quote, value in re.findall(r"([\w:-]+)\s*=\s*([\"'])(.*?)\2", tag, flags=re.DOTALL)
            }
            if (attrs.get("property", "").casefold() == key.casefold()
                    or attrs.get("name", "").casefold() == key.casefold()):
                return attrs.get("content", "").strip()
        return ""

    def _spotify_track_metadata(self, url: str) -> tuple[str, str]:
        """Получает публичные метаданные трека Spotify; аудиопоток Spotify не загружает."""
        parsed = urllib.parse.urlparse(url)
        if not (parsed.netloc.casefold().endswith("spotify.com") and "/track/" in parsed.path):
            raise ValueError("В режиме Spotify нужна ссылка именно на отдельный трек (open.spotify.com/track/...).")

        track_url = url.split("?", 1)[0]
        title = ""
        artist = ""
        page = ""
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/130 Safari/537.36"}

        # Самый надёжный источник — Spotify Web API: он возвращает имя исполнителя
        # отдельно от названия. Используем уже настроенную авторизацию, если она есть.
        track_match = re.search(r"/track/([A-Za-z0-9]{10,32})", urllib.parse.urlparse(track_url).path)
        if track_match:
            try:
                token = self._spotify_access_token()
                api_data = self._spotify_api_get(
                    f"https://api.spotify.com/v1/tracks/{track_match.group(1)}", token
                )
                api_title = str(api_data.get("name") or "").strip()
                api_artists = api_data.get("artists") or []
                api_artist = ", ".join(
                    str(item.get("name") or "").strip()
                    for item in api_artists if isinstance(item, dict) and item.get("name")
                ).strip()
                if api_title and api_artist:
                    self.log("Spotify: название и исполнитель получены через Web API.")
                    return html_lib.unescape(api_title), html_lib.unescape(api_artist)
            except Exception as exc:  # noqa: BLE001
                # Публичная страница содержит только общедоступные метаданные;
                # защищённый API и аудиопоток без авторизации не используем.
                self.log(f"Spotify Web API недоступен для метаданных, пробую публичную страницу: {exc}")

        # Публичный агрегатор метаданных song.link — запасной вариант, когда
        # Spotify Web API требует Client ID/OAuth. Он возвращает title и artistName
        # по ссылке, не предоставляя аудиопоток.
        if track_match and not artist:
            try:
                lookup_url = (
                    "https://api.song.link/v1-alpha.1/links?url="
                    + urllib.parse.quote(track_url, safe="")
                )
                req = urllib.request.Request(lookup_url, headers=headers)
                with urllib.request.urlopen(req, timeout=15) as response:
                    lookup = json.loads(response.read(3 * 1024 * 1024).decode("utf-8", errors="replace"))
                entities = lookup.get("entitiesByUniqueId") or {}
                for entity in entities.values():
                    if not isinstance(entity, dict):
                        continue
                    candidate_title = str(entity.get("title") or "").strip()
                    candidate_artist = str(entity.get("artistName") or "").strip()
                    if candidate_title and candidate_artist:
                        title = title or candidate_title
                        artist = candidate_artist
                        self.log("Spotify: метаданные трека получены через резервный каталог.")
                        break
            except Exception as exc:  # noqa: BLE001
                self.log(f"Song.link не вернул метаданные (резервный источник пропущен): {exc}")

        # Попытка получить точные метаданные из публичной embed-страницы Spotify.
        # В некоторых версиях обычная track-страница отдаёт только название,
        # тогда как embed-страница содержит объект текущего трека с artists.
        if track_match and not artist:
            try:
                embed_url = f"https://open.spotify.com/embed/track/{track_match.group(1)}"
                req = urllib.request.Request(embed_url, headers=headers)
                with urllib.request.urlopen(req, timeout=15) as response:
                    embed_page = response.read(5 * 1024 * 1024).decode("utf-8", errors="replace")
                # Сначала пробуем JSON-LD / сериализованные объекты с полями track.
                json_candidates = re.findall(
                    r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>|'
                    r'<script[^>]+id=["\']__NEXT_DATA__["\'][^>]*>(.*?)</script>',
                    embed_page, flags=re.IGNORECASE | re.DOTALL,
                )
                for pair in json_candidates:
                    for raw_json in pair:
                        if not raw_json.strip():
                            continue
                        try:
                            root = json.loads(html_lib.unescape(raw_json))
                        except (ValueError, TypeError):
                            continue
                        stack = [root]
                        while stack:
                            obj = stack.pop()
                            if isinstance(obj, dict):
                                obj_id = str(obj.get("id") or obj.get("uri") or "")
                                id_matches = (track_match.group(1) in obj_id)
                                obj_title = str(obj.get("name") or obj.get("title") or "").strip()
                                obj_artists = obj.get("artists") or obj.get("artist") or []
                                if isinstance(obj_artists, dict):
                                    obj_artists = [obj_artists]
                                if isinstance(obj_artists, str):
                                    obj_artists = [obj_artists]
                                artist_names = []
                                if isinstance(obj_artists, list):
                                    for a in obj_artists:
                                        if isinstance(a, dict):
                                            n = str(a.get("name") or a.get("title") or "").strip()
                                        else:
                                            n = str(a or "").strip()
                                        if n and n not in artist_names:
                                            artist_names.append(n)
                                if id_matches and artist_names:
                                    title = title or obj_title
                                    artist = ", ".join(artist_names)
                                    break
                                stack.extend(obj.values())
                            elif isinstance(obj, list):
                                stack.extend(obj)
                        if artist:
                            break
                # Дополнительный узкий regex: artist names рядом с ID конкретного трека.
                if not artist:
                    id_pos = embed_page.find(track_match.group(1))
                    if id_pos >= 0:
                        nearby = embed_page[max(0, id_pos - 2500):id_pos + 9000]
                        artist_match = re.search(
                            r'"artists"\s*:\s*\[\s*\{.{0,1200}?"name"\s*:\s*"((?:\\.|[^"\\])+)"',
                            nearby, re.DOTALL,
                        )
                        if artist_match:
                            try:
                                artist = json.loads('"' + artist_match.group(1) + '"')
                            except (ValueError, TypeError):
                                artist = html_lib.unescape(artist_match.group(1))
                if artist:
                    self.log("Spotify: исполнитель получен из embed-страницы трека.")
            except Exception as exc:  # noqa: BLE001
                self.log(f"Spotify embed-страница не дала метаданные: {exc}")

        # Официальный oEmbed Spotify предназначен для получения заголовка/обложки,
        # не для выдачи самого аудио.
        try:
            oembed_url = "https://open.spotify.com/oembed?url=" + urllib.parse.quote(track_url, safe="")
            req = urllib.request.Request(oembed_url, headers=headers)
            with urllib.request.urlopen(req, timeout=15) as response:
                data = json.loads(response.read(1024 * 1024).decode("utf-8", errors="replace"))
            title = title or str(data.get("title") or "").strip()
        except Exception as exc:  # noqa: BLE001
            self.log(f"Spotify oEmbed недоступен, пробую публичную страницу: {exc}")

        # На открытой странице иногда доступно имя исполнителя в метаданных.
        try:
            req = urllib.request.Request(track_url, headers=headers)
            with urllib.request.urlopen(req, timeout=15) as response:
                page = response.read(3 * 1024 * 1024).decode("utf-8", errors="replace")
                final_url = response.geturl()
            if "/track/" in urllib.parse.urlparse(final_url).path:
                track_url = final_url.split("?", 1)[0]
        except Exception as exc:  # noqa: BLE001
            self.log(f"Не удалось прочитать страницу Spotify: {exc}")

        if page:
            title = title or self._decode_meta_content(page, "og:title")
            description = (self._decode_meta_content(page, "og:description")
                           or self._decode_meta_content(page, "description"))
            # Сначала используем описание именно этой страницы трека: JSON страницы
            # содержит и другие сущности, поэтому первый массив "artists" может
            # относиться не к текущей композиции.
            if description:
                pieces = [piece.strip() for piece in re.split(r"[·•]", description) if piece.strip()]
                # Возможные форматы публичной страницы Spotify:
                # «Track · ARTIST · Song · YEAR» и
                # «Listen to TITLE on Spotify. ARTIST · Song · YEAR».
                if len(pieces) >= 3 and pieces[0].casefold() in {"track", "song"}:
                    artist = pieces[1]
                if not artist:
                    spotify_suffix = re.search(
                        r"Spotify[.!]?\s+(.+?)\s*[·•]\s*(?:song|track)\b",
                        description, re.IGNORECASE,
                    )
                    if spotify_suffix:
                        candidate_artist = spotify_suffix.group(1).strip(" .,:;\"")
                        # Не принимаем заголовок песни за имя исполнителя.
                        if candidate_artist and re.sub(r"[^0-9a-zа-я]+", "", candidate_artist.casefold().replace("ё", "е")) != re.sub(r"[^0-9a-zа-я]+", "", title.casefold().replace("ё", "е")):
                            artist = candidate_artist
                # Другой формат: «Listen to TITLE by ARTIST on Spotify».
                if not artist:
                    by_match = re.search(r"\bby\s+(.+?)\s+on\s+Spotify\b", description, re.IGNORECASE)
                    if by_match:
                        artist = by_match.group(1).strip(" .,:;\"'")
            # Последний резерв — встроенные данные страницы. Не перезаписываем
            # исполнителя, извлечённого из описания конкретного трека.
            if not artist:
                match = re.search(r'"artists"\s*:\s*\[\s*\{.{0,1800}?"name"\s*:\s*"((?:\\.|[^"\\])+)', page, re.DOTALL)
                if match:
                    try:
                        artist = json.loads('"' + match.group(1) + '"')
                    except (ValueError, TypeError):
                        artist = html_lib.unescape(match.group(1))

        title = html_lib.unescape(title).strip().strip('"')
        artist = html_lib.unescape(artist).strip().strip('"')
        if not title:
            raise RuntimeError("Не удалось получить название трека Spotify. Проверь ссылку или обнови yt-dlp.")
        return title, artist

    def _download_spotisaver_track(self, track: dict, title: str, artist: str, item_id: str) -> Path:
        """Резервный прямой запрос к публичному интерфейсу SpotiSaver без запуска браузера.

        Интерфейс не является официально документированным API и может измениться;
        загружаются только результаты, которые сервис сам возвращает.
        """
        spotify_url = str(track.get("url") or "")
        match = re.search(r"open\.spotify\.com/track/([A-Za-z0-9]+)", spotify_url, re.I)
        if not match:
            raise RuntimeError("в метаданных отсутствует ссылка на отдельный трек Spotify")
        spotify_id = match.group(1)
        base_url = "https://spotisaver.net/en1"
        opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/125.0 Safari/537.36",
            "Referer": base_url,
            "Accept": "text/html,application/json,*/*",
        }

        def request(url: str, data: bytes | None = None, extra_headers: dict | None = None) -> bytes:
            request_headers = dict(headers)
            if extra_headers:
                request_headers.update(extra_headers)
            # HTTP 5xx иногда бывает кратковременным у резервного сервиса. Делаем
            # одну повторную попытку, но не маскируем 401/403 и другие постоянные ошибки.
            for attempt in range(2):
                req = urllib.request.Request(
                    url, data=data, headers=request_headers,
                    method="POST" if data is not None else "GET",
                )
                try:
                    with opener.open(req, timeout=35) as response:
                        self._checkpoint(item_id)
                        limit = 80 * 1024 * 1024
                        payload = response.read(limit + 1)
                        if len(payload) > limit:
                            raise ValueError("Audio response exceeds 80 MiB")
                        self._checkpoint(item_id)
                        return payload
                except urllib.error.HTTPError as exc:
                    detail = exc.read(1200).decode("utf-8", errors="replace").strip()
                    exc.close()
                    if exc.code in {500, 502, 503, 504} and attempt == 0:
                        time.sleep(0.8)
                        continue
                    if detail:
                        detail = re.sub(r"\s+", " ", detail)[:300]
                    suffix = f": {detail}" if detail else ""
                    raise RuntimeError(f"SpotiSaver вернул HTTP {exc.code}{suffix}") from exc
                except (urllib.error.URLError, TimeoutError, OSError) as exc:
                    if attempt == 0:
                        time.sleep(0.5)
                        continue
                    raise RuntimeError(f"Ошибка соединения со SpotiSaver: {exc}") from exc
            raise RuntimeError("SpotiSaver не ответил после повторной попытки")

        page = request(base_url).decode("utf-8", errors="replace")
        ip_match = re.search(r'const\s+user_ip\s*=\s*"([^"]+)"', page)
        token_match = re.search(r'requestToken\s*:\s*"([^"]+)"', page)
        wire_match = re.search(r'wire\s*:\s*(\{[^\r\n]+\})\s*\};', page)
        if not (ip_match and token_match and wire_match):
            raise RuntimeError("не удалось прочитать параметры запроса сервиса (возможно, сайт изменился)")
        user_ip, request_token = ip_match.group(1), token_match.group(1)
        wire = json.loads(wire_match.group(1))

        def b64_context(context: dict) -> str:
            raw = json.dumps(context, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
            return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

        def get_signature(action: str, context: dict) -> dict:
            params = {
                wire["token_param"]: request_token,
                wire["action_param"]: wire["actions"][action],
                wire["ctx_param"]: b64_context(context),
            }
            url = "https://spotisaver.net/api/get_signature.php?" + urllib.parse.urlencode(params)
            return json.loads(request(url).decode("utf-8", errors="replace"))

        self.item_update.emit(item_id, 12.0, "SpotiSaver: получаю метаданные…")
        playlist_sig = get_signature("get_playlist", {"id": spotify_id, "type": "track", "lang": "en"})
        playlist_params = urllib.parse.urlencode({"id": spotify_id, "type": "track", "lang": "en"})
        playlist_headers = {
            wire["sig_header"]: str(playlist_sig["token"]),
            wire["exp_header"]: str(playlist_sig["exp"]),
            "Accept": "application/json",
        }
        playlist_data = json.loads(request("https://spotisaver.net/api/get_playlist.php?" + playlist_params, extra_headers=playlist_headers).decode("utf-8", errors="replace"))
        tracks = playlist_data.get("tracks") or []
        if not tracks:
            raise RuntimeError("SpotiSaver не нашёл аудиоверсию этого трека")
        remote_track = tracks[0]
        download_context = {
            "lang": "en",
            "id": str(remote_track.get("id", "")),
            "name": str(remote_track.get("name", "")),
            "duration_ms": str(int(float(remote_track.get("duration_ms") or 0))),
        }
        download_sig = get_signature("download_track", download_context)
        download_headers = {
            wire["sig_header"]: str(download_sig["token"]),
            wire["exp_header"]: str(download_sig["exp"]),
            "Content-Type": "application/json",
            "Accept": "audio/*,application/json,*/*",
        }
        payload = {
            "track": remote_track,
            "download_dir": "downloads",
            "filename_tag": "SPOTISAVER",
            "user_ip": user_ip,
            "is_premium": False,
            "lang": "en",
        }
        self.item_update.emit(item_id, 25.0, "SpotiSaver: скачиваю аудио…")
        self._set_item_detail(item_id, "downloading", percent=None, source="SpotiSaver", downloaded=0, total=0)
        data = request(
            "https://spotisaver.net/api/download_track.php",
            data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
            extra_headers=download_headers,
        )
        # Защита от сохранения JSON/HTML страницы ошибки под видом MP3.
        if not data or data.lstrip().startswith((b"{", b"<")):
            try:
                error_text = data[:500].decode("utf-8", errors="replace")
            except Exception:
                error_text = "пустой ответ"
            raise RuntimeError("сервис вернул не аудиофайл: " + error_text)

        suffix = ".mp3" if data.startswith(b"ID3") or data.startswith(b"\xff\xfb") or data.startswith(b"\xff\xf3") or data.startswith(b"\xff\xf2") else ".audio"
        safe_artist = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", artist).strip(" .") or "Неизвестный исполнитель"
        safe_title = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", title).strip(" .") or "Без названия"
        base_name = f"{safe_artist[:90]} - {safe_title[:90]}"
        attempt = self._attempts[str(item_id)]
        final_path = attempt.media / f"{base_name}.{self.spotify_format}"
        copy_index = 2
        while final_path.exists():
            final_path = attempt.media / f"{base_name} ({copy_index}).{self.spotify_format}"
            copy_index += 1
        self.folder.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix=".yamifm_spotisaver_", dir=str(attempt.directory)) as temp_dir:
            source_path = Path(temp_dir) / ("source" + suffix)
            source_path.write_bytes(data)
            ffmpeg = shutil.which("ffmpeg") or str(APP_DIR / "ffmpeg.exe")
            if self.spotify_format == "mp3" and suffix == ".mp3" and self.spotify_bitrate == "0":
                shutil.move(str(source_path), str(final_path))
            else:
                if not Path(ffmpeg).is_file() and not shutil.which(ffmpeg):
                    raise RuntimeError("для преобразования формата нужен FFmpeg")
                command = [ffmpeg, "-y", "-i", str(source_path), "-vn"]
                if self.spotify_format == "mp3":
                    command += ["-b:a", f"{self.spotify_bitrate}k"]
                command += [str(final_path)]
                self._checkpoint(item_id)
                self._set_item_detail(item_id, "converting", percent=None, source="SpotiSaver", downloaded=len(data), total=len(data))
                previous = getattr(_DOWNLOAD_PROCESS_CONTEXT, "task", None)
                try:
                    _DOWNLOAD_PROCESS_CONTEXT.task = (self, str(item_id), attempt)
                    result = run_download_command(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
                finally:
                    _DOWNLOAD_PROCESS_CONTEXT.task = previous
                self._checkpoint(item_id)
                if result.returncode != 0 or not final_path.is_file():
                    raise RuntimeError("FFmpeg не смог преобразовать ответ SpotiSaver: " + result.stderr.decode("utf-8", errors="replace")[-500:])
        return final_path

    @staticmethod
    def _cover_match_key(value: str) -> str:
        """Нормализует текст для осторожного сопоставления названия и исполнителя."""
        value = html_lib.unescape(str(value or "")).casefold().replace("ё", "е")
        return re.sub(r"[^0-9a-zа-я]+", "", value)

    def _find_spotify_cover_url(self, track: dict) -> str:
        """Ищет обложку последовательно в метаданных Spotify и резервном каталоге."""
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/130 Safari/537.36",
            "Accept": "text/html,application/json,image/avif,image/webp,*/*",
        }
        direct = str(track.get("cover_url") or track.get("image_url") or track.get("thumbnail") or "").strip()
        if direct.startswith(("https://", "http://")):
            return html_lib.unescape(direct).replace("&amp;", "&")

        track_url = str(track.get("url") or "").strip()
        track_id_match = re.search(r"/track/([A-Za-z0-9]{10,32})", urllib.parse.urlparse(track_url).path)
        track_id = track_id_match.group(1) if track_id_match else ""
        # Spotify oEmbed, публичная track-страница и embed-страница независимы от
        # пользовательского OAuth. Пробуем все варианты, а не прекращаем поиск
        # после первой страницы без og:image.
        page_urls = []
        if track_url:
            page_urls.extend([
                track_url,
                "https://open.spotify.com/oembed?url=" + urllib.parse.quote(track_url, safe=""),
            ])
        if track_id:
            page_urls.append(f"https://open.spotify.com/embed/track/{track_id}")
        for page_url in page_urls:
            try:
                req = urllib.request.Request(page_url, headers=headers)
                with urllib.request.urlopen(req, timeout=12) as response:
                    raw = response.read(4 * 1024 * 1024).decode("utf-8", errors="replace")
                if "oembed" in page_url:
                    try:
                        data = json.loads(raw)
                        candidate = str(data.get("thumbnail_url") or "").strip()
                        if candidate.startswith(("https://", "http://")):
                            self.log("Spotify: URL обложки получен через oEmbed.")
                            return candidate
                    except (ValueError, TypeError):
                        pass
                candidate = self._decode_meta_content(raw, "og:image")
                if not candidate:
                    candidate = self._decode_meta_content(raw, "twitter:image")
                if not candidate:
                    # Встроенные JSON-данные иногда экранируют слеши.
                    match = re.search(r'"(?:image|thumbnail_url|cover_url)"\s*:\s*"(https?:\\?/\\?/[^"\\]+)', raw, re.I)
                    if match:
                        candidate = match.group(1).replace("\\/", "/")
                if candidate.startswith(("https://", "http://")):
                    self.log("Spotify: URL обложки получен из публичной страницы.")
                    return html_lib.unescape(candidate).replace("&amp;", "&")
            except Exception as exc:  # источник обложки необязателен
                self.log(f"Spotify: источник метаданных обложки недоступен: {exc}")

        # Резерв: публичный iTunes Search API. Принимаем только результат с
        # совпадающими названием и исполнителем, чтобы не прикрепить чужую обложку.
        title = str(track.get("name") or track.get("title") or "").strip()
        artist = track.get("artists") or track.get("artist") or ""
        if isinstance(artist, list):
            artist = ", ".join(str(a) for a in artist if a)
        artist = str(artist).strip()
        if title and artist:
            try:
                query = urllib.parse.urlencode({"term": f"{artist} {title}", "entity": "song", "limit": 15})
                req = urllib.request.Request("https://itunes.apple.com/search?" + query, headers={"User-Agent": headers["User-Agent"]})
                with urllib.request.urlopen(req, timeout=12) as response:
                    results = json.loads(response.read(2 * 1024 * 1024).decode("utf-8", errors="replace"))
                wanted_title = self._cover_match_key(title)
                wanted_artist = self._cover_match_key(artist.split(",", 1)[0])
                for result in results.get("results", []):
                    result_title = self._cover_match_key(result.get("trackName", ""))
                    result_artist = self._cover_match_key(result.get("artistName", ""))
                    title_match = bool(wanted_title and result_title and (wanted_title == result_title or wanted_title in result_title or result_title in wanted_title))
                    artist_match = bool(wanted_artist and result_artist and (wanted_artist == result_artist or wanted_artist in result_artist or result_artist in wanted_artist))
                    artwork = str(result.get("artworkUrl100") or "").strip()
                    if title_match and artist_match and artwork.startswith("https://"):
                        artwork = re.sub(r"/\d+x\d+bb\.", "/1000x1000bb.", artwork)
                        self.log("Spotify: обложка найдена через резервный каталог по названию и исполнителю.")
                        return artwork
            except Exception as exc:
                self.log(f"Spotify: резервный поиск обложки не удался: {exc}")
        return ""

    def _save_spotify_cover(self, track: dict, audio_path: Path) -> Path | None:
        """Получает, проверяет и сохраняет обложку рядом с аудиофайлом."""
        try:
            # Если соседнее изображение есть, сначала убеждаемся, что оно декодируется.
            for ext in (".jpg", ".png"):
                existing = audio_path.with_suffix(ext)
                if existing.is_file() and existing.stat().st_size > 0:
                    try:
                        from PyQt6.QtGui import QImage
                        if not QImage(str(existing)).isNull():
                            return existing
                    except Exception:
                        # Не затираем рабочий JPEG/PNG, если Qt временно недоступен.
                        if existing.suffix.lower() in {".jpg", ".png"}:
                            return existing

            cover_url = self._find_spotify_cover_url(track)
            if not cover_url:
                self.log("Spotify: URL обложки не найден; аудио сохранено без обложки.")
                return None

            headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/130 Safari/537.36"}
            request = urllib.request.Request(cover_url, headers=headers)
            with urllib.request.urlopen(request, timeout=15) as response:
                data = response.read(10 * 1024 * 1024 + 1)
            if len(data) > 10 * 1024 * 1024:
                self.log("Spotify: изображение обложки слишком большое, пропускаю.")
                return None

            if data.startswith(b"\xff\xd8\xff"):
                target = audio_path.with_suffix(".jpg")
            elif data.startswith(b"\x89PNG\r\n\x1a\n"):
                target = audio_path.with_suffix(".png")
            else:
                # QImage декодирует WebP и другие форматы, если поддерживает их
                # Qt-сборка; сохраняем в PNG, который понимает VideoFrameWidget.
                try:
                    from PyQt6.QtGui import QImage
                    image = QImage.fromData(data)
                    if image.isNull():
                        self.log("Spotify: сервер вернул данные, которые не являются изображением.")
                        return None
                    target = audio_path.with_suffix(".png")
                    if not image.save(str(target), "PNG"):
                        return None
                    self.log(f"Spotify: обложка сохранена — {target.name}")
                    return target
                except Exception as exc:
                    self.log(f"Spotify: не удалось декодировать обложку: {exc}")
                    return None
            # Сигнатура JPEG/PNG уже проверена; QImage проверяет реальное декодирование.
            try:
                from PyQt6.QtGui import QImage
                if QImage.fromData(data).isNull():
                    self.log("Spotify: файл обложки повреждён.")
                    return None
            except ImportError:
                pass
            target.write_bytes(data)
            self.log(f"Spotify: обложка сохранена — {target.name}")
            return target
        except Exception as exc:  # обложка необязательна, аудиозагрузка должна завершаться
            self.log(f"Spotify: обложку не удалось получить: {exc}")
            return None

    def _download_spotify_audio(self, tracks: list[dict]) -> tuple[int, int]:
        """Ищет аудиоверсии треков по метаданным Spotify и извлекает MP3 из найденных видео.

        Не обращается к защищённому аудиопотоку Spotify: поиск выполняется по названию
        и исполнителю в YouTube через yt-dlp. Используйте только для материалов,
        которые разрешено скачивать.
        """
        self.folder.mkdir(parents=True, exist_ok=True)
        self.total_videos = len(tracks)
        self.finished_videos = 0
        self.stats.emit(0.0, 0, len(tracks))
        self.queue_items.emit([
            {"id": f"spotify-{i}", "title": f"{t.get('artists', '')} - {t.get('name', 'Трек')}".strip(" -")}
            for i, t in enumerate(tracks, 1)
        ])
        ok = 0
        failed = 0
        for i, track in enumerate(tracks, 1):
            self._checkpoint()
            title = str(track.get("name") or "Трек").strip()
            artist_value = track.get("artists") or ""
            if isinstance(artist_value, list):
                artist = ", ".join(str(a) for a in artist_value if a)
            else:
                artist = str(artist_value).strip()
            query = " ".join(part for part in (artist, title) if part).strip()
            item_id = f"spotify-{i}"
            label = f"{artist} - {title}".strip(" -")
            if self.is_item_cancelled(item_id):
                self.item_update.emit(item_id, 0.0, "Отменено")
                continue
            self.status.emit(f"Spotify: поиск {i}/{len(tracks)} — {title}")
            self.item_update.emit(item_id, 0.0, "Поиск аудио…")
            self.log(f"[Spotify {i}/{len(tracks)}] Ищу: {label}")
            attempt = DownloadAttempt(self, item_id)
            self._attempts[item_id] = attempt
            try:
                # Приоритет №1 — SpotiSaver. Только если он не вернул пригодный файл,
                # переходим к поиску YouTube, а затем SoundCloud.
                try:
                    self.item_update.emit(item_id, 5.0, "SpotiSaver: пробую основной источник…")
                    spotisaver_path = self._download_spotisaver_track(track, title, artist, item_id)
                    self._save_spotify_cover(track, spotisaver_path)
                    attempt.publish()
                    self._set_item_detail(item_id, "finalizing", percent=None, eta=None)
                    attempt.commit()
                    ok += 1
                    self.finished_videos += 1
                    self.item_update.emit(item_id, 100.0, f"Готово · {self.spotify_format.upper()}")
                    self.log(f"[OK] Spotify: {spotisaver_path.name} (источник: SpotiSaver)")
                    self.stats.emit(0.0, self.finished_videos, len(tracks))
                    continue
                except Exception as spotisaver_first_error:
                    self._checkpoint(item_id)
                    self.log(f"Spotify: SpotiSaver не сработал, перехожу к YouTube: {spotisaver_first_error}")

                # Берём несколько результатов, а не первый попавшийся: одинаковые
                # названия песен часто принадлежат разным исполнителям.
                # Не глушим предупреждения YouTube: иначе challenge/ограничения
                # могут выглядеть как обычный пустой результат поиска.
                owner = self
                class SpotifySearchLogger:
                    def debug(self, message):
                        # Полный debug yt-dlp слишком шумный; сохраняем только
                        # диагностические строки, связанные с поиском/ограничениями.
                        text = str(message or "")
                        lowered = text.lower()
                        if any(token in lowered for token in (
                            "youtube:search", "soundcloud:search", "http error", "challenge", "captcha",
                            "429", "403", "401", "sign in", "not a bot", "extracting url",
                        )):
                            return
                    def warning(self, message):
                        owner.log("yt-dlp предупреждение: " + str(message or ""))
                    def error(self, message):
                        owner.log("yt-dlp ошибка: " + str(message or ""))

                search_opts = {
                    "quiet": True, "no_warnings": False, "noplaylist": True,
                    "skip_download": True, "logger": SpotifySearchLogger(),
                    **self.ytdlp_auth_options(),
                }
                # YouTube Search иногда не возвращает результаты для запроса в кавычках
                # или с суффиксом official audio. Пробуем несколько вариантов независимо:
                # ошибка одного запроса не должна отменять остальные попытки.
                search_queries = []
                if artist and title:
                    search_queries.extend([
                        f"ytsearch10:{artist} - {title}",
                        f'ytsearch10:"{title}" "{artist}"',
                        f"ytsearch10:{title} {artist}",
                        f"ytsearch10:{artist} {title} official audio",
                        f"ytsearch10:{title} topic {artist}",
                        # Используем только поддерживаемый префикс ytsearch.
                        f"ytsearch10:{title} - {artist} audio",
                    ])

                    # Для некоторых русскоязычных/стилизованных релизов поиск YouTube
                    # возвращает пустой список по кириллице, но находит транслитерацию.
                    # Делаем простую транслитерацию без внешних зависимостей.
                    translit_map = {
                        "а":"a", "б":"b", "в":"v", "г":"g", "д":"d", "е":"e",
                        "ё":"yo", "ж":"zh", "з":"z", "и":"i", "й":"y", "к":"k",
                        "л":"l", "м":"m", "н":"n", "о":"o", "п":"p", "р":"r",
                        "с":"s", "т":"t", "у":"u", "ф":"f", "х":"kh", "ц":"ts",
                        "ч":"ch", "ш":"sh", "щ":"shch", "ъ":"", "ы":"y", "ь":"",
                        "э":"e", "ю":"yu", "я":"ya",
                    }
                    def transliterate(text):
                        out = []
                        for char in str(text or "").lower():
                            out.append(translit_map.get(char, char))
                        return re.sub(r"\s+", " ", "".join(out)).strip()

                    artist_latin = transliterate(artist)
                    title_latin = transliterate(title)
                    latin_queries = [
                        f"ytsearch10:{artist_latin} {title_latin}",
                        f"ytsearch10:{title_latin} {artist_latin}",
                        f"ytsearch10:{title_latin} official audio",
                    ]
                    for latin_query in latin_queries:
                        if latin_query not in search_queries:
                            search_queries.append(latin_query)

                    # Дополнительный каталог: SoundCloud. scsearch поддерживается yt-dlp
                    # и часто находит независимые релизы/ремиксы, отсутствующие в YouTube.
                    # Берём те же варианты написания, чтобы не зависеть от кириллицы.
                    soundcloud_queries = [
                        f"scsearch10:{artist} {title}",
                        f"scsearch10:{title} {artist}",
                    ]
                    if artist_latin and title_latin:
                        soundcloud_queries.extend([
                            f"scsearch10:{artist_latin} {title_latin}",
                            f"scsearch10:{title_latin} {artist_latin}",
                        ])
                    for soundcloud_query in soundcloud_queries:
                        if soundcloud_query not in search_queries:
                            search_queries.append(soundcloud_query)
                else:
                    search_queries.append("ytsearch10:" + query)
                candidates = []
                seen_ids = set()
                search_errors = []
                self.log(
                    f"Spotify: yt-dlp {getattr(yt_dlp.version, '__version__', 'версия неизвестна')}; "
                    f"Deno: {shutil.which('deno') or 'не найден'}; проверяю {len(search_queries)} вариантов поиска."
                )
                with yt_dlp.YoutubeDL(search_opts) as ydl:
                    for search_query in search_queries:
                        self._checkpoint(item_id)
                        try:
                            search_info = ydl.extract_info(search_query, download=False)
                        except Exception as search_exc:
                            search_errors.append(f"{search_query}: {search_exc}")
                            continue
                        entries = list(flatten(search_info.get("entries"))) if search_info else []
                        self.log(f"Spotify: запрос {search_query!r} — найдено результатов: {len(entries)}.")
                        for entry in entries:
                            if not entry:
                                continue
                            key = str(entry.get("id") or entry.get("webpage_url") or entry.get("url") or "")
                            if key and key not in seen_ids:
                                seen_ids.add(key)
                                candidate_entry = dict(entry)
                                candidate_entry["_spotify_source"] = "soundcloud" if search_query.startswith("scsearch") else "youtube"
                                candidates.append(candidate_entry)
                if not candidates:
                    detail = (" Ошибки запросов: " + " | ".join(search_errors[:3])) if search_errors else ""
                    self.log("Spotify: YouTube/SoundCloud не дали результатов; пробую резервный источник SpotiSaver без браузера.")

                def norm_match(value):
                    value = html_lib.unescape(str(value or "")).lower().replace("ё", "е")
                    value = re.sub(r"\[[^]]*\]|\([^)]*\)|【[^】]*】", " ", value)
                    value = re.sub(r"[^0-9a-zа-я]+", " ", value)
                    return " ".join(value.split())

                # Сопоставляем латинское написание Spotify с кириллическим именем
                # исполнителя в заголовке/канале YouTube. Простого сравнения строк
                # недостаточно: Parfjonov, Parfyonov и Парфёнов — варианты одного имени.
                match_translit_map = {
                    "а":"a", "б":"b", "в":"v", "г":"g", "д":"d", "е":"e",
                    "ё":"yo", "ж":"zh", "з":"z", "и":"i", "й":"y", "к":"k",
                    "л":"l", "м":"m", "н":"n", "о":"o", "п":"p", "р":"r",
                    "с":"s", "т":"t", "у":"u", "ф":"f", "х":"kh", "ц":"ts",
                    "ч":"ch", "ш":"sh", "щ":"shch", "ъ":"", "ы":"y", "ь":"",
                    "э":"e", "ю":"yu", "я":"ya",
                }
                def latin_match(value):
                    normalized = norm_match(value)
                    return norm_match("".join(match_translit_map.get(ch, ch) for ch in normalized))

                def artist_token_match(wanted_tokens, candidate_tokens):
                    if not wanted_tokens:
                        return False
                    # Допускаем небольшие различия транслитерации, но требуем
                    # совпадения каждого значимого токена, чтобы не брать чужого артиста.
                    for wanted_token in wanted_tokens:
                        if wanted_token in candidate_tokens:
                            continue
                        if len(wanted_token) < 4:
                            return False
                        if not any(
                            len(candidate_token) >= 4
                            and difflib.SequenceMatcher(None, wanted_token, candidate_token).ratio() >= 0.82
                            for candidate_token in candidate_tokens
                        ):
                            return False
                    return True

                wanted_title = norm_match(title)
                wanted_artist = norm_match(artist)
                wanted_artist_tokens = wanted_artist.split()
                wanted_title_tokens = set(wanted_title.split())
                ranked = []
                for entry in candidates:
                    entry_title = norm_match(entry.get("title", ""))
                    uploader = norm_match(entry.get("artist") or entry.get("uploader") or entry.get("channel") or "")
                    combined = f"{entry_title} {uploader}".strip()
                    title_tokens = set(entry_title.split())
                    combined_tokens = set(combined.split())
                    latin_combined_tokens = set(latin_match(combined).split())
                    title_hits = len(wanted_title_tokens & title_tokens) / max(1, len(wanted_title_tokens))
                    title_exact = bool(wanted_title and (wanted_title in entry_title or entry_title in wanted_title))
                    artist_exact = bool(wanted_artist and (
                        wanted_artist in combined or wanted_artist in uploader
                        or artist_token_match(wanted_artist_tokens, combined_tokens)
                        or artist_token_match(wanted_artist_tokens, latin_combined_tokens)
                    ))
                    artist_hits = sum(
                        1 for token in wanted_artist_tokens
                        if token in combined_tokens or token in latin_combined_tokens
                        or any(
                            len(token) >= 4 and len(candidate_token) >= 4
                            and difflib.SequenceMatcher(None, token, candidate_token).ratio() >= 0.82
                            for candidate_token in (combined_tokens | latin_combined_tokens)
                        )
                    ) / max(1, len(wanted_artist_tokens))
                    # Название обязательно должно совпадать, а исполнитель — не быть явно другим.
                    score = title_hits * 0.55 + (0.25 if title_exact else 0.0) + (0.45 if artist_exact else 0.0)
                    if wanted_artist and not artist_exact and artist_hits < 0.5:
                        score -= 0.7
                    ranked.append((score, title_hits, artist_exact, entry))
                # Источник важнее небольших различий score: сначала проверяем
                # подходящие результаты YouTube, и лишь при их недоступности — SoundCloud.
                ranked.sort(
                    key=lambda item: (2 if item[3].get("_spotify_source") == "youtube" else 1, item[0]),
                    reverse=True,
                )
                downloaded_ok = False
                candidate_failures = []
                for candidate_score, candidate_title_hits, candidate_artist_exact, candidate in ranked:
                    self._checkpoint(item_id)
                    if candidate_title_hits < 0.6 or candidate_score < 0.75 or (wanted_artist and not candidate_artist_exact):
                        continue
                    try:
                        media_url = candidate.get("webpage_url") or candidate.get("url")
                        video_id = str(candidate.get("id") or i)
                        self.item_update.emit(item_id, 5.0, "Скачивание аудио…")
                        def progress_hook(d, _id=item_id, _title=title):
                            self._checkpoint()
                            if d.get("status") == "downloading":
                                total = d.get("total_bytes") or d.get("total_bytes_estimate") or 0
                                pct = 5.0 + 90.0 * (d.get("downloaded_bytes", 0) / total if total else 0)
                                self.item_update.emit(_id, min(pct, 95.0), "Скачивание аудио…")
                            elif d.get("status") == "finished":
                                self.item_update.emit(_id, 96.0, f"Преобразование в {self.spotify_format.upper()}…")
                        # Скачиваем в отдельную временную папку, затем даём файлу имя строго
                        # по метаданным Spotify, а не по случайному заголовку YouTube.
                        with tempfile.TemporaryDirectory(prefix=".yamifm_spotify_", dir=str(attempt.directory)) as temp_dir:
                            audio_opts = {
                                "format": "bestaudio/best",
                                "outtmpl": str(Path(temp_dir) / "%(id)s.%(ext)s"),
                                "windowsfilenames": True, "noplaylist": True,
                                "quiet": True, "noprogress": True, "retries": 3,
                                "socket_timeout": 12, "progress_hooks": [self.make_hook(item_id)],
                                "postprocessor_hooks": [self.make_post_hook(item_id)],
                                "postprocessors": [{"key": "FFmpegExtractAudio", "preferredcodec": self.spotify_format,
                                                    "preferredquality": self.spotify_bitrate if self.spotify_format == "mp3" else "0"}],
                                **self.ytdlp_auth_options(),
                            }
                            # Частота дискретизации из общих настроек не применяется к Spotify.
                            with DownloadYoutubeDL(audio_opts, self, item_id, attempt) as ydl:
                                ydl.download([media_url])
                            downloaded_audio = Path(temp_dir) / f"{video_id}.{self.spotify_format}"
                            if not downloaded_audio.is_file():
                                found_audio = list(Path(temp_dir).glob(f"*.{self.spotify_format}"))
                                if not found_audio:
                                    raise RuntimeError(f"yt-dlp завершился, но итоговый файл {self.spotify_format.upper()} не найден")
                                downloaded_audio = found_audio[0]
                            safe_artist = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", artist).strip(" .") or "Неизвестный исполнитель"
                            safe_title = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", title).strip(" .") or "Без названия"
                            base_name = f"{safe_artist[:90]} - {safe_title[:90]}"
                            final_path = attempt.media / f"{base_name}.{self.spotify_format}"
                            copy_index = 2
                            while final_path.exists():
                                final_path = attempt.media / f"{base_name} ({copy_index}).{self.spotify_format}"
                                copy_index += 1
                            shutil.move(str(downloaded_audio), str(final_path))
                            # Обложка сохраняется рядом с аудио; плеер автоматически покажет её.
                            self._save_spotify_cover(track, final_path)
                        downloaded_ok = True
                        break
                    except Exception as candidate_exc:
                        self._checkpoint(item_id)
                        candidate_name = str(candidate.get("title") or candidate.get("id") or "неизвестный результат")
                        candidate_failures.append(f"{candidate_name}: {candidate_exc}")
                        self.log(f"Spotify: пропускаю недоступный результат {candidate_name!r}: {candidate_exc}")
                if not downloaded_ok:
                    preview = "; ".join(
                        f"{e.get('title', '?')} — {e.get('uploader') or e.get('channel') or '?'}"
                        for _score, _hits, _artist_ok, e in ranked[:3]
                    )
                    detail = (" Ошибки кандидатов: " + " | ".join(candidate_failures[:3])) if candidate_failures else ""
                    raise RuntimeError(
                        "Не удалось скачать подходящий результат из SpotiSaver, YouTube или SoundCloud. "
                        "Проверь сетевые ограничения и доступность источников. "
                        f"Кандидаты: {preview}.{detail}"
                    )
                attempt.publish()
                self._set_item_detail(item_id, "finalizing", percent=None, eta=None)
                attempt.commit()
                ok += 1
                self.finished_videos += 1
                self.item_update.emit(item_id, 100.0, f"Готово · {self.spotify_format.upper()}")
                self.log(f"[OK] Spotify: {final_path.name} (источник: {media_url})")
            except DownloadCancelled:
                if self._stop_event.is_set():
                    break
            except Exception as exc:  # noqa: BLE001
                failed += 1
                self.item_update.emit(item_id, 0.0, f"Ошибка: {str(exc)[:90]}")
                self.log(f"[ошибка Spotify] {label}: {exc}")
            finally:
                self._cleanup_attempt(attempt)
                self._attempts.pop(item_id, None)
                if not attempt.record["committed"] and (self._stop_event.is_set() or self.is_item_cancelled(item_id)):
                    self._set_item_detail(item_id, "cancelled", percent=None, eta=None)
                    self.item_update.emit(item_id, 0.0, "Отменено")
            self.stats.emit(0.0, self.finished_videos, len(tracks))
        return ok, failed

    def get_entries(self):
        target = download_url(self.single_url or self.url, self.source, "single" if self.single_url else "playlist")
        if self.single_url:
            self.single_url = target
        else:
            self.url = target
        if self.source == "direct":
            check_direct_video_url(target, self._direct_cookie_file())
        if self.single_url:
            self.status.emit("получаю информацию о ссылке...")
            self.log(f"Один элемент: {self.single_url}")
            if self.source == "spotify":
                raise ValueError("Spotify поддерживается как источник метаданных: вставь ссылку на трек, альбом или плейлист.")
            with yt_dlp.YoutubeDL({"quiet": True, "noplaylist": True, **self.ytdlp_auth_options()}) as ydl:
                info = ydl.extract_info(self.single_url, download=False)
            if not info:
                return None
            self._check_download_info(info)
            if info.get("entries") or not info.get("id"):
                return None  # требуется ссылка на отдельный ролик/публикацию
            return [{
                "id": info["id"],
                "title": info.get("title"),
                "webpage_url": info.get("webpage_url") or self.single_url,
                "source_url": info.get("webpage_url") or self.single_url,
            }]

        self.status.emit("получаю список публикаций...")
        self.log(f"Получаю список: {self.url}")
        with yt_dlp.YoutubeDL({
            "extract_flat": "in_playlist",
            "quiet": True,
            "ignoreerrors": True,
            **self.ytdlp_auth_options(),
        }) as ydl:
            info = ydl.extract_info(self.url, download=False)
        if not info:
            return []
        self._check_download_info(info)
        entries = list(flatten(info.get("entries")))
        if entries:
            return entries
        # В поле профиля иногда вставляют одиночный ролик вместо ссылки на аккаунт.
        if info.get("id"):
            return [{
                "id": info["id"],
                "title": info.get("title"),
                "webpage_url": info.get("webpage_url") or self.url,
                "source_url": info.get("webpage_url") or self.url,
            }]
        return []

    # ---------- загрузка ----------
    def _run_job(self):
        started = time.monotonic()
        try:
            self._checkpoint()
            if self.source == "spotify":
                download_url(self.single_url or self.url, self.source)
            elif not self.retry_entries:
                download_url(self.single_url or self.url, self.source)
            spotify_kind, _spotify_id = spotify_url_kind(self.single_url or "")
            if self.source == "spotify" and self.single_url and spotify_kind in {"track", "album", "playlist"}:
                self.status.emit("Spotify: читаю метаданные…")
                if spotify_kind == "track":
                    title, artist = self._spotify_track_metadata(self.single_url)
                    self.log(f"Метаданные Spotify: исполнитель={artist or '[не определён]'}; трек={title}")
                    if not artist:
                        raise RuntimeError(
                            "Spotify не вернул надёжное имя исполнителя. Скачивание остановлено, "
                            "чтобы не выбрать другую песню с таким же названием."
                        )
                    collection_title = f"{title} - {artist}"
                    tracks = [{"name": title, "artists": artist, "url": self.single_url.split("?", 1)[0]}]
                else:
                    collection_title, tracks = self._spotify_collection_metadata(self.single_url)
                output, csv_output = self._write_spotify_tracklist(self.single_url, collection_title, tracks)
                self.spotify_export_path = str(output)
                self.spotify_export_csv_path = str(csv_output)
                self.spotify_export_count = len(tracks)
                self.log(f"Spotify: TXT сохранён: {output}")
                self.log(f"Spotify: CSV сохранён: {csv_output}")
                self.status.emit(f"Spotify: список готов, начинаю поиск аудио ({len(tracks)} треков)…")
                ok, failed = self._download_spotify_audio(tracks)
                # Экспортные списки TXT/CSV были созданы только для этой операции.
                # Удаляем именно эти файлы (не любые документы из папки загрузки).
                for generated_path in (self.spotify_export_path, self.spotify_export_csv_path):
                    if generated_path:
                        try:
                            Path(generated_path).unlink(missing_ok=True)
                        except OSError as cleanup_error:
                            self.log(f"Не удалось удалить временный файл {generated_path}: {cleanup_error}")
                self.spotify_export_path = ""
                self.spotify_export_csv_path = ""
                self.log(f"Spotify: аудио готово {ok}/{len(tracks)}, ошибок {failed}.")
                if failed:
                    self.status.emit(f"Spotify: скачано {ok} из {len(tracks)}; ошибок: {failed}")
                else:
                    self.status.emit(f"Spotify: скачано {ok} трек(ов) в MP3")
                self.done.emit()
                return
            browser = self._cookie_browser_in_use()
            if browser:
                self.status.emit(ui_text("Читаю cookies браузера…", "Reading browser cookies…"))
                check_browser_cookies(browser)  # понятная ошибка вместо общего «failed to load cookies»
            if self._clip_invalid:
                raise DownloadSourceError(ui_text("Конец фрагмента должен быть позже начала.", "The clip end must be later than its start."))
            if self.clip:
                self._validate_clip(None)
            entries = self.retry_entries if self.retry_entries else self.get_entries()
            if entries is None:
                self.log("Это ссылка на канал или плейлист. Вставьте ссылку на одно видео.")
                self.status.emit("это не ссылка на видео")
                self.done.emit()
                return

            have = downloaded_ids(self.folder, clip_tag(self.clip))
            # Сравниваем именно ID ролика, а не профиль качества/метку:
            # один и тот же ролик не должен скачиваться повторно из-за смены формата.
            # Убираем повторы в самом списке канала по ID, сохраняя порядок.
            valid_entries = []
            seen_ids = set()
            for entry in entries:
                vid = entry.get("id") if entry else None
                if vid and vid not in seen_ids:
                    seen_ids.add(vid)
                    valid_entries.append(entry)
            available = valid_entries if self.retry_entries else [e for e in valid_entries if e["id"] not in have]
            skipped = len(valid_entries) - len(available)
            todo = available if (self.single_url or self.retry_entries) else available[: self.count]
            if not self.single_url:
                self.log(f"Уже есть в папке: {skipped}; новых найдено: {len(available)}.")

            self.total_videos = len(todo)
            if not todo:
                self.log(f"Проверено {len(entries)} видео канала; новых для загрузки не найдено.")
                self.status.emit("новых видео не найдено")
                self.done.emit()
                return

            self.queue_items.emit([{ "id": e["id"], "title": e.get("title") or e["id"], "source": self.source } for e in todo])
            self.log(
                f"Найдено {len(valid_entries)}, к загрузке {len(todo)} "
                f"(одновременно {self.parallel_videos} видео x {self.fragment_threads} потоков) "
                f"-> {self.folder}"
            )
            self.log(f"Формат: {self.fmt}")
            self.status.emit("скачиваю...")
            self.stats.emit(0.0, 0, len(todo))

            self._pending_queue = list(todo)
            def consume_queue(_worker_index):
                while not self._stop_event.is_set():
                    with self.lock:
                        if not self._pending_queue:
                            return
                        entry = self._pending_queue.pop(0)
                    self.fetch(entry)
            with ThreadPoolExecutor(max_workers=min(self.parallel_videos, max(1, len(todo)))) as pool:
                list(pool.map(consume_queue, range(min(self.parallel_videos, len(todo)))))

            elapsed = max(time.monotonic() - started, 0.001)
            self.log(
                f"Готово: {self.finished_videos} из {len(todo)} видео, "
                f"{fmt_size(self.total_bytes)} за {elapsed:.0f} с, "
                f"средняя скорость {fmt_speed(self.total_bytes / elapsed)}"
            )
            self.stats.emit(0.0, self.finished_videos, len(todo))
            if self._failed:
                self.status.emit(f"готово, ошибок: {len(self._failed)}")
            else:
                self.status.emit("готово")
        except Exception as e:  # noqa: BLE001
            self.error_text = "" if isinstance(e, DownloadCancelled) else redact_diagnostic(e)
            self.log(f"ОШИБКА: {e}")
            if self.source == "spotify" and spotify_url_kind(self.single_url or "")[0] in {"album", "playlist"}:
                self.status.emit(f"Spotify: {e}")
            else:
                self.status.emit(ui_text("Ошибка: ", "Error: ") + str(e))
        self.done.emit()

    def make_hook(self, vid):
        def hook(data):
            self._checkpoint(vid)
            if getattr(_DOWNLOAD_PROCESS_CONTEXT, "format_probe", False):
                return
            info = data.get("info_dict") or {}
            try:
                duration = float(info.get("duration") or 0)
                if math.isfinite(duration) and duration > 0:
                    with self.lock:
                        self._item_states.setdefault(str(vid), {})["duration"] = duration
            except (ValueError, TypeError):
                pass
            status = data.get("status")
            if status == "downloading":
                total = data.get("total_bytes") or data.get("total_bytes_estimate") or 0
                downloaded = data.get("downloaded_bytes") or 0
                component_key = str(data.get("filename") or (data.get("info_dict") or {}).get("format_id") or "media")
                with self.lock:
                    self._stream_bytes.setdefault(vid, {})[component_key] = downloaded
                    self._stream_totals.setdefault(vid, {})[component_key] = total
                    self._stream_estimates.setdefault(vid, {})[component_key] = not bool(data.get("total_bytes")) and bool(total)
                    downloaded = sum(self._stream_bytes[vid].values())
                    totals = self._stream_totals[vid].values()
                    total = sum(totals) if all(totals) else 0
                percent = min(100.0, downloaded / total * 100) if total else None
                speed = max(0.0, float(data.get("speed") or 0))
                info = data.get("info_dict") or {}
                self._set_item_detail(vid, "downloading", percent=percent, downloaded=downloaded, total=total,
                                      speed=speed, eta=data.get("eta"), estimated=any(self._stream_estimates.get(vid, {}).values()),
                                      source=str(info.get("extractor_key") or info.get("extractor") or self.source),
                                      component=str(info.get("format_id") or ""))
                with self.lock:
                    self.active[vid] = (percent or 0.0, speed)
                    self.render()
            elif status == "finished":
                with self.lock:
                    component_key = str(data.get("filename") or (data.get("info_dict") or {}).get("format_id") or "media")
                    if (vid, component_key) not in self._counted_streams:
                        self.total_bytes += data.get("downloaded_bytes") or 0
                        self._counted_streams.add((vid, component_key))
                    self.active[vid] = (100, 0)
                self._set_item_detail(vid, "waiting", percent=None, speed=0, eta=None,
                                      downloaded=sum(self._stream_bytes.get(vid, {}).values()) or data.get("downloaded_bytes") or 0,
                                      total=sum(self._stream_totals.get(vid, {}).values()) or data.get("total_bytes") or data.get("downloaded_bytes") or 0)
        return hook

    def cancel_item(self, vid: str):
        with self.lock:
            if self._item_states.get(str(vid), {}).get("stage") == "done":
                return
            self.cancelled_items.add(str(vid))
        if not self._child_mode:
            self._send_control("cancel", id=str(vid))
        self.item_update.emit(str(vid), 0.0, "Отменяется…")

    def reorder_pending_item(self, vid: str, delta: int) -> bool:
        """Переставляет только ещё не начавшие скачиваться элементы очереди."""
        if not self._child_mode:
            if self._item_states.get(str(vid), {}).get("stage", "queued") != "queued":
                return False
            self._send_control("move", id=str(vid), delta=int(delta))
            return True
        with self.lock:
            if str(vid) in self._in_progress_ids:
                return False
            index = next((i for i, entry in enumerate(self._pending_queue)
                          if str(entry.get("id")) == str(vid)), None)
            if index is None:
                return False
            target = max(0, min(len(self._pending_queue) - 1, index + int(delta)))
            if target == index:
                return False
            entry = self._pending_queue.pop(index)
            self._pending_queue.insert(target, entry)
            return True

    def is_item_cancelled(self, vid: str) -> bool:
        with self.lock:
            return str(vid) in self.cancelled_items

    def set_paused(self, paused: bool):
        if paused:
            self.resume_event.clear()
        else:
            self.resume_event.set()
        if not self._child_mode:
            self._send_control("pause", paused=bool(paused))
        self.status.emit(ui_text("Пауза загрузок" if paused else "Загрузка продолжается", "Downloads paused" if paused else "Downloads resumed"))

    def _validate_clip(self, duration):
        """Проверяет фрагмент до любой загрузки; ошибка не повторяется и ничего не скачивает."""
        if not self.clip:
            return
        if not shutil.which("ffmpeg"):
            raise DownloadSourceError(ui_text("Для загрузки фрагмента нужен FFmpeg: он не найден.",
                                              "FFmpeg is required to download a clip and was not found."))
        start, end = self.clip
        try:
            clip_range(format_clip_time(start), format_clip_time(end) if end is not None else "", duration)
        except ValueError as exc:
            raise DownloadSourceError(str(exc)) from None

    def _clip_length(self, duration):
        if not self.clip:
            return duration
        start, end = self.clip
        total = format_number(duration)
        stop = end if end is not None else total
        if total and stop is not None:
            stop = min(stop, total)
        return max(0.0, stop - start) if stop is not None else None

    def _clip_ranges(self, info, ydl):
        """download_ranges yt-dlp: FFmpeg получает только нужный отрезок, а не всё видео."""
        self._validate_clip(info.get("duration"))
        start, end = self.clip
        yield {"start_time": start, "end_time": end if end is not None else float("inf")}

    def _friendly_failure(self, exc):
        text = str(exc)
        if self.clip and "partially downloaded" in text.lower():
            return DownloadSourceError(ui_text(
                "Источник не позволяет скачать фрагмент этого формата. Скачайте видео целиком или выберите другой формат/разрешение.",
                "The source cannot deliver a clip of this format. Download the whole video or choose another format/resolution."))
        return exc

    def choose_source_format(self, ctx, vid, ydl, metadata):
        formats = list(ctx.get("formats") or [])
        unavailable = False
        if self.clip:
            self._validate_clip(metadata.get("duration"))
        while formats:
            self._checkpoint(vid)
            selected, summary, components = select_source_formats(formats, self.video_profile, self.mode,
                self.audio_quality, self.vcodec, self.container, self._clip_length(metadata.get("duration")), self.video_resolution,
                self.overall_bitrate_mode, self.overall_bitrate_kbps, self.fps_preference)
            if self.clip:
                summary["clip"] = list(self.clip)
            # Verify only the selected resources with yt-dlp's bounded test
            # download, not hundreds of unrelated formats. Probe files stay in
            # this attempt. Progress hooks still check cancellation but do not
            # count probe bytes as a real download.
            previous = getattr(_DOWNLOAD_PROCESS_CONTEXT, "format_probe", False)
            try:
                _DOWNLOAD_PROCESS_CONTEXT.format_probe = True
                valid = {id(f) for f in ydl._check_formats(components, warning=False)}
            finally:
                _DOWNLOAD_PROCESS_CONTEXT.format_probe = previous
            rejected = {id(f) for f in components if id(f) not in valid}
            if rejected:
                unavailable = True
                formats = [f for f in formats if id(f) not in rejected]
                continue
            if unavailable: summary["warnings"].append("unavailable")
            self._set_item_detail(vid, "connecting", selection=summary, duration=self._clip_length(metadata.get("duration")),
                                  title=metadata.get("title") or self._item_states.get(str(vid),{}).get("title",str(vid)))
            yield selected
            return
        raise DownloadSourceError(ui_text("Доступные потоки не прошли проверку загрузки.", "Available streams failed the download check."))

    def fetch(self, entry):
        vid = str(entry["id"])
        title = str(entry.get("title") or vid)
        with self.lock:
            self._in_progress_ids.add(vid)
        try:
            media_url = entry.get("source_url") or entry.get("webpage_url") or entry.get("original_url")
            if not media_url:
                entry_url = entry.get("url")
                if isinstance(entry_url, str) and entry_url.startswith(("http://", "https://")):
                    media_url = entry_url
                elif self.source == "youtube":
                    media_url = f"https://www.youtube.com/watch?v={vid}"
            for attempt_number in range(1, 4):
                attempt = None
                failure = None
                completed = False
                try:
                    self._checkpoint(vid)
                    if not media_url:
                        raise DownloadSourceError("yt-dlp не вернул ссылку на публикацию")
                    media_url = download_url(media_url, self.source)
                    if self.source == "direct":
                        check_direct_video_url(media_url, self._direct_cookie_file())
                    self._checkpoint(vid)
                    attempt = DownloadAttempt(self, vid)
                    with self.lock:
                        self._attempts[vid] = attempt
                        self._stream_bytes.pop(vid, None)
                        self._stream_totals.pop(vid, None)
                        self._stream_estimates.pop(vid, None)
                    self._set_item_detail(vid, "connecting", title=title, source=self.source,
                                          percent=None, attempt=attempt_number)
                    self.log(f"[попытка {attempt_number}/3] {title}")
                    metadata = {}
                    opts = {
                        "format": lambda ctx: self.choose_source_format(ctx, vid, ydl, metadata),
                        "outtmpl": str(attempt.media / f"%(title)s [%(id)s]{self.tag_suffix}.%(ext)s"),
                        "paths": {"home": str(attempt.media), "temp": str(attempt.media)},
                        "concurrent_fragment_downloads": self.fragment_threads,
                        "windowsfilenames": True, "noplaylist": True,
                        "retries": 5, "fragment_retries": 10, "socket_timeout": 12,
                        "ratelimit": (int(self.rate_limit) * 1024 if self.rate_limit.isdigit() and int(self.rate_limit) > 0 else None),
                        "quiet": True, "noprogress": True,
                        "progress_hooks": [self.make_hook(vid)],
                        "postprocessor_hooks": [self.make_post_hook(vid)],
                        **self.ytdlp_auth_options(vid),
                    }
                    if self.clip:
                        # Отрезок скачивает FFmpeg по HTTP range/сегментам; потоки копируются без перекодирования.
                        opts["download_ranges"] = self._clip_ranges
                        opts["force_keyframes_at_cuts"] = False
                    with DownloadYoutubeDL(opts, self, vid, attempt) as ydl:
                        ydl.add_post_processor(SourceMetadataPP(ydl, lambda info: metadata.update(
                            duration=info.get("duration"), title=info.get("title"))), when="after_filter")
                        ydl.add_post_processor(SourceStreamRemuxPP(ydl, self, vid), when="post_process")
                        if self.dl_sample_rate != "0" and self.source != "spotify" and self.mode in ("audio", "both"):
                            ydl.add_post_processor(
                                AudioSampleRatePP(ydl, self.dl_sample_rate, include_video=(self.mode == "both")), when="post_process")
                        if ydl.download([media_url]):
                            raise yt_dlp.utils.DownloadError("yt-dlp returned an unsuccessful result")
                    self._checkpoint(vid)
                    attempt.publish()
                    self._set_item_detail(vid, "finalizing", percent=None, eta=None)
                    attempt.commit()
                    with self.lock:
                        self.finished_videos += 1
                        self.active.pop(vid, None)
                        self.emit_stats()
                    completed = True
                except Exception as exc:  # Includes cancellation from progress hooks.
                    failure = self._friendly_failure(exc)
                finally:
                    if attempt is not None:
                        self._cleanup_attempt(attempt)
                    with self.lock:
                        self._attempts.pop(vid, None)
                        self.active.pop(vid, None)
                if completed:
                    self.item_update.emit(vid, 100.0, "Готово")
                    self.log(f"[OK]    {title}")
                    return
                if self._stop_event.is_set() or self.is_item_cancelled(vid) or isinstance(failure, DownloadCancelled):
                    self._set_item_detail(vid, "cancelled", percent=None, eta=None)
                    self.item_update.emit(vid, 0.0, "Отменено")
                    self.log(f"[отмена] {title}")
                    return
                self.log(f"[ошибка {attempt_number}/3] {title}: {failure}")
                if attempt_number < 3 and not isinstance(failure, (DownloadSourceError, ValueError)):
                    self.item_update.emit(vid, 0.0, f"Повтор через 2 с · {attempt_number}/3")
                    for _ in range(20):
                        if self._stop_event.wait(.1) or self.is_item_cancelled(vid):
                            break
                else:
                    self._failed.append(f"{title}: {failure}")
                    failed_entry = dict(entry)
                    failed_entry.setdefault("source_url", media_url)
                    self._failed_entries.append(failed_entry)
                    self._set_item_detail(vid, "failed", percent=None, message=redact_diagnostic(failure))
                    self.item_update.emit(vid, 0.0, "Ошибка: " + redact_diagnostic(failure)[:150])
                    return
        finally:
            with self.lock:
                self._in_progress_ids.discard(vid)
                self.active.pop(vid, None)

    def _send_control(self, action, **fields):
        directory = getattr(self, "_ipc_directory", None)
        if directory is None:
            return
        try:
            with self._control_lock, (directory / "control.jsonl").open("a", encoding="utf-8") as handle:
                handle.write(json.dumps({"action": action, **fields}) + "\n")
        except OSError:
            pass

    def request_stop(self):
        self._stop_event.set()
        self.resume_event.set()
        self.requestInterruption()
        if not self._child_mode:
            self._send_control("stop")

    def _checkpoint(self, vid=None):
        while not self.resume_event.wait(.1):
            if self._stop_event.is_set() or (vid is not None and self.is_item_cancelled(vid)):
                raise DownloadCancelled("Cancelled")
        if self._stop_event.is_set() or (vid is not None and self.is_item_cancelled(vid)):
            raise DownloadCancelled("Cancelled")

    def _set_item_detail(self, vid, stage, **fields):
        now = time.monotonic()
        with self.lock:
            old = self._item_states.get(str(vid), {})
            if stage != old.get("stage") or ("processor" in fields and fields["processor"] != old.get("processor")):
                fields = {"percent": None, "eta": None, "stage_started_at": now, **fields}
            state = {**old, **fields, "id": str(vid), "stage": stage, "updated_at": now}
            self._item_states[str(vid)] = state
            last = self._detail_emitted.get(str(vid), 0)
            if stage == old.get("stage") and now - last < .25 and stage == "downloading":
                return
            self._detail_emitted[str(vid)] = now
        self.item_detail.emit(dict(state))

    def _ffmpeg_progress(self, vid, block):
        with self.lock:
            state = dict(self._item_states.get(str(vid), {}))
        phase = state.get("stage", "processing")
        if phase not in {"merging", "converting", "transcoding", "processing", "downloading", "finalizing"}:
            phase = "processing"
        elapsed = max(0, time.monotonic() - state.get("stage_started_at", time.monotonic()))
        percent = eta = None
        try:
            processed = max(0, float(block.get("out_time_us", block.get("out_time_ms", 0))) / 1_000_000)
            duration = float(state.get("duration") or 0)
            if math.isfinite(duration) and duration > 0 and math.isfinite(processed):
                percent = min(99.9, processed / duration * 100)
                speed = float(str(block.get("speed", "")).rstrip("x"))
                if math.isfinite(speed) and speed > 0 and processed > 0 and elapsed >= .25:
                    eta = max(0, (duration - processed) / speed)
        except (ValueError, TypeError):
            pass
        if block.get("progress") == "end" or (percent is not None and processed >= duration):
            phase, percent, eta = "finalizing", None, None
        self._set_item_detail(vid, phase, percent=percent, eta=eta,
                              processed_seconds=block.get("out_time_us"), speed=0)

    def _ffmpeg_duration(self, vid, command):
        with self.lock:
            if self._item_states.get(str(vid), {}).get("duration"):
                return
        ffprobe = shutil.which("ffprobe")
        if not ffprobe:
            return
        durations = []
        for index, value in enumerate(command[:-1]):
            if value != "-i":
                continue
            path = str(command[index + 1])
            if path.startswith("file:"):
                path = path[5:]
            if not Path(path).is_file():
                continue  # Never probe an additional network URL to estimate duration.
            try:
                result = run_download_command([ffprobe, "-v", "error", "-show_entries", "format=duration",
                    "-of", "default=noprint_wrappers=1:nokey=1", path],
                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=10)
                self._checkpoint(vid)
                duration = float(result.stdout.strip())
                if result.returncode == 0 and math.isfinite(duration) and duration > 0:
                    durations.append(duration)
            except (OSError, ValueError, subprocess.SubprocessError):
                continue
        if durations:
            with self.lock:
                self._item_states.setdefault(str(vid), {})["duration"] = max(durations)

    def _cleanup_attempt(self, attempt):
        errors = DownloadAttempt.cleanup_record(attempt.record)
        if errors:
            message = ui_text("Не удалось удалить файлы задачи: ", "Could not remove task files: ") + "; ".join(errors)
            self.status.emit(message)
            self.log(message)
            with self.lock:
                state = self._item_states.get(attempt.vid, {})
            self._set_item_detail(attempt.vid, state.get("stage", "cancelling"), cleanup_errors=errors, message=message)
        return errors

    def make_post_hook(self, vid):
        def hook(data):
            self._checkpoint(vid)
            processor = str(data.get("postprocessor") or "")
            if processor == "SourceMetadata": return
            status = data.get("status")
            if status in ("started", "processing"):
                key = processor.casefold()
                stage = ("merging" if "merger" in key else "transcoding" if "videoconvertor" in key or "samplerate" in key
                         else "converting" if "extractaudio" in key else "saving" if "movefiles" in key else "processing")
                self._set_item_detail(vid, stage, percent=None, speed=0, eta=None, processor=processor)
            elif status == "finished":
                self._set_item_detail(vid, "waiting", percent=None, speed=0, eta=None, processor=processor)
        return hook

    def run(self):
        if self._child_mode:
            self._run_job()
            return
        proc = None
        try:
            with tempfile.TemporaryDirectory(prefix="nop-download-") as name:
                directory = Path(name)
                if os.name != "nt":
                    os.chmod(directory, 0o700)
                self._ipc_directory = directory
                _private_write(directory / "request.dat", _pack_private(json.dumps({**self._job_arguments, "__language": LANG}).encode("utf-8")))
                _private_write(directory / "events.jsonl", b"")
                _private_write(directory / "control.jsonl", b"")
                args = ([sys.executable] if FROZEN else [sys.executable, str(Path(__file__).resolve())])
                args += ["--nop-download-job", str(directory)]
                options = {"creationflags": getattr(subprocess, "CREATE_NO_WINDOW", 0)} if os.name == "nt" else {"start_new_session": True}
                proc = subprocess.Popen(args, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                        stderr=subprocess.DEVNULL, **options)
                self._child_process = proc
                stop_started = None
                with (directory / "events.jsonl").open(encoding="utf-8") as events:
                    while True:
                        if self._stop_event.is_set():
                            if stop_started is None:
                                stop_started = time.monotonic()
                                self._send_control("stop")
                            elif time.monotonic() - stop_started > 1:
                                stop_owned_process(proc)
                        line = events.readline(8 * 1024 * 1024 + 1)
                        if len(line) > 8 * 1024 * 1024:
                            raise RuntimeError("Download event exceeds the size limit")
                        if line:
                            data = json.loads(line)
                            kind, values = data["kind"], data["args"]
                            if kind == "summary":
                                summary = values[0]
                                self.finished_videos = int(summary.get("finished_videos", 0))
                                self.total_videos = int(summary.get("total_videos", 0))
                                self.total_bytes = int(summary.get("total_bytes", 0))
                                self.error_text = str(summary.get("error_text", ""))
                                self._failed_entries = list(summary.get("failed_entries", []))
                            elif kind == "tokens":
                                tokens = json.loads(_unpack_private(base64.b64decode(values[0])))
                                self.spotify_tokens_updated.emit(tokens)
                            elif kind == "detail":
                                self._item_states[str(values[0]["id"])] = dict(values[0])
                                self.item_detail.emit(values[0])
                            elif kind == "attempt":
                                record = values[0]
                                self._attempt_records[record["directory"]] = record
                            elif kind in {"status", "stats", "queue", "item"}:
                                signal = {"status": self.status, "stats": self.stats,
                                          "queue": self.queue_items, "item": self.item_update}[kind]
                                signal.emit(*values)
                            continue
                        if proc.poll() is not None:
                            break
                        self._stop_event.wait(.05) if not self._stop_event.is_set() else time.sleep(.02)
                proc.wait()
                if proc.returncode and not self._stop_event.is_set() and not self.error_text:
                    failure_path = directory / "failure.txt"
                    detail = failure_path.read_text(encoding="utf-8")[:4000] if failure_path.is_file() else str(proc.returncode)
                    self.error_text = ui_text("Процесс загрузки завершился с ошибкой: ", "Download process exited with code: ") + redact_diagnostic(detail)
        except Exception as exc:
            self.error_text = redact_diagnostic(exc)
            self.status.emit(self.error_text)
        finally:
            if proc is not None and proc.poll() is None:
                try:
                    stop_owned_process(proc)
                except (OSError, subprocess.SubprocessError):
                    pass
            self._child_process = None
            self._ipc_directory = None
            # The process has exited and FFmpeg handles have been released. Read the
            # per-attempt journals, including a publication interrupted by forced stop.
            for record in self._attempt_records.values():
                errors = DownloadAttempt.cleanup_record(record)
                if errors:
                    message = ui_text("Не удалось удалить файлы задачи: ", "Could not remove task files: ") + "; ".join(errors)
                    self.status.emit(message)
                    self._set_item_detail(record["id"], "done" if record.get("committed") else "cancelled" if self._stop_event.is_set() or self.is_item_cancelled(record["id"]) else "failed",
                                          percent=None, cleanup_errors=errors, message=message)
            self.done.emit()

    def make_logger(self, vid=None):
        owner = self
        class Logger:
            def debug(self, _message):
                pass
            def warning(self, message):
                text = redact_diagnostic(message)
                owner.status.emit(text)
                if vid is not None and re.search(r"retry|reconnect|HTTP Error", text, re.I):
                    owner._set_item_detail(vid, "retry", percent=None, message=text)
            def error(self, message):
                text = redact_diagnostic(message)
                owner.status.emit(text)
                if vid is not None:
                    owner._set_item_detail(vid, "retry", percent=None, message=text)
        return Logger()


class VideoCompatibilityThread(QThread):
    """Резервное перекодирование проблемного видео в H.264/AAC для Qt Multimedia."""
    finished_file = pyqtSignal(str, str)

    def __init__(self, source: Path, parent=None):
        super().__init__(parent)
        self.source = source

    def run(self):
        proc = None
        partial = None
        try:
            if self.isInterruptionRequested():
                return
            ffmpeg = shutil.which("ffmpeg")
            if not ffmpeg:
                raise RuntimeError("FFmpeg not found")
            cache = DATA_DIR / "converted"
            cache.mkdir(parents=True, exist_ok=True)
            stamp = self.source.stat()
            key = hashlib.sha256((str(self.source.resolve()) + str(stamp.st_size) + str(stamp.st_mtime_ns)).encode()).hexdigest()[:24]
            target = cache / (key + "_h264.mp4")
            if target.is_file() and target.stat().st_size:
                self.finished_file.emit(str(target), "")
                return
            partial = target.with_name(target.stem + ".partial.mp4")
            command = [ffmpeg, "-nostdin", "-y", "-hide_banner", "-loglevel", "error", "-i", str(self.source),
                       "-map", "0:v:0", "-map", "0:a?", "-c:v", "libx264", "-preset", "veryfast",
                       "-crf", "22", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k", "-movflags", "+faststart", str(partial)]
            options = {"creationflags": getattr(subprocess, "CREATE_NO_WINDOW", 0)} if os.name == "nt" else {"start_new_session": True}
            with tempfile.TemporaryFile() as error_file:
                proc = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=error_file, **options)
                self._process = proc
                while proc.poll() is None:
                    if self.isInterruptionRequested():
                        stop_owned_process(proc)
                        return
                    self.msleep(50)
                if proc.returncode or not partial.is_file() or not partial.stat().st_size:
                    error_file.seek(max(0, error_file.tell()-4096))
                    raise RuntimeError(error_file.read(4096).decode("utf-8", "replace"))
            os.replace(partial, target)
            self.finished_file.emit(str(target), "")
        except Exception as exc:
            if not self.isInterruptionRequested():
                self.finished_file.emit("", redact_diagnostic(exc))
        finally:
            if proc is not None and proc.poll() is None:
                stop_owned_process(proc)
            self._process = None
            if partial is not None:
                partial.unlink(missing_ok=True)

    def request_stop(self):
        self.requestInterruption()


class EqualizerAudioThread(QThread):
    """Потоковый аудиотракт FFmpeg -> QAudioSink с десятиполосным EQ."""
    failed = pyqtSignal(str)

    def __init__(self, path: Path, start_ms: int, gains: list[float], volume: float, frequencies=None, parent=None):
        super().__init__(parent)
        self.path = str(path)
        self.start_ms = max(0, int(start_ms))
        self.gains = list(gains)
        self.frequencies = list(frequencies or EQ_FREQUENCIES)
        self.volume = max(0.0, min(1.0, float(volume)))
        self._stop_requested = threading.Event()
        self._pause_requested = threading.Event()
        self._process = None
        self._sink = None
        self.clock_ms = self.start_ms     # позиция трека по реально проигранному звуку (главные часы плеера)
        self.started = False              # звук уже пошёл на устройство
        self.ended = False                # поток полностью закончился

    def stop_audio(self):
        self._stop_requested.set()
        self._pause_requested.clear()
        proc = self._process
        if proc is not None and proc.poll() is None:
            try:
                proc.terminate()
            except OSError:
                pass

    def set_paused(self, paused: bool):
        if paused:
            self._pause_requested.set()
        else:
            self._pause_requested.clear()

    def _update_clock(self, sink):
        try:
            processed = sink.processedUSecs()
        except Exception:  # noqa: BLE001
            return
        if processed > 0:
            self.started = True
        self.clock_ms = self.start_ms + processed // 1000

    def _drain(self, sink):
        """Конец потока: даём доиграть звук, оставшийся в буфере (иначе обрывается последняя полсекунды)."""
        deadline = time.monotonic() + 1.0
        while not self._stop_requested.is_set() and time.monotonic() < deadline:
            self._update_clock(sink)
            try:
                if sink.bytesFree() >= sink.bufferSize() - 2048:
                    break
            except Exception:  # noqa: BLE001
                break
            self.msleep(20)

    def set_volume(self, volume: float):
        self.volume = max(0.0, min(1.0, float(volume)))

    def run(self):
        sink = None
        proc = None
        stderr_thread = None
        error_tail = collections.deque(maxlen=8)
        try:
            ffmpeg = shutil.which("ffmpeg")
            if not ffmpeg:
                self.failed.emit("FFmpeg не найден. Установите FFmpeg или положите ffmpeg.exe рядом с программой.")
                return
            filters = []
            for freq, gain in zip(self.frequencies, self.gains):
                if gain:
                    filters.append(f"equalizer=f={freq}:t=q:w=1:g={float(gain):.2f}")
            af = ",".join(filters) if filters else "anull"
            cmd = [ffmpeg, "-nostdin", "-hide_banner", "-loglevel", "error"]
            if self.start_ms:
                cmd += ["-ss", f"{self.start_ms / 1000:.3f}"]
            cmd += ["-i", self.path, "-vn", "-sn", "-dn", "-af", af,
                    "-ac", "2", "-ar", "48000", "-f", "s16le", "-acodec", "pcm_s16le", "pipe:1"]
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                    stdin=subprocess.DEVNULL, bufsize=0,
                                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            self._process = proc
            def drain_errors():
                try:
                    for chunk in iter(lambda: proc.stderr.read(4096), b""):
                        error_tail.append(chunk)
                except (OSError, ValueError):
                    pass
            stderr_thread = threading.Thread(target=drain_errors, name="NOP EQ stderr", daemon=True)
            stderr_thread.start()

            fmt = QAudioFormat()
            fmt.setSampleRate(48000)
            fmt.setChannelCount(2)
            fmt.setSampleFormat(QAudioFormat.SampleFormat.Int16)
            sink = QAudioSink(fmt)
            self._sink = sink
            sink.setVolume(self.volume)
            sink.setBufferSize(96_000)
            device = sink.start()
            if device is None:
                self.failed.emit("Не удалось открыть аудиовыход для эквалайзера.")
                return

            while not self._stop_requested.is_set():
                if self._pause_requested.is_set():
                    sink.suspend()
                    self.msleep(30)
                    continue
                else:
                    sink.resume()
                sink.setVolume(self.volume)
                self._update_clock(sink)
                chunk = proc.stdout.read(8192)
                if not chunk:
                    self._drain(sink)
                    break
                offset = 0
                while offset < len(chunk) and not self._stop_requested.is_set():
                    if self._pause_requested.is_set():
                        sink.suspend()
                        self.msleep(30)
                        continue
                    free = sink.bytesFree()
                    if free <= 0:
                        self._update_clock(sink)
                        self.msleep(5)
                        continue
                    take = min(len(chunk) - offset, max(free, 2048))
                    written = device.write(chunk[offset:offset + take])
                    if written > 0:
                        offset += written
                    else:
                        self.msleep(5)
            if not self._stop_requested.is_set() and proc.poll() not in (None, 0):
                if stderr_thread is not None:
                    stderr_thread.join(.3)
                err = b"".join(error_tail).decode("utf-8", "replace").strip()
                self.failed.emit(err or "FFmpeg не смог обработать аудио.")
        except Exception as exc:  # noqa: BLE001
            if not self._stop_requested.is_set():
                self.failed.emit(str(exc))
        finally:
            if sink is not None:
                try:
                    sink.stop()
                except Exception:
                    pass
            if proc is not None:
                try:
                    if proc.poll() is None:
                        proc.terminate()
                        proc.wait(timeout=1)
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        pass
            self._sink = None
            if sink is not None:
                sink.deleteLater()
            if stderr_thread is not None:
                stderr_thread.join(1)
            if proc is not None:
                for stream in (proc.stdout, proc.stderr):
                    if stream is not None:
                        stream.close()
                try:
                    proc.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait(timeout=1)
            self._process = None
            self.ended = True


