COLOR_PRESETS = {key: (label, params) for _g, items in COLOR_PRESET_GROUPS for key, label, params in items}

_LUMA_W = (0.299, 0.587, 0.114)


def _srgb_to_linear(x):
    x = np.asarray(x, dtype=np.float32)
    return np.where(x <= 0.04045, x / 12.92, ((x + 0.055) / 1.055) ** 2.4).astype(np.float32)


def _linear_to_srgb(x):
    x = np.clip(np.asarray(x, dtype=np.float32), 0.0, 1.0)
    return np.where(x <= 0.0031308, x * 12.92, 1.055 * np.power(x, 1 / 2.4) - 0.055).astype(np.float32)


def _smoothstep(e0, e1, x):
    t = np.clip((x - e0) / (e1 - e0), 0.0, 1.0)
    return t * t * (3.0 - 2.0 * t)


def _hue_chroma(hue_deg: float) -> np.ndarray:
    """Цветовой вектор оттенка без изменения яркости (добавка к кадру тонирует, а не осветляет)."""
    import colorsys
    r, g, b = colorsys.hsv_to_rgb((hue_deg % 360.0) / 360.0, 1.0, 1.0)
    luma = _LUMA_W[0] * r + _LUMA_W[1] * g + _LUMA_W[2] * b
    return np.array([r - luma, g - luma, b - luma], dtype=np.float32)


def blend_color_preset(params: dict, amount: int) -> dict:
    """Пресет с силой amount (0-100 %), как ползунок «Количество» в Lightroom.
    Оттенки (hue) не смешиваются - иначе при промежуточных значениях появлялись бы чужие цвета."""
    k = max(0, min(100, int(amount))) / 100.0
    full = ColorGrade.normalize(params)
    out = {}
    for key, value in full.items():
        neutral = COLOR_NEUTRAL[key]
        out[key] = value if key.endswith("_hue") else round(neutral + (value - neutral) * k)
    return out


class ColorGrade:
    """Цветокоррекция кадра. Параметры задают ползунки (как в Lightroom / Lumetri), результат считается
    через таблицы поиска и numpy, поэтому быстрый. Порядок обработки:
      1) баланс белого + экспозиция - в линейном свете, таблица на канал;
      2) тоновая кривая по яркости: чёрные, тени, света, белые, затем контраст;
      3) насыщенность и красочность;
      4) тонирование теней и светов, выцветание;
      5) виньетка."""

    def __init__(self, params: dict | None = None):
        self.params = dict(COLOR_NEUTRAL)
        self._state = None
        self._vignette_cache: dict = {}
        self.set_params(params or {})

    # ---------- параметры ----------
    @staticmethod
    def normalize(params: dict) -> dict:
        out = {}
        for key, (lo, hi) in COLOR_RANGE.items():
            try:
                v = int(round(float(params.get(key, COLOR_NEUTRAL[key]))))
            except (TypeError, ValueError):
                v = COLOR_NEUTRAL[key]
            out[key] = max(lo, min(hi, v))
        return out

    @staticmethod
    def _effective(p: dict) -> dict:
        """Параметры без «пустых» зависимостей: оттенок не важен при нулевой насыщенности и т. п."""
        e = dict(p)
        if e["shadow_sat"] == 0:
            e["shadow_hue"] = 0
        if e["highlight_sat"] == 0:
            e["highlight_hue"] = 0
        if e["shadow_sat"] == 0 and e["highlight_sat"] == 0:
            e["balance"] = 0
        if e["vignette"] == 0:
            e["vignette_mid"], e["vignette_feather"] = 50, 50
        return e

    @classmethod
    def is_neutral_params(cls, params: dict) -> bool:
        return cls._effective(cls.normalize(params)) == cls._effective(dict(COLOR_NEUTRAL))

    @property
    def is_neutral(self) -> bool:
        return self._state is None

    def set_params(self, params: dict):
        p = self.normalize(params)
        self.params = p
        self._state = None if self.is_neutral_params(p) else self._compile(p)

    # ---------- подготовка таблиц ----------
    def _compile(self, p: dict) -> dict:
        xs = np.arange(256, dtype=np.float32) / 255.0
        st: dict = {}

        # 1) баланс белого + экспозиция (линейный свет)
        t, tn = p["temperature"] / 100.0, p["tint"] / 100.0
        gr = 2.0 ** (0.5 * t) * 2.0 ** (0.10 * tn)
        gb = 2.0 ** (-0.5 * t) * 2.0 ** (0.10 * tn)
        gg = 2.0 ** (-0.35 * tn)
        norm = 1.0 / (0.2126 * gr + 0.7152 * gg + 0.0722 * gb)    # яркость не должна «плыть» от баланса белого
        mult = 2.0 ** (p["exposure"] / 100.0)
        st["wb"] = bool(p["temperature"] or p["tint"] or p["exposure"])
        if st["wb"]:
            lin = _srgb_to_linear(xs)
            st["lut1"] = [
                np.clip(_linear_to_srgb(lin * g * norm * mult) * 255.0 + 0.5, 0, 255).astype(np.uint8)
                for g in (gr, gg, gb)
            ]

        # 2) тоновая кривая по яркости (аддитивно: цвет сохраняется)
        y = xs
        bell = lambda c, w: np.exp(-(((y - c) / w) ** 2))      # noqa: E731
        d = (
            (p["blacks"] / 100.0) * 0.22 * (1.0 - y) ** 4
            + (p["shadows"] / 100.0) * 0.30 * bell(0.25, 0.20)
            + (p["highlights"] / 100.0) * 0.30 * bell(0.75, 0.20)
            + (p["whites"] / 100.0) * 0.22 * y ** 4
        )
        y2 = np.clip(y + d, 0.0, 1.0)
        c = p["contrast"] / 100.0
        if c > 0:
            g_ = 1.0 + 7.0 * c
            sig = lambda v: 1.0 / (1.0 + np.exp(-v))           # noqa: E731
            lo_, hi_ = sig(-g_ / 2), sig(g_ / 2)
            y3 = (sig(g_ * (y2 - 0.5)) - lo_) / (hi_ - lo_)
        elif c < 0:
            y3 = 0.5 + (y2 - 0.5) * (1.0 + 0.8 * c)
        else:
            y3 = y2
        st["tone"] = bool(p["blacks"] or p["shadows"] or p["highlights"] or p["whites"] or p["contrast"])
        st["delta"] = ((np.clip(y3, 0, 1) - y) * 255.0).astype(np.float32)

        # 3) насыщенность и красочность
        st["sat"] = 1.0 + p["saturation"] / 100.0
        st["vib"] = p["vibrance"] / 100.0

        # 4) тонирование теней / светов + выцветание
        s_amt, h_amt = p["shadow_sat"] / 100.0, p["highlight_sat"] / 100.0
        if s_amt or h_amt:
            m = 0.5 - 0.25 * p["balance"] / 100.0
            w_hi = _smoothstep(m - 0.35, m + 0.35, y)
            w_sh = 1.0 - w_hi
            tint = (
                s_amt * w_sh[:, None] * _hue_chroma(p["shadow_hue"])[None, :]
                + h_amt * w_hi[:, None] * _hue_chroma(p["highlight_hue"])[None, :]
            ) * 70.0
            st["tint"] = [np.ascontiguousarray(tint[:, i]).astype(np.float32) for i in range(3)]
        else:
            st["tint"] = None
        f = p["fade"] / 100.0
        lift = 38.0 * f
        st["A"] = (255.0 - lift - 25.5 * f) / 255.0
        st["B"] = lift + 0.5                                  # +0,5 - округление при переводе в uint8

        # 5) виньетка
        st["vig"] = (p["vignette"], p["vignette_mid"], p["vignette_feather"]) if p["vignette"] else None
        return st

    def _vignette_mask(self, w: int, h: int, amount: int, mid: int, feather: int) -> np.ndarray:
        key = (w, h, amount, mid, feather)
        mask = self._vignette_cache.get(key)
        if mask is None:
            xs = (np.arange(w, dtype=np.float32) - (w - 1) / 2.0) / (w / 2.0)
            ys = (np.arange(h, dtype=np.float32) - (h - 1) / 2.0) / (h / 2.0)
            r = np.sqrt(ys[:, None] ** 2 + xs[None, :] ** 2) / 1.4142
            start = mid / 100.0 * 0.9
            span = max(0.05, feather / 100.0 * 0.9 + 0.1)
            edge = _smoothstep(start, start + span, r)
            mask = (1.0 + (amount / 100.0) * edge).astype(np.float32)
            if len(self._vignette_cache) > 4:
                self._vignette_cache.clear()
            self._vignette_cache[key] = mask
        return mask

    # ---------- обработка ----------
    def process(self, rgb: np.ndarray, vignette: bool = True) -> np.ndarray:
        """rgb: uint8 (высота, ширина, 3). Возвращает новый uint8-массив такого же размера."""
        st = self._state
        if st is None:
            return rgb
        h, w = rgb.shape[:2]
        r, g, b = rgb[..., 0], rgb[..., 1], rgb[..., 2]
        if st["wb"]:
            r, g, b = st["lut1"][0][r], st["lut1"][1][g], st["lut1"][2][b]

        if st["tone"]:
            y8 = (r.astype(np.uint16) * 77 + g.astype(np.uint16) * 150 + b.astype(np.uint16) * 29) >> 8
            d = st["delta"][y8]
            rf, gf, bf = r + d, g + d, b + d                    # uint8 + float32 -> float32
        else:
            rf, gf, bf = r.astype(np.float32), g.astype(np.float32), b.astype(np.float32)

        yf = None
        if st["sat"] != 1.0 or st["vib"] != 0.0:
            yf = _LUMA_W[0] * rf + _LUMA_W[1] * gf + _LUMA_W[2] * bf
            factor = st["sat"]
            if st["vib"] != 0.0:
                cmax = np.maximum(np.maximum(rf, gf), bf)
                cmin = np.minimum(np.minimum(rf, gf), bf)
                sp = np.clip((cmax - cmin) * (1.0 / 255.0), 0.0, 1.0)
                v = st["vib"]
                vf = 1.0 + v * (1.0 - sp) ** 2 if v > 0 else 1.0 + v * sp
                factor = vf * st["sat"]
            rf = yf + (rf - yf) * factor
            gf = yf + (gf - yf) * factor
            bf = yf + (bf - yf) * factor

        if st["tint"] is not None:
            yl = _LUMA_W[0] * rf + _LUMA_W[1] * gf + _LUMA_W[2] * bf
            yi = np.clip(yl, 0, 255).astype(np.intp)
            rf = rf + st["tint"][0][yi]
            gf = gf + st["tint"][1][yi]
            bf = bf + st["tint"][2][yi]

        A, B = st["A"], st["B"]
        if A != 1.0 or B != 0.5:
            rf, gf, bf = rf * A + (B - 0.5), gf * A + (B - 0.5), bf * A + (B - 0.5)

        if st["vig"] is not None and vignette:
            mask = self._vignette_mask(w, h, *st["vig"])
            rf, gf, bf = rf * mask, gf * mask, bf * mask

        out = np.empty((h, w, 3), dtype=np.uint8)
        for i, plane in enumerate((rf, gf, bf)):
            np.clip(plane + 0.5, 0, 255, out=plane)
            out[..., i] = plane
        return out

    def write_cube(self, path, size: int = 52):
        """Записывает коррекцию как 3D-LUT (.cube) для фильтра lut3d в ffmpeg. size=52: шаг узлов ровно 5
        уровней (0, 5, ... 255), поэтому узлы точно совпадают с 8-битными значениями. Виньетка не входит
        (она пространственная) - её рисует плеер поверх кадра."""
        steps = np.round(np.linspace(0, 255, size)).astype(np.uint8)
        b, g, r = np.meshgrid(steps, steps, steps, indexing="ij")          # красный меняется быстрее всего
        grid = np.stack([r, g, b], axis=-1).reshape(size * size, size, 3)
        out = self.process(grid, vignette=False).reshape(-1, 3).astype(np.float64) / 255.0
        with open(path, "w", encoding="ascii") as f:
            f.write(f'TITLE "NOP grade"\nLUT_3D_SIZE {size}\nDOMAIN_MIN 0 0 0\nDOMAIN_MAX 1 1 1\n')
            np.savetxt(f, out, fmt="%.6f")

    @staticmethod
    def _pq_to_nits(v):
        """ST 2084 PQ code values (0..1) to absolute luminance (0..10000 cd/m²)."""
        v = np.clip(np.asarray(v, dtype=np.float32), 0.0, 1.0)
        m1 = 2610.0 / 16384.0
        m2 = 2523.0 / 32.0
        c1 = 3424.0 / 4096.0
        c2 = 2413.0 / 128.0
        c3 = 2392.0 / 128.0
        vp = np.power(v, 1.0 / m2)
        num = np.maximum(vp - c1, 0.0)
        den = np.maximum(c2 - c3 * vp, 1e-7)
        return np.power(num / den, 1.0 / m1) * 10000.0

    @staticmethod
    def _hable(x):
        """Hable filmic curve, normalized when used by write_mpv_cube()."""
        x = np.maximum(np.asarray(x, dtype=np.float32), 0.0)
        A, B, C, D, E, F = 0.15, 0.50, 0.10, 0.20, 0.02, 0.30
        return ((x * (A * x + C * B) + D * E) /
                (x * (A * x + B) + D * F)) - E / F

    def write_mpv_cube(self, path, size: int = 52, hdr: bool = False):
        """Write a LUT meant for mpv/gpu-next's GPU color pipeline.

        SDR: preserve the existing sRGB-domain grade (native LUT type).
        HDR: bake a PQ/BT.2020 -> SDR/BT.709 Hable transform and then the same
        NOP sRGB grade into one conversion LUT, avoiding a CPU lavfi filter
        on every decoded 4K frame.
        """
        if not hdr:
            self.write_cube(path, size=size)
            return
        axis = np.linspace(0.0, 1.0, size, dtype=np.float32)
        b, g, r = np.meshgrid(axis, axis, axis, indexing="ij")
        pq = np.stack([r, g, b], axis=-1)
        rgb2020 = self._pq_to_nits(pq)
        # Linear-light BT.2020 -> BT.709 conversion.
        mat = np.array([
            [1.660491, -0.587641, -0.072850],
            [-0.124550, 1.132900, -0.008349],
            [-0.018151, -0.100579, 1.118730],
        ], dtype=np.float32)
        rgb709 = np.einsum("...c,dc->...d", rgb2020, mat, optimize=True)
        rgb709 = np.maximum(rgb709, 0.0)
        luma_nits = (0.2126 * rgb709[..., 0] + 0.7152 * rgb709[..., 1] + 0.0722 * rgb709[..., 2])
        x = luma_nits / 100.0  # linear working values, 1.0 = 100 nits
        reference_peak = float(self._hable(np.array([10.0], dtype=np.float32))[0])
        mapped_luma = np.clip(self._hable(x) / max(reference_peak, 1e-6), 0.0, 1.0)
        scale = np.divide(mapped_luma, x, out=np.zeros_like(mapped_luma), where=x > 1e-7)
        mapped_linear = np.clip(rgb709 * scale[..., None], 0.0, 1.0)
        srgb = _linear_to_srgb(mapped_linear)
        encoded = np.round(srgb * 255.0).astype(np.uint8)
        grid = encoded.reshape(size * size, size, 3)
        out = self.process(grid, vignette=False).reshape(-1, 3).astype(np.float64) / 255.0
        with open(path, "w", encoding="ascii") as f:
            f.write(f'TITLE "NOP HDR to SDR grade"\nLUT_3D_SIZE {size}\nDOMAIN_MIN 0 0 0\nDOMAIN_MAX 1 1 1\n')
            np.savetxt(f, out, fmt="%.6f")

    def apply_to_image(self, image):
        """QImage -> QImage с применённой коррекцией (кадры больше COLOR_MAX_PIXELS уменьшаются)."""
        if self._state is None:
            return image
        img = image
        w, h = img.width(), img.height()
        if w * h > COLOR_MAX_PIXELS:
            s = (COLOR_MAX_PIXELS / float(w * h)) ** 0.5
            img = img.scaled(max(1, int(w * s)), max(1, int(h * s)),
                             Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
        return rgb_to_qimage(self.process(qimage_to_rgb(img)))


def qimage_to_rgb(img) -> np.ndarray:
    img = img.convertToFormat(QImage.Format.Format_RGB888)
    w, h, bpl = img.width(), img.height(), img.bytesPerLine()
    ptr = img.constBits()
    ptr.setsize(bpl * h)
    arr = np.frombuffer(ptr, dtype=np.uint8).reshape(h, bpl)[:, : w * 3].reshape(h, w, 3)
    # ОБЯЗАТЕЛЬНО копия: ascontiguousarray не копирует, если строки уже подряд, а память QImage
    # освобождается при выходе из функции - массив указывал бы на мусор.
    return np.array(arr, dtype=np.uint8, order="C", copy=True)


def rgb_to_qimage(arr: np.ndarray):
    arr = np.ascontiguousarray(arr)
    h, w = arr.shape[:2]
    return QImage(arr.data, w, h, w * 3, QImage.Format.Format_RGB888).copy()


def make_color_reference() -> np.ndarray:
    """Эталонная картинка для миниатюр пресетов: серая шкала + типичные цвета (кожа, небо, трава...)."""
    img = np.zeros((40, 64, 3), dtype=np.uint8)
    img[:14, :, :] = np.linspace(0, 255, 64, dtype=np.uint8)[None, :, None]
    patches = [(224, 172, 105), (95, 150, 220), (80, 140, 60), (200, 50, 50), (230, 200, 60), (130, 70, 160)]
    for i, col in enumerate(patches):
        x0 = int(i * 64 / len(patches))
        x1 = int((i + 1) * 64 / len(patches))
        img[14:, x0:x1, :] = col
    return img


class GradeWorker(QThread):
    """Обрабатывает кадры в отдельном потоке: всегда берёт самый свежий кадр, лишние отбрасывает,
    поэтому интерфейс не тормозит, даже если обработка медленнее частоты кадров."""

    processed = pyqtSignal(QImage)

    def __init__(self, grade: "ColorGrade", parent=None):
        super().__init__(parent)
        self.grade = grade
        self._lock = threading.Lock()
        self._pending = None
        self._event = threading.Event()
        self._running = True

    def submit(self, image):
        with self._lock:
            self._pending = (image, dict(self.grade.params))
        self._event.set()

    def stop(self):
        self.request_stop()
        return self.wait(1500)

    def request_stop(self):
        self._running = False
        self._event.set()

    def run(self):
        grade = ColorGrade()
        while self._running:
            self._event.wait()
            self._event.clear()
            if not self._running:
                break
            with self._lock:
                pending, self._pending = self._pending, None
            if pending is None:
                continue
            image, params = pending
            try:
                grade.set_params(params)
                result = grade.apply_to_image(image)
                if self._running:
                    self.processed.emit(result)
            except Exception:  # noqa: BLE001
                self.processed.emit(image)


class ResetSlider(ClickSlider):
    """Ползунок: двойной клик возвращает значение по умолчанию (как в Lightroom)."""

    def __init__(self, default: int, orientation, parent=None):
        super().__init__(orientation, parent)
        self.default = default

    def mouseDoubleClickEvent(self, e):
        self.setValue(self.default)
        e.accept()


_HUE_STOPS = ", ".join(
    f"stop:{i / 6:.3f} {c}"
    for i, c in enumerate(["#ff0000", "#ffff00", "#00ff00", "#00ffff", "#0000ff", "#ff00ff", "#ff0000"])
)
# Цветные «дорожки» ползунков, как у Adobe: видно, в какую сторону сдвигается цвет.
COLOR_SLIDER_GRADIENTS = {
    "temperature": "stop:0 #3a7bff, stop:1 #ffb02e",
    "tint": "stop:0 #3cc66a, stop:1 #e04bd0",
    "saturation": "stop:0 #7b8190, stop:1 #ff2d6f",
    "shadow_hue": _HUE_STOPS,
    "highlight_hue": _HUE_STOPS,
}


class ParamSlider(QWidget):
    """Строка «название - ползунок - значение» для параметра цветокоррекции."""

    valueChanged = pyqtSignal(str, int)

    def __init__(self, key: str, label: str, lo: int, hi: int, default: int, parent=None):
        super().__init__(parent)
        self.key = key
        self.default = default
        self.name = ElidedLabel(label)
        self.name.setObjectName("muted")
        self.name.setFixedWidth(84)
        self.slider = ResetSlider(default, Qt.Orientation.Horizontal)
        self.slider.setRange(lo, hi)
        self.slider.setValue(default)
        self.slider.setFixedHeight(16)
        self.slider.setToolTip("Двойной клик - сбросить")
        self.value_lbl = QLabel()
        self.value_lbl.setObjectName("muted")
        self.value_lbl.setFixedWidth(38)
        self.value_lbl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        gradient = COLOR_SLIDER_GRADIENTS.get(key)
        if gradient:
            self.slider.setStyleSheet(
                "QSlider::groove:horizontal { height:5px; border-radius:2px;"
                f" background:qlineargradient(x1:0,y1:0,x2:1,y2:0,{gradient}); }}"
                "QSlider::sub-page:horizontal { background:transparent; }"
                "QSlider::add-page:horizontal { background:transparent; }"
            )
        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)
        lay.addWidget(self.name)
        lay.addWidget(self.slider, 1)
        lay.addWidget(self.value_lbl)
        self.slider.valueChanged.connect(self._changed)
        self._update_label(default)

    def _update_label(self, v: int):
        if self.key == "exposure":
            text = f"{v / 100:+.2f}"
        elif self.key.endswith("_hue"):
            text = f"{v}\u00b0"
        elif self.slider.minimum() < 0:
            text = f"{v:+d}"
        else:
            text = str(v)
        self.value_lbl.setText(text)

    def _changed(self, v: int):
        self._update_label(v)
        self.valueChanged.emit(self.key, v)

    def setValue(self, v: int):
        self.slider.blockSignals(True)
        self.slider.setValue(v)
        self.slider.blockSignals(False)
        self._update_label(self.slider.value())


class CollapsibleSection(QWidget):
    """Сворачиваемый раздел панели (как «Основные», «Творческие» в Lumetri)."""

    toggled = pyqtSignal(bool)

    def __init__(self, title: str, expanded: bool = True, parent=None):
        super().__init__(parent)
        self._title = title
        self.header = QPushButton()
        self.header.setObjectName("sectionHeader")
        self.header.setCheckable(True)
        self.header.setCursor(Qt.CursorShape.PointingHandCursor)
        self.body = QWidget()
        self.body_layout = QVBoxLayout(self.body)
        self.body_layout.setContentsMargins(0, 2, 0, 2)
        self.body_layout.setSpacing(5)
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(5)
        lay.addWidget(self.header)
        lay.addWidget(self.body)
        self.header.setChecked(expanded)
        self._apply(expanded)
        self.header.toggled.connect(self._on_toggled)

    def _apply(self, expanded: bool):
        self.header.setIcon(make_icon("chev_d" if expanded else "chev_r", ICON_MUTED))
        self.header.setIconSize(QSize(12, 12))
        self.header.setText(" " + self._title)
        self.body.setVisible(expanded)

    def _on_toggled(self, expanded: bool):
        self._apply(expanded)
        self.toggled.emit(expanded)


# ====================================================================================
# Видеодвижки: libmpv (основной для видео) + прежние Qt/FFmpeg пути как fallback
# ====================================================================================
# libmpv управляет декодированием, аудиочасами, рендерингом и синхронизацией. В отличие от
# прежнего пути FFmpeg -> raw RGB -> Python/QImage, кадры не копируются через Python.
# Положи runtime libmpv в папку mpv рядом с программой (setup_mpv.bat делает это автоматически).
NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)

QT_NATIVE_VIDEO = {"h264", "vp8", "vp9", "mpeg4"}      # эти кодеки Qt играет надёжно
QT_NATIVE_AUDIO = {"aac", "mp3", "opus", "vorbis", "flac", "pcm_s16le", "pcm_s24le", "pcm_f32le"}
FF_MAX_SIZE = (1920, 1080)       # обычный потолок вывода FFmpeg
FF_4K_MAX_SIZE = (1280, 720)    # для 4K снижаем объём кадров: raw RGB в 1080p слишком тяжёл для Python/QImage
FF_HW_CODECS = {"h264", "hevc", "av1", "vp9", "mpeg2video", "vc1"}
FF_QUEUE_FRAMES = 6              # очередь готовых кадров (память ограничена)
FF_HDR_TONEMAP = (
    "zscale=t=linear:npl=100,format=gbrpf32le,zscale=p=bt709,"
    "tonemap=tonemap=hable:desat=0,zscale=t=bt709:m=bt709:r=tv,format=yuv420p"
)


class MediaInfo:
    """Сведения о файле: что в нём есть (по выводу ffmpeg -i)."""

    def __init__(self):
        self.ok = False
        self.duration_ms = 0
        self.v_codec = None
        self.width = 0
        self.height = 0
        self.sar = 1.0
        self.fps = 0.0
        self.pix_fmt = ""
        self.hdr = False
        self.interlaced = False
        self.audio: list[tuple[str, str]] = []     # (кодек, язык)

    @property
    def has_video(self) -> bool:
        return self.v_codec is not None

    @property
    def has_audio(self) -> bool:
        return bool(self.audio)

    @property
    def disp_size(self) -> tuple[int, int]:
        """Размер кадра на экране с учётом формата пикселя (анаморфное видео)."""
        return max(2, int(round(self.width * self.sar))), max(2, self.height)


def parse_ffmpeg_info(text: str) -> MediaInfo:
    info = MediaInfo()
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", text)
    if m:
        info.duration_ms = int((int(m[1]) * 3600 + int(m[2]) * 60 + float(m[3])) * 1000)
    stream_re = re.compile(r"Stream #\d+:\d+(?:\[0x[0-9a-fA-F]+\])?(?:\((\w*)\))?: (Video|Audio): (.*)$")
    for line in text.splitlines():
        sm = stream_re.search(line)
        if not sm:
            continue
        lang, kind, details = sm[1] or "", sm[2], sm[3]
        codec_m = re.match(r"([\w\-]+)", details)
        codec = codec_m[1] if codec_m else "?"
        if kind == "Audio":
            info.audio.append((codec, lang))
            continue
        if info.v_codec is not None or "attached pic" in line:
            continue                                   # вторая дорожка или обложка альбома - не видео
        info.v_codec = codec
        pf = re.search(r",\s*((?:yuvj?|nv|p0|gbr|rgb|bgr|gray|pal|ya|argb|rgba|bgra)[a-z0-9_]*)", details)
        info.pix_fmt = pf[1] if pf else ""
        sz = re.search(r"(?<![0-9A-Za-z])(\d{2,5})x(\d{2,5})(?![0-9A-Za-z])", details)
        if sz:
            info.width, info.height = int(sz[1]), int(sz[2])
        sar = re.search(r"SAR (\d+):(\d+)", details)
        if sar and int(sar[2]):
            info.sar = int(sar[1]) / int(sar[2])
        fps = re.search(r"([\d.]+) fps", details) or re.search(r"([\d.]+) tbr", details)
        info.fps = float(fps[1]) if fps else 0.0
        info.hdr = "smpte2084" in details or "arib-std-b67" in details
        info.interlaced = bool(re.search(r"top first|bottom first|\btff\b|\bbff\b", details))
    rot = re.search(r"rotation of (-?[\d.]+) degrees", text)
    if rot and info.has_video and int(round(abs(float(rot[1])))) % 180 == 90:
        info.width, info.height = info.height, info.width
    info.ok = bool(info.duration_ms or info.v_codec or info.audio)
    return info


_PROBE_CACHE: dict = {}


def probe_media(path) -> MediaInfo:
    path = str(path)
    try:
        key = (path, os.path.getmtime(path))
    except OSError:
        return MediaInfo()
    cached = _PROBE_CACHE.get(key)
    if cached is not None:
        return cached
    info = MediaInfo()
    ffmpeg = shutil.which("ffmpeg")
    if ffmpeg:
        options = {"creationflags": NO_WINDOW} if os.name == "nt" else {"start_new_session": True}
        proc = None
        try:
            with tempfile.TemporaryFile() as output:
                proc = subprocess.Popen([ffmpeg, "-nostdin", "-hide_banner", "-probesize", "8388608",
                                         "-analyzeduration", "3000000", "-i", path],
                                        stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=output, **options)
                deadline = time.monotonic() + 12
                while proc.poll() is None:
                    if QThread.currentThread().isInterruptionRequested() or time.monotonic() > deadline:
                        stop_owned_process(proc)
                        break
                    time.sleep(.03)
                output.seek(max(0, output.tell()-256*1024))
                info = parse_ffmpeg_info(output.read(256*1024).decode("utf-8", "replace"))
        except (OSError, subprocess.SubprocessError):
            pass
        finally:
            if proc is not None and proc.poll() is None:
                stop_owned_process(proc)
    if len(_PROBE_CACHE) >= 64:
        _PROBE_CACHE.pop(next(iter(_PROBE_CACHE)))
    _PROBE_CACHE[key] = info
    return info


class MediaProbeThread(QThread):
    ready = pyqtSignal(str, int)
    def __init__(self, path, generation, parent):
        super().__init__(parent)
        self.path, self.generation = Path(path), generation
    def request_stop(self):
        self.requestInterruption()
    def run(self):
        try:
            probe_media(self.path)
        except Exception:
            try:
                _PROBE_CACHE[(str(self.path), os.path.getmtime(self.path))] = MediaInfo()
            except OSError:
                pass
        if not self.isInterruptionRequested():
            self.ready.emit(str(self.path), self.generation)


def choose_backend(info, force: str = "") -> str:
    """'qt' - родной Qt Multimedia, 'ff' - плеер на ffmpeg (любые кодеки, 4K, HDR)."""
    have_ffmpeg = shutil.which("ffmpeg") is not None
    if force == "qt" or not have_ffmpeg:
        return "qt"
    if force == "ff":
        return "ff"
    if info is None or not info.ok:
        return "qt"
    if info.has_video:
        if info.v_codec not in QT_NATIVE_VIDEO:
            return "ff"
        if info.width * info.height > FF_MAX_SIZE[0] * FF_MAX_SIZE[1]:
            return "ff"            # 4K: через Qt кадры пришлось бы преобразовывать на процессоре
        if info.hdr or re.search(r"(p0\d\d|\d{2}(le|be))", info.pix_fmt):
            return "ff"            # 10-бит и HDR
    if info.audio and info.audio[0][0] not in QT_NATIVE_AUDIO:
        return "ff"
    return "qt"


def snap_fps(fps: float) -> tuple[float, str]:
    """Частота кадров -> (число, строка для ffmpeg). 23.976 и т. п. приводятся к точным дробям."""
    for target, text in ((24000 / 1001, "24000/1001"), (30000 / 1001, "30000/1001"), (60000 / 1001, "60000/1001")):
        if abs(fps - target) < 0.02:
            return target, text
    fps = round(fps, 3)
    return fps, (str(int(fps)) if fps == int(fps) else f"{fps:g}")


def build_ffmpeg_video_cmd(ffmpeg, path, pos_ms, out_w, out_h, fps_text, info, opts, cube_name=None):
    """Команда ffmpeg: декодировать видео, уменьшить, (HDR -> SDR), (цветокоррекция) -> сырые кадры RGB24."""
    vf = []
    if info.interlaced or info.v_codec == "mpeg2video":
        vf.append("yadif=deint=interlaced")
    vf.append(f"fps=fps={fps_text}")                      # постоянная частота: номер кадра = время
    vf.append(f"scale={out_w}:{out_h}:flags=bilinear")
    if abs(info.sar - 1.0) > 0.01:
        vf.append("setsar=1")                              # ширина уже пересчитана с учётом SAR
    if opts.get("tonemap"):
        vf.append(FF_HDR_TONEMAP)
    vf.append("format=rgb24")
    if opts.get("lut") and cube_name:
        vf.append(f"lut3d=file={cube_name}:interp=tetrahedral")
    cmd = [ffmpeg, "-nostdin", "-hide_banner", "-loglevel", "error"]
    if opts.get("hw"):
        # On Windows prefer D3D11VA explicitly. For HEVC Main10 this asks the GPU
        # (Intel UHD / NVIDIA) to decode the compressed 4K stream instead of relying
        # on FFmpeg's generic auto-selection. Do not force hw output frames here:
        # filters below need regular system-memory frames and FFmpeg transfers them.
        hw_method = "d3d11va" if os.name == "nt" else "auto"
        cmd += ["-hwaccel", hw_method]
    cmd += ["-ss", f"{max(pos_ms, 0) / 1000:.3f}", "-i", str(path), "-map", "0:v:0",
            "-an", "-sn", "-dn", "-vf", ",".join(vf), "-f", "rawvideo", "-pix_fmt", "rgb24", "pipe:1"]
    return cmd


class _VideoPipe:
    """Процесс ffmpeg с сырыми кадрами RGB24. Кадры читает фоновый поток и кладёт в очередь ограниченного
    размера: когда очередь полна, ffmpeg сам ждёт (в Python не копятся гигабайты)."""

    def __init__(self, cmd, cwd, width, height, fps, start_ms):
        self.width, self.height, self.fps, self.start_ms = width, height, fps, start_ms
        self.frames: collections.deque = collections.deque()
        self.lock = threading.Lock()
        self.count = 0
        self.eof = False
        self.eof_t = 0.0
        self.started = time.monotonic()
        self._stop = threading.Event()
        self._err: collections.deque = collections.deque(maxlen=20)
        self.proc = subprocess.Popen(cmd, cwd=cwd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                     stderr=subprocess.PIPE, bufsize=0, creationflags=NO_WINDOW)
        self._threads = [threading.Thread(target=self._read_frames, name="NOP video frames", daemon=True),
                         threading.Thread(target=self._drain_stderr, name="NOP video stderr", daemon=True)]
        for thread in self._threads:
            thread.start()

    def _drain_stderr(self):
        try:
            for line in iter(self.proc.stderr.readline, b""):
                self._err.append(line.decode("utf-8", "replace").strip())
        except (OSError, ValueError):
            pass

    def _read_frames(self):
        size = self.width * self.height * 3
        out = self.proc.stdout
        idx = 0
        try:
            while not self._stop.is_set():
                buf = bytearray(size)
                view = memoryview(buf)
                got = 0
                while got < size:
                    n = out.readinto(view[got:])
                    if not n:
                        break
                    got += n
                if got < size:
                    break
                # Never pause FFmpeg decoding because the GUI is busy. Blocking stdout
                # here makes the video decoder fall behind the audio clock. Keep only the
                # newest frames when the bounded queue is full; the GUI will display the
                # newest frame whose presentation time has arrived.
                with self.lock:
                    if len(self.frames) >= FF_QUEUE_FRAMES:
                        self.frames.popleft()
                    self.frames.append((self.start_ms + idx * 1000.0 / self.fps, buf))
                idx += 1
                self.count += 1
        except (OSError, ValueError):
            pass
        finally:
            self.eof_t = time.monotonic()
            self.eof = True

    def pop_due(self, now_ms: float):
        """Самый свежий кадр, время которого уже наступило (устаревшие пропускаются)."""
        latest = None
        with self.lock:
            while self.frames and self.frames[0][0] <= now_ms + 4:
                latest = self.frames.popleft()
            # If decoding temporarily fell behind, discard expired queued frames
            # instead of displaying a burst of stale frames after a stall.
            stale_limit = max(1000.0 / max(self.fps, 1.0), 25.0)
            while self.frames and self.frames[0][0] < now_ms - stale_limit:
                self.frames.popleft()
        return latest

    @property
    def pending(self) -> int:
        with self.lock:
            return len(self.frames)

    def error_text(self) -> str:
        return " ".join(self._err)[-400:]

    def kill(self):
        self._stop.set()
        try:
            if self.proc.poll() is None:
                self.proc.kill()
            self.proc.wait(timeout=2)
        except (OSError, subprocess.TimeoutExpired):
            pass
        for thread in self._threads:
            thread.join(1)
        for stream in (self.proc.stdout, self.proc.stderr):
            if stream is not None:
                try:
                    stream.close()
                except OSError:
                    pass
        with self.lock:
            self.frames.clear()


class FFmpegPlayer(QObject):
    """Плеер на ffmpeg: видео - сырые кадры (с цветокоррекцией и HDR-тонмаппингом на стороне ffmpeg),
    звук - EqualizerAudioThread (он же даёт «часы» для синхронизации). Умеет паузу, перемотку, конец трека."""

    positionChanged = pyqtSignal(int)
    durationChanged = pyqtSignal(int)
    stateChanged = pyqtSignal(object)
    statusChanged = pyqtSignal(object)
    failed = pyqtSignal(str)
    frameReady = pyqtSignal(object)
    videoSizeChanged = pyqtSignal(int, int)
    _lutReady = pyqtSignal(int, str)

    Stopped = QMediaPlayer.PlaybackState.StoppedState
    Playing = QMediaPlayer.PlaybackState.PlayingState
    Paused = QMediaPlayer.PlaybackState.PausedState

    def __init__(self, parent=None):
        super().__init__(parent)
        self.path = None
        self.info = None
        self.use_hwaccel = True
        self._state = self.Stopped
        self._base_ms = 0
        self._frozen_ms = 0
        self._wall_t0 = 0.0
        self._wall_mode = False
        self._started_at = 0.0
        self._audio = None
        self._pipe = None
        self._volume = 0.5
        self._eq = (False, [], [])
        self._eq_enabled = False             # отдельно от набора фильтров: «Ровный» тоже можно включить/выключить
        self._eq_eff = None                  # то, что реально меняет звук (None = без эквалайзера)
        self._grade = None
        self._lut_name = None
        self._lut_gen = 0
        self._widget_size = QSize(640, 360)
        self._out_size = (0, 0)
        self._ladder: list = []
        self._ladder_i = 0
        self._seek_target = None
        self._last_emit = 0.0
        self._done_since = 0.0
        self._tmpdir = Path(tempfile.mkdtemp(prefix="yamifm_ff_"))
        self._timer = QTimer(self)
        self._timer.setInterval(8)
        self._timer.timeout.connect(self._tick)
        self._seek_timer = QTimer(self)
        self._seek_timer.setSingleShot(True)
        self._seek_timer.setInterval(120)
        self._seek_timer.timeout.connect(self._do_seek)
        self._grade_timer = QTimer(self)
        self._grade_timer.setSingleShot(True)
        self._grade_timer.setInterval(250)
        self._grade_timer.timeout.connect(self._apply_grade)
        self._resize_timer = QTimer(self)
        self._resize_timer.setSingleShot(True)
        self._resize_timer.setInterval(400)
        self._resize_timer.timeout.connect(self._on_resized)
        self._lutReady.connect(self._on_lut_ready)

    # ---------- загрузка и состояние ----------
    def set_media(self, path: str, info: MediaInfo):
        self._timer.stop()
        self._kill_all()
        self.path, self.info = path, info
        self._state = self.Stopped
        self._base_ms = self._frozen_ms = 0
        self._seek_target = None
        self.durationChanged.emit(info.duration_ms)
        if info.has_video:
            w, h = info.disp_size
            self.videoSizeChanged.emit(w, h)
        self.statusChanged.emit(QMediaPlayer.MediaStatus.LoadedMedia)

    def duration(self) -> int:
        return self.info.duration_ms if self.info else 0

    def playbackState(self):
        return self._state

    def position(self) -> int:
        return int(self._clock_ms())

    # ---------- часы ----------
    def _begin_clock(self, pos_ms: int):
        self._frozen_ms = int(pos_ms)
        self._started_at = time.monotonic()
        self._wall_mode = False
        self._wall_t0 = time.monotonic() - pos_ms / 1000.0

    def _switch_to_wall(self, at_ms: float):
        self._wall_mode = True
        self._wall_t0 = time.monotonic() - at_ms / 1000.0

    def _clock_ms(self) -> float:
        """Текущая позиция. Главные часы - звук: видео подстраивается под него. Если звука нет
        (или он не запустился / закончился раньше видео) - идём по системным часам."""
        if self._state != self.Playing or self._seek_target is not None:
            return float(self._frozen_ms)
        a = self._audio
        if a is not None and not self._wall_mode:
            if a.started:
                if a.ended:
                    self._switch_to_wall(a.clock_ms)
                return float(a.clock_ms)
            if time.monotonic() - self._started_at < 3.0:
                return float(self._frozen_ms)           # ждём, пока зазвучит звук
            self._switch_to_wall(self._frozen_ms)       # звук не запустился - играем без него
        elif a is None and not self._wall_mode:
            self._switch_to_wall(self._frozen_ms)
        return (time.monotonic() - self._wall_t0) * 1000.0

    # ---------- управление ----------
    def play(self):
        if self.path is None or self.info is None or self._state == self.Playing:
            return
        if self._state == self.Paused:
            pos = self._frozen_ms
            self._state = self.Playing
            self._begin_clock(pos)
            self._start_audio(pos)
            # A video FFmpeg process may have reached EOF while paused (or after
            # seeking in the paused state). Always recreate it from the frozen
            # timestamp; checking only for None leaves a dead pipe attached and
            # causes audio to resume without pictures.
            if self.info.has_video:
                self._start_video(pos)
            self._timer.start()
            self.stateChanged.emit(self.Playing)
            return
        dur = self.duration()
        pos = self._base_ms if (not dur or self._base_ms < dur - 300) else 0
        self.play_from(pos)

    def play_from(self, pos_ms: int):
        if self.path is None or self.info is None:
            return
        self._kill_all()
        pos = max(0, int(pos_ms))
        self._base_ms = pos
        self._seek_target = None
        self._state = self.Playing
        self._begin_clock(pos)
        self._start_audio(pos)
        self._start_video(pos)
        self._timer.start()
        self.stateChanged.emit(self.Playing)

    def pause(self):
        if self._state != self.Playing:
            return
        self._frozen_ms = int(self._clock_ms())
        self._state = self.Paused
        self._stop_audio()
        # Stop the decoder while paused so it cannot run to EOF in the background.
        # Resume will start a fresh video pipe at _frozen_ms.
        self._kill_video()
        self.stateChanged.emit(self.Paused)

    def stop(self):
        self._timer.stop()
        self._seek_timer.stop()
        self._kill_all()
        was = self._state
        self._state = self.Stopped
        self._frozen_ms = self._base_ms = 0
        self._seek_target = None
        if was != self.Stopped:
            self.stateChanged.emit(self.Stopped)

    def setPosition(self, ms: int):
        if self.path is None:
            return
        ms = max(0, int(ms))
        dur = self.duration()
        if dur:
            ms = min(ms, max(dur - 1, 0))
        self._seek_target = ms
        self._frozen_ms = ms
        self.positionChanged.emit(ms)
        if self._state == self.Playing:
            self._stop_audio()               # на время перетаскивания ползунка звук молчит
        self._seek_timer.start()

    def _do_seek(self):
        target, self._seek_target = self._seek_target, None
        if target is None:
            return
        self._base_ms = target
        self._frozen_ms = target
        if self._state == self.Playing:
            self._begin_clock(target)
            self._start_audio(target)
            self._start_video(target)
        elif self._state == self.Paused:
            self._start_video(target)        # покажет кадр в новой позиции
        # в состоянии «остановлен» позиция просто запоминается

    def set_volume(self, volume: float):
        self._volume = max(0.0, min(1.0, float(volume)))
        a = self._audio
        if a is not None and a.isRunning():
            a.set_volume(self._volume)

    def set_equalizer(self, enabled: bool, gains, freqs):
        """Настройки эквалайзера. Звук перезапускается с текущей позиции ТОЛЬКО если фильтр реально изменился
        (перемотка, смена трека и пустые вызовы лишних перезапусков не вызывают)."""
        enabled = bool(enabled)
        gains, freqs = list(gains or []), list(freqs or [])
        eff = (tuple(gains), tuple(freqs)) if (enabled and gains and any(gains)) else None
        if eff == self._eq_eff and enabled == self._eq_enabled:
            return
        self._eq_eff = eff
        self._eq_enabled = enabled
        self._eq = (enabled, gains, freqs)
        if self._state == self.Playing and self.info is not None and self.info.has_audio:
            pos = int(self._clock_ms())
            self._begin_clock(pos)
            self._start_audio(pos)

    # ---------- звук ----------
    def _start_audio(self, pos_ms: int):
        self._stop_audio()
        info = self.info
        if info is None or not info.has_audio:
            return
        enabled, gains, freqs = self._eq
        freqs = list(freqs) or list(EQ_FREQUENCIES)
        gains = list(gains) if (enabled and gains) else [0] * len(freqs)
        thread = EqualizerAudioThread(Path(self.path), pos_ms, gains, self._volume, frequencies=freqs, parent=self)
        thread.failed.connect(self._on_audio_failed)
        thread.finished.connect(lambda: _retire_audio(self, "_audio", thread))
        self._audio = thread
        thread.start()

    def _stop_audio(self):
        thread, self._audio = self._audio, None
        if thread is not None:
            try:
                thread.failed.disconnect(self._on_audio_failed)
            except TypeError:
                pass
            thread.stop_audio()
            thread.wait(800)

    def _on_audio_failed(self, message: str):
        thread, self._audio = self._audio, None
        if thread is not None:
            thread.stop_audio()
        if self.info is not None and self.info.has_video:
            self._switch_to_wall(thread.clock_ms if thread is not None and thread.started else self._frozen_ms)
        else:
            self._fail(message)

    # ---------- видео ----------
    def _make_ladder(self) -> list:
        """Варианты запуска от лучшего к самому надёжному: если ffmpeg не стартует, пробуем следующий."""
        info = self.info
        lut = self._lut_name is not None
        hw = bool(self.use_hwaccel and info.v_codec in FF_HW_CODECS and info.width >= 1280)
        tm = bool(info.hdr)
        ladder = [dict(hw=hw, tonemap=tm, lut=lut)]
        if hw:
            ladder.append(dict(hw=False, tonemap=tm, lut=lut))
        if tm:
            ladder.append(dict(hw=False, tonemap=False, lut=lut))
        if lut:
            ladder.append(dict(hw=False, tonemap=False, lut=False))
        return ladder

    def _choose_out_size(self) -> tuple[int, int]:
        sw, sh = self.info.disp_size
        # Некоторые контейнеры/потоки не сообщают размер кадра; не делим на ноль.
        if sw <= 0 or sh <= 0:
            return 640, 360
        # 4K decode -> RGB24 -> Python/QImage can saturate memory bandwidth and make
        # the picture fall behind the independently played audio. Keep the 4K path
        # at 720p output; ordinary sources retain the 1080p ceiling.
        max_w, max_h = FF_4K_MAX_SIZE if sw >= 3000 or sh >= 1700 else FF_MAX_SIZE
        scale = min(1.0, max_w / sw, max_h / sh)
        tw, th = max(self._widget_size.width(), 1), max(self._widget_size.height(), 1)
        fit = min(tw / sw, th / sh)
        if 0 < fit < scale:                    # окно меньше кадра - декодируем кадр поменьше (но не мельче ~640)
            scale = max(fit, min(scale, 640 / sw))
        return max(2, int(round(sw * scale)) // 2 * 2), max(2, int(round(sh * scale)) // 2 * 2)

    def _choose_fps(self) -> tuple[float, str]:
        src = self.info.fps or 24.0
        cap = 30.0 if self.info.width >= 3000 else 60.0
        return snap_fps(min(src, cap))

    def _start_video(self, pos_ms: int):
        self._kill_video()
        if self.info is None or not self.info.has_video:
            return
        self._ladder = self._make_ladder()
        self._ladder_i = 0
        self._launch_video(pos_ms)

    def _launch_video(self, pos_ms: int):
        ffmpeg = shutil.which("ffmpeg")
        if not ffmpeg:
            self._fail("FFmpeg не найден в PATH или рядом с программой")
            return
        opts = self._ladder[self._ladder_i]
        w, h = self._choose_out_size()
        fps, fps_text = self._choose_fps()
        cmd = build_ffmpeg_video_cmd(ffmpeg, self.path, pos_ms, w, h, fps_text, self.info, opts, self._lut_name)
        try:
            self._pipe = _VideoPipe(cmd, str(self._tmpdir), w, h, fps, pos_ms)
        except OSError as exc:
            self._fail(f"Не удалось запустить ffmpeg: {exc}")
            return
        self._out_size = (w, h)

    def _restart_video(self):
        if self._state in (self.Playing, self.Paused) and self.info is not None and self.info.has_video:
            self._start_video(int(self._clock_ms()))

    def _kill_video(self):
        pipe, self._pipe = self._pipe, None
        if pipe is not None:
            pipe.kill()

    def _kill_all(self):
        self._stop_audio()
        self._kill_video()

    # ---------- цветокоррекция (3D-LUT для ffmpeg) ----------
    def set_color(self, params):
        grade = dict(params) if (params and not ColorGrade.is_neutral_params(params)) else None
        if grade == self._grade:
            return
        self._grade = grade
        self._grade_timer.start()

    def _apply_grade(self):
        self._lut_gen += 1
        gen = self._lut_gen
        if self._grade is None:
            self._lut_name = None
            self._restart_video()
            return
        params, name = dict(self._grade), f"grade_{gen}.cube"
        path = self._tmpdir / name

        def work():
            try:
                ColorGrade(params).write_cube(path)
                ok = True
            except Exception:  # noqa: BLE001
                ok = False
            if not getattr(self, "_closing_lut", False):
                self._lutReady.emit(gen, name if ok else "")

        _submit_lut(self, work)

    def _on_lut_ready(self, gen: int, name: str):
        if gen != self._lut_gen:
            return                              # пока считалась таблица, параметры успели измениться
        self._lut_name = name or None
        self._restart_video()
        for f in self._tmpdir.glob("grade_*.cube"):
            if f.name != name:
                try:
                    f.unlink()
                except OSError:
                    pass

    def set_widget_size(self, size: QSize):
        self._widget_size = QSize(size)
        if self._pipe is not None:
            self._resize_timer.start()

    def _on_resized(self):
        if self._pipe is None or self.info is None:
            return
        new_w = self._choose_out_size()[0]
        if abs(new_w - self._out_size[0]) > 0.2 * max(self._out_size[0], 1):
            self._restart_video()               # размер окна заметно изменился - перезапускаем с нужным размером

    # ---------- такт воспроизведения ----------
    def _to_image(self, buf, pipe) -> QImage:
        w, h = pipe.width, pipe.height
        return QImage(memoryview(buf), w, h, w * 3, QImage.Format.Format_RGB888).copy()

    def _tick(self):
        if self._state == self.Stopped:
            return
        now = self._clock_ms()
        mono = time.monotonic()
        if self._state == self.Playing and mono - self._last_emit >= 0.05:
            self._last_emit = mono
            dur = self.duration()
            self.positionChanged.emit(int(min(now, dur) if dur else now))
        pipe = self._pipe
        if pipe is not None:
            item = pipe.pop_due(now)
            if item is not None:
                self.frameReady.emit(self._to_image(item[1], pipe))
            if pipe.eof and pipe.count == 0:
                self._on_pipe_dead(now)
                return
        if self._state == self.Playing:
            self._check_end()

    def _on_pipe_dead(self, now: float):
        dur = self.duration()
        if dur and now >= dur - 300:
            self._finish()
            return
        err = self._pipe.error_text() if self._pipe is not None else ""
        if self._ladder_i + 1 < len(self._ladder):
            self._ladder_i += 1
            self._kill_video()
            self._launch_video(int(now))
        else:
            self._fail("Не удалось декодировать видео" + (f": {err}" if err else ""))

    def _check_end(self):
        pipe, a = self._pipe, self._audio
        video_done = pipe is None or (pipe.eof and pipe.pending == 0)
        audio_done = a is None or a.ended
        if video_done and audio_done:
            if not self._done_since:
                self._done_since = time.monotonic()
            elif time.monotonic() - self._done_since > 0.2:
                self._done_since = 0.0
                self._finish()
        else:
            self._done_since = 0.0

    def _finish(self):
        self._timer.stop()
        self._kill_all()
        self._state = self.Stopped
        self._frozen_ms = self._base_ms = 0
        self.stateChanged.emit(self.Stopped)
        self.statusChanged.emit(QMediaPlayer.MediaStatus.EndOfMedia)

    def _fail(self, message: str):
        self._timer.stop()
        self._kill_all()
        self._state = self.Stopped
        self.stateChanged.emit(self.Stopped)
        self.failed.emit(message)

    def shutdown(self):
        self._timer.stop()
        self._kill_all()
        _finish_lut(self)
        shutil.rmtree(self._tmpdir, ignore_errors=True)


class MpvPlayer(QObject):
    """libmpv backend. mpv owns decode, audio clock, video sync and GPU presentation."""

    positionChanged = pyqtSignal(int)
    durationChanged = pyqtSignal(int)
    stateChanged = pyqtSignal(object)
    statusChanged = pyqtSignal(object)
    failed = pyqtSignal(str)
    videoSizeChanged = pyqtSignal(int, int)
    _lutReady = pyqtSignal(int, str)

    Stopped = QMediaPlayer.PlaybackState.StoppedState
    Playing = QMediaPlayer.PlaybackState.PlayingState
    Paused = QMediaPlayer.PlaybackState.PausedState

    # Keep the DLL search handle alive: Windows otherwise may unload the added
    # search directory while resolving libmpv's dependent DLLs.
    _dll_directory_handles = {}
    seekWarning = pyqtSignal(str)

    class _Event(ctypes.Structure):
        _fields_ = [("event_id", ctypes.c_int), ("error", ctypes.c_int),
                    ("reply_userdata", ctypes.c_uint64), ("data", ctypes.c_void_p)]

    class _EndFile(ctypes.Structure):
        _fields_ = [("reason", ctypes.c_int), ("error", ctypes.c_int),
                    ("playlist_entry_id", ctypes.c_int64)]

    def __init__(self, parent=None):
        super().__init__(parent)
        self._lib = None
        self._handle = None
        self._widget = None
        self._available = False
        self._load_error = ""
        self.path = None
        self.info = None
        self._state = self.Stopped
        self._position_ms = 0
        self._duration_ms = 0
        self._volume = 0.5
        self._loaded = False
        self._ended = False
        self._file_ready = False
        self._file_event_id = None
        self._seek_auto_blocked = False
        self._pending_seek = None
        self._seek_in_flight = False
        self._seek_started = 0.0
        self._seek_warnings = set()
        self._last_seek = None
        self._last_position_emit = 0.0
        self._last_size = (0, 0)
        self._grade = None
        self._lut_path = None
        self._lut_gen = 0
        self._vignette_signature = None
        self._vignette_generation = 0
        self._vignette_shader_path = None
        self._tmpdir = Path(tempfile.mkdtemp(prefix="yamifm_mpv_"))
        self._eq_signature = None
        self._eq_enabled = False
        self._timer = QTimer(self)
        self._timer.setInterval(40)
        self._timer.timeout.connect(self._poll)
        self._lutReady.connect(self._on_lut_ready)

    @property
    def available(self):
        return self._available and self._handle is not None

    @property
    def load_error(self):
        return self._load_error

    def set_video_widget(self, widget):
        self._widget = widget

    @staticmethod
    def _mpv_dir_candidates():
        return [APP_DIR / "mpv", APP_DIR / "bin", APP_DIR]

    def _find_library(self):
        for directory in self._mpv_dir_candidates():
            dll = directory / "libmpv-2.dll"
            if dll.is_file():
                return directory, dll
        return None, None

    def ensure_initialized(self) -> bool:
        if self.available:
            return True
        if self._load_error and "not found" in self._load_error.lower():
            return False
        directory, dll = self._find_library()
        if dll is None:
            self._load_error = (
                "Встроенный libmpv-2.dll не найден. Переустановите NOP из NOP_Setup.exe."
                if FROZEN else
                "libmpv-2.dll не найден. Поместите полный runtime движка в папку mpv рядом с NOP_1.1.py."
            )
            return False
        try:
            if os.name == "nt" and hasattr(os, "add_dll_directory"):
                directory_key = os.path.normcase(str(directory.resolve()))
                if directory_key not in MpvPlayer._dll_directory_handles:
                    MpvPlayer._dll_directory_handles[directory_key] = os.add_dll_directory(str(directory))
            lib = ctypes.CDLL(str(dll))
            lib.mpv_client_api_version.argtypes = []
            lib.mpv_client_api_version.restype = ctypes.c_ulong
            if int(lib.mpv_client_api_version()) >> 16 != 2:
                raise RuntimeError("Unsupported libmpv client API; reinstall the NOP media runtime")
            lib.mpv_wait_event.restype = ctypes.POINTER(self._Event)
            lib.mpv_wait_event.argtypes = [ctypes.c_void_p, ctypes.c_double]
            lib.mpv_create.restype = ctypes.c_void_p
            lib.mpv_create.argtypes = []
            lib.mpv_set_option_string.restype = ctypes.c_int
            lib.mpv_set_option_string.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p]
            lib.mpv_initialize.restype = ctypes.c_int
            lib.mpv_initialize.argtypes = [ctypes.c_void_p]
            lib.mpv_command.restype = ctypes.c_int
            lib.mpv_command.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_char_p)]
            lib.mpv_set_property_string.restype = ctypes.c_int
            lib.mpv_set_property_string.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p]
            lib.mpv_get_property.restype = ctypes.c_int
            lib.mpv_get_property.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int, ctypes.c_void_p]
            lib.mpv_get_property_string.restype = ctypes.c_void_p
            lib.mpv_get_property_string.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
            lib.mpv_free.restype = None
            lib.mpv_free.argtypes = [ctypes.c_void_p]
            lib.mpv_error_string.restype = ctypes.c_char_p
            lib.mpv_error_string.argtypes = [ctypes.c_int]
            lib.mpv_terminate_destroy.restype = None
            lib.mpv_terminate_destroy.argtypes = [ctypes.c_void_p]
            handle = lib.mpv_create()
            if not handle:
                raise RuntimeError("mpv_create вернул пустой указатель")
            if self._widget is None:
                raise RuntimeError("не задано окно видеовывода mpv")

            # A dedicated native child window is the only video surface. mpv keeps
            # full-resolution frames on its decode/render path instead of copying RGB
            # frames through Python and QImage.
            surface = self._widget.mpv_surface()
            wid = int(surface.winId())
            options = {
                "wid": str(wid),
                "config": "no",
                "vo": "gpu-next",
                "gpu-context": "d3d11",
                "gpu-api": "d3d11",
                "hwdec": "auto-safe",
                "video-sync": "audio",
                "keep-open": "yes",
                "force-window": "no",
                "osc": "no",
                "osd-level": "0",
                "input-default-bindings": "no",
                "input-vo-keyboard": "no",
                "pause": "yes",
                "volume": "50",
                "audio-display": "no",
                "msg-level": "all=warn",
            }
            for name, value in options.items():
                code = lib.mpv_set_option_string(handle, name.encode(), value.encode())
                if code < 0:
                    raise RuntimeError(f"mpv не принял настройку {name}: {self._error_text(lib, code)}")
            code = lib.mpv_initialize(handle)
            if code < 0:
                raise RuntimeError(f"mpv_initialize: {self._error_text(lib, code)}")
            self._lib, self._handle = lib, handle
            self._available = True
            self._load_error = ""
            self._timer.start()
            self._set_property("volume", str(self._volume * 100.0))
            return True
        except Exception as exc:  # noqa: BLE001
            try:
                if 'handle' in locals() and handle and 'lib' in locals():
                    lib.mpv_terminate_destroy(handle)
            except Exception:  # noqa: BLE001
                pass
            self._available = False
            self._handle = None
            self._lib = None
            self._load_error = f"Не удалось инициализировать libmpv: {exc}"
            return False

    @staticmethod
    def _error_text(lib, code):
        try:
            raw = lib.mpv_error_string(int(code))
            return raw.decode("utf-8", "replace") if raw else str(code)
        except Exception:  # noqa: BLE001
            return str(code)

    def _command(self, *args) -> int:
        if not self.available:
            return -1
        values = [str(arg).encode("utf-8") for arg in args]
        argv = (ctypes.c_char_p * (len(values) + 1))(*values, None)
        code = int(self._lib.mpv_command(self._handle, argv))
        return code

    def _set_property(self, name: str, value: str) -> int:
        if not self.available:
            return -1
        return int(self._lib.mpv_set_property_string(
            self._handle, name.encode("utf-8"), str(value).encode("utf-8")
        ))

    def _set_option(self, name: str, value: str) -> int:
        """Set a live mpv option, using the explicit options/ namespace first."""
        if not self.available:
            return -1
        code = self._set_property("options/" + name, value)
        if code >= 0:
            return code
        # Some older libmpv builds expose a subset of option properties without the
        # namespace. Keep this fallback so supported builds can still change LUTs live.
        return self._set_property(name, value)

    def _get_double(self, name: str):
        if not self.available:
            return None
        value = ctypes.c_double()
        code = self._lib.mpv_get_property(self._handle, name.encode("utf-8"), 5, ctypes.byref(value))
        return value.value if code >= 0 and value.value == value.value else None

    def _get_int64(self, name: str):
        if not self.available:
            return None
        value = ctypes.c_int64()
        code = self._lib.mpv_get_property(self._handle, name.encode("utf-8"), 4, ctypes.byref(value))
        return int(value.value) if code >= 0 else None

    def _get_flag(self, name: str):
        if not self.available:
            return None
        value = ctypes.c_int()
        code = self._lib.mpv_get_property(self._handle, name.encode("utf-8"), 3, ctypes.byref(value))
        return bool(value.value) if code >= 0 else None

    def _get_string(self, name: str):
        """Read a string property from libmpv and release its allocated buffer."""
        if not self.available:
            return None
        ptr = self._lib.mpv_get_property_string(self._handle, name.encode("utf-8"))
        if not ptr:
            return None
        try:
            return ctypes.string_at(ptr).decode("utf-8", "replace")
        finally:
            self._lib.mpv_free(ptr)

    def get_tracks(self):
        """Return the actual track-list exposed by mpv, including selected IDs."""
        count = self._get_int64("track-list/count")
        if count is None:
            return []
        tracks = []
        for index in range(max(0, min(int(count), 256))):
            prefix = f"track-list/{index}/"
            track_id = self._get_int64(prefix + "id")
            track_type = self._get_string(prefix + "type") or ""
            if track_id is None or track_type not in {"audio", "video", "sub"}:
                continue
            tracks.append({
                "id": int(track_id),
                "type": track_type,
                "title": self._get_string(prefix + "title") or "",
                "lang": self._get_string(prefix + "lang") or "",
                "codec": self._get_string(prefix + "codec") or "",
                "selected": (self._get_string(prefix + "selected") or "no").lower() == "yes",
                "external": (self._get_string(prefix + "external") or "no").lower() == "yes",
            })
        return tracks

    def select_track(self, track_type: str, track_id=None) -> bool:
        """Select an mpv audio/video/subtitle track; None disables subtitles."""
        prop = {"audio": "aid", "video": "vid", "sub": "sid"}.get(track_type)
        if not prop or not self.available:
            return False
        value = "no" if track_id is None else str(int(track_id))
        return self._set_property(prop, value) >= 0

    def set_media(self, path: str, info: MediaInfo):
        if not self.ensure_initialized():
            return False
        self.stop()
        # Discard notifications belonging to the stopped file before replacing it.
        while self._lib.mpv_wait_event(self._handle, 0).contents.event_id:
            pass
        self.path, self.info = str(path), info
        self._position_ms = 0
        self._duration_ms = int(info.duration_ms or 0)
        self._ended = False
        self._loaded = False
        self._file_ready = False
        self._seek_warnings.clear()
        self._file_event_id = None
        self._seek_auto_blocked = False
        self.statusChanged.emit(QMediaPlayer.MediaStatus.LoadingMedia)
        self._last_size = (0, 0)
        self.durationChanged.emit(self._duration_ms)
        if info.has_video:
            w, h = info.disp_size
            self._last_size = (w, h)
            self.videoSizeChanged.emit(w, h)
        # Load while paused, then allow play() to release playback. This avoids a race
        # in which video starts before the UI switches the native surface on.
        self._set_property("pause", "yes")
        code = self._command("loadfile", self.path, "replace")
        if code < 0:
            self.failed.emit("mpv не смог открыть файл: " + self._error_text(self._lib, code))
            return False
        self._loaded = True
        self._state = self.Stopped
        # The correction LUT's input domain depends on the source transfer function.
        # Regenerate when switching between SDR and HDR while a grade is enabled.
        # Clear a previous track's LUT immediately; it may use a different HDR/SDR
        # domain. The appropriate table is regenerated below for the new source.
        self._lut_path = None
        self._apply_video_filters()
        if self._grade is not None:
            self._request_lut_generation()
        self._apply_equalizer()
        return True

    def duration(self) -> int:
        value = self._get_double("duration")
        if value is not None and value >= 0:
            return int(value * 1000)
        return self._duration_ms

    def position(self) -> int:
        value = self._get_double("time-pos")
        if value is not None and value >= 0:
            self._position_ms = int(value * 1000)
        return self._position_ms

    def playbackState(self):
        return self._state

    def play(self):
        if not self.available:
            return
        if not self._loaded:
            if not self.path or self.info is None or not self.set_media(self.path, self.info):
                return
        if self._ended:
            self.setPosition(0)
            self._ended = False
        self._set_property("pause", "no")
        if self._state != self.Playing:
            self._state = self.Playing
            self.stateChanged.emit(self.Playing)

    def play_from(self, pos_ms: int):
        if not self._loaded:
            return
        self.setPosition(pos_ms)
        self.play()

    def pause(self):
        if self._state != self.Playing:
            return
        self._position_ms = self.position()
        self._set_property("pause", "yes")
        self._state = self.Paused
        self.stateChanged.emit(self.Paused)

    def stop(self):
        was_active = self._state != self.Stopped or self._loaded
        if self.available and was_active:
            self._command("stop")
            self._set_property("pause", "yes")
        self._state = self.Stopped
        self._position_ms = 0
        self._loaded = False
        self._ended = False
        self._file_ready = False
        self._pending_seek = None
        self._seek_in_flight = False
        self._last_seek = None
        self._seek_auto_blocked = False
        if was_active:
            self.stateChanged.emit(self.Stopped)
            self.statusChanged.emit(QMediaPlayer.MediaStatus.NoMedia)
        if self.available:
            self._timer.start()

    def set_playback_rate(self, rate: float) -> bool:
        if not self.available:
            return False
        code = self._command("set", "speed", str(max(0.25, min(8.0, float(rate)))))
        return code >= 0

    def setPosition(self, ms: int, *, automatic=False):
        try:
            value = float(ms)
            if not math.isfinite(value):
                raise ValueError("non-finite position")
            ms = max(0, int(value))
        except (TypeError, ValueError, OverflowError):
            self._seek_warning("position", ui_text("Недопустимая позиция перемотки", "Invalid seek position"))
            return False
        if not self.available or not self._loaded:
            return False  # stop/unloaded must not retain a seek for a later file
        if automatic and self._seek_auto_blocked:
            return False
        if not automatic:
            self._seek_auto_blocked = False
        dur = self.duration()
        if dur > 0:
            ms = min(ms, max(0, dur - 1))
        if self._last_seek == ms and (self._seek_in_flight or abs(self.position() - ms) <= 20):
            self._pending_seek = None
            return True
        # One latest target, including requests received while a file/seek is loading.
        self._pending_seek = ms
        return self._flush_seek() is not False

    def _seek_warning(self, key, message):
        if key in self._seek_warnings:
            return
        self._seek_warnings.add(key)
        self.seekWarning.emit(message)

    def _flush_seek(self):
        if self._pending_seek is None or not self._loaded or not self._file_ready:
            return None
        if self._seek_in_flight or self._get_flag("seeking") is True:
            return None
        if self._get_flag("idle-active") is not False or self._get_double("time-pos") is None:
            return None
        ms, self._pending_seek = self._pending_seek, None
        if self._get_flag("seekable") is False:
            self._seek_auto_blocked = True
            self._seek_warning("unseekable", ui_text(
                "Этот источник mpv не поддерживает перемотку.", "This mpv source does not support seeking."))
            return False
        dur = self.duration()
        if dur > 0:
            ms = min(ms, max(0, dur - 1))
        code = self._command("seek", f"{ms / 1000.0:.3f}", "absolute+exact")
        if code < 0:
            self._seek_auto_blocked = True
            # A rejected seek is recoverable and must not fail the entire media.
            self._seek_warning(("command", code), ui_text(
                "Перемотка mpv не выполнена", "mpv seek failed") +
                f": {self._error_text(self._lib, code)} ({code}); " +
                f"{Path(self.path).name}, {ms / 1000:.3f}s / {dur / 1000:.3f}s; " +
                f"idle={self._get_flag('idle-active')}, seeking={self._get_flag('seeking')}.")
            return False
        self._last_seek = ms
        self._seek_in_flight = True
        self._seek_started = time.monotonic()
        self._position_ms = ms
        self.positionChanged.emit(ms)
        return True

    def _read_events(self):
        while True:
            event = self._lib.mpv_wait_event(self._handle, 0).contents
            if event.event_id == 0:
                break
            if event.event_id == 6:  # MPV_EVENT_START_FILE
                self._file_event_id = ctypes.cast(event.data, ctypes.POINTER(ctypes.c_int64)).contents.value if event.data else None
                self._file_ready = False
                self._seek_in_flight = False
            elif event.event_id == 8 and self._loaded:  # MPV_EVENT_FILE_LOADED
                loaded_path = self._get_string("path")
                if loaded_path and os.path.normcase(os.path.abspath(loaded_path)) == os.path.normcase(os.path.abspath(self.path)):
                    self._file_ready = True
                    self.statusChanged.emit(QMediaPlayer.MediaStatus.LoadedMedia)
            elif event.event_id == 21:  # MPV_EVENT_PLAYBACK_RESTART (also while paused)
                self._seek_in_flight = False
            elif event.event_id == 7 and event.data:  # MPV_EVENT_END_FILE
                end = ctypes.cast(event.data, ctypes.POINTER(self._EndFile)).contents
                if end.reason == 4 and self._loaded and end.playlist_entry_id == self._file_event_id:
                    self._loaded = self._file_ready = False
                    self._pending_seek = None
                    self._state = self.Stopped
                    self.stateChanged.emit(self.Stopped)
                    self.statusChanged.emit(QMediaPlayer.MediaStatus.InvalidMedia)
                    self.failed.emit(ui_text("Ошибка загрузки mpv: ", "mpv load failed: ") +
                                     self._error_text(self._lib, end.error))

    def set_volume(self, volume: float):
        self._volume = max(0.0, min(1.0, float(volume)))
        if self.available:
            self._set_property("volume", str(self._volume * 100.0))

    def set_equalizer(self, enabled: bool, gains, freqs):
        gains, freqs = list(gains or []), list(freqs or [])
        eff = tuple((int(f), round(float(g), 2)) for f, g in zip(freqs, gains) if enabled and abs(float(g)) >= 0.005)
        enabled = bool(enabled)
        signature = eff if enabled else ()
        if signature == self._eq_signature and enabled == self._eq_enabled:
            return
        self._eq_signature = signature
        self._eq_enabled = enabled
        self._eq_filters = eff
        self._apply_equalizer()

    def _apply_equalizer(self):
        if not self.available or not self._loaded:
            return
        filters = getattr(self, "_eq_filters", ())
        if not filters:
            # Убираем именно всю цепочку аудиофильтров mpv при выключении EQ.
            # Команда выполняется и при повторном выключении: после смены файла
            # mpv мог восстановить цепочку из состояния предыдущего файла.
            code = self._command("af", "clr")
            if code < 0:
                # Резервный способ для сборок mpv, где команда af clr не поддержана.
                self._command("af", "set", "")
            return
        pieces = []
        for freq, gain in filters:
            # A chain of FFmpeg's native equalizer filters, managed by mpv with the
            # same transport clock as the video; no second audio playback process.
            pieces.append(f"equalizer=f={freq}:width_type=q:width=1:g={gain:.2f}")
        graph = "lavfi=[" + ",".join(pieces) + "]"
        code = self._command("af", "set", graph)
        if code < 0:
            self.failed.emit("Не удалось включить эквалайзер mpv: " + self._error_text(self._lib, code))

    def set_color(self, params):
        grade = dict(params) if (params and not ColorGrade.is_neutral_params(params)) else None
        if grade == self._grade:
            return
        self._grade = grade
        self._lut_gen += 1
        if grade is None:
            self._lut_path = None
            self._apply_video_filters()
            return
        self._request_lut_generation()

    def set_vignette(self, params):
        """Render vignette in libplacebo on the video texture, never in a native overlay HWND."""
        if params is None:
            signature = None
        else:
            p = ColorGrade.normalize(params)
            amount = int(p.get("vignette", 0))
            signature = (amount, int(p.get("vignette_mid", 50)), int(p.get("vignette_feather", 50))) if amount else None

        if signature == self._vignette_signature:
            # If the request was made before libmpv initialized, retry once it is available.
            if not self.available:
                return
            if signature is None or self._vignette_shader_path is not None:
                return
        self._vignette_signature = signature
        self._vignette_generation += 1
        if not self.available:
            return

        if signature is None:
            code = self._set_option("glsl-shaders", "")
            self._vignette_shader_path = None
            if code < 0:
                self._load_error = "Не удалось отключить GPU-виньетку mpv: " + self._error_text(self._lib, code)
                self.failed.emit(self._load_error)
            return

        amount, mid, feather = signature
        start = mid / 100.0 * 0.9
        span = max(0.05, feather / 100.0 * 0.9 + 0.1)
        strength = abs(amount) / 100.0
        generation = self._vignette_generation
        shader_path = self._tmpdir / f"vignette_{generation}.hook"
        # HOOK PREOUTPUT runs after video scaling and color conversion, before
        # subtitle/OSD alpha blending. That avoids an extra pass at full source
        # resolution (e.g. 4K), reducing GPU load on slower/mobile GPUs, and keeps
        # the vignette tied to the rendered video rather than the UI/panel geometry.
        if amount < 0:
            effect = f"color.rgb *= (1.0 - edge * {strength:.8f});"
        else:
            effect = f"color.rgb = mix(color.rgb, vec3(1.0), edge * {strength:.8f});"
        shader = f"""//!HOOK PREOUTPUT
//!BIND HOOKED

vec4 hook()
{{
    vec4 color = HOOKED_tex(HOOKED_pos);
    vec2 centered = (HOOKED_pos - vec2(0.5)) * 2.0;
    float radius = length(centered) / 1.41421356;
    float edge = smoothstep({start:.8f}, {start + span:.8f}, radius);
    {effect}
    return color;
}}
"""
        try:
            shader_path.write_text(shader, encoding="utf-8")
        except OSError as exc:
            self._load_error = f"Не удалось создать GPU-шейдер виньетки: {exc}"
            self.failed.emit(self._load_error)
            self._vignette_shader_path = None
            return

        code = self._set_option("glsl-shaders", str(shader_path.resolve()))
        if code < 0:
            self._load_error = "Не удалось применить GPU-виньетку mpv: " + self._error_text(self._lib, code)
            self.failed.emit(self._load_error)
            self._vignette_shader_path = None
            return
        self._vignette_shader_path = shader_path
        self._load_error = ""

    def _request_lut_generation(self):
        if self._grade is None:
            self._lut_path = None
            self._apply_video_filters()
            return
        self._lut_gen += 1
        gen = self._lut_gen
        hdr = bool(self.info is not None and self.info.hdr)
        # PQ has a much more demanding dark range; use a denser LUT for HDR sources.
        # The grade is designed in normalized SDR/sRGB space. Build one 3D LUT;
        # mpv's target-lut applies it after HDR/SDR source conversion on the GPU.
        # For HDR, target-trc/target-prim are switched to an SDR BT.709 target while
        # the grade is active, so mpv itself performs the source tone mapping first.
        size = 52
        path = self._tmpdir / f"grade_{gen}.cube"
        params_copy = dict(self._grade)

        def work():
            try:
                ColorGrade(params_copy).write_cube(path, size=size)
                name = str(path)
            except Exception:  # noqa: BLE001
                name = ""
            if not getattr(self, "_closing_lut", False):
                self._lutReady.emit(gen, name)

        _submit_lut(self, work)

    def _on_lut_ready(self, gen: int, path: str):
        if gen != self._lut_gen:
            return
        self._lut_path = path or None
        self._apply_video_filters()
        if not path and self._grade is not None:
            self.failed.emit("Цветокоррекция не применена: не удалось создать LUT.")
        # Once mpv has switched to the new LUT, older temporary files are no longer used.
        for old in self._tmpdir.glob("grade_*.cube"):
            if self._lut_path and old == Path(self._lut_path):
                continue
            try:
                old.unlink()
            except OSError:
                pass

    def _apply_video_filters(self):
        """Apply the existing SDR grade after mpv's source-to-display conversion.

        target-lut is part of gpu-next/libplacebo's GPU renderer. For graded video,
        the output target is explicitly SDR BT.709 so the existing grade remains in
        its intended normalized sRGB-like domain. mpv still performs HDR tone mapping
        itself; no HDR frame is transferred to Python or LUT-baked using guessed PQ math.
        With correction off, target-lut and target overrides are cleared so normal
        display-aware HDR handling returns.
        """
        if not self.available or not self._loaded:
            return
        lut_path = self._lut_path if self._lut_path and Path(self._lut_path).is_file() else None
        if not lut_path:
            code = self._set_option("target-lut", "")
            code_trc = self._set_option("target-trc", "auto")
            code_prim = self._set_option("target-prim", "auto")
            if code < 0:
                self._load_error = "Не удалось сбросить GPU LUT mpv: " + self._error_text(self._lib, code)
            elif code_trc < 0 or code_prim < 0:
                bad = code_trc if code_trc < 0 else code_prim
                self._load_error = "Не удалось вернуть автоматическую HDR-обработку mpv: " + self._error_text(self._lib, bad)
            else:
                self._load_error = ""
            return

        # The LUT itself uses the same SDR-domain transform as the previous FFmpeg
        # correction path. Tone mapping is left to libplacebo/mpv before target-lut.
        code_trc = self._set_option("target-trc", "srgb")
        code_prim = self._set_option("target-prim", "bt.709")
        code_lut = self._set_option("target-lut", str(Path(lut_path).resolve()))
        if code_trc < 0 or code_prim < 0 or code_lut < 0:
            code = code_trc if code_trc < 0 else code_prim if code_prim < 0 else code_lut
            message = "Не удалось применить GPU LUT mpv: " + self._error_text(self._lib, code)
            self._load_error = message
            self.failed.emit(message)
            return
        self._load_error = ""

    def _poll(self):
        if not self.available:
            return
        self._read_events()
        # Playback-restart normally completes a seek. Property fallback handles
        # builds that omit it, without issuing a second command in the same poll.
        if (self._seek_in_flight and time.monotonic() - self._seek_started > 0.1
                and self._get_flag("seeking") is False):
            self._seek_in_flight = False
        self._flush_seek()
        position = self._get_double("time-pos")
        if position is not None and position >= 0:
            self._position_ms = int(position * 1000)
        duration = self._get_double("duration")
        if duration is not None and duration > 0:
            dms = int(duration * 1000)
            if dms != self._duration_ms:
                self._duration_ms = dms
                self.durationChanged.emit(dms)
        now = time.monotonic()
        if self._state == self.Playing and now - self._last_position_emit >= 0.05:
            self._last_position_emit = now
            self.positionChanged.emit(self._position_ms)
        width = self._get_int64("video-params/dw") or self._get_int64("video-params/w")
        height = self._get_int64("video-params/dh") or self._get_int64("video-params/h")
        if width and height and (width, height) != self._last_size:
            self._last_size = (width, height)
            self.videoSizeChanged.emit(int(width), int(height))
        eof = self._get_flag("eof-reached")
        if eof and self._state == self.Playing and not self._ended:
            self._ended = True
            self._position_ms = self.duration() or self._position_ms
            self._state = self.Stopped
            self.stateChanged.emit(self.Stopped)
            self.statusChanged.emit(QMediaPlayer.MediaStatus.EndOfMedia)

    def shutdown(self):
        self._timer.stop()
        handle, self._handle = self._handle, None
        self._available = False
        if handle and self._lib is not None:
            try:
                self._lib.mpv_terminate_destroy(handle)
            except Exception:  # noqa: BLE001
                pass
        self._lib = None
        _finish_lut(self)
        shutil.rmtree(self._tmpdir, ignore_errors=True)


class PlayerFacade(QObject):
    """Unified controls over libmpv (video), Qt Multimedia and legacy FFmpeg fallback."""

    positionChanged = pyqtSignal(int)
    durationChanged = pyqtSignal(int)
    playbackStateChanged = pyqtSignal(object)
    mediaStatusChanged = pyqtSignal(object)
    errorOccurred = pyqtSignal(object, str)
    frameReady = pyqtSignal(object)
    videoSizeChanged = pyqtSignal(int, int)
    backendChanged = pyqtSignal(str)
    seekWarning = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.qt = QMediaPlayer(self)
        self.ff = FFmpegPlayer(self)
        self.mpv = MpvPlayer(self)
        self._video_widget = None
        self.active = "qt"
        self.path = ""
        self.info = None
        self.force = os.environ.get("YAMI_BACKEND", "").lower()      # "ff" или "qt" - принудительно (отладка)
        self._ff_tried: set[str] = set()
        self._qt_frames = 0
        self._qt_play_t0 = 0.0
        qt = self.qt
        qt.positionChanged.connect(lambda v: self._from("qt", self.positionChanged, v))
        qt.durationChanged.connect(lambda v: self._from("qt", self.durationChanged, v))
        qt.playbackStateChanged.connect(lambda v: self._from("qt", self.playbackStateChanged, v))
        qt.mediaStatusChanged.connect(self._on_qt_status)
        qt.errorOccurred.connect(self._on_qt_error)
        ff = self.ff
        ff.positionChanged.connect(lambda v: self._from("ff", self.positionChanged, v))
        ff.durationChanged.connect(lambda v: self._from("ff", self.durationChanged, v))
        ff.stateChanged.connect(lambda v: self._from("ff", self.playbackStateChanged, v))
        ff.statusChanged.connect(lambda v: self._from("ff", self.mediaStatusChanged, v))
        ff.frameReady.connect(lambda img: self._from("ff", self.frameReady, img))
        ff.videoSizeChanged.connect(lambda w, h: self._from("ff", self.videoSizeChanged, w, h))
        ff.failed.connect(lambda msg: self.errorOccurred.emit(QMediaPlayer.Error.ResourceError, msg))
        mpv = self.mpv
        mpv.seekWarning.connect(self.seekWarning)
        mpv.positionChanged.connect(lambda v: self._from("mpv", self.positionChanged, v))
        mpv.durationChanged.connect(lambda v: self._from("mpv", self.durationChanged, v))
        mpv.stateChanged.connect(lambda v: self._from("mpv", self.playbackStateChanged, v))
        mpv.statusChanged.connect(lambda v: self._from("mpv", self.mediaStatusChanged, v))
        mpv.videoSizeChanged.connect(lambda w, h: self._from("mpv", self.videoSizeChanged, w, h))
        mpv.failed.connect(lambda msg: self.errorOccurred.emit(QMediaPlayer.Error.ResourceError, msg))
        self._watch = QTimer(self)
        self._watch.setInterval(1000)
        self._watch.timeout.connect(self._watchdog)
        self._watch.start()

    def _from(self, name: str, signal, *args):
        if self.active == name:
            signal.emit(*args)

    # ---------- настройка выходов ----------
    def setAudioOutput(self, output):
        self.qt.setAudioOutput(output)

    def setVideoSink(self, sink):
        self.qt.setVideoSink(sink)
        sink.videoFrameChanged.connect(self._on_qt_frame)

    def setVideoWidget(self, widget):
        self._video_widget = widget
        self.mpv.set_video_widget(widget)

    def _on_qt_frame(self, _frame=None):
        self._qt_frames += 1

    # ---------- источник и управление ----------
    def setSource(self, url):
        self.qt.stop()
        self.ff.stop()
        self.mpv.stop()
        self.path = url.toLocalFile() if url.isLocalFile() else ""
        self.info = probe_media(self.path) if self.path else None
        self._qt_frames = 0
        self._qt_play_t0 = 0.0

        has_playable_stream = bool(
            self.path and self.info and (self.info.has_video or self.info.audio)
        )
        if self.force == "mpv":
            want_mpv = bool(has_playable_stream and self.mpv.ensure_initialized())
        else:
            # mpv умеет менять скорость и у аудио, поэтому используем его не только для видео.
            # Если libmpv недоступен, остаются Qt/FFmpeg как раньше.
            want_mpv = bool(
                self.force not in ("qt", "ff") and has_playable_stream
                and self.mpv.ensure_initialized()
            )
        if want_mpv:
            self.active = "mpv"
            loaded = self.mpv.set_media(self.path, self.info)
            if not loaded:
                # Never leave the facade on a dead mpv backend after a load error.
                self.active = choose_backend(self.info, "ff" if self.force == "ff" else "")
                if self.active == "ff":
                    self.ff.set_media(self.path, self.info)
                else:
                    self.qt.setSource(url)
        else:
            self.active = choose_backend(self.info, "ff" if self.force == "ff" else self.force)
            if self.active == "ff":
                self.ff.set_media(self.path, self.info)
            else:
                self.qt.setSource(url)
        self.backendChanged.emit(self.active)

    def play(self):
        if self.active == "mpv":
            self.mpv.play()
        elif self.active == "ff":
            self.ff.play()
        else:
            if not self._qt_play_t0:
                self._qt_play_t0 = time.monotonic()
            self.qt.play()

    def pause(self):
        (self.mpv if self.active == "mpv" else self.ff if self.active == "ff" else self.qt).pause()

    def stop(self):
        self.qt.stop()
        self.ff.stop()
        self.mpv.stop()

    def setPosition(self, ms: int, *, automatic=False):
        if self.active == "mpv":
            return self.mpv.setPosition(ms, automatic=automatic)
        return (self.ff if self.active == "ff" else self.qt).setPosition(int(ms))

    def set_playback_rate(self, rate: float) -> bool:
        """Изменяет скорость Qt/mpv; FFmpeg fallback пока не поддерживает изменение скорости."""
        rate = max(0.25, min(8.0, float(rate)))
        if self.active == "mpv":
            return self.mpv.set_playback_rate(rate)
        if self.active == "qt":
            self.qt.setPlaybackRate(rate)
            # У Qt Multimedia поддержка скорости аудио зависит от системного backend;
            # не сообщаем UI, что ускорение MP3 гарантированно сработало.
            if self.info is not None and not self.info.has_video and abs(rate - 1.0) > 0.001:
                return False
            return True
        return False

    def position(self) -> int:
        return self.mpv.position() if self.active == "mpv" else self.ff.position() if self.active == "ff" else self.qt.position()

    def duration(self) -> int:
        return self.mpv.duration() if self.active == "mpv" else self.ff.duration() if self.active == "ff" else self.qt.duration()

    def playbackState(self):
        return self.mpv.playbackState() if self.active == "mpv" else self.ff.playbackState() if self.active == "ff" else self.qt.playbackState()

    # ---------- возможности аппаратного / FFmpeg backend ----------
    def set_volume(self, volume: float):
        self.ff.set_volume(volume)
        self.mpv.set_volume(volume)

    def set_color(self, params):
        if self.active == "mpv":
            self.mpv.set_color(params)
        else:
            self.ff.set_color(params)

    def set_vignette(self, params):
        # mpv renders this spatial effect as a libplacebo shader. FFmpeg's fallback
        # continues to draw it into the QImage frame through VideoFrameWidget.
        self.mpv.set_vignette(params if self.active == "mpv" else None)

    def set_equalizer(self, enabled: bool, gains, freqs):
        if self.active == "mpv":
            self.mpv.set_equalizer(enabled, gains, freqs)
        else:
            self.ff.set_equalizer(enabled, gains, freqs)

    def set_widget_size(self, size):
        self.ff.set_widget_size(size)

    def shutdown(self):
        self._watch.stop()
        self.qt.stop()
        self.qt.setSource(QUrl())
        self.qt.setVideoSink(None)
        self.qt.setAudioOutput(None)
        self.ff.shutdown()
        self.mpv.shutdown()

    # ---------- переход на ffmpeg, если Qt не справился ----------
    def _on_qt_status(self, status):
        if self.active != "qt":
            return
        if status == QMediaPlayer.MediaStatus.InvalidMedia and self._try_ff():
            return
        self.mediaStatusChanged.emit(status)

    def _on_qt_error(self, error, message=""):
        if self.active != "qt":
            return
        if self._try_ff():
            return
        self.errorOccurred.emit(error, message)

    def _try_ff(self, pos_ms: int = 0) -> bool:
        if (not self.path or self.path in self._ff_tried or self.info is None or not self.info.ok
                or shutil.which("ffmpeg") is None):
            return False
        self._ff_tried.add(self.path)
        self.active = "ff"
        self.qt.stop()
        self.ff.set_media(self.path, self.info)
        self.backendChanged.emit("ff")
        self.ff.play_from(int(pos_ms))
        return True

    def _watchdog(self):
        """Qt «играет», но картинки нет (кодек не поддерживается) - переключаемся на ffmpeg."""
        if (self.active == "qt" and self.info is not None and self.info.has_video and self._qt_frames == 0
                and self.qt.playbackState() == QMediaPlayer.PlaybackState.PlayingState
                and self._qt_play_t0 and time.monotonic() - self._qt_play_t0 > 4.0):
            self._try_ff(self.qt.position())


WINDOW_CORNER_RADIUS = 12
VIDEO_CORNER_RADIUS = 12


def rounded_widget_region(size, radius):
    """A small symmetric native region, in Qt logical pixels (Qt handles DPI)."""
    width, height = size.width(), size.height()
    radius = max(0, min(int(radius), width // 2, height // 2))
    if width <= 0 or height <= 0:
        return QRegion()
    if not radius:
        return QRegion(QRect(0, 0, width, height))
    region = QRegion(QRect(0, radius, width, height - 2 * radius))
    for row in range(radius):
        # Test pixel centers; use identical rows at both ends and mirror X.
        inset = max(0, math.ceil(radius - math.sqrt(radius * radius - (radius - row - .5) ** 2) - .5))
        region |= QRegion(QRect(inset, row, width - 2 * inset, 1))
        region |= QRegion(QRect(inset, height - row - 1, width - 2 * inset, 1))
    return region


class VideoFrameWidget(QWidget):
    """Видеовывод. Два источника кадров: QVideoSink (движок Qt; цветокоррекция делается здесь, в отдельном
    потоке) и плеер на ffmpeg (кадры приходят уже готовыми - с цветокоррекцией и HDR->SDR на стороне ffmpeg).
    Без коррекции кадр показывается как есть."""

    resized = pyqtSignal(QSize)
    doubleClicked = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        # Keep VideoFrameWidget as the native parent of mpv's child HWND.
        self.setAttribute(Qt.WidgetAttribute.WA_NativeWindow, True)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)
        self.setMinimumSize(VIDEO_MIN_WIDTH, VIDEO_MIN_HEIGHT)
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setStyleSheet("background:black;")
        self._sink = QVideoSink(self)
        self._sink.videoFrameChanged.connect(self._on_frame)
        self._raw_image = None
        self._frame_image = None
        self._static_cover = None
        self._grade = ColorGrade()
        self._grade_active = False
        self._worker = None
        self._ext_active = False
        self._ext_size = QSize()
        self._vignette = None
        self._vig_key = None
        self._vig_image = None
        self._vig_grade = ColorGrade()
        self._mpv_active = False

        # mpv renders to its own native child HWND; decoded frames are never copied
        # through a Python RGB queue or QImage.
        self._mpv_surface = QWidget(self)
        self._mpv_surface.setObjectName("mpvVideoSurface")
        self._mpv_surface.setStyleSheet("background:black;")
        self._mpv_surface.setAttribute(Qt.WidgetAttribute.WA_NativeWindow, True)
        # Не устанавливаем WA_DontCreateNativeAncestors: поверхность должна быть
        # дочерним HWND именно VideoFrameWidget, а не координатно привязанной к окну приложения.
        self._mpv_surface.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self._mpv_surface.setMouseTracking(True)
        self._mpv_surface.hide()


    def set_static_cover(self, path: str | Path | None):
        image = QImage(str(path)) if path else QImage()
        self._static_cover = image if not image.isNull() else None
        # Не показываем последний кадр предыдущего видео поверх обложки нового аудио.
        self._raw_image = None
        self._frame_image = None
        self.update()

    def videoSink(self):
        return self._sink

    def mpv_surface(self):
        return self._mpv_surface

    def set_mpv_active(self, on: bool):
        self._mpv_active = bool(on)
        self.sync_mpv_surfaces()
        self._mpv_surface.setVisible(self._mpv_active)
        if self._mpv_active:
            # mpv is the sole native video surface. Spatial effects are rendered
            # inside libplacebo, so no transparent child HWND covers the picture.
            self._mpv_surface.raise_()
        self.update()

    def _sync_rounded_video(self):
        surface = getattr(self, "_mpv_surface", None)
        top = self.window()
        if getattr(top, "_closing", False) or getattr(getattr(top, "owner", None), "_closing", False):
            return
        # Interior video stays rounded even in a maximized player. An actual
        # edge-to-edge surface has square corners, so it fills the whole screen.
        wide = top.isFullScreen() or top.isMaximized() or bool(getattr(top, "_fullscreen_layout_active", False))
        fills_window = self.size() == top.size() and self.mapTo(top, QPoint()) == QPoint()
        radius = 0 if top.objectName() == "videoOnlyFullscreen" or wide and fills_window else VIDEO_CORNER_RADIUS
        key = (self.width(), self.height(), radius, self.devicePixelRatioF())
        if key == getattr(self, "_video_rounding_key", None):
            return
        self._video_rounding_key = key
        if radius:
            region = rounded_widget_region(self.size(), radius)
            self.setMask(region)
            if surface is not None:
                surface.setMask(region)
        else:
            self.clearMask()
            if surface is not None:
                surface.clearMask()
        self.update()


    def sync_mpv_surfaces(self):
        """Resize the existing native child only when its rectangle changes."""
        bounds = self.rect()
        if self._mpv_surface.geometry() != bounds:
            self._mpv_surface.setGeometry(bounds)
        self._sync_rounded_video()
        if self._mpv_active and self._mpv_surface.isHidden():
            self._mpv_surface.show()
            self._mpv_surface.raise_()

    def native_size(self) -> QSize:
        """Собственный размер видео (для режима «Авто»)."""
        return QSize(self._ext_size) if self._ext_active else self._sink.videoSize()

    def set_native_size(self, w: int, h: int):
        self._ext_size = QSize(int(w), int(h))

    def set_external(self, on: bool):
        if bool(on) == self._ext_active:
            return
        self._ext_active = bool(on)
        self._grade_active = False
        self._raw_image = None
        self._frame_image = None
        self.update()

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.doubleClicked.emit()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def moveEvent(self, event):
        super().moveEvent(event)
        # Moving the native VideoFrameWidget moves its child HWND with it.

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.sync_mpv_surfaces()
        self.resized.emit(self.size())

    # ---------- кадры ----------
    def _on_frame(self, frame: QVideoFrame):
        if self._ext_active:
            return
        image = frame.toImage()
        if image.isNull():
            return
        self._raw_image = image
        if self._grade_active and self._worker is not None:
            self._worker.submit(image)
        else:
            self._show(image)

    def show_external_frame(self, image):
        if self._ext_active:
            self._frame_image = image
            self.update()

    def _show(self, image):
        self._frame_image = image
        self.update()

    def _on_processed(self, image):
        if self._grade_active:        # запоздавший кадр после выключения коррекции не показываем
            self._show(image)

    def set_grade(self, params):
        """params - словарь параметров цветокоррекции; None или нейтральные - показывать оригинал."""
        if params is None or ColorGrade.is_neutral_params(params):
            self._grade_active = False
            if self._raw_image is not None:
                self._show(self._raw_image)
            return
        self._grade.set_params(params)
        if self._worker is None:
            self._worker = GradeWorker(self._grade, self)
            self._worker.processed.connect(self._on_processed)
            self._worker.start()
        self._grade_active = True
        if self._raw_image is not None:    # на паузе кадр не приходит - обновляем последний
            self._worker.submit(self._raw_image)

    def set_vignette(self, params):
        """Виньетка поверх кадров ffmpeg (3D-LUT пространственные эффекты не умеет)."""
        value = None
        if params is not None:
            p = ColorGrade.normalize(params)
            if p["vignette"]:
                value = (p["vignette"], p["vignette_mid"], p["vignette_feather"])
        if value != self._vignette:
            self._vignette = value
            self.update()

    def shutdown(self):
        if self._worker is not None:
            if not self._worker.stop():
                return False
            self._worker.deleteLater()
            self._worker = None
        self._grade_active = False
        self._raw_image = self._frame_image = self._static_cover = self._vig_image = None
        return True

    # ---------- отрисовка ----------
    def _vignette_overlay(self):
        if self._vig_key != self._vignette:
            amount, mid, feather = self._vignette
            mask = self._vig_grade._vignette_mask(160, 90, amount, mid, feather)   # 1 + сила * край
            a8 = np.round(np.clip(np.abs(mask - 1.0), 0.0, 1.0) * 255).astype(np.uint8)
            argb = np.zeros((90, 160, 4), dtype=np.uint8)
            if amount > 0:                        # светлая виньетка: белый цвет с прозрачностью
                argb[..., 0:3] = a8[..., None]
            argb[..., 3] = a8                     # тёмная: чёрный цвет с прозрачностью
            self._vig_image = QImage(argb.data, 160, 90, 160 * 4,
                                     QImage.Format.Format_ARGB32_Premultiplied).copy()
            self._vig_key = self._vignette
        return self._vig_image

    def paintEvent(self, event):
        painter = QPainter(self)
        region = self.mask()
        if not region.isEmpty():
            painter.setClipRegion(region)
        painter.fillRect(self.rect(), QColor("black"))
        if self._mpv_active:
            painter.end()
            return
        image = self._frame_image if self._frame_image is not None and not self._frame_image.isNull() else self._static_cover
        if image is not None and not image.isNull():
            target = image.size()
            target.scale(self.size(), Qt.AspectRatioMode.KeepAspectRatio)
            x = (self.width() - target.width()) // 2
            y = (self.height() - target.height()) // 2
            rect = QRectF(x, y, target.width(), target.height())
            painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
            painter.drawImage(rect, image)
            if self._ext_active and self._vignette is not None:
                painter.drawImage(rect, self._vignette_overlay())
        painter.end()


class VideoFullscreenWindow(QWidget):
    """Чистый fullscreen видеорежим с нижними, автоматически скрывающимися контролами."""

    HIDE_DELAY_MS = 2400

    def __init__(self, owner: "Window", video: VideoFrameWidget):
        super().__init__(owner, Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)
        self.owner = owner
        self.video = video
        self.setObjectName("videoOnlyFullscreen")
        self.setStyleSheet("QWidget#videoOnlyFullscreen { background:#000; }")
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setMouseTracking(True)
        self._cursor_hidden = False
        self._closed_by_owner = False

        # Видео является единственным постоянным элементом; контролы накладываются сверху.
        self.video.setParent(self)
        self.video.setMinimumSize(VIDEO_MIN_WIDTH, VIDEO_MIN_HEIGHT)
        self.video.setMaximumSize(16777215, 16777215)
        self.video.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.video.setMouseTracking(True)
        self.video.installEventFilter(self)
        self.video.mpv_surface().installEventFilter(self)

        self.controls = QFrame(self)
        self.controls.setObjectName("fsControls")
        self.controls.setMouseTracking(True)
        self.controls.setAttribute(Qt.WidgetAttribute.WA_NativeWindow, True)
        self.update_theme()
        controls_layout = QVBoxLayout(self.controls)
        controls_layout.setContentsMargins(14, 9, 14, 9)
        controls_layout.setSpacing(5)
        seek_row = QHBoxLayout()
        seek_row.setContentsMargins(0, 0, 0, 0)
        seek_row.setSpacing(8)
        self.now_label = QLabel("0:00")
        self.total_label = QLabel("0:00")
        self.now_label.setFixedWidth(46)
        self.total_label.setFixedWidth(46)
        self.now_label.setMouseTracking(True)
        self.total_label.setMouseTracking(True)
        self.total_label.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        self.seek = ClickSlider(Qt.Orientation.Horizontal, self.controls)
        self.seek.setRange(0, 0)
        self.seek.setMouseTracking(True)
        self.seek.setFixedHeight(16)
        self.seek.setToolTip("Перемотка")
        self.seek.sliderMoved.connect(self.owner.on_seek_moved)
        seek_row.addWidget(self.now_label)
        seek_row.addWidget(self.seek, 1)
        seek_row.addWidget(self.total_label)
        controls_layout.addLayout(seek_row)

        buttons_row = QHBoxLayout()
        buttons_row.setContentsMargins(0, 0, 0, 0)
        buttons_row.setSpacing(12)
        # Громкость справа; слева пустой блок такой же ширины, чтобы кнопки остались по центру.
        self._restore_volume = 50
        self.volume_box = QWidget(self.controls)
        self.volume_box.setFixedWidth(190)
        self.volume_box.setMouseTracking(True)
        volume_layout = QHBoxLayout(self.volume_box)
        volume_layout.setContentsMargins(0, 0, 0, 0)
        volume_layout.setSpacing(6)
        self.vol_btn = QPushButton(self.volume_box)
        self.vol_btn.setIconSize(QSize(20, 20))
        self.vol_btn.setFixedSize(36, 32)
        self.vol_btn.setToolTip("Выключить / включить звук (M)")
        self.vol_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.vol_btn.setMouseTracking(True)
        self.vol_btn.clicked.connect(self.toggle_mute)
        self.volume = ClickSlider(Qt.Orientation.Horizontal, self.volume_box)
        self.volume.setRange(0, 100)
        self.volume.setFixedHeight(16)
        self.volume.setMouseTracking(True)
        self.volume.setToolTip("Громкость (колесо мыши или ↑ ↓)")
        self.vol_pct = QLabel(self.volume_box)
        self.vol_pct.setFixedWidth(40)
        self.vol_pct.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        self.vol_pct.setMouseTracking(True)
        volume_layout.addWidget(self.vol_btn)
        volume_layout.addWidget(self.volume, 1)
        volume_layout.addWidget(self.vol_pct)
        self.volume.setValue(int(self.owner.volume.value()))
        self._refresh_volume_ui(self.volume.value())
        self.volume.valueChanged.connect(self._on_volume_slider)
        self.owner.volume.valueChanged.connect(self._volume_from_owner)
        volume_spacer = QWidget(self.controls)
        volume_spacer.setFixedWidth(190)
        buttons_row.addWidget(volume_spacer)
        buttons_row.addStretch(1)
        self.prev_btn = self._button("prev", "Предыдущий трек", lambda: self.owner.step(-1))
        self.play_btn = self._button("play", "Пауза / продолжить", self.owner.toggle_play)
        self.next_btn = self._button("next", "Следующий трек", lambda: self.owner.step(1))
        buttons_row.addWidget(self.prev_btn)
        buttons_row.addWidget(self.play_btn)
        buttons_row.addWidget(self.next_btn)
        buttons_row.addStretch(1)
        buttons_row.addWidget(self.volume_box)
        controls_layout.addLayout(buttons_row)

        self._hide_timer = QTimer(self)
        self._hide_timer.setSingleShot(True)
        self._hide_timer.setInterval(self.HIDE_DELAY_MS)
        self._hide_timer.timeout.connect(self.hide_controls)
        app = QApplication.instance()
        if app is not None:
            app.installEventFilter(self)

        # Первичная раскладка нужна, если окно успело получить размер до
        # завершения создания контролов и нового resizeEvent уже не будет.
        self._layout_fullscreen_children()

    def _button(self, icon: str, tooltip: str, slot):
        button = QPushButton(self.controls)
        button.setIcon(make_icon(icon))
        button.setIconSize(QSize(24, 24))
        button.setFixedSize(46, 42)
        button.setToolTip(tooltip)
        button.setCursor(Qt.CursorShape.PointingHandCursor)
        button.setMouseTracking(True)
        button.clicked.connect(slot)
        return button

    def _refresh_volume_ui(self, value):
        self.vol_btn.setIcon(make_icon("mute" if int(value) == 0 else "volume"))
        self.vol_pct.setText(f"{int(value)}%")

    def _on_volume_slider(self, value):
        self.owner.volume.setValue(int(value))  # дальше работает обычная громкость плеера и сохранение

    def _volume_from_owner(self, value):
        blocked = self.volume.blockSignals(True)
        self.volume.setValue(int(value))
        self.volume.blockSignals(blocked)
        self._refresh_volume_ui(value)

    def change_volume(self, step):
        self.owner.volume.setValue(max(0, min(100, self.owner.volume.value() + int(step))))
        self.show_controls()

    def toggle_mute(self):
        current = self.owner.volume.value()
        if current > 0:
            self._restore_volume = current
            self.owner.volume.setValue(0)
        else:
            self.owner.volume.setValue(self._restore_volume or 50)
        self.show_controls()

    def update_theme(self):
        _fs_bg_r, _fs_bg_g, _fs_bg_b = _rgb(_THEME["bg"])
        self.controls.setStyleSheet(themed(
            f"QFrame#fsControls {{ background:rgba({_fs_bg_r},{_fs_bg_g},{_fs_bg_b},220); border:1px solid #384154; border-radius:12px; }}"
            "QLabel { color:#e9edf5; background:transparent; font-size:12px; }"
            "QPushButton { background:#242a38; color:#f1f3f8; border:1px solid #3b4559; "
            "border-radius:9px; padding:6px; }"
            "QPushButton:hover { background:#374257; border-color:#ff426d; }"
            "QPushButton:pressed { background:#4a2a3b; }"
            "QSlider::groove:horizontal { height:4px; background:#40495c; border-radius:2px; }"
            "QSlider::sub-page:horizontal { background:#ff426d; border-radius:2px; }"
            "QSlider::handle:horizontal { background:#fff; border:2px solid #ff426d; width:10px; height:10px; margin:-4px 0; border-radius:6px; }"
        ))

    def resizeEvent(self, event):
        # Qt может вызвать resizeEvent ещё во время инициализации QWidget,
        # до создания self.video и self.controls. Поэтому раскладка безопасна
        # и для частично созданного объекта.
        super().resizeEvent(event)
        self._layout_fullscreen_children()

    def _layout_fullscreen_children(self):
        video = getattr(self, "video", None)
        if video is None:
            return

        video.setGeometry(self.rect())
        controls = getattr(self, "controls", None)
        if controls is None:
            # Контролы ещё не созданы; resizeEvent может прийти повторно позже.
            return

        width = min(700, max(300, self.width() - 32))
        height = 94
        controls.setGeometry(
            (self.width() - width) // 2,
            max(8, self.height() - height - 24),
            width,
            height,
        )
        video.lower()
        controls.raise_()
        # Синхронизация нативной поверхности mpv выполняется только после
        # того, как оба виджета созданы и получили актуальную геометрию.
        video.sync_mpv_surfaces()

    def eventFilter(self, watched, event):
        etype = event.type()
        if etype == QEvent.Type.MouseMove:
            try:
                pos = event.globalPosition().toPoint()
            except AttributeError:
                pos = QCursor.pos()
            if self.isVisible() and self.frameGeometry().contains(pos):
                self.show_controls()
        elif etype == QEvent.Type.Wheel and self.isVisible() and watched in (self.video, self.video.mpv_surface()):
            delta = event.angleDelta().y()
            if delta:
                self.change_volume(5 if delta > 0 else -5)  # колесо над видео меняет громкость
            return True
        elif etype == QEvent.Type.MouseButtonDblClick:
            try:
                pos = event.globalPosition().toPoint()
            except AttributeError:
                pos = QCursor.pos()
            video_targets = (self.video, self.video.mpv_surface())
            if (self.isVisible() and watched in video_targets
                    and self.frameGeometry().contains(pos)):
                self.owner.exit_video_fullscreen()
                return True
        elif etype == QEvent.Type.WindowDeactivate and watched is self:
            # Не оставляем глобально скрытый курсор при переключении в другое приложение.
            if self._cursor_hidden:
                QApplication.restoreOverrideCursor()
                self._cursor_hidden = False
        elif etype == QEvent.Type.WindowActivate and watched is self and self.isVisible():
            self.show_controls()
        return False

    def show_controls(self):
        if self._cursor_hidden:
            QApplication.restoreOverrideCursor()
            self._cursor_hidden = False
        self.setCursor(Qt.CursorShape.ArrowCursor)
        self.controls.show()
        self.controls.raise_()
        self._hide_timer.start()

    def hide_controls(self):
        self.controls.hide()
        if not self._cursor_hidden:
            QApplication.setOverrideCursor(QCursor(Qt.CursorShape.BlankCursor))
            self._cursor_hidden = True

    def update_position(self, pos: int):
        if not self.seek.isSliderDown():
            self.seek.setValue(max(self.seek.minimum(), min(self.seek.maximum(), int(pos))))
        self.now_label.setText(fmt_time(pos))

    def update_duration(self, duration: int):
        self.seek.setRange(0, max(0, int(duration)))
        self.total_label.setText(fmt_time(duration))

    def update_state(self, playing: bool):
        self.play_btn.setIcon(make_icon("pause" if playing else "play"))

    def activate(self):
        self.showFullScreen()
        self.video.show()
        self.video.sync_mpv_surfaces()
        self.show_controls()
        self.activateWindow()
        self.setFocus(Qt.FocusReason.ActiveWindowFocusReason)

    def keyPressEvent(self, event):
        if event.key() == Qt.Key.Key_Escape:
            self.owner.exit_video_fullscreen()
            event.accept()
            return
        if event.key() == Qt.Key.Key_Space:
            self.owner.toggle_play()
            event.accept()
            return
        if event.key() == Qt.Key.Key_Left:
            self.owner.seek_by(-5000)
            event.accept()
            return
        if event.key() == Qt.Key.Key_Right:
            self.owner.seek_by(5000)
            event.accept()
            return
        if event.key() in (Qt.Key.Key_Up, Qt.Key.Key_Down):
            self.change_volume(5 if event.key() == Qt.Key.Key_Up else -5)
            event.accept()
            return
        if event.key() == Qt.Key.Key_M:
            self.toggle_mute()
            event.accept()
            return
        super().keyPressEvent(event)

    def closeEvent(self, event):
        self.owner.exit_video_fullscreen()
        event.accept()

    def detach(self):
        self._hide_timer.stop()
        try:
            self.owner.volume.valueChanged.disconnect(self._volume_from_owner)
        except (TypeError, RuntimeError):
            pass
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        if self._cursor_hidden:
            QApplication.restoreOverrideCursor()
            self._cursor_hidden = False
        self.video.removeEventFilter(self)
        self.video.mpv_surface().removeEventFilter(self)
        self._closed_by_owner = True
        self.hide()


def find_converter_tool(*names: str) -> str | None:
    """Находит внешний конвертер в PATH, рядом с NOP или в типичных папках Windows."""
    # Private engines must win over unrelated versions in a user's PATH.
    private_engines = {
        "soffice": "libreoffice/program", "libreoffice": "libreoffice/program",
        "blender": "blender", "inkscape": "inkscape/bin",
        "ebook-convert": "calibre", "calibre-debug": "calibre",
    }
    # Resolve every bundled alias before considering any external alias.
    for name in names:
        stem = Path(name).stem.lower()
        candidates = [APP_DIR / name, APP_DIR / "bin" / name]
        if stem in private_engines:
            candidates.insert(0, APP_DIR / "converters" / private_engines[stem] / name)
        for candidate in candidates:
            if candidate.is_file():
                return str(candidate)
    for name in names:
        found = shutil.which(name)
        if found:
            return found
        candidates = [APP_DIR / name, APP_DIR / "bin" / name]
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            candidates.extend([Path(meipass) / name, Path(meipass) / "bin" / name])
        if os.name == "nt":
            program_roots = [Path(os.environ.get("ProgramFiles", r"C:\Program Files")),
                             Path(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"))]
            lower = name.lower()
            for root in program_roots:
                if lower.startswith("blender"):
                    candidates.extend(root.glob("Blender Foundation/*/blender.exe"))
                elif lower in {"soffice.exe", "soffice", "libreoffice.exe"}:
                    candidates.append(root / "LibreOffice" / "program" / "soffice.exe")
                elif lower.startswith("inkscape"):
                    candidates.extend([root / "Inkscape" / "bin" / "inkscape.exe",
                                       root / "Inkscape" / "inkscape.exe"])
                elif lower.startswith("ebook-convert"):
                    candidates.extend([root / "Calibre2" / "ebook-convert.exe",
                                       root / "calibre" / "ebook-convert.exe"])
        for candidate in candidates:
            try:
                if candidate.is_file():
                    return str(candidate)
            except OSError:
                pass
    return None


def _bounded_probe_run(args, timeout=15, **_options):
    options = {"creationflags": getattr(subprocess, "CREATE_NO_WINDOW", 0)} if os.name == "nt" else {"start_new_session": True}
    proc = None
    try:
        with tempfile.TemporaryFile() as output, tempfile.TemporaryFile() as errors:
            proc = subprocess.Popen(args, stdin=subprocess.DEVNULL, stdout=output, stderr=errors, **options)
            deadline = time.monotonic()+timeout
            while proc.poll() is None:
                cancel_event = getattr(_PROBE_CONTEXT, "cancel_event", None)
                if ((cancel_event is not None and cancel_event.is_set())
                        or QThread.currentThread().isInterruptionRequested()):
                    stop_owned_process(proc)
                    raise DownloadCancelled("Probe cancelled")
                if time.monotonic()>deadline:
                    stop_owned_process(proc)
                    raise subprocess.TimeoutExpired(args, timeout)
                if output.tell()>8*1024*1024 or errors.tell()>1024*1024:
                    stop_owned_process(proc)
                    raise ValueError("Media metadata exceeds the size limit")
                time.sleep(.03)
            if output.tell()>8*1024*1024 or errors.tell()>1024*1024:
                raise ValueError("Media metadata exceeds the size limit")
            output.seek(0);errors.seek(0)
            return subprocess.CompletedProcess(args,proc.returncode,output.read().decode("utf-8","replace"),errors.read().decode("utf-8","replace"))
    finally:
        if proc is not None and proc.poll() is None:
            stop_owned_process(proc)


def probe_media_info(source: Path) -> dict:
    """Получает исходные кодеки, битрейты, длительность и аудиодорожки через ffprobe."""
    ffprobe = find_converter_tool("ffprobe.exe", "ffprobe")
    if not ffprobe:
        return {"error": "FFprobe не найден", "audio_tracks": []}
    try:
        result = _bounded_probe_run(
            [ffprobe, "-v", "error", "-protocol_whitelist", "file,pipe,crypto,data", "-show_entries",
             "format=duration,bit_rate:stream=index,codec_type,codec_name,channels,channel_layout,bit_rate,duration,width,height,r_frame_rate:stream_tags=language,title",
             "-of", "json", str(source)],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=15,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        if result.returncode != 0:
            return {"error": (result.stderr or "Не удалось прочитать метаданные")[-500:], "audio_tracks": []}
        data = json.loads(result.stdout or "{}")
    except (OSError, subprocess.SubprocessError, ValueError) as exc:
        return {"error": str(exc), "audio_tracks": []}

    streams = data.get("streams") or []
    fmt = data.get("format") or {}
    videos = [st for st in streams if st.get("codec_type") == "video"]
    audios = [st for st in streams if st.get("codec_type") == "audio"]

    def kbps(value):
        try:
            number = float(value)
            return int(round(number / 1000)) if number > 0 else None
        except (TypeError, ValueError):
            return None

    video = videos[0] if videos else {}
    duration = None
    for value in (video.get("duration"), fmt.get("duration")):
        try:
            if value is not None and float(value) > 0:
                duration = float(value)
                break
        except (TypeError, ValueError):
            pass

    audio_tracks = []
    for audio_index, st in enumerate(audios):
        tags = st.get("tags") or {}
        audio_tracks.append({
            "audio_index": audio_index,
            "stream_index": st.get("index", audio_index),
            "codec": str(st.get("codec_name") or "неизвестно"),
            "channels": st.get("channels"),
            "channel_layout": str(st.get("channel_layout") or ""),
            "bitrate_kbps": kbps(st.get("bit_rate")) or kbps(tags.get("BPS") or tags.get("BPS-eng")),
            "language": str(tags.get("language") or ""),
            "title": str(tags.get("title") or ""),
        })

    def frame_rate(value):
        from fractions import Fraction
        try:
            number = float(Fraction(str(value)))
            return round(number, 3) if math.isfinite(number) and number > 0 else None
        except (ValueError, ZeroDivisionError, OverflowError):
            return None

    video_bitrate = kbps(video.get("bit_rate"))
    format_bitrate = kbps(fmt.get("bit_rate"))
    audio_codecs = list(dict.fromkeys(str(st.get("codec_name") or "неизвестно") for st in audios))
    return {
        "duration": duration,
        "video_codec": str(video.get("codec_name") or "неизвестно"),
        "width": video.get("width"), "height": video.get("height"),
        "fps": frame_rate(video.get("r_frame_rate")),
        "subtitle_tracks": [{"subtitle_index": i, "codec": st.get("codec_name", "unknown")} for i, st in enumerate(st for st in streams if st.get("codec_type") == "subtitle")],
        "video_bitrate_kbps": video_bitrate,
        "format_bitrate_kbps": format_bitrate,
        "audio_codecs": audio_codecs,
        "audio_tracks": audio_tracks,
    }


class FilePropertiesSignals(QObject):
    completed = pyqtSignal(object)


def _metadata_display(value, suffix=""):
    if value is None or value == "":
        return "Нет данных"
    if isinstance(value, float):
        return f"{value:g}{suffix}"
    return f"{value}{suffix}"


_FILE_PROPERTY_MEASURE_KEY = "__file_property_measure__"


def _property_measure(kind, value):
    """Хранит исходное числовое значение, чтобы менять единицы без повторного анализа."""
    try:
        number = float(value)
        if not math.isfinite(number) or number < 0:
            return "Нет данных"
        return {_FILE_PROPERTY_MEASURE_KEY: True, "kind": str(kind), "value": number}
    except (TypeError, ValueError, OverflowError):
        return "Нет данных"


def _compact_number(value, precision=2):
    """Число без ненужных нулей в дробной части."""
    if abs(value - round(value)) < 1e-9:
        return str(int(round(value)))
    return f"{value:.{precision}f}".rstrip("0").rstrip(".")


def _format_duration_value(seconds, mode="auto"):
    seconds = max(0.0, float(seconds))
    if mode == "seconds":
        return f"{_compact_number(seconds, 2)} с"

    # Для длинных значений используем целые секунды, чтобы не допускать
    # округления 59:59 до следующей минуты и аналогичных скачков.
    whole = int(seconds)
    if mode == "auto":
        if seconds < 60:
            return f"{_compact_number(seconds, 2)} с"
        mode = "mmss" if seconds < 3600 else "hhmmss"

    if mode == "mmss":
        minutes, secs = divmod(whole, 60)
        # В ручном режиме MM — суммарные минуты; длительность не обрезается по часам.
        return f"{minutes:02d}:{secs:02d}"

    hours, remainder = divmod(whole, 3600)
    minutes, secs = divmod(remainder, 60)
    return f"{hours:02d}:{minutes:02d}:{secs:02d}"


def _format_bitrate_value(bits_per_second, mode="auto"):
    value = max(0.0, float(bits_per_second))
    units = {
        "bps": (1, "бит/с"),
        "kbps": (1000, "кбит/с"),
        "mbps": (1000 ** 2, "Мбит/с"),
        "gbps": (1000 ** 3, "Гбит/с"),
    }
    if mode == "auto":
        modes = ("bps", "kbps", "mbps", "gbps")
        if value >= 1000 ** 3:
            mode = "gbps"
        elif value >= 1000 ** 2:
            mode = "mbps"
        elif value >= 1000:
            mode = "kbps"
        else:
            mode = "bps"
        # Не оставляем некрасивое округлённое «1000 кбит/с», если уже
        # уместнее показать около «1 Мбит/с».
        index = modes.index(mode)
        if index < len(modes) - 1:
            divisor = units[mode][0]
            if round(value / divisor, 2) >= 1000:
                mode = modes[index + 1]
    divisor, label = units.get(mode, units["bps"])
    return f"{_compact_number(value / divisor, 2)} {label}"


def _format_filesize_value(size_bytes, mode="auto"):
    value = max(0.0, float(size_bytes))
    units = {
        "bytes": (1, "Б"),
        "kib": (1024, "КБ"),
        "mib": (1024 ** 2, "МБ"),
        "gib": (1024 ** 3, "ГБ"),
        "tib": (1024 ** 4, "ТБ"),
    }
    if mode == "auto":
        modes = ("bytes", "kib", "mib", "gib", "tib")
        mode = "bytes"
        for candidate in modes[1:]:
            divisor, _label = units[candidate]
            if value >= divisor:
                mode = candidate
            else:
                break
        index = modes.index(mode)
        divisor = units[mode][0]
        precision = 0 if mode == "bytes" else 2
        if index < len(modes) - 1 and round(value / divisor, precision) >= 1024:
            mode = modes[index + 1]
    divisor, label = units.get(mode, units["bytes"])
    precision = 0 if mode == "bytes" else 2
    return f"{_compact_number(value / divisor, precision)} {label}"


def _format_file_property_value(value, duration_mode="auto", bitrate_mode="auto", filesize_mode="auto"):
    """Форматирует описание измерения из сохранённого исходного значения."""
    if not isinstance(value, dict) or not value.get(_FILE_PROPERTY_MEASURE_KEY):
        return str(value) if value not in (None, "") else "Нет данных"
    kind = value.get("kind")
    number = value.get("value", 0)
    if kind == "duration":
        return _format_duration_value(number, duration_mode)
    if kind == "bitrate":
        return _format_bitrate_value(number, bitrate_mode)
    if kind == "filesize":
        return _format_filesize_value(number, filesize_mode)
    return str(number)


def collect_file_properties(path: Path) -> dict:
    """Собирает доступные метаданные файла. Вызывается в фоновом потоке."""
    result = {"sections": [], "warnings": []}
    path = Path(path)
    if not path.exists() or not path.is_file():
        result["error"] = "Файл отсутствует или не является обычным файлом."
        return result

    try:
        st = path.stat()
        general = [
            ("Имя", path.name),
            ("Полный путь", str(path.resolve(strict=False))),
            ("Расширение", path.suffix or "Без расширения"),
            ("Размер", _property_measure("filesize", st.st_size)),
            ("Изменён", datetime.datetime.fromtimestamp(st.st_mtime).astimezone().strftime("%d.%m.%Y %H:%M:%S")),
        ]
        birth = getattr(st, "st_birthtime", None)
        if birth is not None:
            general.append(("Создан", datetime.datetime.fromtimestamp(birth).astimezone().strftime("%d.%m.%Y %H:%M:%S")))
        mime, _encoding = mimetypes.guess_type(str(path), strict=False)
        general.append(("MIME-тип по расширению", mime or "Неизвестно"))
        result["sections"].append(("Общие сведения", general))
    except OSError as exc:
        result["error"] = f"Не удалось прочитать сведения о файле: {exc}"
        return result

    # FFprobe возвращает параметры контейнера и всех обнаруженных потоков.
    ffprobe = find_converter_tool("ffprobe.exe", "ffprobe")
    probe_succeeded = False
    if ffprobe:
        try:
            proc = _bounded_probe_run(
                [ffprobe, "-v", "error", "-show_format", "-show_streams", "-show_chapters", "-of", "json", str(path)],
                capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=25,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            if proc.returncode == 0:
                data = json.loads(proc.stdout or "{}")
                probe_succeeded = True
                fmt = data.get("format") or {}
                streams = data.get("streams") or []
                def nice_num(v, suffix=""):
                    try:
                        return f"{float(v):g}{suffix}" if v not in (None, "", "N/A") else "Нет данных"
                    except (TypeError, ValueError):
                        return "Нет данных"
                def bitrate(v):
                    return _property_measure("bitrate", v)
                fmt_items = [
                    ("Формат контейнера", fmt.get("format_long_name") or fmt.get("format_name") or "Нет данных"),
                    ("Краткое имя формата", fmt.get("format_name") or "Нет данных"),
                    ("Длительность", _property_measure("duration", fmt.get("duration"))),
                    ("Общий битрейт", bitrate(fmt.get("bit_rate"))),
                    ("Размер по данным контейнера", _property_measure("filesize", fmt.get("size")) if fmt.get("size") not in (None, "", "N/A") else "Нет данных"),
                ]
                tags = fmt.get("tags") or {}
                if tags:
                    fmt_items.append(("Теги контейнера", "; ".join(f"{k}: {v}" for k, v in tags.items())))
                result["sections"].append(("Мультимедиа / контейнер", fmt_items))
                for number, stream in enumerate(streams, 1):
                    stype = stream.get("codec_type") or "неизвестный"
                    items = [
                        ("Индекс потока", stream.get("index", number - 1)),
                        ("Тип потока", stype),
                        ("Кодек", stream.get("codec_long_name") or stream.get("codec_name") or "Нет данных"),
                        ("Профиль", stream.get("profile") or "Нет данных"),
                        ("Битрейт", bitrate(stream.get("bit_rate"))),
                        ("Длительность", _property_measure("duration", stream.get("duration"))),
                    ]
                    if stype == "video":
                        w, h = stream.get("width"), stream.get("height")
                        items.extend([
                            ("Разрешение", f"{w} × {h}" if w and h else "Нет данных"),
                            ("Соотношение сторон", stream.get("display_aspect_ratio") or "Нет данных"),
                            ("Частота кадров", stream.get("avg_frame_rate") or stream.get("r_frame_rate") or "Нет данных"),
                            ("Пиксельный формат", stream.get("pix_fmt") or "Нет данных"),
                            ("Разрядность цвета", stream.get("bits_per_raw_sample") or "Нет данных"),
                            ("Цветовое пространство", stream.get("color_space") or "Нет данных"),
                        ])
                    elif stype == "audio":
                        items.extend([
                            ("Частота дискретизации", nice_num(stream.get("sample_rate"), " Гц")),
                            ("Каналы", stream.get("channels") or "Нет данных"),
                            ("Расположение каналов", stream.get("channel_layout") or "Нет данных"),
                            ("Разрядность сэмпла", stream.get("bits_per_sample") or stream.get("bits_per_raw_sample") or "Нет данных"),
                            ("Формат сэмплов", stream.get("sample_fmt") or "Нет данных"),
                        ])
                    elif stype == "subtitle":
                        items.append(("Кодировка субтитров", stream.get("codec_name") or "Нет данных"))
                    stream_tags = stream.get("tags") or {}
                    if stream_tags:
                        items.append(("Метаданные потока", "; ".join(f"{k}: {v}" for k, v in stream_tags.items())))
                    disposition = stream.get("disposition") or {}
                    flags = [k for k, v in disposition.items() if v and k in ("default", "forced", "comment", "hearing_impaired", "visual_impaired")]
                    if flags:
                        items.append(("Признаки потока", ", ".join(flags)))
                    result["sections"].append((f"Поток {number} — {stype}", items))
                chapters = data.get("chapters") or []
                if chapters:
                    result["sections"].append(("Главы", [(f"Глава {i+1}", f"{ch.get('start_time', '?')}–{ch.get('end_time', '?')} с; " + "; ".join(f"{k}: {v}" for k, v in (ch.get("tags") or {}).items())) for i, ch in enumerate(chapters)]))
            else:
                err = (proc.stderr or "FFprobe не смог прочитать файл").strip()
                result["warnings"].append(f"FFprobe не смог прочитать файл: {err[-350:]}")
        except (OSError, subprocess.SubprocessError, json.JSONDecodeError, ValueError) as exc:
            result["warnings"].append(f"Ошибка анализа мультимедиа: {exc}")
    else:
        result["warnings"].append("FFprobe не найден: подробные параметры аудио/видео могут быть недоступны.")

    # Дополнительные встроенные теги аудиофайлов (если установлен mutagen).
    try:
        import mutagen
        media = mutagen.File(str(path), easy=False)
        if media is not None:
            audio_items = []
            info = getattr(media, "info", None)
            if info is not None:
                for attr, label, suffix in (("length", "Длительность", " с"), ("bitrate", "Битрейт", " бит/с"), ("sample_rate", "Частота дискретизации", " Гц"), ("channels", "Количество каналов", ""), ("bits_per_sample", "Разрядность", " бит"), ("bit_depth", "Глубина бита", " бит")):
                    value = getattr(info, attr, None)
                    if value is not None:
                        if attr == "length":
                            display_value = _property_measure("duration", value)
                        elif attr == "bitrate":
                            display_value = _property_measure("bitrate", value)
                        else:
                            display_value = _metadata_display(round(value, 3) if isinstance(value, float) else value, suffix)
                        audio_items.append((label, display_value))
            tags = getattr(media, "tags", None)
            if tags:
                for key, value in tags.items():
                    if isinstance(value, (list, tuple)):
                        value = "; ".join(str(v) for v in value)
                    audio_items.append((f"Тег: {key}", str(value)))
            if audio_items:
                result["sections"].append(("Аудиоинформация и встроенные теги", audio_items))
    except Exception as exc:
        result["warnings"].append(f"Дополнительные аудиометаданные недоступны: {exc}")

    # Изображения: геометрия и режим цвета, если Pillow поддерживает формат.
    try:
        from PIL import Image
        with Image.open(path) as image_file:
            image_items = [("Размер изображения", f"{image_file.width} × {image_file.height}"),
                           ("Цветовой режим", image_file.mode),
                           ("Формат изображения", image_file.format or "Неизвестно")]
            if getattr(image_file, "n_frames", 1) > 1:
                image_items.append(("Количество кадров", image_file.n_frames))
            image_info = getattr(image_file, "info", {}) or {}
            for key, value in image_info.items():
                if isinstance(value, (str, int, float)):
                    image_items.append((f"Метаданные изображения: {key}", value))
            result["sections"].append(("Изображение", image_items))
    except ImportError:
        pass
    except Exception:
        # Не каждый файл является изображением; не считать это ошибкой чтения файла.
        pass

    # Документы PDF: свойства документа и количество страниц.
    if path.suffix.casefold() == ".pdf":
        try:
            import fitz
            with fitz.open(str(path)) as pdf_doc:
                pdf_items = [("Количество страниц", len(pdf_doc)), ("Зашифрован", "Да" if pdf_doc.is_encrypted else "Нет")]
                meta = pdf_doc.metadata or {}
                for key in ("title", "author", "subject", "keywords", "creator", "producer", "creationDate", "modDate", "format"):
                    value = meta.get(key)
                    if value:
                        pdf_items.append((f"Метаданные PDF: {key}", value))
                result["sections"].append(("Документ PDF", pdf_items))
        except ImportError:
            result["warnings"].append("Для подробных свойств PDF библиотека PyMuPDF (fitz) не установлена.")
        except Exception as exc:
            result["warnings"].append(f"Не удалось прочитать свойства PDF: {exc}")

    # Контейнеры ZIP/OOXML (например DOCX, XLSX, PPTX) и архивы.
    if zipfile.is_zipfile(path):
        try:
            with zipfile.ZipFile(path, "r") as archive:
                members = archive.infolist()
                archive_items = [("Количество элементов", len(members)),
                                 ("Несжатый суммарный размер", Window._format_file_size(sum(i.file_size for i in members))),
                                 ("Размер содержимого архива", Window._format_file_size(sum(i.compress_size for i in members)))]
                names = {i.filename for i in members}
                kind = "Архив ZIP"
                if "word/document.xml" in names:
                    kind = "Документ Word (OOXML)"
                elif "xl/workbook.xml" in names:
                    kind = "Книга Excel (OOXML)"
                elif "ppt/presentation.xml" in names:
                    kind = "Презентация PowerPoint (OOXML)"
                elif "META-INF/container.xml" in names:
                    kind = "Электронная книга EPUB"
                archive_items.append(("Тип контейнера", kind))
                if "docProps/core.xml" in names:
                    try:
                        import xml.etree.ElementTree as ET
                        metadata = archive.getinfo("docProps/core.xml")
                        if metadata.file_size > 1024 * 1024:
                            raise ValueError("Document metadata is too large")
                        with archive.open(metadata) as metadata_file:
                            raw_metadata = metadata_file.read(1024 * 1024 + 1)
                        if len(raw_metadata) > 1024 * 1024:
                            raise ValueError("Document metadata is too large")
                        root = ET.fromstring(raw_metadata)
                        for child in root:
                            value = (child.text or "").strip()
                            if value:
                                archive_items.append((f"Свойство документа: {child.tag.split('}')[-1]}", value))
                    except Exception:
                        pass
                result["sections"].append(("Документ / архив", archive_items))
        except (OSError, zipfile.BadZipFile, RuntimeError) as exc:
            result["warnings"].append(f"Не удалось прочитать структуру архива: {exc}")

    if not probe_succeeded and not any(section[0] == "Аудиоинформация и встроенные теги" for section in result["sections"]):
        if result["warnings"]:
            result["sections"].append(("Состояние анализа", [("Результат", "Общие сведения доступны, но дополнительные метаданные не удалось получить."), ("Причина", result["warnings"][0])]))
    return result

def format_time_seconds(seconds) -> str:
    try:
        seconds = max(0, int(seconds))
    except (TypeError, ValueError):
        return "—"
    hours, remainder = divmod(seconds, 3600)
    minutes, secs = divmod(remainder, 60)
    return f"{hours:d}:{minutes:02d}:{secs:02d}" if hours else f"{minutes:02d}:{secs:02d}"


# ---------- owned conversion outputs and process lifetime ----------
class ConversionText(str):
    """Keep both versions of a conversion message without retaining exceptions."""
    def __new__(cls, ru, en):
        value = super().__new__(cls, ui_text(ru, en))
        value.ru, value.en = ru, en
        return value

    def __add__(self, other):
        if not isinstance(other, str):
            return NotImplemented
        return ConversionText(self.ru + getattr(other, "ru", str(other)),
                              self.en + getattr(other, "en", str(other)))

    def __radd__(self, other):
        if not isinstance(other, str):
            return NotImplemented
        return ConversionText(getattr(other, "ru", str(other)) + self.ru,
                              getattr(other, "en", str(other)) + self.en)


def conversion_probe_error(info):
    message = info.get("error", "")
    if message in {"FFprobe не найден", "FFprobe not found"}:
        return conversion_text("FFprobe не найден", "FFprobe not found")
    if message in {"Не удалось прочитать метаданные", "Could not read metadata"}:
        return conversion_text("Не удалось прочитать метаданные", "Could not read metadata")
    return message


def conversion_text(ru, en):
    return ConversionText(ru, en)


class ConversionCleanupError(RuntimeError):
    pass


class ConversionOutputTransaction:
    """Only the private directory is disposable; public files are never replaced."""
    def __init__(self, source, folder, extension, checkpoint):
        self.source, self.folder = Path(source), Path(folder)
        self.extension, self.checkpoint = extension, checkpoint
        self.folder.mkdir(parents=True, exist_ok=True)
        self._temp = tempfile.TemporaryDirectory(prefix=".nop-convert-", dir=str(self.folder))
        self.root = Path(self._temp.name)
        self._root_identity = self._identity(self.root)
        self.files = self.root / "files"
        self.files.mkdir()
        self.stem = conversion_stem(self.source)
        # Leave space for suffixes on NTFS and on filesystems limiting UTF-8 names.
        while len(self.stem.encode("utf-8")) > 180 or len(self.stem) > 180:
            self.stem = self.stem[:-1]
        self.stem = self.stem.rstrip(" .") or "result"
        self.destination = self.files / (self.stem + "." + extension)

    @staticmethod
    def _identity(path):
        st = path.lstat()
        return st.st_dev, st.st_ino

    @classmethod
    def _unlink_owned(cls, path, identity):
        try:
            if cls._identity(path) == identity:
                path.unlink()
        except OSError:
            pass

    def _publish_file(self, source, destination):
        self.checkpoint()
        try:
            # link is atomic and fails even for a dangling destination symlink.
            os.link(source, destination, follow_symlinks=False)
            return self._identity(destination)
        except FileExistsError:
            raise
        except NotImplementedError:
            pass  # Some Windows/Python/filesystem combinations lack link options.
        except OSError as exc:
            import errno
            if exc.errno not in (errno.EXDEV, errno.EPERM, errno.EACCES,
                                 errno.ENOTSUP, errno.EOPNOTSUPP, errno.ENOSYS):
                raise
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0)
        fd = os.open(str(destination), flags, 0o600)
        st = os.fstat(fd)
        identity = st.st_dev, st.st_ino
        try:
            with os.fdopen(fd, "wb") as dst, source.open("rb") as src:
                while True:
                    self.checkpoint()
                    block = src.read(256 * 1024)
                    if not block:
                        break
                    dst.write(block)
                dst.flush()
                os.fsync(dst.fileno())
        except BaseException:
            self._unlink_owned(destination, identity)
            raise
        return identity

    def publish(self):
        entries = []
        for path in self.files.rglob("*"):
            self.checkpoint()
            if len(entries) >= 50000:
                raise RuntimeError(conversion_text("Экспорт превышает 50 000 файлов/папок.", "Export exceeds 50,000 files/directories."))
            entries.append(path)
        for path in entries:
            st = path.lstat()
            if (stat.S_ISLNK(st.st_mode) or getattr(st, "st_file_attributes", 0) & 0x400
                    or not (stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode))):
                raise RuntimeError(conversion_text("Движок создал небезопасную ссылку или специальный файл.",
                                           "The engine created an unsafe link or special file."))
        if not self.destination.is_file() or not self.destination.stat().st_size:
            raise RuntimeError(conversion_text("Движок не создал непустой результат.", "The engine did not create a nonempty result."))
        files = [p for p in entries if p.is_file()]
        if len(files) == 1:
            while True:
                candidate = unique_conversion_output(self.source, self.folder, self.extension)
                # Use the same shortened stem as the private output, if necessary.
                if len(candidate.name.encode("utf-8")) > 240:
                    candidate = self.folder / self.destination.name
                    index = 2
                    while os.path.lexists(candidate):
                        candidate = self.folder / f"{self.stem} ({index}).{self.extension}"
                        index += 1
                try:
                    self._publish_file(self.destination, candidate)
                    return candidate
                except FileExistsError:
                    continue
        # Multi-file exports get their own namespace. Relative HTML/glTF links
        # stay valid and cannot overwrite assets of a previous conversion.
        index = 1
        while True:
            suffix = "" if index == 1 else f" ({index})"
            bundle = self.folder / f"{self.stem}_{self.extension.replace('.', '_')}{suffix}"
            try:
                bundle.mkdir()
                break
            except FileExistsError:
                index += 1
        written, directories = [], [bundle]
        try:
            for path in sorted(entries, key=lambda p: (len(p.parts), str(p))):
                self.checkpoint()
                target = bundle / path.relative_to(self.files)
                if path.is_dir():
                    target.mkdir()
                    directories.append(target)
                else:
                    identity = self._publish_file(path, target)
                    written.append((target, identity))
            return bundle / self.destination.relative_to(self.files)
        except BaseException:
            for target, identity in reversed(written):
                self._unlink_owned(target, identity)
            for directory in reversed(directories):
                try:
                    directory.rmdir()  # Never recursively remove a public directory.
                except OSError:
                    pass
            raise

    def close(self):
        for attempt in range(3):
            try:
                if self._identity(self.root) != self._root_identity:
                    self._temp._finalizer.detach()
                    raise ConversionCleanupError(conversion_text(
                        f"Рабочий каталог заменён другим объектом и не удалён: {self.root}",
                        f"The work directory was replaced by another object and was not removed: {self.root}"))
                self._temp.cleanup()
                return
            except FileNotFoundError:
                self._temp._finalizer.detach()
                return
            except OSError as exc:
                if attempt == 2:
                    raise ConversionCleanupError(conversion_text(
                        f"Не удалось очистить собственный рабочий каталог {self.root}: {exc}",
                        f"Could not clean this job's work directory {self.root}: {exc}")) from exc
                time.sleep(.05)



class ConversionWindowsJob:
    """A private Job Object; assignment happens before the child is resumed."""
    def __init__(self):
        from ctypes import wintypes
        class Basic(ctypes.Structure):
            _fields_ = [("process_time", ctypes.c_int64), ("job_time", ctypes.c_int64),
                        ("flags", ctypes.c_uint32), ("min_ws", ctypes.c_size_t),
                        ("max_ws", ctypes.c_size_t), ("active_limit", ctypes.c_uint32),
                        ("affinity", ctypes.c_size_t), ("priority", ctypes.c_uint32),
                        ("scheduling", ctypes.c_uint32)]
        class Counters(ctypes.Structure):
            _fields_ = [(name, ctypes.c_uint64) for name in
                        ("read_ops", "write_ops", "other_ops", "read_bytes", "write_bytes", "other_bytes")]
        class Extended(ctypes.Structure):
            _fields_ = [("basic", Basic), ("io", Counters), ("process_memory", ctypes.c_size_t),
                        ("job_memory", ctypes.c_size_t), ("peak_process_memory", ctypes.c_size_t),
                        ("peak_job_memory", ctypes.c_size_t)]
        self.api = ctypes.WinDLL("kernel32", use_last_error=True)
        self.api.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
        self.api.CreateJobObjectW.restype = wintypes.HANDLE
        self.api.SetInformationJobObject.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
        self.api.SetInformationJobObject.restype = wintypes.BOOL
        self.api.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
        self.api.AssignProcessToJobObject.restype = wintypes.BOOL
        self.api.TerminateJobObject.argtypes = [wintypes.HANDLE, wintypes.UINT]
        self.api.TerminateJobObject.restype = wintypes.BOOL
        self.api.CloseHandle.argtypes = [wintypes.HANDLE]
        self.api.CloseHandle.restype = wintypes.BOOL
        self.api.QueryInformationJobObject.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD, ctypes.c_void_p]
        self.api.QueryInformationJobObject.restype = wintypes.BOOL
        self.handle = self.api.CreateJobObjectW(None, None)
        if not self.handle:
            raise ctypes.WinError(ctypes.get_last_error())
        limits = Extended()
        limits.basic.flags = 0x2000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
        if not self.api.SetInformationJobObject(self.handle, 9, ctypes.byref(limits), ctypes.sizeof(limits)):
            error = ctypes.get_last_error()
            self.close()
            raise ctypes.WinError(error)

    def assign_and_resume(self, process):
        handle = ctypes.c_void_p(int(process._handle))
        if not self.api.AssignProcessToJobObject(self.handle, handle):
            raise ctypes.WinError(ctypes.get_last_error())
        resume = ctypes.WinDLL("ntdll").NtResumeProcess
        resume.argtypes, resume.restype = [ctypes.c_void_p], ctypes.c_long
        result = int(resume(handle))
        if result:
            raise OSError(f"NtResumeProcess: {result}")

    def close(self):
        if self.handle:
            class Accounting(ctypes.Structure):
                _fields_ = [("times", ctypes.c_int64 * 4), ("faults", ctypes.c_uint32),
                            ("total", ctypes.c_uint32), ("active", ctypes.c_uint32), ("terminated", ctypes.c_uint32)]
            try:
                if not self.api.TerminateJobObject(self.handle, 1):
                    raise ctypes.WinError(ctypes.get_last_error())
                deadline = time.monotonic() + 2
                while True:
                    state = Accounting()
                    if not self.api.QueryInformationJobObject(self.handle, 1, ctypes.byref(state), ctypes.sizeof(state), None):
                        raise ctypes.WinError(ctypes.get_last_error())
                    if not state.active:
                        break
                    if time.monotonic() >= deadline:
                        raise OSError("Windows has not finished terminating the conversion job")
                    time.sleep(.02)
            finally:
                self.api.CloseHandle(self.handle)
                self.handle = None



def conversion_stop_process(process, job=None):
    """Conversion-only cleanup; the downloader/player process helper is unchanged."""
    job_error = None
    if job is not None:
        try:
            job.close()
        except OSError as exc:
            job_error = exc
    elif os.name != "nt":
        # Deliberately do not return when the group leader has already exited.
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
    elif process.poll() is None:
        process.kill()  # Only used if assignment to the job failed while suspended.
    try:
        process.wait(timeout=0.7)
    except subprocess.TimeoutExpired:
        if os.name != "nt":
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        else:
            process.kill()
        process.wait(timeout=2)
    finally:
        if os.name != "nt":
            # A descendant can ignore TERM after its parent has been reaped.
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
    if job_error is not None:
        raise job_error


class ConversionPipeReader:
    """Single-owner, nonblocking reads. There is no blocking reader thread."""
    def __init__(self, pipe):
        self.pipe, self.eof = pipe, False
        self.fd = pipe.fileno()
        if os.name == "nt":
            import msvcrt
            from ctypes import wintypes
            self.handle = msvcrt.get_osfhandle(self.fd)
            self.dword = wintypes.DWORD
            self.peek = ctypes.WinDLL("kernel32", use_last_error=True).PeekNamedPipe
            self.peek.argtypes = [wintypes.HANDLE, ctypes.c_void_p, wintypes.DWORD,
                                  ctypes.c_void_p, ctypes.POINTER(wintypes.DWORD), ctypes.c_void_p]
            self.peek.restype = wintypes.BOOL
        else:
            os.set_blocking(self.fd, False)

    def read(self):
        size = 65536
        if os.name == "nt":
            available = self.dword()
            if not self.peek(self.handle, None, 0, None, ctypes.byref(available), None):
                error = ctypes.get_last_error()
                if error in (109, 232):
                    self.eof = True
                    return b""
                raise ctypes.WinError(error)
            size = min(size, available.value)
            if not size:
                return b""
        try:
            block = os.read(self.fd, size)
        except BlockingIOError:
            return b""
        if not block:
            self.eof = True
        return block



class ConversionOutputLines:
    def __init__(self):
        import codecs
        self.decoder = codecs.getincrementaldecoder("utf-8")("replace")
        self.pending, self.truncated = "", False

    def feed(self, block, final=False):
        text = self.decoder.decode(block, final=final)
        lines = []
        parts = text.split("\n")
        for index, part in enumerate(parts):
            if self.truncated:
                self.pending = self.pending[:2000] + (self.pending[2000:] + part)[-2000:]
            elif len(self.pending) + len(part) > 4000:
                combined = self.pending + part  # At most one read block plus 4,000 characters.
                self.pending = combined[:2000] + combined[-2000:]
                self.truncated = True
            else:
                self.pending += part
            if index < len(parts) - 1 or final:
                line = self.pending.rstrip("\r")
                if self.truncated:
                    line = line[:2000] + " [middle truncated] " + line[2000:]
                lines.append(line)
                self.pending, self.truncated = "", False
        return lines


_CONVERSION_MEDIA_CACHE = collections.OrderedDict()
_CONVERSION_MEDIA_CACHE_LOCK = threading.RLock()


def cached_conversion_probe(source):
    path = Path(source)
    st = path.stat()  # This function is only called by background workers.
    key = (str(path.absolute()), st.st_size, st.st_mtime_ns)
    with _CONVERSION_MEDIA_CACHE_LOCK:
        cached = _CONVERSION_MEDIA_CACHE.get(key)
        if cached is not None:
            _CONVERSION_MEDIA_CACHE.move_to_end(key)
            return copy.deepcopy(cached)
    info = probe_media_info(path)
    if not info.get("error") and len(json.dumps(info, ensure_ascii=False)) < 256 * 1024:
        with _CONVERSION_MEDIA_CACHE_LOCK:
            _CONVERSION_MEDIA_CACHE[key] = copy.deepcopy(info)
            while len(_CONVERSION_MEDIA_CACHE) > 128:
                _CONVERSION_MEDIA_CACHE.popitem(last=False)
    return info


class ConversionMediaProbe(QThread):
    ready = pyqtSignal(int, str, object)

    def __init__(self, source, generation, parent):
        super().__init__(parent)
        self.source, self.generation = Path(source), generation

    def request_stop(self):
        self.requestInterruption()

    def run(self):
        try:
            info = cached_conversion_probe(self.source)
            if not self.isInterruptionRequested():
                self.ready.emit(self.generation, str(self.source), info)
        except DownloadCancelled:
            pass
        except Exception as exc:
            if not self.isInterruptionRequested():
                self.ready.emit(self.generation, str(self.source), {"error": redact_diagnostic(exc), "audio_tracks": []})


def conversion_archive_zip_preflight(source):
    """Check the central-directory budget before ZipFile allocates its index."""
    import struct
    with Path(source).open("rb") as stream:
        stream.seek(0, 2)
        size = stream.tell()
        stream.seek(max(0, size - 65557))
        tail = stream.read(65557)
        offset = tail.rfind(b"PK\x05\x06")
        if offset < 0 or len(tail) - offset < 22:
            raise RuntimeError(ui_text("Повреждённый ZIP: не найден каталог.", "Invalid ZIP: central directory not found."))
        fields = struct.unpack_from("<4s4H2LH", tail, offset)
        disk, directory_disk, count_disk, count, directory_size = fields[1:6]
        directory_offset = fields[6]
        end_offset = max(0, size - 65557) + offset
        if disk or directory_disk:
            raise RuntimeError(ui_text("Многотомные ZIP не поддерживаются.", "Multipart ZIP archives are not supported."))
        if count == 65535 or directory_size == 0xffffffff:
            if end_offset < 20:
                raise RuntimeError("Invalid ZIP64 locator")
            stream.seek(end_offset - 20)
            locator = struct.unpack("<4sLQL", stream.read(20))
            if locator[0] != b"PK\x06\x07" or locator[1] or locator[3] != 1:
                raise RuntimeError("Invalid ZIP64 locator")
            stream.seek(locator[2])
            record = struct.unpack("<4sQ2H2L4Q", stream.read(56))
            if record[0] != b"PK\x06\x06" or record[4] or record[5]:
                raise RuntimeError("Invalid ZIP64 directory")
            count, directory_size, directory_offset = record[7:10]
        if count > 50000 or directory_size > 16 * 1024 * 1024:
            raise RuntimeError(ui_text("ZIP превышает 50 000 записей или 16 МиБ метаданных.",
                                       "ZIP exceeds 50,000 entries or 16 MiB of metadata."))
        if directory_offset + directory_size > size:
            raise RuntimeError("Invalid ZIP central directory bounds")
        stream.seek(directory_offset)
        if directory_size and stream.read(4) != b"PK\x01\x02":
            # ZIP can be prefixed by arbitrary data; mirror the normal EOCD
            # offset correction without trusting the advertised entry count.
            directory_offset = end_offset - directory_size
        stream.seek(directory_offset)
        used = actual_count = 0
        while used < directory_size:
            if QThread.currentThread().isInterruptionRequested():
                raise DownloadCancelled()
            header = stream.read(46)
            if len(header) != 46 or header[:4] != b"PK\x01\x02":
                raise RuntimeError("Invalid ZIP central directory entry")
            name, extra, comment = struct.unpack_from("<3H", header, 28)
            length = 46 + name + extra + comment
            actual_count += 1
            if actual_count > 50000 or used + length > directory_size:
                raise RuntimeError("ZIP central directory exceeds its entry/size limit")
            stream.seek(length - 46, 1)
            used += length
        if actual_count != count:
            raise RuntimeError("ZIP central directory count does not match its header")


class ConversionTarInfo(tarfile.TarInfo):
    def _metadata_budget(self, archive):
        archive._nop_metadata_bytes = getattr(archive, "_nop_metadata_bytes", 0) + self.size
        if self.size > 1024 * 1024 or archive._nop_metadata_bytes > 16 * 1024 * 1024:
            raise RuntimeError("TAR extended metadata exceeds the size limit")

    def _proc_pax(self, archive):
        self._metadata_budget(archive)
        return super()._proc_pax(archive)

    def _proc_gnulong(self, archive):
        self._metadata_budget(archive)
        return super()._proc_gnulong(archive)

    def _proc_sparse(self, archive):
        raise RuntimeError(conversion_text("Разрежённые GNU TAR записи не поддерживаются.", "GNU sparse TAR entries are not supported."))

    def _proc_gnusparse_00(self, *args):
        raise RuntimeError("Sparse TAR entries are not supported")

    _proc_gnusparse_01 = _proc_gnusparse_00
    _proc_gnusparse_10 = _proc_gnusparse_00



