_CONVERSION_FFMPEG_CACHE = {}
_CONVERSION_FFMPEG_CACHE_LOCK = threading.RLock()


def conversion_ffmpeg_capabilities(run):
    tool = find_converter_tool("ffmpeg.exe", "ffmpeg")
    if not tool:
        raise RuntimeError(conversion_text("FFmpeg не найден.", "FFmpeg was not found."))
    st = Path(tool).stat()
    key = (str(Path(tool).resolve()), st.st_mtime_ns, st.st_size)
    with _CONVERSION_FFMPEG_CACHE_LOCK:
        if key in _CONVERSION_FFMPEG_CACHE:
            return _CONVERSION_FFMPEG_CACHE[key]
    encoders, experimental, muxers = set(), set(), set()
    text = run([tool, "-hide_banner", "-encoders"], timeout=15, capture_limit=2*1024*1024)
    for line in text.splitlines():
        parts = line.split()
        if len(parts) >= 2 and re.fullmatch(r"[VAS.][A-Z.]{5}", parts[0]) and parts[1] != "=":
            encoders.add(parts[1])
            if "X" in parts[0]:
                experimental.add(parts[1])
    text = run([tool, "-hide_banner", "-muxers"], timeout=15, capture_limit=2*1024*1024)
    for line in text.splitlines():
        parts = line.split()
        if len(parts) >= 2 and parts[0] == "E" and parts[1] != "=":
            muxers.update(parts[1].split(","))
    if not encoders or not muxers:
        raise RuntimeError(conversion_text("Не удалось прочитать список кодировщиков/контейнеров FFmpeg.",
                                   "Could not read FFmpeg's encoder/muxer lists."))
    value = {"tool": tool, "encoders": encoders, "experimental": experimental, "muxers": muxers}
    with _CONVERSION_FFMPEG_CACHE_LOCK:
        _CONVERSION_FFMPEG_CACHE[key] = value
        while len(_CONVERSION_FFMPEG_CACHE) > 4:
            _CONVERSION_FFMPEG_CACHE.pop(next(iter(_CONVERSION_FFMPEG_CACHE)))
    return value



def conversion_require_codecs(capabilities, muxer, *codecs):
    if muxer not in capabilities["muxers"]:
        raise RuntimeError(conversion_text(f"Эта сборка FFmpeg не содержит выходной контейнер {muxer}.",
                                   f"This FFmpeg build has no {muxer} output muxer."))
    for codec in codecs:
        if not codec or codec == "copy":
            continue
        if codec not in capabilities["encoders"]:
            raise RuntimeError(conversion_text(f"Эта сборка FFmpeg не содержит кодировщик {codec}.",
                                       f"This FFmpeg build has no {codec} encoder."))
        if codec in capabilities["experimental"]:
            raise RuntimeError(conversion_text(f"Кодировщик {codec} экспериментальный и не включается автоматически.",
                                       f"Encoder {codec} is experimental and is not enabled automatically."))



