class TranscodePreviewCanvas(QWidget):
    """One bounded raster frame; independent of the main player's native surface."""
    def __init__(self, parent):
        super().__init__(parent)
        self.image = QImage()
        self.setMinimumSize(160, 90)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)

    def sizeHint(self):
        return QSize(320,180)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.fillRect(self.rect(), Qt.GlobalColor.black)
        if not self.image.isNull():
            size = self.image.size()
            size.scale(self.size(), Qt.AspectRatioMode.KeepAspectRatio)
            target = QRect((self.width()-size.width())//2, (self.height()-size.height())//2, size.width(), size.height())
            painter.drawImage(target, self.image)


class TranscodePreviewFullscreen(QDialog):
    def __init__(self, preview):
        super().__init__(preview.owner, Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)
        self.preview = preview
        self.setObjectName('transcodePreviewFullscreen')
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)
        self._escape = QShortcut(QKeySequence('Esc'), self, activated=preview.exit_fullscreen)

    def reject(self):
        self.preview.exit_fullscreen()

    def closeEvent(self, event):
        self.preview.exit_fullscreen()
        event.accept()


class TranscodePreview(QWidget):
    """Preview of the original, silent by default; never a compression simulation."""
    def __init__(self, owner, parent):
        super().__init__(parent)
        self.owner, self._embed_layout = owner, parent.layout()
        self._source, self._positions = '', collections.OrderedDict()
        self._closed = self._moving = self._priming = False
        self._fullscreen = None
        self._seeking_slider = False
        self._error_text = ''
        self._needs_initial_frame = False
        self.title, self.status = QLabel(), QLabel()
        for label in (self.title, self.status):
            label.setProperty('i18n_skip', True)
            label.setMinimumWidth(0)
            label.setWordWrap(True)
        self.status.setObjectName('muted')
        self.canvas = TranscodePreviewCanvas(self)
        self.canvas.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.canvas.setMaximumHeight(240)
        self.player = QMediaPlayer(self)
        self.audio = QAudioOutput(self)
        self.audio.setMuted(True)
        self.player.setAudioOutput(self.audio)
        self.sink = QVideoSink(self)
        self.player.setVideoSink(self.sink)
        self.sink.videoFrameChanged.connect(self._frame)
        self.player.mediaStatusChanged.connect(self._media_status)
        self.player.positionChanged.connect(self._position)
        self.player.durationChanged.connect(self._duration)
        self.player.playbackStateChanged.connect(lambda _state: self.update_language())
        self.player.seekableChanged.connect(lambda seekable: self.seek.setEnabled(seekable))
        self.player.errorOccurred.connect(self._error)
        self.play_button, self.fullscreen_button = QPushButton(), QPushButton()
        for button in (self.play_button, self.fullscreen_button):
            button.setProperty('i18n_skip', True)
            button.setMinimumWidth(0)
        self.play_button.clicked.connect(self.toggle_play)
        self.fullscreen_button.clicked.connect(self.toggle_fullscreen)
        self.seek = QSlider(Qt.Orientation.Horizontal)
        self.seek.setRange(0,0)
        self.seek.setEnabled(False)
        self.seek.valueChanged.connect(self._seek_changed)
        self.seek.sliderReleased.connect(lambda: self.player.setPosition(self.seek.value()))
        self.time = QLabel('00:00 / 00:00')
        self.time.setProperty('i18n_skip', True)
        controls = QGridLayout()
        controls.setSpacing(5)
        controls.addWidget(self.play_button,0,0)
        controls.addWidget(self.fullscreen_button,0,1)
        controls.addWidget(self.time,1,0,1,2)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0,0,0,0)
        layout.setSpacing(4)
        layout.addWidget(self.title)
        layout.addWidget(self.canvas, 1)
        layout.addWidget(self.seek)
        layout.addLayout(controls)
        layout.addWidget(self.status)
        for widget in (self,self.canvas,self.play_button,self.fullscreen_button,self.seek):
            widget.installEventFilter(self)
        self.update_language()

    def eventFilter(self, watched, event):
        if event.type() in (QEvent.Type.ShortcutOverride,QEvent.Type.KeyPress) and event.key() in (Qt.Key.Key_Space,Qt.Key.Key_Left,Qt.Key.Key_Right):
            if event.type()==QEvent.Type.KeyPress and not event.isAutoRepeat():
                if event.key()==Qt.Key.Key_Space:self.toggle_play()
                else:self.player.setPosition(max(0,min(self.player.duration(),self.player.position()+(5000 if event.key()==Qt.Key.Key_Right else -5000))))
            event.accept()
            return True
        return super().eventFilter(watched,event)

    def update_language(self):
        self.title.setText(ui_text('Предпросмотр исходника · без звука', 'Original preview · muted'))
        playing = self.player.playbackState() == QMediaPlayer.PlaybackState.PlayingState and not self._priming
        self.play_button.setText(ui_text('Пауза', 'Pause') if playing else ui_text('Воспроизвести', 'Play'))
        self.fullscreen_button.setText(ui_text('Вернуться (Esc)', 'Return (Esc)') if self._fullscreen and self._fullscreen.isVisible()
                                       else ui_text('Во весь экран', 'Full screen'))
        self.play_button.setEnabled(bool(self._source) and not self._error_text)
        self.fullscreen_button.setEnabled(bool(self._source))
        error = getattr(self._error_text,'en' if LANG=='en' else 'ru',self._error_text)
        self.status.setText((ui_text('Ошибка предпросмотра: ', 'Preview error: ')+error) if self._error_text else
                            Path(self._source).name if self._source else ui_text('Выберите видео в очереди.', 'Select a video in the queue.'))
        self.status.setToolTip(ui_text('Это оригинал, а не результат сжатия. Предпросмотр использует отдельный декодер Qt.',
                                      'This is the original, not compressed output. Preview uses a separate Qt decoder.'))
        if self._fullscreen:
            self._fullscreen.setWindowTitle(ui_text('Предпросмотр исходника', 'Original preview'))

    def _remember_position(self):
        if self._source:
            self._positions[self._source] = max(0, self.player.position())
            self._positions.move_to_end(self._source)
            while len(self._positions)>32:
                self._positions.popitem(last=False)

    def set_source(self, source):
        path = str(Path(source).absolute()) if source else ''
        if self._closed or path == self._source:
            return
        self._remember_position()
        self._priming = False
        self.player.stop()
        self._source, self._error_text = path, ''
        self._needs_initial_frame = bool(path)
        self.canvas.image = QImage()
        self.canvas.update()
        self.seek.setEnabled(False)
        self.player.setSource(QUrl.fromLocalFile(path) if path else QUrl())
        self.update_language()

    def _media_status(self, status):
        if self._closed or not self._source:
            return
        if status == QMediaPlayer.MediaStatus.LoadedMedia and self._needs_initial_frame:
            # LoadedMedia also occurs after paused seeking; initialize only once.
            self._needs_initial_frame = False
            self.player.setActiveAudioTrack(-1)
            self.player.setPosition(self._positions.get(self._source,0))
            self._priming = True
            self.player.play()  # Decode one frame, then pause; audio always muted.
        elif status == QMediaPlayer.MediaStatus.EndOfMedia:
            self._priming = False
            self.update_language()

    def _frame(self, frame):
        if self._closed or not self._source or not frame.isValid():
            return
        image = frame.toImage()
        if image.isNull():
            return
        # Never retain a QVideoFrame or a queue of decoder/GPU buffers.
        self.canvas.image = image.scaled(1920,1080, Qt.AspectRatioMode.KeepAspectRatio,
                                         Qt.TransformationMode.SmoothTransformation) if image.width()>1920 or image.height()>1080 else image.copy()
        self.canvas.update()
        if self._priming:
            self._priming = False
            self.player.pause()

    def _duration(self, duration):
        self._seeking_slider = True
        self.seek.setRange(0, min(2147483647, max(0,duration)))
        self._seeking_slider = False
        self._position(self.player.position())

    def _position(self, position):
        if not self.seek.isSliderDown():
            self._seeking_slider = True
            self.seek.setValue(position)
            self._seeking_slider = False
        self.time.setText(fmt_time(position)+' / '+fmt_time(self.player.duration()))

    def _seek_changed(self, value):
        if not self._seeking_slider and not self.seek.isSliderDown() and self.player.isSeekable():
            self.player.setPosition(value)

    def _error(self, error, message):
        if self._closed or error == QMediaPlayer.Error.NoError:
            return
        self._priming = False
        self._error_text = redact_diagnostic(message)[:500] or conversion_text(
            'Qt не смог открыть видео ('+error.name+'). Проверьте файл, доступ и поддержку кодека Qt.',
            'Qt could not open the video ('+error.name+'). Check the file, access and Qt codec support.')
        self.update_language()

    def toggle_play(self):
        if self._closed or not self._source or self._error_text:
            return
        self._priming = False
        if self.player.playbackState() == QMediaPlayer.PlaybackState.PlayingState:
            self.player.pause()
        else:
            if self.player.mediaStatus() == QMediaPlayer.MediaStatus.EndOfMedia:
                self.player.setPosition(0)
            self.player.play()

    def toggle_fullscreen(self):
        if self._fullscreen and self._fullscreen.isVisible():
            self.exit_fullscreen()
            return
        if self._closed or not self._source:
            return
        if self._fullscreen is None:
            self._fullscreen = TranscodePreviewFullscreen(self)
        self._moving = True
        try:
            self._embed_layout.removeWidget(self)
            self._fullscreen.layout().addWidget(self)
            self.canvas.setMaximumHeight(16777215)
            screen = self.owner.screen()
            if self._fullscreen.windowHandle() is not None:
                self._fullscreen.windowHandle().setScreen(screen)
            self._fullscreen.setGeometry(screen.geometry())
            self._fullscreen.setStyleSheet(self.owner.styleSheet())
            self._fullscreen.showFullScreen()
            self.show()
            self.play_button.setFocus()
        finally:
            self._moving = False
        self.update_language()

    def exit_fullscreen(self):
        if self._fullscreen is None or self.parentWidget() is not self._fullscreen:
            return
        self._moving = True
        try:
            self._fullscreen.layout().removeWidget(self)
            self._embed_layout.addWidget(self)
            self.canvas.setMaximumHeight(240)
            self._fullscreen.hide()
            self.show()
        finally:
            self._moving = False
        self.update_language()

    def hideEvent(self, event):
        if not self._moving:
            self._priming = False
            self.player.pause()
        super().hideEvent(event)

    def shutdown(self):
        if self._closed:
            return
        self.exit_fullscreen()
        self._closed = True
        self._priming = False
        self.player.stop()
        self.player.setSource(QUrl())
        self.player.setVideoSink(None)
        self.canvas.image = QImage()
        self.canvas.update()
        self._positions.clear()
        if self._fullscreen:
            self._fullscreen.deleteLater()
            self._fullscreen = None


class PanelToolButton(QPushButton):
    """Кнопка панели со сглаженной обводкой, окрашиваемой текущей темой.

    Контур рисуется самим виджетом, чтобы сохранить гладкие скругления.
    Цвет задаётся свойством outlineColor при обновлении темы, поэтому
    отрисовка не зависит от фиксированного цвета исходной темы.
    """
    def paintEvent(self, event):
        super().paintEvent(event)
        if self.objectName() not in ("tool", "special") or not bool(self.property("on")) or bool(self.property("quietOutline")):
            return

        outline = self.property("outlineColor")
        if not isinstance(outline, str) or not outline:
            outline = SPECIAL if self.objectName() == "special" else ACCENT

        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        pen = QPen(QColor(outline))
        pen.setWidthF(1.0)
        pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        # Оставляем контур внутри геометрии виджета, чтобы не обрезались углы.
        rect = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        painter.drawRoundedRect(rect, 7.0, 7.0)
        painter.end()


class DraggableSideBlock(QFrame):
    """Блок боковой панели. Перетаскивание начинается только с разделителя."""
    def __init__(self, key, content_layout, owner):
        super().__init__()
        self.block_key = key
        self.owner = owner
        self.setObjectName("draggableSideBlock")
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        outer.addLayout(content_layout)


class DraggableSideSeparator(QFrame):
    """Обычная тонкая линия, которая одновременно служит областью перетаскивания."""
    def __init__(self, target_key, owner):
        super().__init__()
        self.target_key = target_key
        self.owner = owner
        self._drag_start = None
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setObjectName("sep")
        self.setFixedHeight(5)  # линия остаётся тонкой; расширена только невидимая область захвата
        self.setCursor(Qt.CursorShape.ArrowCursor)
        self.setMouseTracking(True)

    def paintEvent(self, event):
        # Рисуем исходную тонкую линию по центру расширенной области захвата.
        painter = QPainter(self)
        color = self.palette().color(QPalette.ColorRole.Mid)
        if self.property("dropTarget"):
            color = QColor(SPECIAL if _THEME["name"] in {"jet_black_orchid", "wine_ash_turquoise"} else "#ffb02e")
        painter.setPen(QPen(color, 1))
        painter.drawLine(0, self.height() // 2, self.width(), self.height() // 2)
        painter.end()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_start = event.globalPosition().toPoint()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._drag_start is not None and event.buttons() & Qt.MouseButton.LeftButton:
            if (event.globalPosition().toPoint() - self._drag_start).manhattanLength() >= QApplication.startDragDistance():
                self.owner._begin_side_separator_drag(self.target_key, event.globalPosition().toPoint())
                self._drag_start = None
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self.owner._side_separator_dragging:
            self.owner._finish_side_separator_drag(event.globalPosition().toPoint())
        self._drag_start = None
        super().mouseReleaseEvent(event)

    def keyPressEvent(self, event):
        if event.key() == Qt.Key.Key_Escape and self.owner._side_separator_dragging:
            self.owner._cancel_side_separator_drag()
            self._drag_start = None
            event.accept()
            return
        super().keyPressEvent(event)


