class CnpQtTranslator(QTranslator):
    """Qt's own catalog follows NOP's single LANG setting.

    The existing EN_TEXT dictionary also covers common file-dialog chrome if
    a packaged build omits the optional Qt Russian translation catalog.
    """
    def __init__(self, parent):
        super().__init__(parent)
        self.load("qtbase_ru", QLibraryInfo.path(QLibraryInfo.LibraryPath.TranslationsPath))
        self._fallback = {}
        for ru, en in EN_TEXT.items():
            self._fallback.setdefault(en, ru)

    def isEmpty(self):
        return False

    def translate(self, context, source, disambiguation=None, n=-1):
        translated = super().translate(context, source, disambiguation, n)
        if translated:
            return translated
        if context in ("QFileDialog", "QFileSystemModel", "QDialogButtonBox", "QLineEdit", "QWidgetTextControl", "QPlatformTheme"):
            return self._fallback.get(source.replace("&", ""), "")
        return ""


