class TrackCell(QTableWidgetItem):
    def __lt__(self, other):
        a = self.data(int(Qt.ItemDataRole.UserRole) + 1)
        b = other.data(int(Qt.ItemDataRole.UserRole) + 1)
        if self.column() == 0:
            def natural(text):
                return [(1, int(p)) if p.isdecimal() else (0, p.casefold()) for p in re.split(r"(\d+)", text)]
            a, b = natural(self.text()), natural(other.text())
        elif self.column() == 3:
            a, b = self.text().casefold(), other.text().casefold()
        else:
            a, b = (a is not None, a or 0), (b is not None, b or 0)
        if a == b:
            return str(self.data(Qt.ItemDataRole.UserRole)).casefold() < str(other.data(Qt.ItemDataRole.UserRole)).casefold()
        return a < b


class TrackTable(QTableWidget):
    reordered = pyqtSignal(list)

    def __init__(self):
        super().__init__(0, 4)
        self.setSelectionBehavior(self.SelectionBehavior.SelectRows)
        self.setSelectionMode(self.SelectionMode.ExtendedSelection)
        self.setEditTriggers(self.EditTrigger.NoEditTriggers)
        self.setDragEnabled(True)
        self.setAcceptDrops(True)
        self.setDragDropMode(self.DragDropMode.InternalMove)
        self.setDragDropOverwriteMode(False)
        self.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.setShowGrid(False)
        self.setAlternatingRowColors(True)
        self.setHorizontalScrollMode(self.ScrollMode.ScrollPerPixel)
        self.verticalHeader().hide()
        self.setHorizontalHeader(CnpFileHeader(self))
        self._column_minima = {1:40, 2:40, 3:40}
        self._enforcing_widths = False
        self._width_timer = QTimer(self)
        self._width_timer.setSingleShot(True)
        self._width_timer.timeout.connect(self.recalculate_column_minima)
        header = self.horizontalHeader()
        header.setResizeContentsPrecision(-1)  # Include long values beyond the first 1000 rows.
        header.sectionResized.connect(self._enforce_column_minimum)
        for model_signal in (self.model().dataChanged, self.model().rowsInserted, self.model().rowsRemoved,
                             self.model().modelReset, self.model().headerDataChanged):
            model_signal.connect(self.schedule_column_minima)
        header.installEventFilter(self)

    def schedule_column_minima(self, *_args):
        self._width_timer.start(0)

    def recalculate_column_minima(self):
        header = self.horizontalHeader()
        metrics = header.fontMetrics()
        for column in (1, 2, 3):
            title = str(self.model().headerData(column, Qt.Orientation.Horizontal) or '')
            # Custom header: 8 px padding each side + 18 px for its active arrow.
            self._column_minima[column] = max(40, metrics.horizontalAdvance(title)+34, self.sizeHintForColumn(column))
            self._enforce_column_minimum(column, 0, self.columnWidth(column))

    def _enforce_column_minimum(self, column, old, new):
        minimum = self._column_minima.get(column, 0)
        if new < minimum and not self._enforcing_widths:
            self._enforcing_widths = True
            try: self.horizontalHeader().resizeSection(column, minimum)
            finally: self._enforcing_widths = False

    def changeEvent(self, event):
        super().changeEvent(event)
        if hasattr(self, '_width_timer') and event.type() in (QEvent.Type.FontChange, QEvent.Type.StyleChange, QEvent.Type.ApplicationFontChange):
            self.schedule_column_minima()

    def event(self, event):
        result = super().event(event)
        if hasattr(self, '_width_timer') and event.type()==QEvent.Type.DevicePixelRatioChange:
            self.schedule_column_minima()
        return result

    def eventFilter(self, watched, event):
        if watched is self.horizontalHeader() and event.type() in (QEvent.Type.FontChange, QEvent.Type.StyleChange):
            self.schedule_column_minima()
        return super().eventFilter(watched, event)

    def move_rows(self, rows, destination):
        rows = sorted(set(r for r in rows if 0 <= r < self.rowCount()))
        if not rows:
            return
        destination = max(0, min(self.rowCount(), destination))
        hidden = [self.isRowHidden(r) for r in range(self.rowCount())]
        self.setSortingEnabled(False)
        self.horizontalHeader().setSortIndicatorShown(False)
        records = [([self.takeItem(r, c) for c in range(4)], hidden[r]) for r in range(self.rowCount())]
        moving = [records[r] for r in rows]
        moving_ids = {id(record[0]) for record in moving}
        remaining = [record for r, record in enumerate(records) if r not in rows]
        index = destination - sum(r < destination for r in rows)
        records = remaining[:index] + moving + remaining[index:]
        self.setRowCount(0)
        self.setRowCount(len(records))
        for r, (cells, is_hidden) in enumerate(records):
            for c, cell in enumerate(cells):
                self.setItem(r, c, cell)
                cell.setSelected(id(cells) in moving_ids)
            self.setRowHidden(r, is_hidden)
        self.reordered.emit([self.item(r, 0).data(Qt.ItemDataRole.UserRole) for r in range(self.rowCount())])

    def dropEvent(self, event):
        if event.source() is not self:
            event.ignore()
            return
        point = event.position().toPoint()
        row = self.indexAt(point).row()
        if row < 0:
            row = self.rowCount()
        elif point.y() > self.visualRect(self.model().index(row, 0)).center().y():
            row += 1
        self.move_rows([i.row() for i in self.selectionModel().selectedRows() if not self.isRowHidden(i.row())], row)
        event.setDropAction(Qt.DropAction.MoveAction)
        event.accept()


