class NopApoJob(QThread):
    """Disk I/O and UAC never block the Qt GUI thread."""
    def __init__(self, callback, parent):
        super().__init__(parent)
        self.callback = callback
        self.result = None

    def run(self):
        try:
            self.result = {"ok": True, "value": self.callback()}
        except PermissionError as exc:
            self.result = {"ok": False, "permission": True, "error": str(exc)}
        except Exception as exc:
            self.result = {"ok": False, "error": str(exc)}


