    def _support_link_button(self, text: str, url: str) -> QPushButton:
        button = QPushButton(text)
        button.setObjectName("donate")
        button.setProperty("support_url", url)
        button.setToolTip(url)
        button.setCursor(Qt.CursorShape.PointingHandCursor)
        button.clicked.connect(lambda _checked=False, target=url: QDesktopServices.openUrl(QUrl(target)))
        return button

    def _qr_label(self, stem: str):
        path = find_asset(stem)
        if path is None and stem == "donate_ozon_qr":
            path = find_asset("donate_ru_qr")  # Existing Ozon asset remains usable.
        if path is None:
            return None
        pm = QPixmap(str(path))
        if pm.isNull():
            return None
        pm = pm.scaled(168, 168, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.FastTransformation)
        lbl = QLabel()
        lbl.setPixmap(pm)
        lbl.setProperty("support_asset", stem)
        lbl.setFixedSize(pm.width() + 12, pm.height() + 12)
        lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lbl.setStyleSheet("background:#ffffff; border-radius:8px;")
        lbl.setProperty("i18n_skip", True)
        return lbl

    def fill_about(self):
        texts = ABOUT_TEXT["en" if LANG == "en" else "ru"]
        self.about_tagline.setText(texts["tagline"])
        help_texts = NOP_HELP["en" if LANG == "en" else "ru"]
        self.about_features.setText(help_texts["main"])
        self.about_how.setText("")
        if hasattr(self, "about_tabs"):
            self.about_tabs.setTabText(0, T("Пошагово"))
            self.about_tabs.setTabText(1, T("Подробно"))
            self.about_panels_doc.setHtml(help_texts["panels"] + help_texts["details"])
            self.about_panels_doc.setStyleSheet("QTextBrowser {background:transparent;border:0;color:" + ICON_COLOR + ";}")
        self.about_version.setText(f"{texts['version']} {APP_VERSION}")
        for label in (self.about_tagline, self.about_features, self.about_how, self.about_version):
            # Display labels keep mouse selection and Copy, without a typing caret.
            label.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse |
                Qt.TextInteractionFlag.LinksAccessibleByMouse)
            label.setOpenExternalLinks(True)
        if hasattr(self, "about_network_label"):
            self.about_network_label.setText(T("Сеть:") + " " + str(SUPPORT["crypto"].get("network", "")).strip())
        self._refresh_about_selection()
        if hasattr(self, "about_zoom_controls"):
            self.about_zoom_controls.update_language()
            self.about_zoom_controls.refresh()

    def _refresh_about_selection(self):
        labels = (self.about_tabs.widget(0).findChildren(QLabel) if hasattr(self, "about_tabs")
                  else [self.about_tagline, self.about_features, self.about_how, self.about_version])
        for label in labels:
            palette = label.palette()
            palette.setColor(QPalette.ColorRole.Highlight, QColor(ACCENT))
            palette.setColor(QPalette.ColorRole.HighlightedText, QColor(ON_ACCENT))
            label.setPalette(palette)
        browsers = self.about_tabs.widget(0).findChildren(HelpTextBrowser) + [self.about_panels_doc] if hasattr(self, "about_tabs") else []
        for browser in browsers:
            palette = browser.palette()
            palette.setColor(QPalette.ColorRole.Highlight, QColor(ACCENT))
            palette.setColor(QPalette.ColorRole.HighlightedText, QColor(ON_ACCENT))
            browser.setPalette(palette)

    def refresh_avatar(self):
        size = 88
        pm = QPixmap(size, size)
        pm.fill(Qt.GlobalColor.transparent)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        clip = QPainterPath()
        clip.addEllipse(QRectF(0, 0, size, size))
        p.setClipPath(clip)
        src_path = find_asset("avatar")
        img = QPixmap(str(src_path)) if src_path is not None else QPixmap()
        if not img.isNull():
            side = min(img.width(), img.height())
            p.drawPixmap(QRectF(0, 0, size, size), img,
                         QRectF((img.width() - side) / 2, (img.height() - side) / 2, side, side))
        else:
            p.fillRect(QRectF(0, 0, size, size), QColor(SPECIAL))
            p.setPen(QColor(ON_SPECIAL))
            font = p.font()
            font.setPixelSize(int(size * 0.36))
            font.setBold(True)
            p.setFont(font)
            p.drawText(QRectF(0, 0, size, size), Qt.AlignmentFlag.AlignCenter, "CN")
        p.setClipping(False)
        p.setPen(QPen(QColor(SPECIAL), 2.5))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(QRectF(1.25, 1.25, size - 2.5, size - 2.5))
        p.end()
        self.about_avatar.setPixmap(pm)

    def copy_donate_address(self):
        QApplication.clipboard().setText(str(SUPPORT["crypto"].get("address", "")).strip())
        self.btn_copy_address.setText(T("Скопировано ✓"))
        QTimer.singleShot(1600, lambda: self.btn_copy_address.setText(T("Скопировать адрес")))

    # ---------- основной аудиоплеер Windows ----------
    @staticmethod
    def _register_default_player_windows() -> None:
        """Register per-user audio/video candidates; never write UserChoice or extension defaults."""
        if sys.platform != "win32":
            raise OSError("Эта настройка доступна только в Windows.")
        import winreg

        executable = os.path.abspath(sys.executable)
        frozen = bool(getattr(sys, "frozen", False))
        if not frozen and executable.lower().endswith("python.exe"):
            windowed_python = executable[:-10] + "pythonw.exe"
            if os.path.isfile(windowed_python):
                executable = windowed_python
        command_parts = [executable] if frozen else [executable, os.path.abspath(__file__)]
        command = subprocess.list2cmdline(command_parts) + ' "%1"'
        icon = f'"{executable}",0'
        capabilities = r"Software\YAMI.FM.Player\Capabilities"
        friendly_name = DEFAULT_PLAYER_REGISTRY_NAME

        def write(path, name, value, kind=winreg.REG_SZ):
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER, path) as key:
                winreg.SetValueEx(key, name, 0, kind, value)

        write(capabilities, "ApplicationName", friendly_name)
        write(capabilities, "ApplicationDescription", "NOP — audio and video player")
        write(capabilities, "ApplicationIcon", icon)
        for prog_id, extensions, description in (
                ("YAMI.FM.Audio", AUDIO_EXTS, "NOP audio"),
                ("YAMI.FM.Video", VIDEO_EXTS, "NOP video")):
            base = "Software\\Classes\\" + prog_id
            write(base, "", description)
            write(base + r"\DefaultIcon", "", icon)
            write(base + r"\Application", "ApplicationName", friendly_name)
            write(base + r"\Application", "ApplicationDescription", "NOP — audio and video player")
            write(base + r"\Application", "ApplicationIcon", icon)
            write(base + r"\shell\open\command", "", command)
            for extension in sorted(extensions):
                write(capabilities + r"\FileAssociations", extension, prog_id)
                write(rf"Software\Classes\{extension}\OpenWithProgids", prog_id, b"", winreg.REG_NONE)
        write(r"Software\RegisteredApplications", DEFAULT_PLAYER_REGISTRY_NAME, capabilities)
        # ApplicationName must match its RegisteredApplications value name.
        # Retain the legacy audio ProgID (and the user's choice), but remove
        # only our obsolete registration alias after the new NOP entry exists.
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\RegisteredApplications", 0,
                            winreg.KEY_READ | winreg.KEY_WRITE) as key:
            for legacy_name in DEFAULT_PLAYER_LEGACY_REGISTRY_NAMES:
                try:
                    legacy_path, _kind = winreg.QueryValueEx(key, legacy_name)
                except FileNotFoundError:
                    continue
                if str(legacy_path).rstrip("\\").casefold() == capabilities.casefold():
                    winreg.DeleteValue(key, legacy_name)
        # Do not overwrite Applications\python.exe: that would affect unrelated Python apps.
        if frozen:
            name = os.path.basename(executable)
            base = rf"Software\Classes\Applications\{name}"
            write(base, "FriendlyAppName", friendly_name)
            write(base + r"\shell\open\command", "", command)
            for extension in sorted(MEDIA_EXTS):
                write(base + r"\SupportedTypes", extension, "")
        shell = getattr(getattr(ctypes, "windll", None), "shell32", None)
        if shell is not None:
            shell.SHChangeNotify(0x08000000, 0x0000, None, None)  # SHCNE_ASSOCCHANGED / SHCNF_IDLIST

    def on_default_player_toggled(self, enabled: bool):
        if sys.platform != "win32":
            self.show_message(T("Основной плеер"), ui_text(
                "Выбор основного плеера доступен в Windows.", "Default player selection is available on Windows."))
            return
        try:
            if enabled:
                self._register_default_player_windows()
                self.cfg["use_as_default_player"] = True
                self.save_settings()
                url = "ms-settings:defaultapps?registeredAppUser=" + urllib.parse.quote(DEFAULT_PLAYER_REGISTRY_NAME, safe="")
                if not QDesktopServices.openUrl(QUrl(url)):
                    QDesktopServices.openUrl(QUrl("ms-settings:defaultapps"))
                self.open_information("windows")
            else:
                self.cfg["use_as_default_player"] = False
                self.save_settings()
                QDesktopServices.openUrl(QUrl("ms-settings:defaultapps"))
                self.show_message(T("Основной плеер"), ui_text(
                    "В настройках Windows выберите другой плеер для нужных аудио- и видеоформатов.",
                    "Choose another player for the desired audio and video formats in Windows Settings."), simple=True)
        except Exception as exc:
            self.show_message(T("Основной плеер"), ui_text(
                "Не удалось зарегистрировать NOP.\n", "Could not register NOP.\n") + str(exc))

    # ---------- действия настроек ----------
    def on_setting_toggled(self, key: str, state: bool):
        self.cfg[key] = bool(state)
        self.save_settings()

    def on_language_changed(self, _index=None):
        set_language(self.cmb_language.currentData() or "ru")
        self.cfg["language"] = LANG
        self.retranslate_ui()
        self.schedule_relayout()
        self.save_settings()

    def on_theme_changed(self, *_args):
        name = self.cmb_theme.currentData() or "classic"
        self.apply_theme(name, False)

    def apply_theme(self, name: str, light: bool = False, save: bool = True):
        set_theme(name, light)
        self.cfg["theme"] = _THEME["name"]
        self.cfg["theme_light"] = False
        self.setStyleSheet(themed(STYLE.replace("%ARROW%", ensure_arrow_png())))
        # Обводка блока «Настройки / О приложении» использует SPLINE,
        # вычисляемый из специального цвета текущей темы.
        if hasattr(self, "special_block"):
            self.special_block.update()
        self._refresh_title_bar_theme()
        if hasattr(self, 'track_list'):
            self.track_list.horizontalHeader().update_theme()
            self.track_list.schedule_column_minima()
        dialog = getattr(self, "_system_eq_dialog", None)
        if dialog is not None: dialog.update_theme()
        tool_dialog = getattr(self, "_apo_tool_dialog", None)
        if tool_dialog is not None: tool_dialog.update_theme()
        preview = getattr(self, "transcode_preview", None)
        if preview is not None and preview._fullscreen is not None:
            preview._fullscreen.setStyleSheet(self.styleSheet())
        self.refresh_theme_icons()
        self.refresh_avatar()
        self._refresh_about_selection()
        self.about_zoom_controls.refresh()
        if hasattr(self, "window_placement"):
            self.window_placement.refresh_theme()
        self.schedule_relayout()
        if save:
            self.save_settings()


    def _set_window_status(self, text: str):
        self._title_status = str(text)
        self._update_app_title()

    def _update_app_title(self):
        if not hasattr(self, "title_label"):
            return
        label = self.title_label
        full_width = label.fontMetrics().horizontalAdvance(APP_NAME)
        # Allow 24 px of breathing room at either end of the allocated text area.
        available = max(0, label.contentsRect().width() - 48)
        name = APP_NAME if available >= full_width + 2 else APP_SHORT_NAME
        if label.text() != name:
            label.setText(name)
        if self.windowTitle() != name:
            self.setWindowTitle(name)
        status = getattr(self, "_title_status", "")
        label.setToolTip(f"{APP_NAME} · {APP_VERSION}" + ("\n" + status if status else ""))

    def _refresh_title_bar_theme(self):
        if hasattr(self, "title_bar"):
            self.title_bar.setStyleSheet(window_title_style())

    def refresh_theme_icons(self):
        """Перекрашивает все иконки под текущую тему."""
        self.icon_play = make_icon("play", ACCENT)
        self.icon_pause = make_icon("pause", ACCENT)
        for b in self.findChildren(QPushButton):
            if b.property("themeRole"):
                self._refresh_button_theme_role(b)
                continue
            info = _ICON_REG.get(b.icon().cacheKey())
            if not info:
                continue
            kind, role, size = info
            obj = b.objectName()
            if b.property("themeIconRole") in {"information", "accent"}:
                color = ACCENT
            elif _THEME["name"] in {"jet_black_orchid", "wine_ash_turquoise"} and (obj in {"accent", "special"} or b.property("information")):
                color = "#ffffff"
            elif obj == "accent":
                color = ON_ACCENT
            elif b.property("information"):
                color = ACCENT
            elif obj == "special":
                color = SPECIAL
            else:
                color = _role_color(role)
            b.setIcon(make_icon(kind, color, size))
        self.btn_pause.setIcon(self.icon_pause if self._is_playing else self.icon_play)
        for key in self.PANEL_KEYS:
            attr, _widgets, button, icon = self._panel_spec(key)
            if button is not None:
                self.tint(button, icon, bool(getattr(self, attr)))
        self.tint(self.btn_pin, "pin", self.pinned)
        self._sync_profile_buttons()
        self.set_playback_mode(self.playback_mode, save=False)
        self.update_playback_speed_button()
        self._refresh_transport_icons()
        self.update_volume_ui(self.volume.value())
        self.btn_handle.setIcon(make_icon("chev_r" if self.controls_visible else "chev_l", ICON_MUTED))
        self.profile_handle.setIcon(make_icon("chev_u" if self.profile_bar_visible else "chev_d", ICON_MUTED))
        self.converter_run_btn.setIcon(make_icon("convert", ON_ACCENT))
        self.transcode_run_btn.setIcon(make_icon("film", ON_ACCENT))
        palette = self.dl_req_label.palette()
        palette.setColor(QPalette.ColorRole.Link, QColor(ACCENT_LIGHT))
        self.dl_req_label.setPalette(palette)
        self.update_download_state()

    def _refresh_transport_icons(self):
        # Keep only these two normal-mode glyphs white, including their disabled
        # state. The buttons retain Qt's existing disabled behavior/background.
        for button, kind in ((self.btn_prev, "prev"), (self.btn_next, "next")):
            icon = make_icon(kind, "#ffffff")
            icon.addPixmap(icon.pixmap(64, 64), QIcon.Mode.Disabled)
            _ICON_REG[icon.cacheKey()] = (kind, "raw:#ffffff", 64)
            button.setIcon(icon)
        classic = _THEME["name"] == "classic"
        if self.btn_pause.property("playbackSurface") != classic:
            self.btn_pause.setProperty("playbackSurface", classic)
            self.btn_pause.style().unpolish(self.btn_pause)
            self.btn_pause.style().polish(self.btn_pause)
            self.btn_pause.update()

    def retranslate_ui(self):
        """Переводит подписи, подсказки, пункты списков и заголовки таблиц на выбранный язык.
        Исходный русский текст запоминается в свойствах виджета, поэтому возврат на русский точный."""
        en = LANG == "en"

        def tr(orig: str) -> str:
            if en:
                return T(orig)
            # Подпись, созданная при выбранном English, помнит только английский текст: возвращаем русский оригинал.
            return _en_to_ru().get(orig, orig) if orig and not _CYR_RE.search(orig) else orig

        def sync(w, slot: str, current: str, setter):
            if not current:
                return
            o_key, l_key = f"i18n_{slot}_o", f"i18n_{slot}_l"
            orig, last = w.property(o_key), w.property(l_key)
            if orig is None or last != current:
                orig = current
            new = tr(orig)
            if new != current:
                setter(new)
            w.setProperty(o_key, orig)
            w.setProperty(l_key, new)

        role_o = Qt.ItemDataRole.UserRole + 77
        role_l = Qt.ItemDataRole.UserRole + 78
        for spin in self.findChildren(QAbstractSpinBox):
            sync(spin, "special", spin.specialValueText(), spin.setSpecialValueText)
        for w in [self] + self.findChildren(QWidget):
            if w.property("i18n_skip") or isinstance(w.window(), (CnpFileDialog, NopInputDialog)):
                continue
            sync(w, "tip", w.toolTip(), w.setToolTip)
            if isinstance(w, FlowHelpText):
                sync(w, "text", w.text(), w.setText)
            if w.property("instruction"):
                sync(w, "name", w.accessibleName(), w.setAccessibleName)
            if isinstance(w, (QLabel, QPushButton, QCheckBox)):
                if isinstance(w, QLabel) and w.pixmap() is not None and not w.pixmap().isNull():
                    continue
                sync(w, "text", w.text(), w.setText)
            elif isinstance(w, QLineEdit):
                sync(w, "ph", w.placeholderText(), w.setPlaceholderText)
            elif isinstance(w, QComboBox):
                for i in range(w.count()):
                    current = w.itemText(i)
                    orig, last = w.itemData(i, role_o), w.itemData(i, role_l)
                    if orig is None or last != current:
                        orig = current
                    new = tr(orig)
                    if new != current:
                        w.setItemText(i, new)
                    w.setItemData(i, orig, role_o)
                    w.setItemData(i, new, role_l)
            elif isinstance(w, QTableWidget):
                for c in range(w.columnCount()):
                    item = w.horizontalHeaderItem(c)
                    if item is None:
                        continue
                    current = item.text()
                    orig, last = item.data(role_o), item.data(role_l)
                    if orig is None or last != current:
                        orig = current
                    new = tr(orig)
                    if new != current:
                        item.setText(new)
                    item.setData(role_o, orig)
                    item.setData(role_l, new)
        dialog = getattr(self, "_system_eq_dialog", None)
        if dialog is not None:
            dialog.setWindowTitle(ui_text("Эквалайзер всего устройства Windows", "Windows device-wide equalizer"))
            dialog.update_language()
        for dialog in self.findChildren(NopInputDialog):
            dialog.update_language()
        for dialog in self.findChildren(QDialog):
            if hasattr(dialog, "_chrome"): dialog._chrome.update_language()
        # тексты, которые собираются программой на лету
        for dialog in self.findChildren(CnpFileDialog):
            dialog.update_language()
        self._apo_device_labels()
        self._apo_refresh_tool_diagnostics()
        self._apo_refresh_ui()
        self.fill_about()
        self._refresh_track_metadata()
        self.filter_track_list()
        self._fill_dl_resolutions()
        self._refresh_resolution_status()
        self.update_playback_speed_button()
        self.update_download_state()
        self.btn_pin.setToolTip(T("Закреплено поверх всех окон (Ctrl+P - открепить)" if self.pinned
                                  else "Закрепить поверх всех окон (Ctrl+P)"))
        self.btn_handle.setToolTip(T("Скрыть панель кнопок (Ctrl+H)" if self.controls_visible
                                     else "Показать панель кнопок (Ctrl+H)"))
        self.profile_handle.setToolTip(T("Скрыть панель раскладки" if self.profile_bar_visible
                                         else "Показать панель раскладки"))

        for dialog in getattr(self, "_information_dialogs", {}).values():
            dialog.update_language()
        for dialog in self.findChildren(InformationDialog):
            if dialog.message_title is not None:
                dialog.update_language()
        if hasattr(self, "spotify_source_note"):
            self.spotify_source_note.setText(ui_text(
                "Spotify: только метаданные. Аудио ищется отдельно в SpotiSaver, YouTube или SoundCloud; это не прямая загрузка из Spotify и версия записи может отличаться.",
                "Spotify provides metadata only. Audio is matched separately via SpotiSaver, YouTube or SoundCloud; this is not a direct Spotify download and the recording may differ."))

        self._conversion_retranslate()

    def open_data_folder(self):
        try:
            if os.name == "nt":
                os.startfile(str(DATA_DIR))  # noqa: S606
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(DATA_DIR)])
            else:
                subprocess.Popen(["xdg-open", str(DATA_DIR)])
        except Exception:
            pass

    def _begin_side_separator_drag(self, source_key: str, global_pos):
        """Отсоединяет настоящий блок, оставляя placeholder и включая прозрачное следование за курсором."""
        if source_key not in self._side_block_keys or self._side_separator_dragging:
            return
        block = self._side_blocks.get(source_key)
        layout = self.side_w.layout()
        if block is None or layout is None:
            return

        # Запоминаем смещение курсора относительно блока до изменения layout,
        # чтобы при начале перетаскивания блок не прыгал к указателю.
        block_global_top_left = block.mapToGlobal(QPoint(0, 0))
        self._side_drag_cursor_offset = QPoint(
            global_pos.x() - block_global_top_left.x(),
            global_pos.y() - block_global_top_left.y(),
        )
        self._side_separator_dragging = True
        self._side_separator_drag_key = source_key
        self._side_separator_target_key = source_key
        self._side_drag_original_order = list(self._side_block_order)
        self._side_drag_height = max(1, block.height())

        placeholder = QFrame(self.side_w)
        placeholder.setObjectName("sideBlockDropPlaceholder")
        placeholder.setFixedHeight(self._side_drag_height)
        placeholder.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        if _THEME["name"] in {"jet_black_orchid", "wine_ash_turquoise"}:
            red, green, blue = _rgb(SPECIAL)
            placeholder.setStyleSheet(
                f"QFrame#sideBlockDropPlaceholder {{ background: rgba({red},{green},{blue},35); "
                f"border: 1px dashed {SPECIAL}; border-radius: 5px; }}")
        else:
            placeholder.setStyleSheet(
                "QFrame#sideBlockDropPlaceholder { background: rgba(255,176,46,35); "
                "border: 1px dashed #ffb02e; border-radius: 5px; }")
        self._side_drag_placeholder = placeholder

        # Эффект применяется к настоящему блоку, поэтому полупрозрачны и фон,
        # и все дочерние кнопки/надписи, а не только отдельная копия.
        opacity = QGraphicsOpacityEffect(block)
        opacity.setOpacity(0.58)
        block.setGraphicsEffect(opacity)
        self._side_drag_opacity_effect = opacity

        for separator in self._side_separators.values():
            separator.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._side_separators[source_key].setFocus(Qt.FocusReason.MouseFocusReason)

        layout.removeWidget(block)
        block.setParent(self.side_w)
        block.setFixedWidth(max(1, self.side_w.width()))
        block.show()
        self._rebuild_side_block_layout(self._side_block_order, source_key)

        # Захватываем события на уровне приложения: курсор продолжает двигать
        # блок даже после выхода за пределы исходной полоски-разделителя.
        app = QApplication.instance()
        if app is not None:
            app.installEventFilter(self)
        self._move_side_dragged_block(global_pos)
        self._update_side_separator_drop_target(global_pos)

    def _rebuild_side_block_layout(self, order, dragging_key=None):
        """Перестраивает порядок блоков/разделителей, оставляя placeholder на месте dragged block."""
        layout = self.side_w.layout()
        if layout is None:
            return
        for block in self._side_blocks.values():
            layout.removeWidget(block)
        for separator in self._side_separators.values():
            layout.removeWidget(separator)
        if self._side_drag_placeholder is not None:
            layout.removeWidget(self._side_drag_placeholder)
        # Закреплённый блок остаётся первым; линия под ним относится к текущему первому блоку.
        if order:
            first_separator = self._side_separators.get(order[0])
            if first_separator is not None:
                layout.insertWidget(1, first_separator)
        insert_at = 2
        for index, key in enumerate(order):
            if index:
                separator = self._side_separators.get(key)
                if separator is not None:
                    layout.insertWidget(insert_at, separator)
                    insert_at += 1
            if dragging_key == key and self._side_drag_placeholder is not None:
                layout.insertWidget(insert_at, self._side_drag_placeholder)
            else:
                layout.insertWidget(insert_at, self._side_blocks[key])
            insert_at += 1
        self.side_w.updateGeometry()
        layout.activate()

    def _move_side_dragged_block(self, global_pos):
        key = self._side_separator_drag_key
        if not key:
            return
        block = self._side_blocks[key]
        local = self.side_w.mapFromGlobal(global_pos)
        offset = getattr(self, "_side_drag_cursor_offset", QPoint(0, 0))
        # Не ограничиваем координату текущей позиции placeholder: блок должен
        # следовать за курсором, а placeholder отдельно управляет layout.
        x = local.x() - offset.x()
        y = local.y() - offset.y()
        block.setGeometry(x, y, max(1, self.side_w.width()), block.height())
        block.raise_()

    def _update_side_separator_drop_target(self, global_pos):
        if not getattr(self, "_side_separator_dragging", False):
            return
        source = self._side_separator_drag_key
        local_y = self.side_w.mapFromGlobal(global_pos).y()
        others = []
        for key in self._side_block_order:
            if key == source:
                continue
            block = self._side_blocks.get(key)
            if block is not None:
                center_y = block.mapTo(self.side_w, QPoint(0, 0)).y() + block.height() // 2
                others.append((center_y, key))
        others.sort()
        # Индекс вставки определяется границами между блоками, поэтому можно
        # переместить элемент и в самое начало, и в самый конец списка.
        insert_index = sum(1 for center_y, _key in others if local_y > center_y)
        order_without_source = [key for key in self._side_block_order if key != source]
        insert_index = max(0, min(insert_index, len(order_without_source)))
        preview_order = list(order_without_source)
        preview_order.insert(insert_index, source)
        target_key = preview_order[insert_index] if preview_order else source
        self._side_separator_target_key = target_key
        if preview_order != self._side_block_order:
            self._side_block_order = preview_order
            self._rebuild_side_block_layout(preview_order, source)
            self._move_side_dragged_block(global_pos)
        # Подсветка остаётся на обычной тонкой линии-разделителе.
        for sep in self._side_separators.values():
            sep.setProperty("dropTarget", False)
            sep.update()
        if target_key in self._side_separators:
            sep = self._side_separators[target_key]
            sep.setProperty("dropTarget", True)
            sep.update()

    def _finish_side_separator_drag(self, global_pos):
        if not getattr(self, "_side_separator_dragging", False):
            return
        self._update_side_separator_drop_target(global_pos)
        source = self._side_separator_drag_key
        final_order = list(self._side_block_order)
        block = self._side_blocks.get(source)
        layout = self.side_w.layout()
        self._side_separator_dragging = False
        self._side_separator_drag_key = None
        self._side_separator_target_key = None
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        if block is not None:
            block.setGraphicsEffect(None)
        self._side_drag_opacity_effect = None
        for sep in self._side_separators.values():
            sep.setProperty("dropTarget", False)
            sep.update()
        if layout is not None and block is not None:
            if self._side_drag_placeholder is not None:
                layout.removeWidget(self._side_drag_placeholder)
                self._side_drag_placeholder.deleteLater()
            self._side_drag_placeholder = None
            block.setParent(self.side_w)
            block.setMinimumWidth(0)
            block.setMaximumWidth(16777215)
            self._rebuild_side_block_layout(final_order)
            block.show()
        self._side_drag_height = 0
        self._side_drag_original_order = None
        self.cfg["side_block_order"] = list(final_order)
        self.save_settings()
        self.side_w.updateGeometry()
        self.schedule_relayout()

    def _cancel_side_separator_drag(self):
        """Отменяет текущую перестановку (Escape) и возвращает исходный порядок."""
        if not self._side_separator_dragging:
            return
        original = list(self._side_drag_original_order or self._side_block_order)
        source = self._side_separator_drag_key
        block = self._side_blocks.get(source)
        layout = self.side_w.layout()
        self._side_separator_dragging = False
        self._side_separator_drag_key = None
        self._side_separator_target_key = None
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        if block is not None:
            block.setGraphicsEffect(None)
        self._side_drag_opacity_effect = None
        if layout is not None:
            if self._side_drag_placeholder is not None:
                layout.removeWidget(self._side_drag_placeholder)
                self._side_drag_placeholder.deleteLater()
            self._side_drag_placeholder = None
            if block is not None:
                block.setParent(self.side_w)
                block.setMinimumWidth(0)
                block.setMaximumWidth(16777215)
            self._side_block_order = original
            self._rebuild_side_block_layout(original)
        for separator in self._side_separators.values():
            separator.setProperty("dropTarget", False)
            separator.update()
        self._side_drag_original_order = None
        self._side_drag_height = 0
        if block is not None:
            block.show()
        self.side_w.updateGeometry()

    def reorder_side_block(self, source_key: str, target_key: str):
        """Переставляет блок вместе с его содержимым и сохраняет новый порядок."""
        allowed = list(getattr(self, "_side_block_keys", ()))
        order = list(getattr(self, "_side_block_order", allowed))
        if source_key not in allowed or target_key not in allowed or source_key == target_key:
            return
        order.remove(source_key)
        order.insert(order.index(target_key), source_key)
        self._side_block_order = order
        self._rebuild_side_block_layout(order)
        self.cfg["side_block_order"] = list(order)
        self.save_settings()
        self.side_w.updateGeometry()
        self.schedule_relayout()

    def reset_panel_layout(self):
        """Возвращает стандартный набор панелей (окно настроек остаётся открытым)."""
        default = {
            "controls": True, "seek": True, "tracks": False, "size": False, "equalizer": True,
            "color": False, "downloads": False, "download_info": False, "converter": False,
            "transcode": False,
        }
        self._applying_panel_profile = True
        try:
            for key, visible in default.items():
                self.set_panel_visible(key, visible, save=False)
            # Сбросить порядок блоков к разработческой раскладке.
            if hasattr(self, "_side_block_order") and hasattr(self, "_side_blocks"):
                default_order = ["playback", "downloads", "view", "tools"]
                self._side_block_order = list(default_order)
                self._rebuild_side_block_layout(default_order)
                self.cfg["side_block_order"] = list(default_order)
        finally:
            self._applying_panel_profile = False
        self.panel_profile = "custom"
        self._profile_restore = None
        self._sync_profile_buttons()
        self.save_settings()
        QTimer.singleShot(120, self.center_window)

    def build_downloads_panel(self) -> QWidget:
        """«Настройки загрузки»: одна цельная панель без прокрутки.
        Сверху - сервис и режим (канал / плейлист / одно видео), ссылка, сколько скачать и папка;
        ниже - качество и cookies; внизу - что ещё не заполнено и красная кнопка «Скачать»."""
        panel = QWidget()
        panel.setObjectName("panel")
        panel.setMinimumWidth(500)
        panel.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        panel.setStyleSheet("QComboBox { padding:4px 6px; }")

        title = QLabel("Настройки загрузки")
        title.setObjectName("title")

        def muted(text: str) -> QLabel:
            lbl = QLabel(text)
            lbl.setObjectName("muted")
            return lbl

        # Выбор площадки загрузки. YouTube остаётся значением по умолчанию.
        self.cmb_source = WheelSafeComboBox()
        for key, label in (
            ("youtube", "YouTube"),
            ("tiktok", "TikTok"),
            ("instagram", "Instagram"),
            ("spotify", "Spotify — трек / альбом / плейлист"),
            ("direct", "Загрузка видео"),
        ):
            self.cmb_source.addItem(label, key)
        self.cmb_source.setCurrentIndex(max(self.cmb_source.findData(self.cfg.get("dl_source", "youtube")), 0))
        self.cmb_source.setMinimumWidth(220)
        self.cmb_source.setToolTip("Spotify: читает метаданные, ищет аудио по названию/исполнителю и сохраняет MP3 как «Исполнитель - Название»; список TXT/CSV удаляется после операции.")
        self.cmb_source.currentIndexChanged.connect(self.on_dl_source_changed)
        raw_source_urls = self.cfg.get("dl_source_urls", {})
        self._dl_source_urls = dict(raw_source_urls) if isinstance(raw_source_urls, dict) else {}
        self._dl_source_urls.setdefault("youtube", self.cfg.get("channel", DEFAULT_CHANNEL))
        self._dl_source_urls.setdefault("tiktok", "")
        self._dl_source_urls.setdefault("instagram", "")
        self._dl_source_urls.setdefault("spotify", "")
        self._dl_source_urls.setdefault("direct", "")
        initial_source = self.cmb_source.currentData() or "youtube"
        self._last_dl_source = initial_source
        self._dl_active = False
        self._dl_ready_flag = None

        # Что скачиваем: канал / плейлист / одно видео - плашка с выбором.
        saved_kind = str(self.cfg.get("dl_kind", self.cfg.get("dl_target_mode", "channel")))
        self.dl_kind = saved_kind if saved_kind in self.DL_KINDS else "channel"
        self.kind_buttons: dict[str, QPushButton] = {}
        kind_layout = QHBoxLayout()
        kind_layout.setSpacing(4)
        for key in self.DL_KINDS:
            b = QPushButton()
            b.setObjectName("chip")
            b.setCheckable(True)
            b.setFixedHeight(30)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _checked=False, k=key: self.set_dl_kind(k))
            kind_layout.addWidget(b, 1)
            self.kind_buttons[key] = b
        self.kind_row_w = self._clear_row(kind_layout)

        # Одно поле ссылки на режим: канал/профиль, плейлист, одно видео. Показано всегда только одно.
        self.channel_edit = QLineEdit(self._dl_source_urls.get(initial_source, ""))
        self.channel_edit.editingFinished.connect(self.apply_channel_text)
        self.playlist_edit = QLineEdit()
        self.video_edit = QLineEdit()
        for edit in (self.channel_edit, self.playlist_edit, self.video_edit):
            edit.setClearButtonEnabled(True)
            edit.returnPressed.connect(self.start_download)

        # Сколько видео скачать (для канала/профиля и плейлиста).
        self.count_label = muted(self.DL_COUNT_LABELS["channel"])
        count_layout = QHBoxLayout()
        count_layout.setSpacing(6)
        count_layout.addWidget(self.count_label)
        count_layout.addStretch(1)
        count_layout.addWidget(self.btn_minus)
        count_layout.addWidget(self.count)
        count_layout.addWidget(self.btn_plus)
        self.count_row_w = self._clear_row(count_layout)

        # куда скачивать
        self.folder_edit = QLineEdit(str(self.download_dir))
        self.folder_edit.setPlaceholderText("Папка для загрузки")
        self.folder_edit.setToolTip("Куда скачивать")
        self.folder_edit.editingFinished.connect(self.apply_folder_text)
        btn_browse = self.icon_button("folder", "Выбрать папку для загрузки")
        btn_browse.clicked.connect(self.browse_folder)
        folder_row = QHBoxLayout()
        folder_row.setSpacing(6)
        folder_row.addWidget(self.folder_edit, 1)
        folder_row.addWidget(btn_browse)

        # что и в каком качестве скачивать
        self.cmb_mode = WheelSafeComboBox()
        self.cmb_resolution = WheelSafeComboBox()
        _old_profile = self.cfg.get('dl_video_profile', self.cfg.get('dl_vq'))
        self._dl_resolution = resolution_choice(self.cfg.get('dl_video_resolution'), _old_profile)
        self._dl_resolution_tiers = []
        self._dl_resolution_signature = None
        self._resolution_generation = 0
        self._resolution_probe = None
        self._resolution_message = None
        self.cmb_resolution.setProperty('i18n_skip', True)
        self._fill_dl_resolutions()
        self.cmb_resolution.currentIndexChanged.connect(self._dl_resolution_selected)
        # Частота кадров: выбор готового значения вместо прежнего блока «Видео».
        self.cmb_fps = WheelSafeComboBox()
        for _key, _label in (("max", "Максимальная"), ("mid", "Средняя"), ("min", "Минимальная")):
            self.cmb_fps.addItem(_label, _key)
        for _n in (24, 25, 30, 50, 60):
            self.cmb_fps.addItem(f"{_n} FPS", str(_n))
        _fps_saved = fps_choice(self.cfg.get("dl_fps"), _old_profile)
        self.cmb_fps.setCurrentIndex(max(0, self.cmb_fps.findData(_fps_saved if isinstance(_fps_saved, str) else f"{_fps_saved:g}")))
        self.cmb_fps.setToolTip("Частота кадров видео. Берётся ближайшая из доступных у источника, без перекодирования.")
        self.cmb_fps.currentIndexChanged.connect(self.on_dl_options_changed)
        self.cmb_aq = WheelSafeComboBox()
        self.cmb_container = WheelSafeComboBox()
        self.cmb_vcodec = WheelSafeComboBox()
        for codec, label in DL_VCODECS:
            self.cmb_vcodec.addItem(label, codec)
        self.cmb_vcodec.setCurrentIndex(max(self.cmb_vcodec.findData(self.cfg.get("dl_vcodec", "any")), 0))
        self.cmb_vcodec.setToolTip("Выбор кодека исходного видеопотока; доступность зависит от площадки")
        self.cmb_vcodec.currentIndexChanged.connect(self.on_dl_options_changed)
        for ext, label in DL_CONTAINERS:
            self.cmb_container.addItem(label, ext)
        self.cmb_container.setCurrentIndex(max(self.cmb_container.findData(self.cfg.get("dl_container", "mkv")), 0))
        self.cmb_container.setToolTip(ui_text("Контейнер без перекодирования. При несовместимых потоках используется MKV с пояснением.",
            "Container without re-encoding. Incompatible streams use MKV with an explanation."))
        self.cmb_container.currentIndexChanged.connect(self.on_dl_options_changed)
        for cmb, items, key, tip in (
            (self.cmb_mode, DL_MODES, "dl_mode", "Что скачивать"),
            (self.cmb_aq, AUDIO_QUALITIES, "dl_aq", "Качество аудио"),
        ):
            for k, label in items:
                cmb.addItem(label, k)
            saved = self.cfg.get(key)
            cmb.setCurrentIndex(max(cmb.findData(saved), 0))
            cmb.setToolTip(tip)
            cmb.currentIndexChanged.connect(self.on_dl_options_changed)
        self.cmb_download_rate = WheelSafeComboBox()
        for rate, label in (("0", "Без ограничений"), ("128", "128 КБ/с"), ("256", "256 КБ/с"),
                            ("512", "512 КБ/с"), ("1024", "1 МБ/с"), ("2048", "2 МБ/с"),
                            ("5120", "5 МБ/с")):
            self.cmb_download_rate.addItem(label, rate)
        self.cmb_download_rate.setCurrentIndex(max(0, self.cmb_download_rate.findData(str(self.cfg.get("download_rate_limit", "0")))))
        self.cmb_download_rate.currentIndexChanged.connect(self.on_dl_options_changed)
        self.cmb_sample_rate = WheelSafeComboBox()
        for rate, label in (("0", "Авто / исходная частота"), ("22050", "22050 Гц"),
                            ("32000", "32000 Гц"), ("44100", "44100 Гц"),
                            ("48000", "48000 Гц"), ("96000", "96000 Гц")):
            self.cmb_sample_rate.addItem(label, rate)
        saved_sample_rate = str(self.cfg.get("dl_sample_rate", "0"))
        sample_index = self.cmb_sample_rate.findData(saved_sample_rate)
        self.cmb_sample_rate.setCurrentIndex(sample_index if sample_index >= 0 else 0)
        self.cmb_sample_rate.setToolTip(
            "При выборе частоты звук будет пересэмплирован через FFmpeg. «Как в оригинале» "
            "не добавляет перекодирование. В режиме «Видео + аудио» меняется частота "
            "аудиодорожки итогового видео без перекодирования видеопотока."
        )
        self.cmb_sample_rate.currentIndexChanged.connect(self.on_dl_options_changed)
        self.sample_rate_label = muted("Частота дискретизации")
        for cmb in (self.cmb_mode, self.cmb_fps, self.cmb_resolution, self.cmb_aq, self.cmb_container,
                    self.cmb_vcodec, self.cmb_download_rate, self.cmb_sample_rate):
            cmb.setMinimumWidth(120)
            cmb.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        # Cookies: браузер ИЛИ файл cookies.txt. Для обычных площадок нужны, чтобы сайт не требовал вход.
        self.cmb_cookies = WheelSafeComboBox()
        self.cmb_cookies.addItem("Не использовать cookies браузера", "none")
        for _browser_key, _browser_name in cookie_browser_choices():
            self.cmb_cookies.addItem(_browser_name, _browser_key)  # названия браузеров не переводятся
        self.cmb_cookies.setCurrentIndex(max(0, self.cmb_cookies.findData(str(self.cfg.get("dl_cookies_browser", "none")))))
        self.cmb_cookies.setToolTip("Необязательно. yt-dlp прочитает cookies авторизованной сессии из выбранного браузера прямо в память; "
                                    "они не сохраняются на диск. Браузер лучше закрыть.")
        self.cmb_cookies.setMinimumWidth(120)
        self.cmb_cookies.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.cmb_cookies.currentIndexChanged.connect(self.on_dl_options_changed)
        self.cmb_cookies_priority = WheelSafeComboBox()
        self.cmb_cookies_priority.addItem("Приоритет: браузер", "browser")
        self.cmb_cookies_priority.addItem("Приоритет: cookies.txt", "file")
        self.cmb_cookies_priority.setCurrentIndex(max(0, self.cmb_cookies_priority.findData(str(self.cfg.get("dl_cookies_priority", "browser")))))
        self.cmb_cookies_priority.setToolTip("Если выбраны и браузер, и файл cookies.txt, используется только выбранный здесь источник.")
        self.cmb_cookies_priority.currentIndexChanged.connect(self.on_dl_options_changed)
        self.cookies_browser_label = muted("Браузер")
        self.cookies_file_edit = QLineEdit(str(self.cfg.get("dl_cookies_file", "")))
        self.cookies_file_edit.setMinimumWidth(100)
        self.cookies_file_edit.setPlaceholderText("путь к cookies.txt")
        self.cookies_file_edit.setToolTip("Файл cookies.txt в формате Netscape, экспортированный из браузера")
        self.cookies_file_edit.editingFinished.connect(self.on_dl_options_changed)
        self.btn_cookies_file = self.icon_button("folder", "Выбрать файл cookies.txt")
        self.btn_cookies_file.clicked.connect(self.browse_cookies_file)
        self.btn_cookies_help = self.instruction_button("Что такое cookies и откуда взять файл cookies.txt")
        self.btn_cookies_help.clicked.connect(self.show_cookies_help)
        self.cookies_label = muted("Cookies")
        cookies_layout = QHBoxLayout()
        cookies_layout.setSpacing(6)
        cookies_layout.addWidget(self.cookies_label)
        cookies_layout.addWidget(self.cookies_file_edit, 1)
        cookies_layout.addWidget(self.btn_cookies_file)
        cookies_layout.addWidget(self.btn_cookies_help)
        browser_layout = QHBoxLayout()
        browser_layout.setSpacing(6)
        browser_layout.addWidget(self.cookies_browser_label)
        browser_layout.addWidget(self.cmb_cookies, 1)
        browser_layout.addWidget(self.cmb_cookies_priority, 1)
        cookies_column = QVBoxLayout()
        cookies_column.setSpacing(4)
        cookies_column.addLayout(browser_layout)
        cookies_column.addLayout(cookies_layout)
        self.cookies_row_w = self._clear_row(cookies_column)

        # Spotify API использует OAuth PKCE: сохраняем Client ID и локальный refresh token,
        # не просим client secret. Redirect URI нужно добавить в настройках Spotify App.
        self.spotify_client_id_edit = QLineEdit(str(self.cfg.get("spotify_client_id", "")))
        self.spotify_client_id_edit.setPlaceholderText("Spotify Client ID")
        self.spotify_client_id_edit.setToolTip("Client ID из Spotify Developer Dashboard. Redirect URI: http://127.0.0.1:8765/callback")
        self.spotify_client_id_edit.editingFinished.connect(self.save_settings)
        self.btn_spotify_auth = QPushButton("Авторизовать Spotify")
        self.btn_spotify_auth.setToolTip("Открыть окно браузера для входа в Spotify через OAuth PKCE")
        self.btn_spotify_auth.clicked.connect(self.authorize_spotify)
        self.btn_spotify_client_help = self.instruction_button("Как получить Spotify Client ID?")
        self.btn_spotify_client_help.clicked.connect(lambda: self.open_information("spotify"))
        self.lbl_spotify_auth = ElidedLabel("OAuth нужен для чтения альбомов и плейлистов Spotify")
        self.lbl_spotify_auth.setObjectName("muted")
        if self.cfg.get("spotify_refresh_token"):
            self.lbl_spotify_auth.setText("Spotify авторизован")
        self.spotify_auth_thread = None
        self.spotify_auth_status_label = ElidedLabel("OAuth redirect: http://127.0.0.1:8765/callback")
        self.spotify_auth_status_label.setObjectName("muted")
        self.cmb_spotify_format = WheelSafeComboBox()
        for fmt, label in (("mp3", "MP3"), ("m4a", "M4A / AAC"), ("flac", "FLAC"), ("opus", "Opus")):
            self.cmb_spotify_format.addItem(label, fmt)
        self.cmb_spotify_format.setCurrentIndex(max(self.cmb_spotify_format.findData(self.cfg.get("spotify_format", "mp3")), 0))
        self.cmb_spotify_format.setToolTip("Формат аудио Spotify-поиска. FLAC не повышает качество исходника.")
        self.cmb_spotify_format.currentIndexChanged.connect(self.on_dl_options_changed)
        self.cmb_spotify_bitrate = WheelSafeComboBox()
        for rate, label in (("128", "128 кбит/с"), ("192", "192 кбит/с"), ("256", "256 кбит/с"), ("320", "320 кбит/с"), ("0", "Лучшее исходное")):
            self.cmb_spotify_bitrate.addItem(label, rate)
        self.cmb_spotify_bitrate.setCurrentIndex(max(self.cmb_spotify_bitrate.findData(self.cfg.get("spotify_bitrate", "192")), 0))
        self.cmb_spotify_bitrate.setToolTip("Целевой битрейт для MP3; выше исходного качества он не создаёт.")
        self.cmb_spotify_bitrate.currentIndexChanged.connect(self.on_dl_options_changed)
        for cmb in (self.cmb_spotify_format, self.cmb_spotify_bitrate):
            cmb.setMinimumWidth(120)
            cmb.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.spotify_client_id_label = muted("Client ID")
        self.spotify_format_label = muted("Формат")
        self.spotify_bitrate_label = muted("Битрейт MP3")

        # Битрейт видео: относится только к видеопотоку (не к звуку и не к общему битрейту файла).
        self.cmb_vbitrate = WheelSafeComboBox()
        for _key, _label in VIDEO_BITRATE_MODES:
            self.cmb_vbitrate.addItem(_label, _key)
        self.cmb_vbitrate.setCurrentIndex(max(0, self.cmb_vbitrate.findData(str(self.cfg.get("dl_tbitrate_mode", "auto")))))
        self.cmb_vbitrate.setToolTip("Общий битрейт = видео + звук. Выбирается ближайший готовый вариант источника, без перекодирования; точного значения у источника может не быть.")
        self.cmb_vbitrate.setMinimumWidth(120)
        self.cmb_vbitrate.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        try:
            _saved_vb = float(self.cfg.get("dl_tbitrate_kbps", 0) or 0)
        except (TypeError, ValueError):
            _saved_vb = 0.0
        self.vbitrate_input = VideoBitrateInput(_saved_vb, str(self.cfg.get("dl_tbitrate_unit", "kbps")))
        self.vbitrate_input.setToolTip("Желаемый общий битрейт: 2500 Кбит/с = 2,5 Мбит/с. Будет выбран ближайший доступный вариант; точное значение источник может не предоставлять.")
        self.cmb_vbitrate.currentIndexChanged.connect(self.on_dl_options_changed)
        self.vbitrate_input.changed.connect(self.on_dl_options_changed)
        self.vbitrate_label = muted("Общий битрейт")
        self.vbitrate_hint = QLabel()
        self.vbitrate_hint.setObjectName("muted")
        self.vbitrate_hint.setWordWrap(True)
        self.vbitrate_hint.setProperty("i18n_skip", True)
        # Фрагмент видео.
        self.clip_start_edit = ClipTimeEdit()
        self.clip_end_edit = ClipTimeEdit()
        self.clip_start_edit.setToolTip("Начало фрагмента, ЧЧ:ММ:СС. Двоеточия расставляются автоматически: 123456 → 12:34:56. Пусто — с начала.")
        self.clip_end_edit.setToolTip("Конец фрагмента, ЧЧ:ММ:СС. Пусто — до конца видео.")
        self.clip_start_label = muted("Начало")
        self.clip_end_label = muted("Конец")
        self.clip_hint = QLabel()
        self.clip_hint.setObjectName("muted")
        self.clip_hint.setWordWrap(True)
        self.clip_hint.setProperty("i18n_skip", True)
        for _edit in (self.clip_start_edit, self.clip_end_edit):
            _edit.textChanged.connect(self.update_download_state)
            _edit.textChanged.connect(self._clip_text_changed)

        # Параметры качества двумя колонками: пары «подпись - список».
        opts_grid = QGridLayout()
        opts_grid.setHorizontalSpacing(8)
        opts_grid.setVerticalSpacing(4)
        opts_grid.setColumnMinimumWidth(0, 66)
        opts_grid.setColumnMinimumWidth(2, 88)
        opts_grid.setColumnStretch(1, 6)
        opts_grid.setColumnStretch(3, 5)
        self._dl_quality_controls = {}
        for setting_key, text, cmb, row, col in (
            ("mode", "Что качать", self.cmb_mode, 0, 0),
            ("resolution", "Разрешение видео", self.cmb_resolution, 1, 0),
            ("fps", "Частота кадров", self.cmb_fps, 1, 2),
            ("container", "Контейнер", self.cmb_container, 2, 0),
            ("vcodec", "Видеокодек", self.cmb_vcodec, 2, 2),
            ("audio", "Аудио", self.cmb_aq, 3, 0),
        ):
            lbl = muted(text)
            opts_grid.addWidget(lbl, row, col)
            opts_grid.addWidget(cmb, row, col + 1)
            self._dl_quality_controls[setting_key] = (lbl, cmb)
        self.download_rate_label = muted("Лимит скорости")
        opts_grid.addWidget(self.download_rate_label, 0, 2)
        opts_grid.addWidget(self.cmb_download_rate, 0, 3)
        # Частота дискретизации показывается только для обычных загрузок; настройки Spotify ниже.
        opts_grid.addWidget(self.sample_rate_label, 3, 2)
        opts_grid.addWidget(self.cmb_sample_rate, 3, 3)
        # Только для Spotify (у обычных площадок эти строки скрыты и места не занимают).
        opts_grid.addWidget(self.spotify_client_id_label, 4, 0)
        opts_grid.addWidget(self.spotify_client_id_edit, 4, 1, 1, 2)
        opts_grid.addWidget(self.btn_spotify_auth, 4, 3)
        opts_grid.addWidget(self.lbl_spotify_auth, 5, 1, 1, 3)
        opts_grid.addWidget(self.spotify_auth_status_label, 6, 1, 1, 3)
        opts_grid.addWidget(self.btn_spotify_client_help, 8, 0, 1, 4, Qt.AlignmentFlag.AlignRight)
        opts_grid.addWidget(self.spotify_format_label, 7, 0)
        opts_grid.addWidget(self.cmb_spotify_format, 7, 1)
        opts_grid.addWidget(self.spotify_bitrate_label, 7, 2)
        opts_grid.addWidget(self.cmb_spotify_bitrate, 7, 3)
        self.dl_profile_note = QLabel()
        self.dl_profile_note.setObjectName("muted")
