    def _fill_dl_resolutions(self):
        blocked = self.cmb_resolution.blockSignals(True)
        self.cmb_resolution.clear()
        for key, ru, en in (("max", "Максимальное", "Maximum"), ("mid", "Среднее", "Medium"), ("min", "Минимальное", "Minimum")):
            self.cmb_resolution.addItem(ui_text(ru, en), key)
        steps = set(RESOLUTION_STEPS)
        if isinstance(self._dl_resolution, int) and self._dl_resolution:
            steps.add(self._dl_resolution)
        for tier in sorted(steps, reverse=True):
            self.cmb_resolution.addItem(f"{tier}p" + (" (8K)" if tier == 4320 else " (4K)" if tier == 2160 else ""), tier)
        self.cmb_resolution.setCurrentIndex(max(0, self.cmb_resolution.findData(self._dl_resolution)))
        self.cmb_resolution.blockSignals(blocked)
        tip = ui_text("Пиксели по короткой стороне кадра. Максимальное/Среднее/Минимальное выбирают уровень из доступных у источника; число выбирает ближайшее разрешение без масштабирования.",
                      "Pixels on the shorter frame side. Maximum/Medium/Minimum pick a tier among those the source offers; a number selects the closest resolution without scaling.")
        if self._dl_resolution_tiers:
            tip += "\n" + ui_text("Доступно у этого видео: ", "Available for this video: ") + ", ".join(f"{n}p" for n in self._dl_resolution_tiers)
        self.cmb_resolution.setToolTip(tip)

    def _dl_profile_value(self):
        """Профиль для задач и меток: ключевое слово разрешения или «max» при явном разрешении."""
        return self._dl_resolution if isinstance(self._dl_resolution, str) else "max"

    def _dl_resolution_selected(self, *_args):
        self._dl_resolution = resolution_choice(self.cmb_resolution.currentData(), "min")
        self.on_dl_options_changed()

    def _dl_resolution_context(self):
        if self.cmb_source.currentData()=='spotify' or self.cmb_mode.currentData()=='audio': return None
        source = self.cmb_source.currentData()
        if source!='direct' and self.dl_kind!='single': return None
        try:
            url = download_url(self.video_edit.text().strip(), source, 'single')
        except ValueError:
            return None
        return (source, url, self.cookies_file_edit.text().strip(),
                self.cmb_cookies.currentData() or "none", self.cmb_cookies_priority.currentData() or "browser")

    def _invalidate_dl_resolutions(self, *_args):
        if not hasattr(self, 'cmb_resolution'): return
        signature = self._dl_resolution_context()
        if signature != self._dl_resolution_signature:
            self._resolution_generation += 1
            self._dl_resolution_signature = signature
            self._dl_resolution_tiers = []
            self._resolution_message = None
            self._dl_duration = None
            self._dl_duration_checked = False
            self._dl_checking = False
            self._pending_after_probe = None
            probe = self._resolution_probe
            if probe is not None and probe.isRunning(): probe.request_stop()
            self._fill_dl_resolutions()
        self._refresh_resolution_status()

    def _refresh_resolution_status(self):
        pass  # кнопки и строки статуса больше нет; подсказка обновляется в _fill_dl_resolutions

    def fetch_dl_resolutions(self):
        if getattr(self, '_closing', False): return
        self._invalidate_dl_resolutions()
        context = self._dl_resolution_context()
        if not context or (self._resolution_probe is not None and self._resolution_probe.isRunning()): return
        self._resolution_generation += 1
        source, url, cookies, browser, priority = context
        probe = ResolutionProbe({'url':url, 'source':source, 'cookies_file':cookies, 'language':LANG,
                                 'cookies_browser':browser, 'cookies_priority':priority,
                                 'generation':self._resolution_generation}, self)
        self._resolution_probe = probe
        self._resolution_message = None
        probe.result.connect(lambda result, generation=self._resolution_generation: self._on_dl_resolutions(generation, result))
        probe.finished.connect(lambda: self._retire_resolution_probe(probe))
        probe.start()
        self._refresh_resolution_status()

    def _retire_resolution_probe(self, probe):
        if self._resolution_probe is probe: self._resolution_probe = None
        probe.deleteLater()
        if not getattr(self, '_closing', False): self._refresh_resolution_status()

    def _on_dl_resolutions(self, generation, result):
        if getattr(self, '_closing', False) or generation != self._resolution_generation: return
        pending, self._pending_after_probe = self._pending_after_probe, None
        self._dl_duration_checked = True  # метаданные запрошены: повторно не проверяем, даже если источник не сообщил длительность
        if result.get('error'):
            self._resolution_message = str(result['error'])
            if pending is not None:
                self._dl_checking = False
                self.lbl_session.setText(ui_text("Не удалось проверить длительность видео: ", "Could not check the video duration: ") + self._resolution_message)
                self.show_message("NOP", self.lbl_session.text())
        else:
            self._dl_duration = format_number(result.get('duration'))
            self._dl_resolution_tiers = sorted({video_resolution(n) for n in result.get('resolutions', []) if video_resolution(n)})
            self._resolution_message = None if self._dl_resolution_tiers else ui_text('Источник не сообщил размеры кадра. Доступен Авто.', 'Source did not report frame dimensions. Auto is available.')
        self._fill_dl_resolutions()
        self._refresh_resolution_status()
        if pending is not None and not result.get('error'):
            self._dl_checking = False
            self.update_download_state()
            if not self.dl_missing():
                pending()

    def _dl_clip_available(self) -> bool:
        source = self.cmb_source.currentData() or "youtube"
        return source != "spotify" and (source == "direct" or self.dl_kind == "single")

    def _clip_text_changed(self, *_args):
        pass

    def _safe_clip(self):
        try:
            return self._current_clip()
        except ValueError:
            return None

    def _current_clip(self):
        """(начало, конец|None) либо None. Бросает ValueError при некорректном диапазоне."""
        if not self._dl_clip_available():
            return None
        return clip_range(self.clip_start_edit.text(), self.clip_end_edit.text(), self._dl_duration)

    def _dl_url_field(self) -> QLineEdit:
        source = self.cmb_source.currentData() or "youtube"
        if source in ("spotify", "direct") or self.dl_kind == "single":
            return self.video_edit
        return self.playlist_edit if self.dl_kind == "playlist" else self.channel_edit

    def set_dl_kind(self, kind: str, save: bool = True):
        if kind not in self.DL_KINDS:
            return
        self.dl_kind = kind
        for key, button in self.kind_buttons.items():
            button.setChecked(key == kind)
        self.update_dl_fields()
        self.on_dl_options_changed(save=False)
        self.update_download_state()
        self._invalidate_dl_resolutions()
        self.schedule_relayout()
        if save:
            self.save_settings()

    def update_dl_fields(self):
        """Показывает только то поле ссылки и те строки, которые нужны выбранному режиму."""
        source = self.cmb_source.currentData() or "youtube"
        spotify = source == "spotify"
        direct = source == "direct"
        kind = "single" if direct else self.dl_kind
        field = self._dl_url_field()
        placeholder = self.DL_PLACEHOLDERS.get(("spotify", "single") if spotify else (source, kind), "Ссылка")
        for edit in (self.channel_edit, self.playlist_edit, self.video_edit):
            edit.setVisible(edit is field)
        field.setPlaceholderText(T(placeholder))
        field.setToolTip(T(placeholder))
        self.count_row_w.setVisible(not spotify and not direct and kind != "single")
        self.count_label.setText(T(self.DL_COUNT_LABELS.get(kind, "")))
        self.count.setToolTip(self.DL_COUNT_LABELS.get(kind, ""))
        self.kind_row_w.setVisible(not spotify and not direct)

    def dl_missing(self) -> list[tuple[str, str]]:
        """Чего не хватает для загрузки: [(ключ, подсказка «что сделать» в HTML)]."""
        source = self.cmb_source.currentData() or "youtube"
        kind = self.dl_kind
        text = self._dl_url_field().text().strip()
        missing: list[tuple[str, str]] = []
        try:
            valid_url = download_url(text, source, "single" if source in ("spotify", "direct") else kind)
        except ValueError as exc:
            missing.append(("url", html_lib.escape(str(exc))))
        else:
            if source == "spotify" and spotify_url_kind(valid_url)[0] in {"album", "playlist"}:
                if not self.spotify_client_id_edit.text().strip() or not self.cfg.get("spotify_refresh_token"):
                    missing.append(("spotify", ui_text("<b>Spotify</b> — введите Client ID и нажмите «Авторизовать Spotify».",
                                                       "<b>Spotify</b> — enter Client ID and click Authorize Spotify.")))
        if not self.folder_edit.text().strip():
            missing.append(("folder", "<b>Папка</b> — выберите, куда сохранять файлы (кнопка с папкой справа от поля)."))
        if source != "spotify":
            try:
                self._current_clip()
            except ValueError as exc:
                missing.append(("clip", "<b>" + ui_text("Фрагмент", "Clip") + "</b> — " + html_lib.escape(str(exc))))
            if self.cmb_vbitrate.currentData() == "manual" and self.cmb_mode.currentData() != "audio":
                bitrate_error = self.vbitrate_input.error()
                if bitrate_error:
                    missing.append(("bitrate", "<b>" + ui_text("Общий битрейт", "Total bitrate") + "</b> — " + html_lib.escape(bitrate_error)))
        cookies_path = self.cookies_file_edit.text().strip()
        browser_wins = (self.cmb_cookies.currentData() or "none") != "none" and self.cmb_cookies_priority.currentData() != "file"
        if source != "spotify" and not browser_wins and ((source != "direct" and self.DL_REQUIRE_COOKIES) or cookies_path):
            file_ok = bool(cookies_path) and Path(cookies_path).is_file()
            if not file_ok:
                link = f" <a href='cookies-help' style='color:{ACCENT_LIGHT};text-decoration:underline'>Где взять cookies.txt?</a>"
                if cookies_path:
                    missing.append(("cookies", "<b>Cookies</b> — файл не найден: проверьте путь к cookies.txt." + link))
                else:
                    missing.append(("cookies", "<b>Cookies</b> — укажите файл cookies.txt." + link))
        return missing

    def _dl_button_tip(self) -> str:
        source = self.cmb_source.currentData() or "youtube"
        if source == "direct":
            return ui_text("Скачать видео или поток по прямому URL", "Download a video or stream from a direct URL")
        if source == "spotify":
            return ui_text("Найти аудио в других источниках по метаданным Spotify", "Match audio from other sources using Spotify metadata")
        name = {"youtube": "YouTube", "tiktok": "TikTok", "instagram": "Instagram"}.get(source, "")
        what = {"channel": "последние видео с канала / из профиля", "playlist": "видео из плейлиста / подборки",
                "single": "одно видео / публикацию"}.get(self.dl_kind, "видео")
        return f"Скачать {what} ({name})"

    def _refresh_bitrate_controls(self):
        for prefix in ("transcode",):
            control = getattr(self, prefix + "_total_bitrate", None)
            if control is not None: control.refresh_text()
        if hasattr(self, "dl_profile_note"):
            note = ""
            if self.cmb_source.currentData() == "spotify":
                note = ui_text("Spotify: свой формат и качество аудио.", "Spotify: own audio format and quality.")
            elif self.cmb_mode.currentData() == "audio":
                note = ui_text("Только аудио: видеонастройки не применяются.", "Audio only: video settings do not apply.")
            if self.cmb_sample_rate.currentData() != "0" and self.cmb_source.currentData() != "spotify" and self.cmb_mode.currentData() in {"audio","both"}:
                note = (note + " " if note else "") + ui_text("Частота звука включает его перекодирование.", "Sample rate re-encodes audio.")
            self.dl_profile_note.setText(note)
            self.dl_profile_note.setVisible(bool(note))
        if hasattr(self, "vbitrate_hint"):
            self.vbitrate_hint.setText("")
            self.vbitrate_hint.setVisible(False)
            self.vbitrate_input.refresh_text()
            self.clip_hint.setText(ui_text(
                "ЧЧ:ММ:СС (123456 → 12:34:56). Пусто — видео целиком.",
                "HH:MM:SS (123456 → 12:34:56). Empty = whole video.")
                if self._dl_clip_available() else ui_text(
                "Только для «Одно видео» и прямой ссылки.",
                "Only for “Single video” and direct links."))
        if hasattr(self, "cmb_cookies_priority"):
            both = (self.cmb_cookies.currentData() or "none") != "none" and bool(self.cookies_file_edit.text().strip())
            self.cmb_cookies_priority.setVisible(both)
        if hasattr(self, "cmb_spotify_bitrate"):
            enabled = self.cmb_source.currentData() == "spotify" and self.cmb_spotify_format.currentData() == "mp3"
            self.cmb_spotify_bitrate.setEnabled(enabled)
            self.spotify_bitrate_label.setEnabled(enabled)
        if hasattr(self, "transcode_total_bitrate"):
            running = self.transcode_worker is not None and self.transcode_worker.isRunning() if hasattr(self, "transcode_worker") else False
            self.transcode_video_bitrate.setEnabled(not self.transcode_total_bitrate.kbps() and not running)
            self.transcode_quality.setEnabled(not self.transcode_total_bitrate.kbps() and not self.transcode_video_bitrate.value() and not running)
            self.transcode_quality.setToolTip(ui_text("При ручном битрейте CRF/CQ не используется; качество задаёт битрейт.", "Manual bitrate replaces CRF/CQ; quality is determined by the bitrate.") if self.transcode_total_bitrate.kbps() or self.transcode_video_bitrate.value() else ui_text("Меньше CRF/CQ/QP — выше качество и обычно больше файл.", "Lower CRF/CQ/QP means higher quality and usually a larger file."))
            self.transcode_preset.setEnabled(choice_text(self.transcode_encoder) == "CPU" and not running)

        if hasattr(self, "transcode_crf"):
            self.transcode_crf.setEnabled(self.transcode_quality.isEnabled())


    def _total_bitrate_changed(self, *_args):
        self._refresh_bitrate_controls()
        if hasattr(self, "dl_req_label"): self.update_download_state()
        for prefix in ("transcode",):
            control = getattr(self, prefix + "_total_bitrate", None)
            if control is not None:
                self.cfg[prefix + "_total_bitrate_kbps"] = control.kbps()
                self.cfg[prefix + "_total_bitrate_unit"] = control.units.currentData()
        save_config(self.cfg)

    def update_download_state(self, *_):
        """Кнопка «Скачать» работает только когда всё заполнено; остальное объясняем текстом."""
        if not hasattr(self, "dl_req_label") or not hasattr(self, "btn_dl"):
            return
        self._refresh_bitrate_controls()
        missing = self.dl_missing()
        active = bool(getattr(self, "_dl_active", False))
        self.btn_dl.setEnabled(not missing and not active)
        if missing:
            items = "".join(f"<div style='margin-top:3px'>✗&nbsp;{msg}</div>" for _key, msg in missing)
            html = T_html(f"<div style='color:{ACCENT_LIGHT}'><b>Чтобы скачать, заполните:</b></div>{items}")
            tip = "Не заполнено:\n" + "\n".join(re.sub(r"<[^>]+>", "", msg) for _key, msg in missing)
        else:
            html = T_html("<div style='color:#7bd88f'><b>✓ Всё заполнено</b> — можно нажимать «Скачать».</div>")
            tip = self._dl_button_tip()
        changed = self.dl_req_label.text() != html
        if changed:
            self.dl_req_label.setText(html)
        ready = not missing
        if self._dl_ready_flag != ready:
            self._dl_ready_flag = ready
            self.dl_req_label.setProperty("ready", ready)
            self.dl_req_label.style().unpolish(self.dl_req_label)
            self.dl_req_label.style().polish(self.dl_req_label)
        self.btn_dl.setToolTip("Идёт загрузка…" if active else tip)
        if changed:
            self.schedule_relayout()

    def on_dl_req_link(self, link: str):
        if link == "cookies-help":
            self.show_cookies_help()

    def show_cookies_help(self):
        self.open_information("cookies")

    def show_direct_video_help(self):
        self.open_information("direct")

    def open_information(self, key):
        dialogs = getattr(self, "_information_dialogs", None)
        if dialogs is None:
            self._information_dialogs = dialogs = {}
        dialog = dialogs.get(key)
        if dialog is None:
            dialog = InformationDialog(self, key)
            dialogs[key] = dialog
            def finished(_result=0):
                if dialogs.get(key) is dialog:
                    dialogs.pop(key, None)
                dialog.deleteLater()
            dialog.finished.connect(finished)
        dialog.showNormal()
        dialog.raise_()
        dialog.activateWindow()
        return dialog

    def show_message(self, title, text, buttons=QMessageBox.StandardButton.Ok, default=QMessageBox.StandardButton.NoButton, *, on_finished=None, parent=None, compact_message=None, simple=False):
        title, text = _dyn(title), _dyn(text)
        dialog = InformationDialog(self, title=title, body=text)
        dialog.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        dialog.setProperty("message_literal", True)
        dialog.setProperty("message_plain", True)
        if compact_message is not None:
            dialog.use_compact_confirmation(*compact_message)
        elif simple:
            # Простое сообщение: без вкладок, «Скопировать всё», масштаба и кнопок окна - только крупный текст и «ОК».
            dialog.use_compact_confirmation(text, text, large=True)
        if parent is not None and parent is not self:
            dialog.setParent(parent, dialog.windowFlags())
        dialog.close_button.hide()
        button_box = QDialogButtonBox(QDialogButtonBox.StandardButton(int(buttons)))
        dialog.footer.insertWidget(2, button_box)
        labels = {QDialogButtonBox.StandardButton.Ok: ("ОК", "OK"),
                  QDialogButtonBox.StandardButton.Yes: ("Да", "Yes"),
                  QDialogButtonBox.StandardButton.No: ("Нет", "No"),
                  QDialogButtonBox.StandardButton.Cancel: ("Отмена", "Cancel")}
        for standard, texts in labels.items():
            button = button_box.button(standard)
            if button is not None:
                button.setProperty("message_button_texts", texts)
                button.setProperty("i18n_skip", True)
                button.setText(ui_text(*texts))
        button_box.clicked.connect(lambda button: dialog.done(button_box.standardButton(button).value))
        if default != QMessageBox.StandardButton.NoButton:
            button = button_box.button(QDialogButtonBox.StandardButton(int(default)))
            if button is not None:
                button.setDefault(True)
                button.setFocus()
        dialog.fit_content(initial=True)
        if on_finished is not None:
            def finished(result):
                if not getattr(self, "_closing", False):
                    on_finished(QMessageBox.StandardButton(result) if result else QMessageBox.StandardButton.Cancel)
            dialog.finished.connect(finished)
        dialog.update_language()
        dialog.show()
        return dialog


    def prompt_input(self, title, label, callback, *, mode="text", value="", choices=()):
        dialogs = getattr(self, "_input_dialogs", None)
        if dialogs is None:
            self._input_dialogs = dialogs = {}
        dialog = dialogs.get(title)
        if dialog is not None:
            dialog.showNormal(); dialog.raise_(); dialog.activateWindow()
            return dialog
        dialog = NopInputDialog(self, title, label, mode, value, choices)
        dialogs[title] = dialog
        def finished(result):
            dialogs.pop(title, None)
            if result == QDialog.DialogCode.Accepted and not self._closing:
                callback(dialog.value())
        dialog.finished.connect(finished)
        dialog.show()
        dialog.input.setFocus()
        return dialog

