    def update_converter_tools_label(self):
        tools = [("FFmpeg", find_converter_tool("ffmpeg.exe", "ffmpeg")),
                 ("Blender", find_converter_tool("blender.exe", "blender")),
                 ("LibreOffice", conversion_office_tool()),
                 ("Calibre", find_converter_tool("ebook-convert.exe", "ebook-convert")),
                 ("Inkscape", conversion_vector_tool())]
        self.converter_tools_label.setText(ui_text("Движки: ", "Engines: ") + " · ".join(f"{name} {'✓' if path else '—'}" for name, path in tools))
        self.converter_tools_label.setToolTip(ui_text(
            "✓ означает найденную программу. Возможности экспорта проверяются отдельно; совместимость входного файла проверяется при запуске.",
            "✓ means the program was found. Export capabilities are checked separately; input compatibility is checked when starting."))


