    def _apo_init(self):
        self.eq_scope = "system" if self.cfg.get("equalizer_scope") == "system" else "local"
        self._apo_endpoint = str(self.cfg.get("equalizer_apo_endpoint", ""))
        self._apo_directory = str(self.cfg.get("equalizer_apo_directory", ""))
        self._apo_linked = bool(self.cfg.get("equalizer_apo_linked", False))
        # Do not briefly enable local DSP before checking a connection left by a
        # previous run, especially when the user's settings were reset.
        self._apo_uncertain = self._apo_linked or os.name == "nt"
        self._apo_verified = False  # A previous session is not proof of today's audio path.
        self._apo_state = "setup" if self._apo_uncertain else "disconnected"
        self._apo_detail = ("Проверяется конфигурация APO…", "Checking APO configuration…") if self._apo_uncertain else ("", "")
        self._apo_install = None
        self._apo_endpoints = []
        self._apo_busy = False
        self._apo_dirty = False
        self._apo_blocked = False
        self._apo_testing = False
        self._apo_requested_local = False
        self._apo_bridge = NopApoBridge()
        self._apo_endpoint_name = str(self.cfg.get("equalizer_apo_endpoint_name", ""))
        self._apo_tool_process = None
        self._apo_tool_directory = None
        self._apo_tool_result = {}
        self._apo_tool_error = ""
        self._apo_tool_launching = False
        self._apo_tool_terminal_seen = False
        self._apo_tool_timer = QTimer(self)
        self._apo_tool_timer.setInterval(300)
        self._apo_tool_timer.timeout.connect(self._apo_poll_tool)
        self._apo_sync_timer = QTimer(self)
        self._apo_sync_timer.setSingleShot(True)
        self._apo_sync_timer.setInterval(650)
        self._apo_sync_timer.timeout.connect(self._apo_sync)
        self._apo_watch = QTimer(self)
        self._apo_watch.setInterval(20000)
        self._apo_watch.timeout.connect(self._apo_periodic_check)
        self._apo_watch.start()

    def _local_eq_enabled(self):
        return self.equalizer_enabled and self.eq_scope == "local" and not (self._apo_linked or self._apo_uncertain)

    def _apo_set_state(self, state, ru="", en=""):
        self._apo_state, self._apo_detail = state, (ru, en)
        self._apo_refresh_ui()

    def _apo_refresh_ui(self):
        if not hasattr(self, "eq_apo_status"):
            return
        names = {"disconnected": ("Не подключено", "Not connected"), "setup": ("Требуется настройка", "Setup required"),
                 "connected": ("Подключено", "Connected"), "error": ("Ошибка", "Error")}
        text = ui_text(*names[self._apo_state])
        detail = ui_text(*self._apo_detail)
        if self._apo_state == "error" and self._apo_tool_error:
            detail = self._apo_tool_error_text()
        self.eq_apo_status.setText(text + (" · " + detail if detail else ""))
        self.eq_apo_status.setToolTip(detail)
        self.eq_scope_combo.blockSignals(True)
        self.eq_scope_combo.setCurrentIndex(self.eq_scope_combo.findData(self.eq_scope))
        self.eq_scope_combo.blockSignals(False)
        system = self.eq_scope == "system"
        self.eq_apo_manage.setVisible(system or self._apo_linked or self._apo_uncertain)
        for widget in (self.eq_apo_devices, self.eq_apo_tool, self.eq_apo_actions_widget, self.eq_apo_status):
            widget.setVisible(system or self._apo_linked or self._apo_uncertain)
        for button in (self.eq_apo_connect, self.eq_apo_check, self.eq_apo_disconnect, self.eq_apo_restore, self.eq_apo_tool):
            button.setEnabled(not self._apo_busy and not self._apo_testing)
        self.eq_apo_tool.setEnabled(not self._apo_busy and not self._apo_testing and not self._apo_tool_launching
            and not (self._apo_tool_process is not None and self._apo_tool_process.poll() is None))
        self.eq_scope_combo.setEnabled(not self._apo_busy and not self._apo_testing)
        self.eq_apo_devices.setEnabled(not self._apo_busy and not self._apo_linked and not self._apo_uncertain)
        if self._apo_linked:
            self.eq_apo_connect.setEnabled(False)
        self.eq_apo_note.setText(ui_text(*names[self._apo_state]) + ui_text(" · APO: запас −15 дБ", " · APO: −15 dB headroom")
            if system else T("Звук обрабатывается через FFmpeg"))
        self.eq_apo_note.setToolTip(ui_text(
            "Изменения передаются только выбранному выходу. NOP не меняет маршрут воспроизведения Windows. Запас −15 дБ сохраняется при EQ ВЫКЛ; внутренний EQ отключён.",
            "Changes affect only the selected endpoint. NOP does not change Windows playback routing. The −15 dB headroom stays with EQ OFF; internal EQ is disabled.") if system else ui_text(
            "Обрабатывает звук плеера. Системный APO управляется отдельно в режиме «Всё устройство».",
            "Processes the player's audio. Control system APO separately in Entire device mode."))
        if system:
            self.eq_apo_note.setToolTip(detail + "\n" + self.eq_apo_note.toolTip())
        self.schedule_relayout()

    def _apo_discover(self):
        installation = nop_apo_installation()
        devices = nop_apo_devices(installation)
        snapshot = nop_apo_snapshot(installation["config"]) if installation else None
        return installation, devices, snapshot

    def _apo_begin(self, operation, spec=None, elevate=False, after=None):
        if self._apo_busy or getattr(self, "_closing", False):
            return
        self._apo_busy = True
        if operation == "connect":
            self._apo_uncertain = True
        self._apo_refresh_ui()
        directory = self._apo_directory
        callback = self._apo_discover if operation == "inspect" else lambda: self._apo_bridge.execute(directory, operation, spec, elevate)
        job = NopApoJob(callback, self)
        self._apo_job = job
        def finished():
            self._apo_busy = False
            result = job.result or {"ok": False, "error": "APO worker stopped"}
            job.deleteLater()
            if getattr(self, "_closing", False):
                return
            if not result["ok"]:
                self._apo_verified = False
                self._apo_blocked = True
                self._apo_testing = False
                if operation == "inspect":
                    self._apo_uncertain = True
                    self.update_equalizer_routing()
                message = str(result.get("error", ""))
                ru, separator, en = message.partition("\n")
                self._apo_set_state("error", ru, en if separator else ru)
                if result.get("permission") and operation != "inspect" and not elevate:
                    # This is separate from the connection/backup consent.
                    self.show_message("Equalizer APO", ui_text(
                        "Windows защищает файлы APO. Разрешить отдельному помощнику NOP изменить только запись NOP, её экспорт, состояние и резервную копию? Появится UAC. Помощник работает до закрытия NOP; права папок и реестр не изменяются.",
                        "Windows protects APO files. Allow a separate NOP helper to modify only NOP's entry, export, state and backup? UAC will appear. The helper lasts until NOP closes; folder permissions and the registry stay unchanged."),
                        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No,
                        on_finished=lambda answer: self._apo_begin(operation, spec, True, after) if answer == QMessageBox.StandardButton.Yes else self._apo_admin_declined())
                return
            if after:
                after(result["value"])
            self._apo_refresh_ui()
            if self._apo_dirty and not self._apo_blocked and not self._apo_testing:
                self._apo_sync_timer.start()
        job.finished.connect(finished)
        job.start()

    def _apo_admin_declined(self):
        self._apo_testing = False
        self._apo_requested_local = False
        self._apo_set_state("setup", "Доступ не разрешён. Последняя записанная конфигурация сохранена; синхронизация остановлена.",
                            "Access was declined. The last saved configuration remains; synchronization is stopped.")

    def _apo_apply_inspection(self, value):
        installation, devices, snapshot = value
        self._apo_install, self._apo_endpoints = installation, devices
        self.eq_apo_devices.blockSignals(True)
        self.eq_apo_devices.clear()
        for device in devices:
            self.eq_apo_devices.addItem(device["name"], device["id"])
            self.eq_apo_devices.setItemData(self.eq_apo_devices.count()-1, device["id"], Qt.ItemDataRole.ToolTipRole)
        self._apo_device_labels()
        if installation:
            self._apo_directory = installation["config"]
        self._apo_linked = bool(snapshot and snapshot["linked"])
        # Even a damaged Include might still process sound. Never fall back to local EQ.
        self._apo_uncertain = bool(snapshot and (snapshot["references"] or NOP_APO_BEGIN.encode() in snapshot["raw"]) and not self._apo_linked)
        if self._apo_linked:
            self._apo_endpoint = snapshot["state"]["endpoint"]
            self.eq_scope = "system"
        index = self.eq_apo_devices.findData(self._apo_endpoint)
        if index >= 0:
            self.eq_apo_devices.setCurrentIndex(index)
        elif not self._apo_linked and devices and not self._apo_endpoint:
            self._apo_endpoint = devices[0]["id"]
        else:
            self.eq_apo_devices.setCurrentIndex(-1)
        self.eq_apo_devices.blockSignals(False)
        self._apo_device_labels()
        device = next((d for d in devices if d["id"] == self._apo_endpoint), None)
        if not installation:
            self._apo_verified = False
            self._apo_set_state("setup" if self.eq_scope == "system" else "disconnected",
                "Equalizer APO не найден. Установите его самостоятельно по инструкции." if os.name == "nt" else "Системный EQ доступен только в Windows.",
                "Equalizer APO was not found. Install it yourself using the guide." if os.name == "nt" else "System EQ is available only on Windows.")
        elif self._apo_uncertain:
            self._apo_verified = False
            self._apo_set_state("error", "Запись NOP изменена. Проверьте config.txt; внутренний EQ заблокирован.",
                "NOP's entry has changed. Check config.txt; internal EQ is blocked.")
        elif self._apo_tool_error:
            self._apo_verified = False
            self._apo_set_state("error", self._apo_tool_error, self._apo_tool_error)
        elif self._apo_endpoint and not device:
            self._apo_verified = False
            self._apo_set_state("setup", "Выбранное устройство недоступно. Выберите выход Windows самостоятельно.",
                "The selected endpoint is unavailable. Select a Windows output manually.")
        elif not self._apo_linked:
            self._apo_verified = False
            self._apo_set_state("disconnected", "Выберите устройство и нажмите «Подключить».", "Select a device and click Connect.")
        elif not device or not device["bound"] or device["unknown"] or device["disabled"] or device["stage"] != snapshot["state"].get("stage"):
            self._apo_verified = False
            self._apo_set_state("setup", "Проверьте выбранное устройство, назначение APO, улучшения звука и перезапуск Windows.",
                "Check the selected endpoint, APO assignment, audio enhancements and restart Windows.")
        elif snapshot["export"] is None or hashlib.sha256(snapshot["export"]).hexdigest() != snapshot["state"].get("export_hash"):
            self._apo_verified = False
            self._apo_set_state("error", "Экспорт отсутствует или изменён извне. Отключите и подключите NOP заново.",
                "The export is missing or changed externally. Disconnect and reconnect NOP.")
        elif snapshot["state"].get("test_active"):
            self._apo_verified = False
            self._apo_dirty = True
            self._apo_set_state("setup", "Восстанавливается обычный уровень после незавершённой проверки звука.",
                "Restoring the normal level after an interrupted sound test.")
        else:
            # Include+COM registration cannot prove the driver's runtime DSP path.
            if self._apo_blocked:
                self._apo_set_state("setup", "Синхронизация остановлена. Для повторного запроса доступа нажмите «Проверить подключение».",
                    "Synchronization is stopped. Click Check connection to retry access.")
            else:
                self._apo_set_state("connected" if self._apo_verified else "setup",
                    "Файлы и привязка проверены; тест звука подтверждён пользователем." if self._apo_verified else "Файлы и привязка проверены. Нужна проверка звука.",
                    "Files and binding checked; the user confirmed the sound test." if self._apo_verified else "Files and binding checked. A sound test is required.")
                spec = self._apo_spec()
                expected = nop_apo_payload(spec["endpoint"], spec["frequencies"], spec["gains"], spec["enabled"], spec["stage"])
                if snapshot["export"] != expected:
                    self._apo_dirty = True
        self.update_equalizer_routing()
        self.save_settings()
        return bool(device and device["bound"] and not device["unknown"] and not device["disabled"]
                    and self._apo_linked and self._apo_state != "error" and not snapshot["state"].get("test_active")
                    and device["stage"] == snapshot["state"].get("stage"))

    def check_system_equalizer(self, _checked=False, sound=True):
        if self._apo_busy or self._apo_testing:
            return
        def checked(value):
            if sound:
                self._apo_tool_error = ""  # Explicit retry; still requires a fresh sound test.
            valid = self._apo_apply_inspection(value)
            if valid and sound and self._apo_blocked:
                self._apo_blocked = False
                self._apo_dirty = True
            if valid and sound:
                self._apo_offer_sound_test()
        self._apo_begin("inspect", after=checked)

    def _apo_periodic_check(self):
        if self._apo_busy or self._apo_testing or getattr(self, "_closing", False):
            return
        if self._apo_bridge.socket is not None:
            self._apo_begin("ping", after=lambda _result: self.check_system_equalizer(sound=False))
        elif self.eq_scope == "system" or self._apo_linked:
            self.check_system_equalizer(sound=False)

    def _apo_scope_changed(self):
        requested = self.eq_scope_combo.currentData()
        if requested == self.eq_scope:
            return
        if requested == "local" and (self._apo_linked or self._apo_uncertain):
            self._apo_requested_local = True
            self._apo_refresh_ui()
            self.disconnect_system_equalizer()
            return
        self.eq_scope = requested
        self._apo_verified = False
        self.update_equalizer_routing()
        self.save_settings()
        self._apo_refresh_ui()
        if requested == "system":
            self.show_system_equalizer_help()
            self.connect_system_equalizer()

    def _apo_device_changed(self):
        self._apo_endpoint = str(self.eq_apo_devices.currentData() or "")
        self._apo_verified = False
        self.save_settings()

    def _apo_spec(self, test=False):
        device = next((d for d in self._apo_endpoints if d["id"] == self._apo_endpoint), None)
        if not device:
            raise nop_apo_error("Выбранное устройство недоступно.", "The selected device is unavailable.")
        return {"endpoint": self._apo_endpoint, "stage": device["stage"], "enabled": self.equalizer_enabled,
                "frequencies": list(self.eq_frequencies), "gains": list(self.equalizer_values), "test": test}

    def connect_system_equalizer(self, _checked=False):
        if self._apo_busy or self._apo_testing:
            return
        self.eq_scope = "system"
        self.update_equalizer_routing()
        def discovered(value):
            self._apo_apply_inspection(value)
            if not self._apo_install:
                self.show_system_equalizer_help()
                return
            if self._apo_linked:
                self._apo_offer_sound_test()
                return
            if self._apo_uncertain:
                self.show_system_equalizer_help()
                return
            device = next((d for d in self._apo_endpoints if d["id"] == self._apo_endpoint), None)
            if device is None:
                self._apo_set_state("setup", "Нет активного устройства воспроизведения.", "No active playback endpoint.")
                return
            if not device["bound"] or device["unknown"] or device["disabled"]:
                self.open_apo_configurator()
                return
            spec = self._apo_spec()
            message = ui_text(
                f"Устройство: {device['name']}\n{device['id']}\nКаталог: {self._apo_directory}\n\nУменьшите громкость. Создать точную резервную копию config.txt и добавить отдельный блок NOP с Include: {NOP_APO_FILE}? Блок ограничен этим устройством. Настройки остальных устройств сохранятся. Внутренний EQ отключится. Запас громкости −15 дБ остаётся даже при EQ ВЫКЛ. Чужие фильтры продолжают работать. После записи потребуется проверить звук.",
                f"Device: {device['name']}\n{device['id']}\nFolder: {self._apo_directory}\n\nLower the volume. Create an exact config.txt backup and add a separate NOP block with Include: {NOP_APO_FILE}? It is restricted to this endpoint. Other endpoints keep their settings. Internal EQ will be disabled. The −15 dB headroom stays even with EQ OFF. Existing third-party filters remain active. A sound test is required after writing.")
            self.show_message("Equalizer APO", message, QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No, on_finished=lambda answer: self._apo_begin("connect", spec, after=self._apo_connected)
                if answer == QMessageBox.StandardButton.Yes else None)
        self._apo_begin("inspect", after=discovered)

    def _apo_connected(self, result):
        self._apo_linked = True
        self._apo_uncertain = False
        self._apo_blocked = False
        self._apo_verified = False
        self._apo_dirty = False
        self.update_equalizer_routing()
        self.save_settings()
        self._apo_set_state("setup", "Конфигурация записана. Проверьте подключение и звук.", "Configuration saved. Check connection and sound.")
        self.check_system_equalizer()

    def _apo_device_labels(self):
        qt_names = {}
        try:
            for endpoint in QMediaDevices.audioOutputs():
                ids = re.findall(r"\{[0-9a-fA-F-]{36}\}", bytes(endpoint.id()).decode("utf-8", errors="ignore"))
                description = endpoint.description().strip()
                if ids and description and not NOP_APO_GUID.fullmatch(description):
                    qt_names[ids[-1].lower()] = description
        except (RuntimeError, OSError):
            pass
        for index, device in enumerate(self._apo_endpoints):
            if not device.get("name") or device.get("_nop_generated_name"):
                name = qt_names.get(device["id"].lower())
                device["_nop_generated_name"] = not bool(name)
                device["name"] = name or ui_text(
                    f"Устройство воспроизведения {index+1} (имя недоступно)", f"Playback device {index+1} (name unavailable)")
            bound = ui_text("APO назначен", "APO assigned") if device["bound"] else ui_text("APO не назначен", "APO not assigned")
            if device["unknown"]:
                bound = ui_text("Привязка APO не проверена", "APO binding unverified")
            state = ui_text("Активно", "Active")
            if device["disabled"]:
                state += ui_text("; улучшения выключены", "; enhancements disabled")
            label = f"{device['name']} · {state} · {bound}"
            row = self.eq_apo_devices.findData(device["id"])
            if row >= 0:
                self.eq_apo_devices.setItemText(row, label)
                self.eq_apo_devices.setItemData(row, f"{device['name']}\nGUID: {device['id']}\n{state}\n{bound}", Qt.ItemDataRole.ToolTipRole)
        selected = next((d for d in self._apo_endpoints if d["id"] == self._apo_endpoint), None)
        if selected:
            self._apo_endpoint_name = selected["name"]

    def _apo_tool_instructions(self):
        name = next((d["name"] for d in self._apo_endpoints if d["id"] == self._apo_endpoint), self._apo_endpoint_name)
        return ui_text(
            f"Выбранное устройство: {name or 'не выбрано'}\nGUID (для диагностики): {self._apo_endpoint or '—'}\n\n"
            "В Configurator / Device Selector → Playback devices отметьте это устройство и нажмите OK. Для сверки имени: Win+R → mmsys.cpl → Воспроизведение. Другие отметки без необходимости не меняйте.\n"
            "При требовании инструмента перезапустите Windows. Затем в NOP нажмите «Проверить подключение» и проверьте звук. Улучшения звука должны быть включены; ASIO/WASAPI exclusive могут обходить APO.\n\n"
            "Если утилита не открывается: закройте NOP и запустите тот же EXE двойным щелчком из Проводника или меню Пуск → Equalizer APO. Если ошибка есть и там, она воспроизводится независимо от NOP: проверьте штатные файлы и зависимости вашей версии APO. Не копируйте DLL PyQt6 и не меняйте системные настройки наугад. Если отдельно EXE работает, а из NOP — нет, откройте «Диагностика запуска» и сравните журнал. Факт конфликта Qt устанавливается по диагностике, а не по одному сообщению о плагине.",
            f"Selected device: {name or 'not selected'}\nGUID (diagnostics): {self._apo_endpoint or '—'}\n\n"
            "In Configurator / Device Selector → Playback devices select this endpoint and click OK. Compare its name in Win+R → mmsys.cpl → Playback. Preserve unrelated selections.\n"
            "Restart Windows if requested, then click Check connection in NOP and test sound. Audio enhancements must be enabled; ASIO/WASAPI exclusive can bypass APO.\n\n"
            "If the tool fails: close NOP and double-click the same EXE in Explorer or use Start → Equalizer APO. A failure there reproduces independently of NOP: check the original files and dependencies for your APO version. Do not copy PyQt6 DLLs or change system settings blindly. If the EXE works separately but fails from NOP, open Launch diagnostics and compare the log. A Qt conflict requires diagnostic evidence; a platform-plugin message alone is insufficient.")

    def open_apo_configurator(self, _checked=False):
        if self._apo_busy or self._apo_testing or self._closing:
            return
        if self._apo_tool_launching or self._apo_tool_process is not None and self._apo_tool_process.poll() is None:
            self.show_apo_launch_diagnostics()
            return
        self._apo_verified = False
        self._apo_tool_error = ""
        self._apo_tool_result = {}
        self._apo_tool_terminal_seen = False
        self._apo_tool_directory = None
        installation = self._apo_install or nop_apo_installation()
        tool = installation.get("tool", "") if installation else ""
        if os.name != "nt" or not tool:
            self._apo_tool_result = {"state": "error", "tool": tool,
                "error_id": "tool_unavailable",
                "error": ui_text("Утилита APO не найдена или текущая ОС не Windows.", "APO tool not found, or this OS is not Windows.")}
            self._apo_tool_failure()
            return
        self._apo_tool_launching = True
        self._apo_set_state("setup", "Запускается утилита APO в отдельном окружении…", "Starting the APO tool in a separate environment…")
        roots = [str(APP_DIR), str(APP_DIR / "bin"), str(getattr(sys, "_MEIPASS", ""))]
        qt_module = sys.modules.get("PyQt6")
        if qt_module is not None and getattr(qt_module, "__file__", None):
            roots.append(str(Path(qt_module.__file__).parent))
        inherited = dict(os.environ)
        def start():
            directory = Path(tempfile.mkdtemp(prefix="apo-launch-", dir=str(DATA_DIR)))
            env, details = nop_apo_tool_environment(tool, inherited, roots, NOP_ORIGINAL_PATH)
            request = {"tool": str(Path(tool).resolve()), "excluded_roots": roots, "original_path": env.get("PATH", env.get("Path", "")),
                       "parent_environment_changes": details}
            path = directory / "request.json"
            _private_write(path, json.dumps(request, ensure_ascii=False).encode("utf-8"))
            args = ([] if FROZEN else [str(Path(__file__).resolve())]) + ["--nop-apo-tool", str(path)]
            if FROZEN:
                env["PYINSTALLER_RESET_ENVIRONMENT"] = "1"
            process = subprocess.Popen([sys.executable] + args, cwd=str(Path(tool).resolve().parent), env=env,
                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            return process, directory
        job = NopApoJob(start, self)
        self._apo_tool_job = job
        def started():
            self._apo_tool_launching = False
            result = job.result or {"ok": False, "error": "APO launch worker stopped"}
            job.deleteLater()
            if result["ok"]:
                self._apo_tool_process, self._apo_tool_directory = result["value"]
                self._apo_tool_started_at = time.monotonic()
                if not self._closing:
                    self._apo_tool_timer.start()
                    self._apo_refresh_ui()
                    self.show_apo_launch_diagnostics()
            elif not self._closing:
                self._apo_tool_result = {"state": "error", "tool": tool, "error": result.get("error", "")}
                self._apo_tool_failure()
        job.finished.connect(started)
        job.start()

    def _apo_poll_tool(self):
        directory, process = self._apo_tool_directory, self._apo_tool_process
        if directory is None or process is None:
            return
        try:
            path = directory / "status.json"
            if path.is_file() and path.stat().st_size <= 262144:
                self._apo_tool_result = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            pass  # The next timer tick retries; no busy waiting in the GUI.
        result = self._apo_tool_result
        terminal = result.get("state") in ("error", "exited")
        if not terminal and process.poll() is not None:
            result = dict(result, state="error", error=ui_text(
                "Помощник запуска завершился без результата; проверьте его журнал.",
                "The launcher exited without a result; check its log."))
            self._apo_tool_result = result
            terminal = True
        if terminal and not self._apo_tool_terminal_seen:
            self._apo_tool_terminal_seen = True
            code = result.get("exit_code")
            if result.get("state") == "error" or code != 0 or result.get("qt_platform_error") or result.get("qt_version_mismatch"):
                self._apo_tool_failure()
            else:
                self._apo_set_state("setup", "Утилита закрыта. Проверьте назначение, перезапуск Windows и звук.",
                    "The tool closed. Check assignment, Windows restart and sound.")
                self.check_system_equalizer(sound=False)
        if terminal and process.poll() is not None:
            self._apo_tool_timer.stop()
        self._apo_refresh_tool_diagnostics()
        self._apo_refresh_ui()

    def _apo_tool_error_text(self):
        result = self._apo_tool_result
        tool = str(result.get("tool") or (self._apo_install or {}).get("tool") or "")
        name = Path(tool).name if tool else "Device Selector / Configurator"
        error = str(result.get("error") or "")
        if result.get("error_id") == "tool_unavailable":
            error = ui_text("Утилита APO не найдена или текущая ОС не Windows.", "APO tool not found, or this OS is not Windows.")
        elif result.get("qt_version_mismatch"):
            error = ui_text("Журнал утилиты сообщает о несовместимой библиотеке Qt.", "The tool's log reports an incompatible Qt library.")
        elif result.get("qt_platform_error"):
            error = ui_text("Не удалось инициализировать Qt platform plugin; точную причину смотрите в журнале.",
                            "Qt platform-plugin initialization failed; see the log for the exact evidence.")
        elif result.get("winerror") == 1223:
            error = ui_text("Запрос UAC отменён.", "The UAC request was cancelled.")
        elif result.get("exit_code") is not None:
            code = result["exit_code"]
            error = ui_text(f"Код завершения: {code} (0x{code & 0xFFFFFFFF:08X}).", f"Exit code: {code} (0x{code & 0xFFFFFFFF:08X}).")
        return ui_text(f"Не удалось запустить {name}. {error}", f"Could not run {name}. {error}")

    def _apo_tool_failure(self):
        self._apo_verified = False
        self._apo_tool_error = self._apo_tool_error_text()
        self._apo_set_state("error", self._apo_tool_error, self._apo_tool_error)
        self.show_apo_launch_diagnostics()

    def show_apo_launch_diagnostics(self, _checked=False):
        dialog = getattr(self, "_apo_tool_dialog", None)
        created = dialog is None
        if dialog is None:
            dialog = InformationDialog(self, title="Диагностика запуска Equalizer APO", body="", details="")
            dialog.setProperty("message_literal", True)
            dialog.setProperty("message_plain", True)
            self._apo_tool_dialog = dialog
            def finished(_result):
                self._apo_tool_dialog = None
                dialog.deleteLater()
            dialog.finished.connect(finished)
        self._apo_refresh_tool_diagnostics()
        if created:
            dialog.update_language()
            dialog.fit_content(initial=True)
        dialog.showNormal(); dialog.raise_(); dialog.activateWindow()
        return dialog

    def _apo_refresh_tool_diagnostics(self):
        dialog = getattr(self, "_apo_tool_dialog", None)
        if dialog is None:
            return
        result = self._apo_tool_result
        statuses = {"starting": ("Запускается", "Starting"), "running": ("Процесс запущен; подключение ещё не проверено", "Process started; connection not verified"),
                    "awaiting_uac": ("Ожидается согласие UAC", "Waiting for UAC consent"), "exited": ("Процесс завершён", "Process exited"),
                    "error": ("Ошибка запуска", "Launch error")}
        state = ui_text(*statuses.get(result.get("state", "starting"), statuses["starting"]))
        directory = self._apo_tool_directory
        path = str(directory / "launch.log") if directory else ui_text("Журнал ещё не создан", "Log not created yet")
        dialog.message_body = (self._apo_tool_error_text() if self._apo_tool_error else state) + "\n\n" + self._apo_tool_instructions() + "\n\n" + ui_text("Журнал: ", "Log: ") + path
        log = ""
        if directory and (directory / "launch.log").is_file():
            try:
                with (directory / "launch.log").open("rb") as handle:
                    handle.seek(max(0, (directory / "launch.log").stat().st_size - 48000))
                    log = handle.read(48000).decode("utf-8", errors="replace")
            except OSError as exc:
                log = str(exc)
        dialog.message_details = json.dumps(result, ensure_ascii=False, indent=2) + "\n\n" + log
        # Updating diagnostics must not refit/recenter a window the user moved.
        dialog._fill_pages()


    def disconnect_system_equalizer(self, _checked=False, restore=False):
        if self._apo_busy or self._apo_testing:
            return
        self.show_message("Equalizer APO", ui_text(
            "Уменьшите громкость Windows перед отключением: запас −15 дБ будет снят. Удалить только блок подключения NOP? Правки других приложений и ваши последующие изменения сохранятся. APO останется назначенным устройству. Резервная копия сохраняется. Для смены устройства затем выберите другой выход и подключите NOP заново.",
            "Lower Windows volume before disconnecting: the −15 dB headroom will be removed. Remove only NOP's connection block? Other applications' settings and your later edits will be preserved. APO stays assigned to the endpoint. The backup is kept. To switch endpoints, select another output and connect NOP again."),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No,
            on_finished=lambda answer: self._apo_begin("restore" if restore else "disconnect", after=self._apo_disconnected)
            if answer == QMessageBox.StandardButton.Yes else self._apo_cancel_disconnect())

    def _apo_cancel_disconnect(self):
        self._apo_requested_local = False
        self._apo_refresh_ui()

    def _apo_disconnected(self, result):
        self._apo_sync_timer.stop()
        self._apo_linked = self._apo_uncertain = self._apo_verified = self._apo_dirty = False
        self._apo_blocked = False
        if self._apo_requested_local:
            self.eq_scope = "local"
            self._apo_requested_local = False
        self._apo_bridge.close()
        self.update_equalizer_routing()
        self.save_settings()
        self._apo_set_state("disconnected", "Блок NOP удалён; остальные настройки сохранены.", "NOP's block removed; other settings preserved.")

    def schedule_apo_sync(self):
        if self.eq_scope == "system" and self._apo_linked:
            self._apo_dirty = True
            if not self._apo_blocked and not self._apo_testing:
                self._apo_sync_timer.start()

    def _apo_sync(self):
        if self._apo_busy:
            self._apo_sync_timer.start()
            return
        if not self._apo_dirty or not self._apo_linked or self._apo_blocked or self._apo_testing:
            return
        try:
            spec = self._apo_spec()
        except RuntimeError as exc:
            self._apo_blocked = True
            self._apo_set_state("setup", str(exc), str(exc))
            return
        self._apo_dirty = False
        self._apo_begin("sync", spec, after=lambda _value: self._apo_set_state(
            "connected" if self._apo_verified else "setup", "Синхронизировано; запас −15 дБ.", "Synchronized; −15 dB headroom."))

    def _apo_offer_sound_test(self):
        if (self._apo_testing or not self._apo_linked or self._apo_state == "error" or self._apo_tool_launching
                or self._apo_tool_process is not None and self._apo_tool_process.poll() is None):
            return
        self.show_message("Equalizer APO", ui_text(
            "Включите негромкую музыку в другом приложении на выбранном устройстве в общем режиме. NOP временно уменьшит её громкость ещё на 12 дБ. Начать проверку? После ответа исходная конфигурация вернётся. Проверяется весь путь Windows; одного наличия файлов недостаточно.",
            "Play quiet music in another application on the selected endpoint in shared mode. NOP will temporarily attenuate it by another 12 dB. Start the test? The original configuration will return after your answer. This checks the Windows audio path; files alone are not proof."),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No,
            on_finished=lambda answer: self._apo_start_sound_test() if answer == QMessageBox.StandardButton.Yes else None)

    def _apo_start_sound_test(self):
        if (self._apo_busy or not self._apo_linked or self._apo_tool_launching or self._apo_tool_error
                or self._apo_tool_process is not None and self._apo_tool_process.poll() is None):
            return
        self._apo_testing = True
        self._apo_blocked = False
        self._apo_sync_timer.stop()
        self._apo_begin("sync", self._apo_spec(test=True), after=self._apo_ask_sound_result)

    def _apo_ask_sound_result(self, _result):
        self._apo_test_dialog = self.show_message("Equalizer APO", ui_text(
            "Звук другого приложения на выбранном устройстве стал заметно тише? После ответа NOP вернёт обычный уровень. Если эффекта нет, ответьте «Нет» и проверьте Configurator, перезапуск и общий режим вывода.",
            "Did the other application's sound on the selected endpoint become noticeably quieter? NOP will restore the normal level after your answer. If there was no effect, choose No and check Configurator, restart and shared output mode."),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No,
            on_finished=self._apo_finish_sound_test)
        # An unattended dialog must not leave persistent test attenuation.
        self._apo_test_timeout = QTimer(self._apo_test_dialog)
        self._apo_test_timeout.setSingleShot(True)
        self._apo_test_timeout.timeout.connect(self._apo_test_dialog.reject)
        self._apo_test_timeout.start(30000)

    def _apo_finish_sound_test(self, answer):
        self._apo_test_timeout.stop()
        self._apo_testing = False
        confirmed = answer == QMessageBox.StandardButton.Yes
        def restored(_result):
            self._apo_verified = confirmed
            self._apo_blocked = False
            self._apo_dirty = False
            self._apo_set_state("connected" if confirmed else "setup",
                "Звук подтверждён пользователем; синхронизация включена." if confirmed else "Звук не подтверждён. Проверьте Configurator, перезапуск и улучшения звука.",
                "The user confirmed audio processing; synchronization is enabled." if confirmed else "Sound was not confirmed. Check Configurator, restart and audio enhancements.")
        self._apo_begin("sync", self._apo_spec(), after=restored)


    def equalizer_apo_text(self):
        endpoint = self._apo_endpoint if NOP_APO_GUID.fullmatch(self._apo_endpoint) else "{00000000-0000-0000-0000-000000000000}"
        return nop_apo_payload(endpoint, self.eq_frequencies, self.equalizer_values,
                               self.equalizer_enabled).decode("utf-8")

    def export_equalizer_apo(self):
        return CnpFileDialog.choose(self, "Экспорт эквалайзера", str(DATA_DIR / "NOP_equalizer_export.txt"),
                                    "Equalizer APO (*.txt)", mode=QFileDialog.FileMode.AnyFile,
                                    accept=QFileDialog.AcceptMode.AcceptSave,
                                    callback=lambda paths: self._export_equalizer_apo(paths[0]) if paths else None)

    def _export_equalizer_apo(self, path):
        if path:
            try:
                if self._apo_directory and Path(path).resolve() == (Path(self._apo_directory) / NOP_APO_FILE).resolve():
                    raise nop_apo_error("Для папки APO используйте «Подключить» и автосинхронизацию. Ручной экспорт сохраните в другую папку.",
                                        "Use Connect and automatic synchronization in the APO folder. Save manual exports elsewhere.")
                _private_write(Path(path), self.equalizer_apo_text().encode("utf-8"))
            except (OSError, RuntimeError, ValueError) as exc:
                self.show_message("NOP", str(exc))

    def show_system_equalizer_help(self):
        dialog = self.open_information("system_eq")
        self._system_eq_dialog = dialog
        if not dialog.property("eqActionsInstalled"):
            dialog.setProperty("eqActionsInstalled", True)
            dialog.layout().itemAt(0).widget().layout().insertWidget(1, self.eq_apo_controls)
            self.eq_apo_controls.show()
            def detach_apo_controls(_result=0):
                self.eq_apo_controls.hide()
                self.eq_apo_controls.setParent(self)
            dialog.finished.connect(detach_apo_controls)
            actions = QHBoxLayout()
            dialog.layout().itemAt(0).widget().layout().insertLayout(2, actions)
            for name, label, slot in (("eqExport", "Экспорт эквалайзера", self.export_equalizer_apo),
                                      ("eqDisableLocal", "Выключить EQ NOP", lambda: self.set_equalizer_enabled(False))):
                button = QPushButton(T(label), dialog)
                button.setObjectName(name)
                button.setProperty("i18n_skip", True)
                actions.addWidget(button)
                button.clicked.connect(slot)
            dialog.close_button.setObjectName("eqHelpClose")
            dialog.finished.connect(lambda _result: setattr(self, "_system_eq_dialog", None))
            dialog.fit_content(initial=True)
        return dialog

    @staticmethod
    def format_frequency(freq: int) -> str:
        return f"{freq // 1000}k" if freq >= 1000 and freq % 1000 == 0 else str(freq)

    def delete_eq_preset(self):
        key = self.eq_preset.currentData()
        if not isinstance(key, str) or not key.startswith("user:"):
            self.show_message("Удаление пресета", "Выбери пользовательский пресет, чтобы удалить его.")
            return
        preset_key = key[5:]
        self.eq_custom_presets.pop(preset_key, None)
        self.equalizer_preset = "flat"
        self.rebuild_eq_preset_combo()
        self.eq_preset.setCurrentIndex(max(0, self.eq_preset.findData("flat")))
        self.apply_equalizer_preset()
        self.save_settings()

    def rebuild_eq_preset_combo(self):
        current = self.eq_preset.currentData()
        self.eq_preset.blockSignals(True)
        self.eq_preset.clear()
        for key, (label, _values) in EQ_PRESETS.items():
            self.eq_preset.addItem(label, key)
        for key, data in self.eq_custom_presets.items():
            if isinstance(data, dict):
                self.eq_preset.addItem(str(data.get("name", key)), "user:" + key)
        self.eq_preset.addItem("Пользовательский", "custom")
        idx = self.eq_preset.findData(current)
        self.eq_preset.setCurrentIndex(idx if idx >= 0 else 0)
        self.eq_preset.blockSignals(False)

    def save_eq_preset(self):
        return self.prompt_input("Сохранить эквалайзер", "Название пресета:", self._save_eq_preset)

    def _save_eq_preset(self, name):
        if not name.strip():
            return
        key = re.sub(r"[^a-zA-Zа-яА-Я0-9_-]+", "_", name.strip()).strip("_") or "custom"
        self.eq_custom_presets[key] = {
            "name": name.strip(),
            "values": list(self.equalizer_values),
            "frequencies": list(self.eq_frequencies),
        }
        idx = self.eq_preset.findData("user:" + key)
        if idx < 0:
            self.eq_preset.addItem(name.strip(), "user:" + key)
            idx = self.eq_preset.findData("user:" + key)
        else:
            self.eq_preset.setItemText(idx, name.strip())
        self.eq_preset.setCurrentIndex(idx)
        self.save_settings()

    def change_eq_frequency(self, index: int, new_frequency: int):
        if not (0 <= index < len(self.eq_frequencies)):
            return
        new_frequency = max(20, min(20000, int(new_frequency)))
        if new_frequency in self.eq_frequencies and self.eq_frequencies[index] != new_frequency:
            self.show_message("Частота уже существует", "У каждой полосы должна быть своя частота.")
            self.rebuild_eq_bands()
            return
        if self.eq_frequencies[index] == new_frequency:
            return
        pairs = list(zip(self.eq_frequencies, self.equalizer_values))
        pairs[index] = (new_frequency, pairs[index][1])
        pairs.sort(key=lambda item: item[0])
        self.eq_frequencies = [f for f, _ in pairs]
        self.equalizer_values = [v for _, v in pairs]
        self.rebuild_eq_bands()
        self.schedule_equalizer_restart()
        self.save_settings()

    def add_eq_frequency(self):
        return self.prompt_input("Добавить частоту", "Частота (Гц, 20–20000):", self._add_eq_frequency,
                                 mode="int", value=1000)

    def _add_eq_frequency(self, freq):
        if freq in self.eq_frequencies:
            return
        pairs = sorted(zip(self.eq_frequencies, self.equalizer_values) + []) if False else list(zip(self.eq_frequencies, self.equalizer_values))
        pairs.append((freq, 0)); pairs.sort()
        self.eq_frequencies = [f for f, _ in pairs]
        self.equalizer_values = [v for _, v in pairs]
        self.rebuild_eq_bands()
        self.schedule_equalizer_restart(); self.save_settings()

    def remove_eq_frequency(self):
        if len(self.eq_frequencies) <= 2:
            return
        return self.prompt_input("Убрать частоту", "Выберите частоту:", self._remove_eq_frequency, mode="choice",
                                 choices=[(f"{f} Hz", f) for f in self.eq_frequencies])

    def _remove_eq_frequency(self, frequency):
        # Other windows can change the bands while this selector is open.
        if frequency not in self.eq_frequencies or len(self.eq_frequencies) <= 2:
            return
        idx = self.eq_frequencies.index(frequency)
        self.eq_frequencies.pop(idx); self.equalizer_values.pop(idx)
        self.rebuild_eq_bands(); self.schedule_equalizer_restart(); self.save_settings()

    @staticmethod

    def _eq_spacer(height: int) -> QWidget:
        spacer = QWidget()
        spacer.setFixedHeight(height)
        return spacer

    def _eq_scale_column(self) -> QWidget:
        """Шкала децибел слева от полос: +12 / 0 / −12."""
        col = QWidget()
        col.setFixedWidth(26)
        lay = QVBoxLayout(col)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(3)
        lay.addWidget(self._eq_spacer(22))              # место под точное значение над ползунком
        scale = QWidget()
        scale.setFixedHeight(self.EQ_SLIDER_H)
        scale_lay = QVBoxLayout(scale)
        scale_lay.setContentsMargins(0, 0, 0, 0)
        scale_lay.setSpacing(0)
        for i, text in enumerate(("+12", "0", "−12")):
            lbl = QLabel(text)
            lbl.setObjectName("eqscale")
            lbl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            scale_lay.addWidget(lbl)
            if i < 2:
                scale_lay.addStretch(1)
        lay.addWidget(scale)
        lay.addWidget(self._eq_spacer(22))              # место под частоту под ползунком
        return col

    def _eq_band_column(self, i: int, freq: int) -> QWidget:
        col = QWidget()
        col.setFixedWidth(self.EQ_COL_W)
        lay = QVBoxLayout(col)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(1)
        value = WheelSafeDoubleSpinBox()
        value.setObjectName("eqgain")
        value.setLocale(QLocale("ru_RU"))  # показываем десятичную запятую: 0,00
        value.setDecimals(2)
        value.setRange(-12.00, 12.00)
        value.setSingleStep(0.01)
        value.setValue(round(float(self.equalizer_values[i]), 2))
        value.setAlignment(Qt.AlignmentFlag.AlignCenter)
        value.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons)
        value.setFixedSize(38, 22)
        value.setToolTip("Усиление этой полосы, дБ: от −12,00 до +12,00. Точность 0,01")
        slider = ResetSlider(0, Qt.Orientation.Vertical)      # двойной клик - в 0,00 дБ
        slider.setRange(-1200, 1200)
        slider.setValue(round(float(self.equalizer_values[i]) * 100))
        slider.setFixedSize(22, self.EQ_SLIDER_H)
        slider.setToolTip(f"{freq} Гц: от −12,00 до +12,00 дБ. Двойной клик - сбросить в 0,00")
        slider.valueChanged.connect(lambda v, idx=i, box=value: self.on_eq_slider_changed(idx, v, box))
        value.valueChanged.connect(lambda v, idx=i, sl=slider, box=value: self.on_eq_gain_spin_changed(idx, v, sl, box))
        spin = WheelSafeSpinBox()
        spin.setObjectName("eqfreq")
        spin.setRange(20, 20000)
        spin.setValue(int(freq))
        spin.setAlignment(Qt.AlignmentFlag.AlignCenter)
        spin.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons)
        spin.setFixedSize(38, 22)
        spin.setToolTip("Центральная частота полосы, Гц (можно изменить)")
        spin.editingFinished.connect(lambda idx=i, box=spin: self.change_eq_frequency(idx, box.value()))
        lay.addWidget(value, 0, Qt.AlignmentFlag.AlignHCenter)
        lay.addWidget(slider, 0, Qt.AlignmentFlag.AlignHCenter)
        lay.addWidget(spin)
        self.eq_sliders.append(slider)
        self.eq_value_labels.append(value)
        return col

    def rebuild_eq_bands(self):
        layout = self.eq_bands_layout
        while layout.count():
            item = layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.hide()
                widget.deleteLater()
        self.eq_sliders = []
        self.eq_value_labels = []
        layout.addWidget(self._eq_scale_column())
        for i, freq in enumerate(self.eq_frequencies):
            layout.addWidget(self._eq_band_column(i, int(freq)))
        if hasattr(self, "eq_toggle") and not self.equalizer_enabled:
            for slider in self.eq_sliders:
                slider.setEnabled(False)
            for value_box in self.eq_value_labels:
                value_box.setEnabled(False)
        self.eq_bands_content.updateGeometry()
        # При первой сборке equalizer_panel ещё не присвоена: build_equalizer_panel()
        # вызывает rebuild_eq_bands() до возврата готовой панели.
        panel = getattr(self, "equalizer_panel", None)
        if panel is not None:
            panel.updateGeometry()
        self.schedule_relayout()          # число полос изменилось - ширина панели тоже

    # ---------- цветокоррекция ----------
    COLOR_SECTION_TITLES = {"basic": "Основные", "creative": "Творческие", "vignette": "Виньетка"}
    COLOR_SECTION_OPEN = {"basic": False, "creative": False, "vignette": False}   # раскрыт только «Пресеты»
    COLOR_PANEL_WIDTH = 272

    def make_color_icon(self, key: str, params: dict) -> QIcon:
        """Миниатюра пресета: эталонная картинка (серая шкала + типичные цвета) с применённым пресетом."""
        icon = self._color_icon_cache.get(key)
        if icon is None:
            out = ColorGrade(params).process(make_color_reference())
            icon = QIcon(QPixmap.fromImage(rgb_to_qimage(out)))
            self._color_icon_cache[key] = icon
        return icon

    def build_color_panel(self):
        panel = QWidget()
        panel.setObjectName("panel")
        # Match the rounded, theme-aware frame used by the other docked panels.
        panel.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        panel.setFixedWidth(self.COLOR_PANEL_WIDTH)
        # Ширина фиксирована, высота - по месту в строке: панель не раздувает окно, лишнее прокручивается.
        panel.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Expanding)

        content = QWidget()
        content.setObjectName("clear")  # Let the panel's border/background show through.
        lay = QVBoxLayout(content)
        lay.setContentsMargins(8, 8, 8, 8)
        lay.setSpacing(6)

        # --- шапка: название, вкл/выкл, до/после ---
        title = ElidedLabel("Цветокоррекция")
        title.setObjectName("title")
        self.color_fx = QPushButton("ВКЛ" if self.color_enabled else "ВЫКЛ")
        self.color_fx.setObjectName("chip")
        self.color_fx.setCheckable(True)
        self.color_fx.setChecked(self.color_enabled)
        self.color_fx.setFixedSize(50, 26)
        self.color_fx.setToolTip("Включить / выключить цветокоррекцию")
        self.color_fx.clicked.connect(self.toggle_color_enabled)
        self.color_compare_btn = QPushButton("До")
        self.color_compare_btn.setObjectName("chip")
        self.color_compare_btn.setCheckable(True)
        self.color_compare_btn.setFixedSize(42, 26)
        self.color_compare_btn.setToolTip("Показать оригинал для сравнения (клавиша \\)")
        self.color_compare_btn.clicked.connect(self.toggle_color_compare)
        header = QHBoxLayout()
        header.setSpacing(6)
        header.addWidget(title, 1)
        header.addWidget(self.color_compare_btn)
        header.addWidget(self.color_fx)
        lay.addLayout(header)

        # --- пресеты ---
        presets = CollapsibleSection("Пресеты", True)
        amount_name = ElidedLabel("Количество")
        amount_name.setObjectName("muted")
        amount_name.setFixedWidth(84)
        self.color_amount_slider = ResetSlider(100, Qt.Orientation.Horizontal)
        self.color_amount_slider.setRange(0, 100)
        self.color_amount_slider.setValue(self.color_amount)
        self.color_amount_slider.setFixedHeight(16)
        self.color_amount_slider.setToolTip("Сила выбранного пресета (двойной клик - 100)")
        self.color_amount_value = QLabel(f"{self.color_amount}")
        self.color_amount_value.setObjectName("muted")
        self.color_amount_value.setFixedWidth(38)
        self.color_amount_value.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        self.color_amount_slider.valueChanged.connect(self.on_color_amount)
        amount_row = QHBoxLayout()
        amount_row.setSpacing(6)
        amount_row.addWidget(amount_name)
        amount_row.addWidget(self.color_amount_slider, 1)
        amount_row.addWidget(self.color_amount_value)
        presets.body_layout.addLayout(amount_row)

        self.color_state_lbl = ElidedLabel("")
        self.color_state_lbl.setObjectName("muted")
        presets.body_layout.addWidget(self.color_state_lbl)

        self.color_list = PresetListWidget()
        self.color_list.setFixedHeight(230)
        self.color_list.setIconSize(QSize(40, 25))
        self.color_list.setToolTip("Готовые пресеты (как в Adobe Lightroom / Premiere). Колесо или стрелки — листать, буква — перейти к пресету.")
        self.color_list.itemClicked.connect(self.on_color_item_clicked)
        self.color_list.picked.connect(self.on_color_item_clicked)
        presets.body_layout.addWidget(self.color_list)

        btn_row = QHBoxLayout()
        btn_row.setSpacing(6)
        for text, tip, slot in (
            ("Сохранить", "Сохранить текущие настройки как свой пресет", self.save_color_preset),
            ("Удалить", "Удалить выбранный свой пресет", self.delete_color_preset),
            ("Сброс", "Сбросить всю цветокоррекцию", self.reset_color),
        ):
            b = QPushButton(text)
            b.setObjectName("chip")
            b.setFixedHeight(26)
            b.setToolTip(tip)
            b.clicked.connect(slot)
            btn_row.addWidget(b)
        presets.body_layout.addLayout(btn_row)
        lay.addWidget(presets)

        # --- ползунки по разделам ---
        self.color_sliders: dict[str, ParamSlider] = {}
        sections = {}
        for key, label, lo, hi, default, section in COLOR_PARAMS:
            if section not in sections:
                sec = CollapsibleSection(self.COLOR_SECTION_TITLES[section], self.COLOR_SECTION_OPEN[section])
                sections[section] = sec
                lay.addWidget(sec)
            slider = ParamSlider(key, label, lo, hi, default)
            slider.setValue(self.color_params[key])
            slider.valueChanged.connect(self.on_color_slider)
            sections[section].body_layout.addWidget(slider)
            self.color_sliders[key] = slider
        lay.addStretch(1)

        # Аккордеон: раскрытие одного раздела сворачивает остальные - панель остаётся компактной.
        self.color_sections = [presets] + list(sections.values())
        for sec in self.color_sections:
            sec.toggled.connect(lambda expanded, s=sec: self.on_color_section_toggled(s, expanded))

        scroll = RowScrollArea(panel)
        scroll.setObjectName("colorSettingsScroll")
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.viewport().setObjectName("clear")
        scroll.viewport().setAutoFillBackground(False)
        scroll.setWidget(content)
        scroll.setStyleSheet('QScrollArea#colorSettingsScroll { background:transparent; border:none; }')
        self.color_scroll = scroll
        outer = QVBoxLayout(panel)
        # Inset the scroll viewport so it cannot paint over the rounded frame.
        outer.setContentsMargins(2, 2, 2, 2)
        outer.setSpacing(0)
        outer.addWidget(scroll)

        self.rebuild_color_list()
        self.update_color_state()
        return panel

    def on_color_section_toggled(self, section, expanded: bool):
        if expanded:
            for other in self.color_sections:
                if other is not section and other.header.isChecked():
                    other.header.setChecked(False)
        self.schedule_relayout()

    # --- список пресетов ---
    def _add_color_header(self, text: str):
        item = QListWidgetItem(T(text).upper())
        item.setFlags(Qt.ItemFlag.NoItemFlags)
        font = item.font()
        font.setBold(True)
        font.setPointSizeF(max(font.pointSizeF() - 1.5, 6.0))
        item.setFont(font)
        item.setForeground(QColor(ICON_MUTED))
        self.color_list.addItem(item)

    def _add_color_item(self, key: str, label: str, params: dict):
        item = QListWidgetItem(self.make_color_icon(key, params), label if key.startswith("user:") else T(label))
        item.setData(Qt.ItemDataRole.UserRole, key)
        self.color_list.addItem(item)

    def rebuild_color_list(self):
        self.color_list.blockSignals(True)
        self.color_list.clear()
        self._add_color_item("original", "Оригинал", dict(COLOR_NEUTRAL))
        for group, items in COLOR_PRESET_GROUPS:
            self._add_color_header(group)
            for key, label, params in items:
                self._add_color_item(key, label, params)
        if self.color_user_presets:
            self._add_color_header("Мои пресеты")
            for name in sorted(self.color_user_presets, key=str.lower):
                self._add_color_item("user:" + name, name, self.color_user_presets[name])
        self.color_list.blockSignals(False)
        self.sync_color_list_selection()

    def sync_color_list_selection(self):
        self.color_list.blockSignals(True)
        self.color_list.clearSelection()
        self.color_list.setCurrentRow(-1)
        for i in range(self.color_list.count()):
            item = self.color_list.item(i)
            if item.data(Qt.ItemDataRole.UserRole) == self.color_preset:
                self.color_list.setCurrentItem(item)
                self.color_list.scrollToItem(item)
                break
        self.color_list.blockSignals(False)

    def update_color_state(self):
        key = self.color_preset
        if key == "original":
            text = T("Оригинал")
        elif key == "custom":
            text = T("Свои настройки")
        elif key.startswith("user:"):
            text = f"{key[5:]} · {self.color_amount}%"
        else:
            text = f"{T(COLOR_PRESETS.get(key, ('?',))[0])} · {self.color_amount}%"
        self.color_state_lbl.setText(T("Текущий: ") + text)
        self.color_amount_slider.setEnabled(key not in ("original", "custom"))

    # --- действия ---
    def color_preset_params(self, key: str):
        if key == "original":
            return dict(COLOR_NEUTRAL)
        if key.startswith("user:"):
            params = self.color_user_presets.get(key[5:])
            return ColorGrade.normalize(params) if params is not None else None
        if key in COLOR_PRESETS:
            return COLOR_PRESETS[key][1]
        return None

    def apply_color_preset(self, key: str, save: bool = True):
        params = self.color_preset_params(key)
        if params is None:
            return
        self.color_preset = key
        self.color_params = dict(COLOR_NEUTRAL) if key == "original" else blend_color_preset(params, self.color_amount)
        for k, slider in self.color_sliders.items():
            slider.setValue(self.color_params[k])
        self.sync_color_list_selection()
        self.update_color_state()
        self.apply_color()
        if save:
            self.schedule_color_save()

    def on_color_item_clicked(self, item: QListWidgetItem):
        key = item.data(Qt.ItemDataRole.UserRole)
        if key:
            self.apply_color_preset(key)

    def on_color_amount(self, value: int):
        self.color_amount = int(value)
        self.color_amount_value.setText(str(value))
        if self.color_preset not in ("original", "custom"):
            self.apply_color_preset(self.color_preset)

    def on_color_slider(self, key: str, value: int):
        self.color_params[key] = int(value)
        if self.color_preset != "custom":
            self.color_preset = "custom"
            self.sync_color_list_selection()
            self.update_color_state()
        self.apply_color()
        self.schedule_color_save()

    def reset_color(self):
        self.color_amount = 100
        self.color_amount_slider.blockSignals(True)
        self.color_amount_slider.setValue(100)
        self.color_amount_slider.blockSignals(False)
        self.color_amount_value.setText("100")
        self.apply_color_preset("original")

    def save_color_preset(self):
        return self.prompt_input("Сохранить пресет", "Название пресета:", self._save_color_preset)

    def _save_color_preset(self, name):
        name = name.strip()[:40]
        if not name:
            return
        self.color_user_presets[name] = dict(self.color_params)
        self._color_icon_cache.pop("user:" + name, None)
        self.color_amount = 100                    # сохранённый пресет применяется ровно как записан
        self.color_amount_slider.blockSignals(True)
        self.color_amount_slider.setValue(100)
        self.color_amount_slider.blockSignals(False)
        self.color_amount_value.setText("100")
        self.color_preset = "user:" + name
        self.rebuild_color_list()
        self.update_color_state()
        self.save_settings()

    def delete_color_preset(self):
        if not self.color_preset.startswith("user:"):
            self.show_message("Удаление пресета",
                                    "Удалять можно только свои пресеты (группа «Мои пресеты»).")
            return
        name = self.color_preset[5:]
        self.color_user_presets.pop(name, None)
        self._color_icon_cache.pop("user:" + name, None)
        self.color_preset = "custom"
        self.rebuild_color_list()
        self.update_color_state()
        self.save_settings()

    def toggle_color_enabled(self, checked: bool):
        self.color_enabled = bool(checked)
        self.color_fx.setText("ВКЛ" if self.color_enabled else "ВЫКЛ")
        self.apply_color()
        self.schedule_color_save()

    def toggle_color_compare(self, checked: bool):
        self.color_compare = bool(checked)
        self.apply_color()

    def apply_color(self):
        """Передаёт текущие параметры видео-виджету (None = показывать оригинал)."""
        if not hasattr(self, "video"):
            return
        on = self.color_enabled and not self.color_compare
        params = self.color_params if on else None
        if self.player.active in ("ff", "mpv"):
            self.video.set_grade(None)
            self.player.set_color(params)
            # FFmpeg frames are QImages, so their vignette is painted into the image.
            # libmpv runs the same spatial effect as a GPU hook on the source texture;
            # this avoids the opaque/incorrectly composited HWND rectangle entirely.
            is_mpv = self.player.active == "mpv"
            self.video.set_vignette(params if not is_mpv else None)
            self.player.set_vignette(params if is_mpv else None)
        else:
            self.player.set_color(None)
            self.player.set_vignette(None)
            self.video.set_vignette(None)
            self.video.set_grade(params)

    def schedule_color_save(self):
        self._color_save_timer.start()

    def load_equalizer_values(self):
        for i, slider in enumerate(self.eq_sliders):
            gain = round(float(self.equalizer_values[i]), 2)
            slider.blockSignals(True)
            slider.setValue(round(gain * 100))
            slider.blockSignals(False)
            value_box = self.eq_value_labels[i]
            value_box.blockSignals(True)
            value_box.setValue(gain)
            value_box.blockSignals(False)

    def apply_equalizer_preset(self, _index=None):
        key = self.eq_preset.currentData()
        if key in EQ_PRESETS:
            source_values = list(EQ_PRESETS[key][1])
            source_frequencies = EQ_PRESET_FREQUENCIES
        elif isinstance(key, str) and key.startswith("user:") and key[5:] in self.eq_custom_presets:
            preset = self.eq_custom_presets[key[5:]]
            source_values = list(preset.get("values", []))
            source_frequencies = preset.get("frequencies")
        else:
            return
        # Старые версии сохраняли только gains. Пересчитываем их на текущие полосы,
        # вместо того чтобы оставлять массив из 10 значений при 21/31 полосах.
        self.equalizer_values = resample_eq_values(
            source_values, self.eq_frequencies, source_frequencies
        )
        self.equalizer_preset = key
        self.load_equalizer_values()
        self.schedule_equalizer_restart()
        self.save_settings()

    def _commit_eq_gain(self, index: int, value: float, slider: QSlider | None = None,
                        value_box: QDoubleSpinBox | None = None):
        gain = round(max(-12.0, min(12.0, float(value))), 2)
        if not (0 <= index < len(self.equalizer_values)):
            return
        self.equalizer_values[index] = gain
        scaled = round(gain * 100)
        if slider is not None and slider.value() != scaled:
            slider.blockSignals(True)
            slider.setValue(scaled)
            slider.blockSignals(False)
        if value_box is not None and abs(value_box.value() - gain) >= 0.005:
            value_box.blockSignals(True)
            value_box.setValue(gain)
            value_box.blockSignals(False)
        # Ручная настройка переводит профиль в пользовательский.
        self.equalizer_preset = "custom"
        self.schedule_equalizer_restart()
        if hasattr(self, "eq_preset"):
            self.eq_preset.blockSignals(True)
            self.eq_preset.setCurrentIndex(max(0, self.eq_preset.findData("custom")))
            self.eq_preset.blockSignals(False)
        if not hasattr(self, "_eq_save_timer"):
            self._eq_save_timer = QTimer(self)
            self._eq_save_timer.setSingleShot(True)
            self._eq_save_timer.setInterval(650)
            self._eq_save_timer.timeout.connect(self.save_settings)
        self._eq_save_timer.start()

    def on_eq_slider_changed(self, index: int, value: int, value_box: QDoubleSpinBox):
        self._commit_eq_gain(index, float(value) / 100.0, value_box=value_box)

    def on_eq_gain_spin_changed(self, index: int, value: float, slider: QSlider,
                                value_box: QDoubleSpinBox):
        self._commit_eq_gain(index, value, slider=slider, value_box=value_box)

    def set_equalizer_enabled(self, enabled: bool, save: bool = True):
        self.equalizer_enabled = bool(enabled)
        if hasattr(self, "eq_toggle"):
            self.eq_toggle.setChecked(self.equalizer_enabled)
            self.eq_toggle.setText(T("Эквалайзер включён" if self.equalizer_enabled else "Включить эквалайзер"))
            self.eq_preset.setEnabled(self.equalizer_enabled)
            for slider in self.eq_sliders:
                slider.setEnabled(self.equalizer_enabled)
            for value_box in self.eq_value_labels:
                value_box.setEnabled(self.equalizer_enabled)
        self.update_equalizer_routing()
        self.schedule_apo_sync()
        if save:
            self.save_settings()

    def on_ff_video_size(self, w: int, h: int):
        self.video.set_native_size(w, h)
        self.fit_to_video()

    def on_backend_changed(self, name: str):
        if getattr(self, "_closing", False):
            return
        has_video = bool(self.player.info and self.player.info.has_video)
        external = name == "ff" or (name == "mpv" and has_video)
        self.video.set_external(external)
        self.video.set_mpv_active(name == "mpv" and has_video)
        if external:
            # FFmpeg/mpv own the audio graph, so don't run the old parallel EQ stream.
            self._eq_restart_timer.stop()
            self.stop_equalizer_audio()
            self.sync_ff_equalizer()
        self.apply_color()
        self.fit_to_video()
        if self.current is not None and name in ("ff", "mpv"):
            suffix = "mpv" if name == "mpv" else "FFmpeg"
            info = self.player.info
            if name == "ff" and info is not None and info.has_video and (info.width >= 2560 or info.hdr) and self.player.mpv.load_error:
                suffix += " · запусти setup_mpv.bat"
            self._set_window_status(display_name(self.current) + f"  ·  {suffix}")

    def sync_ff_equalizer(self):
        self.player.set_equalizer(self._local_eq_enabled(), self.equalizer_values, self.eq_frequencies)

    def update_volume_ui(self, value: int):
        self.vol_icon.setPixmap(make_icon("mute" if value == 0 else "volume", ICON_MUTED).pixmap(16, 16))
        self.vol_pct.setText(f"{int(value)}%")

    def on_volume_changed(self, value: int):
        self.update_volume_ui(value)
        self.player.set_volume(value / 100)
        self.audio.setVolume(0.0 if self._local_eq_enabled() and self.player.active not in ("ff", "mpv") else value / 100)
        thread = self.eq_audio_thread
        if thread is not None and thread.isRunning():
            thread.set_volume(value / 100)

    def stop_equalizer_audio(self):
        thread = self.eq_audio_thread
        self.eq_audio_thread = None
        if thread is not None:
            thread.stop_audio()
            if thread.isRunning():
                thread.wait(1200)
        self.audio.setVolume(self.volume.value() / 100)

    def update_equalizer_routing(self):
        if not self._local_eq_enabled():
            self._eq_restart_timer.stop()
            self.stop_equalizer_audio()
        if self.player.active in ("ff", "mpv"):
            self._eq_restart_timer.stop()
            self.sync_ff_equalizer()
            return
        if self._local_eq_enabled():
            self.audio.setVolume(0.0)
            self.schedule_equalizer_restart(80)
        else:
            self._eq_restart_timer.stop()
            self.stop_equalizer_audio()

    def schedule_equalizer_restart(self, delay_ms: int = 250):
        self.schedule_apo_sync()
        if self._local_eq_enabled() and self.current is not None:
            self._eq_restart_timer.start(delay_ms)

    def restart_equalizer_audio(self):
        if self.player.active in ("ff", "mpv"):
            self.sync_ff_equalizer()
            return
        if not self._local_eq_enabled() or self.current is None:
            return
        state = self.player.playbackState()
        if state == QMediaPlayer.PlaybackState.StoppedState:
            return
        position = self.player.position()
        was_playing = state == QMediaPlayer.PlaybackState.PlayingState
        self.stop_equalizer_audio()
        self.audio.setVolume(0.0)
        thread = EqualizerAudioThread(
            self.current, position, self.equalizer_values,
            self.volume.value() / 100,
            frequencies=self.eq_frequencies, parent=self
        )
        thread.failed.connect(self.on_equalizer_error)
        self.eq_audio_thread = thread
        thread.finished.connect(lambda: _retire_audio(self, "eq_audio_thread", thread))
        thread.start()
        thread.set_paused(not was_playing)

    def on_equalizer_error(self, message: str):
        # Не оставляем звук полностью выключенным, если DSP не удалось запустить.
        self.audio.setVolume(self.volume.value() / 100)
        self.set_equalizer_enabled(False)
        self._set_window_status(f"NOP — ошибка эквалайзера: {message[:100]}")

    def set_equalizer_visible(self, visible: bool, save: bool = True):
        self.set_panel_visible("equalizer", visible, save)

    PROFILE_BUTTONS = (
        ("listen", "headphones", "Слушать: управление, перемотка, треки, эквалайзер"),
        ("download", "download", "Скачивать: управление, настройки и очередь загрузок"),
        ("all", "layout_all", "Всё: показать все панели"),
    )

    def build_panel_profiles(self) -> QWidget:
        """Верхняя панель профилей раскладки: кнопки-иконки как у боковой панели."""
        bar = QWidget()
        bar.setObjectName("panel")
        bar.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        row = QHBoxLayout(bar)
        row.setContentsMargins(8, 6, 8, 6)
        row.setSpacing(self.GAP)
        self._profile_icons = {}
        for key, icon, tip in self.PROFILE_BUTTONS:
            button = self.icon_button(
                icon, tip + "\nПовторное нажатие вернёт панели, которые были открыты до этого"
            )
            button.clicked.connect(lambda _=False, k=key: self.toggle_panel_profile(k))
            setattr(self, f"btn_profile_{key}", button)
            self._profile_icons[key] = icon
            row.addWidget(button)
        row.addStretch(1)
        self._sync_profile_buttons()
        return bar

    def build_tracks_panel(self) -> QWidget:
        panel = QWidget()
        panel.setObjectName("panel")
        screen = self.screen() or QApplication.primaryScreen()
        width = min(480, max(340, int(screen.availableGeometry().width() * .35))) if screen else 480
        panel.setFixedWidth(width)
        panel.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding)

        self.lbl_tracks = QLabel("Треки")
        self.lbl_tracks.setObjectName("title")
        self.lbl_tracks.setProperty("i18n_skip", True)

        # Поиск по имени и счётчик непосредственно над таблицей.
        self.track_search = QLineEdit()
        self.track_search.setPlaceholderText("Поиск трека…")
        self.track_search.setClearButtonEnabled(True)
        self.track_search.setToolTip("Поиск треков по названию; не меняет порядок списка")
        self.track_search.textChanged.connect(self.filter_track_list)

        self.track_count_label = QLabel()
        self.track_count_label.setProperty("i18n_skip", True)
        self.track_count_label.setObjectName("muted")

        self.playback_rate_combo = WheelSafeComboBox()
        for rate in (0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 1.75, 2.0, 4.0, 8.0):
            self.playback_rate_combo.addItem(f"{rate:g}×", rate)
        self.playback_rate_combo.setCurrentIndex(max(0, self.playback_rate_combo.findData(self.playback_rate)))
        self.playback_rate_combo.setToolTip("Скорость аудио и видео через mpv; Qt зависит от формата/системы, FFmpeg fallback не поддерживает")
        self.playback_rate_combo.currentIndexChanged.connect(self.on_playback_rate_changed)
        self.playback_rate_combo.setVisible(False)  # выбор скорости открывается из боковой панели
        self.update_playback_speed_button()

        self.track_list = TrackTable()
        self.track_list.setHorizontalHeaderLabels([T(x) for x in ("Имя", "Дата", "Размер", "Тип")])
        header = self.track_list.horizontalHeader()
        header.setSectionResizeMode(QHeaderView.ResizeMode.Interactive)
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        header.setMinimumSectionSize(40)
        widths = self.cfg.get("track_column_widths", [max(100, width-236), 95, 70, 45])
        if not isinstance(widths, list) or len(widths) != 4:
            widths = [max(100, width-236), 95, 70, 45]
        for col, size in enumerate(widths):
            self.track_list.setColumnWidth(col, max(40, min(2000, int(size))))
        self._track_sort_column = max(0, min(3, int(self.cfg.get("track_sort_column", 0))))
        self._track_sort_desc = bool(self.cfg.get("track_sort_desc", False))
        header.setSortIndicator(self._track_sort_column, Qt.SortOrder.DescendingOrder if self._track_sort_desc else Qt.SortOrder.AscendingOrder)
        self.track_list.setSortingEnabled(not bool(self.cfg.get("track_manual_sort", False)))
        header.setSortIndicatorShown(self.track_list.isSortingEnabled())
        header.sortIndicatorChanged.connect(self._track_header_sorted)
        header.sectionClicked.connect(self._track_header_clicked)
        self.track_list.reordered.connect(self._tracks_reordered)
        self.track_list.setObjectName("trackList")
        self.track_list.setToolTip("Двойной клик или Enter — играть выбранный трек; правая кнопка — действия с файлом")
        self.track_list.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Expanding)
        self.track_list.setMinimumHeight(90)
        self.track_list.itemActivated.connect(self.on_track_activated)
        self.track_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.track_list.customContextMenuRequested.connect(self.track_context_menu)
        # Визуальный блок «Воспроизведение также из» перенесён из clade;
        # обработчики и логика источников остаются из основного файла.
        lbl_src = ElidedLabel("Воспроизведение также из:")
        lbl_src.setObjectName("muted")
        lbl_src.setToolTip("Воспроизведение также из (отметьте папки, треки из которых нужно добавить в список)")
        self.src_list = QListWidget()
        self.src_list.setObjectName("sourceFolders")
        self.src_list.setFixedHeight(84)
        self.src_list.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.src_list.setTextElideMode(Qt.TextElideMode.ElideMiddle)
        self.src_list.setToolTip("Отметьте папки, треки из которых нужно добавить в список")
        self.src_list.itemChanged.connect(self.on_source_item_changed)
        self.btn_src_add = self.icon_button("plus", "Добавить другую папку с треками")
        self.btn_src_del = self.icon_button("minus", "Убрать папку из доступных источников")
        for b_ in (self.btn_src_add, self.btn_src_del):
            b_.setFixedSize(26, 26)
            b_.setIconSize(QSize(14, 14))
        self.btn_src_add.clicked.connect(self.add_source)
        self.btn_src_del.clicked.connect(self.remove_source)
        src_head = QHBoxLayout()
        src_head.setSpacing(4)
        src_head.addWidget(lbl_src, 1)
        src_head.addWidget(self.btn_src_add)
        src_head.addWidget(self.btn_src_del)
        self.rebuild_source_list()

        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(8)
        lay.addWidget(self.lbl_tracks)
        lay.addWidget(self.track_search)
        lay.addWidget(self.track_count_label)
        lay.addWidget(self.track_list, 1)
        lay.addLayout(src_head)
        lay.addWidget(self.src_list)
        self.set_playback_mode(self.playback_mode, save=False)
        self._refresh_track_metadata()
        self.filter_track_list()
        return panel

    def set_profile_bar_visible(self, visible: bool, save: bool = True):
        self._begin_panel_layout("profile")
        self.profile_bar_visible = bool(visible)
        self.profile_bar.setVisible(bool(visible))
        self.profile_handle.setIcon(make_icon("chev_u" if visible else "chev_d", ICON_MUTED))
        self.profile_handle.setToolTip(T("Скрыть панель раскладки" if visible else "Показать панель раскладки"))
        self._finish_panel_layout()
        if save:
            self.save_settings()

    def _panel_snapshot(self) -> dict:
        """Какие панели открыты прямо сейчас."""
        return {key: bool(getattr(self, self._panel_spec(key)[0])) for key in self.PANEL_KEYS}

    def _sync_profile_buttons(self):
        """Подсвечивает кнопку активного профиля так же, как кнопки боковой панели."""
        for key, icon, _tip in self.PROFILE_BUTTONS:
            button = getattr(self, f"btn_profile_{key}", None)
            if button is not None:
                self.tint(button, icon, key == self.panel_profile)

    def toggle_panel_profile(self, profile: str):
        """Первое нажатие включает профиль, повторное - возвращает панели, открытые до него."""
        if profile == self.panel_profile and self._profile_restore:
            snapshot = dict(self._profile_restore)
            self._profile_restore = None
            self._applying_panel_profile = True
            try:
                for key, visible in snapshot.items():
                    if key in self.PANEL_KEYS:
                        self.set_panel_visible(key, visible, save=False)
            finally:
                self._applying_panel_profile = False
                self._finish_panel_layout()
            self.panel_profile = "custom"
            self._sync_profile_buttons()
            self.save_settings()
            return
        self.apply_panel_profile(profile)

    def apply_panel_profile(self, profile: str):
        """Одним нажатием включает подходящий набор панелей."""
        profiles = {
            "listen": {
                "controls": True, "seek": True, "tracks": True, "equalizer": True,
                "color": False, "size": False, "downloads": False, "download_info": False,
                "converter": False, "transcode": False, "settings": False, "about": False,
            },
            "download": {
                "controls": True, "seek": False, "tracks": False, "equalizer": False,
                "color": False, "size": False, "downloads": True, "download_info": True,
                "converter": False, "transcode": False, "settings": False, "about": False,
            },
            "all": {
                "controls": True, "seek": True, "tracks": True, "equalizer": True,
                "color": True, "size": True, "downloads": True, "download_info": True,
                "converter": True, "transcode": True, "settings": False, "about": False,
            },
        }
        if profile not in profiles:
            return
        # Запоминаем раскладку до профиля только при выходе из «своей»; при переходе
        # профиль -> профиль сохраняется самый первый снимок.
        if self.panel_profile == "custom" or not self._profile_restore:
            self._profile_restore = self._panel_snapshot()
        self._applying_panel_profile = True
        try:
            for key, visible in profiles[profile].items():
                self.set_panel_visible(key, visible, save=False)
        finally:
            self._applying_panel_profile = False
            self._finish_panel_layout()
        self.panel_profile = profile
        self._sync_profile_buttons()
        self.save_settings()
        # После применения готового шаблона вернуть окно в центр экрана тем же
        # способом, что и Ctrl+M. Отложенный вызов нужен, чтобы Qt успел
        # пересчитать размеры и видимость всех панелей профиля.
        QTimer.singleShot(120, self.center_window)

    def show_playback_rate_menu(self, anchor=None):
        combo = getattr(self, "playback_rate_combo", None)
        if combo is None:
            return
        anchor = anchor if isinstance(anchor, QWidget) else self.btn_speed
        rate = self.playback_rate
        menu = QMenu(self)
        for i in range(combo.count()):
            value = float(combo.itemData(i))
            if not 0.25 <= value <= 8.0:
                continue
            action = menu.addAction(combo.itemText(i))
            action.setCheckable(True)
            action.setChecked(abs(value - rate) < 0.001)
            action.setData(i)
        chosen = menu.exec(anchor.mapToGlobal(QPoint(0, anchor.height())))
        if chosen is not None:
            combo.setCurrentIndex(int(chosen.data()))
        self.update_playback_speed_button()

    def update_playback_speed_button(self, button=None, rate=None):
        """Refresh the glyph-only speed indication."""
        button = button if button is not None else getattr(self, "btn_speed", None)
        if button is None:
            return
        rate = float(getattr(self, "playback_rate", 1.0) if rate is None else rate)
        active = abs(rate - 1.0) > 0.001
        was_on = bool(button.property("on"))
        button.setChecked(False)
        button.setProperty("on", False)
        # tint() uses white for ordinary rail glyphs in the two colored themes.
        # Their global ICON_COLOR equals ACCENT and cannot indicate a change.
        ordinary = ICON_COLOR if _THEME["name"] == "classic" else "#ffffff"
        button.setIcon(make_icon("speed", ACCENT if active else ordinary, 64))
        if was_on:
            button.style().unpolish(button)
            button.style().polish(button)
        button.update()
        button.setToolTip(f"{T('Скорость воспроизведения')}: {rate:g}×")

    def on_playback_rate_changed(self, _index=None):
        rate = self.playback_rate_combo.currentData()
        if rate is None:
            return
        self.playback_rate = float(rate)
        self.update_playback_speed_button()
        supported = self.player.set_playback_rate(self.playback_rate)
        if not supported:
            self.playback_rate_combo.setToolTip(
                "Текущий движок не подтвердил изменение скорости. Для скорости аудио и видео установи libmpv "
                "(setup_mpv.bat) и не запускай плеер с YAMI_BACKEND=qt/ff."
            )
        else:
            self.playback_rate_combo.setToolTip(
                f"Скорость воспроизведения: {self.playback_rate:g}× · движок {self.player.active}"
            )
        self.save_settings()

    def save_resume_position(self):
        if self.current is None or not self.cfg.get("remember_position", True):
            return
        try:
            pos = int(self.player.position())
            dur = int(self.player.duration())
        except Exception:
            return
        key = str(self.current.resolve())
        # Не возобновляем в самом конце, иначе короткий файл может сразу перескочить дальше.
        if dur > 0 and pos >= max(0, dur - 3000):
            self._resume_positions.pop(key, None)
        elif pos > 1000:
            self._resume_positions[key] = pos
        self.cfg["resume_positions"] = self._resume_positions
        self._last_resume_write = time.monotonic()
        self.save_settings()

    def filter_track_list(self, *_args):
        """Name search changes visibility, never media-library membership."""
        query = self.track_search.text().strip().casefold()
        visible = 0
        for row in range(self.track_list.rowCount()):
            item = self.track_list.item(row, 0)
            matches = not query or query in item.text().casefold()
            self.track_list.setRowHidden(row, not matches)
            visible += int(matches)
        active = bool(query)
        if self.track_search.property("filterActive") != active:
            self.track_search.setProperty("filterActive", active)
            self.track_search.style().unpolish(self.track_search)
            self.track_search.style().polish(self.track_search)
        self.track_count_label.setText(T("Показано")+f": {visible} / {self.track_list.rowCount()}")
        self.lbl_tracks.setText(f"{T('Треки')} ({self.track_list.rowCount()})")

    def _refresh_track_metadata(self):
        if not hasattr(self, "track_list"): return
        table = self.track_list
        # Formatting dates must not reorder rows halfway through this loop.
        sorting = table.isSortingEnabled()
        table.setSortingEnabled(False)
        table.setHorizontalHeaderLabels([T(x) for x in ("Имя", "Дата", "Размер", "Тип")])
        locale = QLocale("ru_RU" if LANG == "ru" else "en_US")
        for row in range(table.rowCount()):
            item = table.item(row, 1)
            if item is None: continue
            modified = item.data(int(Qt.ItemDataRole.UserRole)+1)
            size_item = table.item(row, 2)
            size_item.setText(self._track_size_text(size_item.data(int(Qt.ItemDataRole.UserRole)+1)))
            if modified is not None:
                item.setText(locale.toString(QDateTime.fromSecsSinceEpoch(int(modified)), "dd.MM.yyyy" if LANG == "ru" else "yyyy-MM-dd"))
        table.setSortingEnabled(sorting)
        table.horizontalHeader().setSortIndicatorShown(sorting)
        table.schedule_column_minima()
        self._refresh_bitrate_controls()

    def sort_track_list(self, *_args):
        if self.track_list.isSortingEnabled():
            self.track_list.sortItems(self._track_sort_column, Qt.SortOrder.DescendingOrder if self._track_sort_desc else Qt.SortOrder.AscendingOrder)
        self.filter_track_list()
        self.sync_track_selection()

    def _track_header_sorted(self, column, order):
        self._track_sort_column = column
        self._track_sort_desc = order == Qt.SortOrder.DescendingOrder
        self.cfg.update(track_sort_column=column, track_sort_desc=self._track_sort_desc, track_manual_sort=False)
        self.filter_track_list()
        self.sync_track_selection()

    def _track_header_clicked(self, column):
        if not self.track_list.isSortingEnabled():
            self.track_list.setSortingEnabled(True)
            self.track_list.horizontalHeader().setSortIndicatorShown(True)
            self.track_list.sortItems(column, Qt.SortOrder.AscendingOrder)
            self._track_header_sorted(column, Qt.SortOrder.AscendingOrder)

    def _tracks_reordered(self, paths):
        self.files = [Path(p) for p in paths]
        self._listed = list(paths)
        self.cfg.update(track_manual_order=list(paths), track_manual_sort=True)
        self.filter_track_list()
        self.save_settings()

    def _playback_tracks(self):
        return [Path(str(self.track_list.item(r, 0).data(Qt.ItemDataRole.UserRole)))
                for r in range(self.track_list.rowCount()) if not self.track_list.isRowHidden(r)]

    def show_track_properties(self, path: Path):
        """Открывает тематически оформленное окно свойств; анализ идёт в фоне."""
        path = Path(path)
        dialog = QDialog(self)
        dialog.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        dialog.setObjectName("filePropertiesDialog")
        dialog.setWindowFlags(Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        dialog.setWindowTitle("Свойства файла")
        # Компактный стартовый размер; при этом окно остаётся достаточно широким
        # для двух колонок и ограничивается доступной областью текущего экрана.
        screen = self.screen() or QApplication.primaryScreen()
        available = screen.availableGeometry() if screen is not None else None
        preferred_width = 760
        preferred_height = 600
        if available is not None:
            preferred_width = min(preferred_width, max(1, available.width() - 16))
            preferred_height = min(preferred_height, max(1, available.height() - 16))
        dialog.setMinimumSize(min(520, preferred_width), min(380, preferred_height))
        dialog.resize(preferred_width, preferred_height)
        dialog.setModal(False)
        dialog.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)

        window_layout = QVBoxLayout(dialog)
        window_layout.setContentsMargins(0, 0, 0, 0)
        window_layout.setSpacing(0)

        window_frame = QFrame(dialog)
        window_frame.setObjectName("filePropertiesWindowFrame")
        frame_layout = QVBoxLayout(window_frame)
        frame_layout.setContentsMargins(1, 1, 1, 1)
        frame_layout.setSpacing(0)
        window_layout.addWidget(window_frame)

        # Заголовок повторяет кастомную строку основного окна.
        title_bar = QFrame(window_frame)
        title_bar.setObjectName("windowTitleBar")
        title_bar.setFixedHeight(30)
        title_bar_layout = QHBoxLayout(title_bar)
        title_bar_layout.setContentsMargins(8, 1, 3, 1)
        title_bar_layout.setSpacing(4)
        title_label = QLabel("Свойства файла", title_bar)
        title_label.setObjectName("windowTitleLabel")
        title_bar_layout.addWidget(title_label, 1)
        minimize_button = QPushButton("—", title_bar)
        minimize_button.setObjectName("windowMinButton")
        minimize_button.setFixedSize(34, 26)
        minimize_button.setCursor(Qt.CursorShape.PointingHandCursor)
        minimize_button.setToolTip("Свернуть окно")
        minimize_button.clicked.connect(dialog.showMinimized)
        close_button = QPushButton("×", title_bar)
        close_button.setObjectName("windowCloseButton")
        close_button.setFixedSize(34, 26)
        close_button.setCursor(Qt.CursorShape.PointingHandCursor)
        close_button.setToolTip("Закрыть окно")
        close_button.clicked.connect(dialog.close)
        title_bar_layout.addWidget(minimize_button)
        title_bar_layout.addWidget(close_button)
        title_bar.installEventFilter(self)
        title_label.installEventFilter(self)
        frame_layout.addWidget(title_bar)

        body = QFrame(window_frame)
        body.setObjectName("filePropertiesBody")
        outer = QVBoxLayout(body)
        outer.setContentsMargins(14, 12, 14, 12)
        outer.setSpacing(9)
        frame_layout.addWidget(body, 1)

        file_title = QLabel(path.name)
        file_title.setObjectName("h1")
        file_title.setWordWrap(True)
        outer.addWidget(file_title)
        status = QLabel("Сбор подробных метаданных…")
        status.setObjectName("filePropertiesSubtitle")
        status.setWordWrap(True)
        outer.addWidget(status)

        # Выборы находятся непосредственно в окне свойств. Они меняют только
        # отображение уже собранных чисел и не запускают FFprobe/mutagen повторно.
        format_panel = QFrame(body)
        format_panel.setObjectName("filePropertiesSection")
        format_layout = QVBoxLayout(format_panel)
        format_layout.setContentsMargins(11, 8, 11, 9)
        format_layout.setSpacing(7)
        format_title = QLabel("Формат отображения", format_panel)
        format_title.setObjectName("filePropertiesSectionTitle")
        format_layout.addWidget(format_title)
        format_divider = QFrame(format_panel)
        format_divider.setObjectName("filePropertiesDivider")
        format_divider.setFrameShape(QFrame.Shape.HLine)
        format_divider.setFixedHeight(1)
        format_layout.addWidget(format_divider)
        selectors_layout = QGridLayout()
        selectors_layout.setContentsMargins(0, 0, 0, 0)
        selectors_layout.setHorizontalSpacing(10)
        selectors_layout.setVerticalSpacing(4)

        def make_format_selector(label_text, items, object_name):
            container = QWidget(format_panel)
            selector_layout = QVBoxLayout(container)
            selector_layout.setContentsMargins(0, 0, 0, 0)
            selector_layout.setSpacing(3)
            label = QLabel(label_text, container)
            label.setObjectName("muted")
            combo = QComboBox(container)
            combo.setObjectName(object_name)
            combo.setMinimumWidth(145)
            combo.setToolTip(f"Выберите способ отображения: {label_text.lower()}")
            for title, value in items:
                combo.addItem(title, value)
            selector_layout.addWidget(label)
            selector_layout.addWidget(combo)
            return container, combo

        duration_container, duration_format_combo = make_format_selector(
            "Длительность", [
                ("Автоматически", "auto"),
                ("Секунды", "seconds"),
                ("Минуты:секунды", "mmss"),
                ("Часы:минуты:секунды", "hhmmss"),
            ], "filePropertiesDurationFormat",
        )
        bitrate_container, bitrate_format_combo = make_format_selector(
            "Битрейт", [
                ("Автоматически", "auto"),
                ("бит/с", "bps"),
                ("кбит/с", "kbps"),
                ("Мбит/с", "mbps"),
                ("Гбит/с", "gbps"),
            ], "filePropertiesBitrateFormat",
        )
        filesize_container, filesize_format_combo = make_format_selector(
            "Размер файла", [
                ("Автоматически", "auto"),
                ("Байты", "bytes"),
                ("КБ", "kib"),
                ("МБ", "mib"),
                ("ГБ", "gib"),
                ("ТБ", "tib"),
            ], "filePropertiesFilesizeFormat",
        )
        selectors_layout.addWidget(duration_container, 0, 0)
        selectors_layout.addWidget(bitrate_container, 0, 1)
        selectors_layout.addWidget(filesize_container, 0, 2)
        selectors_layout.setColumnStretch(0, 1)
        selectors_layout.setColumnStretch(1, 1)
        selectors_layout.setColumnStretch(2, 1)
        format_layout.addLayout(selectors_layout)
        outer.addWidget(format_panel)

        scroll = QScrollArea(body)
        scroll.setObjectName("plain")
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        section_cards = []

        class ResponsivePropertiesContent(QWidget):
            """Контейнер карточек, перестраивающий сетку при изменении ширины."""
            def __init__(self, parent=None):
                super().__init__(parent)
                self.reflow_callback = None

            def resizeEvent(self, event):
                super().resizeEvent(event)
                callback = self.reflow_callback
                if callback is not None:
                    callback()

        content = ResponsivePropertiesContent()
        content_layout = QGridLayout(content)
        content_layout.setContentsMargins(2, 2, 7, 2)
        content_layout.setHorizontalSpacing(9)
        content_layout.setVerticalSpacing(9)
        content_layout.setColumnStretch(0, 1)
        content_layout.setColumnStretch(1, 1)
        scroll.setWidget(content)
        outer.addWidget(scroll, 1)

        def reflow_sections():
            """Две колонки при достаточной ширине, иначе одна без обрезания карточек."""
            if not section_cards:
                return
            # 2 * ~330 px на карточку + промежуток; порог учитывает DPI и поля.
            columns = 2 if content.width() >= 690 else 1
            while content_layout.count():
                item = content_layout.takeAt(0)
                # takeAt удаляет элемент из сетки, но оставляет карточку дочерним
                # виджетом контейнера, поэтому повторное размещение не теряет её видимость.
                _widget = item.widget()
            for index, card in enumerate(section_cards):
                row, column = divmod(index, columns)
                content_layout.addWidget(card, row, column, Qt.AlignmentFlag.AlignTop)
            content_layout.setColumnStretch(0, 1)
            content_layout.setColumnStretch(1, 1 if columns == 2 else 0)
            content.updateGeometry()

        content.reflow_callback = reflow_sections

        def format_value(value):
            return _format_file_property_value(
                value,
                duration_mode=duration_format_combo.currentData() or "auto",
                bitrate_mode=bitrate_format_combo.currentData() or "auto",
                filesize_mode=filesize_format_combo.currentData() or "auto",
            )

        def add_section(section_title, rows):
            """Добавляет только непустую группу полей с заголовком и разделителем."""
            visible_rows = [
                (str(label), value) for label, value in (rows or [])
                if value is not None and value != ""
            ]
            if not visible_rows:
                return False

            section = QFrame(content)
            section.setObjectName("filePropertiesSection")
            section_layout = QVBoxLayout(section)
            section_layout.setContentsMargins(11, 9, 11, 10)
            section_layout.setSpacing(7)

            heading = QLabel(str(section_title), section)
            heading.setObjectName("filePropertiesSectionTitle")
            heading.setWordWrap(True)
            section_layout.addWidget(heading)
            divider = QFrame(section)
            divider.setObjectName("filePropertiesDivider")
            divider.setFrameShape(QFrame.Shape.HLine)
            divider.setFixedHeight(1)
            section_layout.addWidget(divider)

            form = QFormLayout()
            form.setContentsMargins(0, 1, 0, 0)
            form.setHorizontalSpacing(18)
            form.setVerticalSpacing(6)
            form.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow)
            form.setLabelAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop)
            for label, value in visible_rows:
                key_label = QLabel(f"{label}:", section)
                key_label.setObjectName("muted")
                key_label.setMinimumWidth(120)
                key_label.setWordWrap(True)
                value_label = QLabel(format_value(value), section)
                value_label.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
                value_label.setWordWrap(True)
                value_label.setTextFormat(Qt.TextFormat.PlainText)
                form.addRow(key_label, value_label)
            section_layout.addLayout(form)
            section.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Maximum)
            section_cards.append(section)
            reflow_sections()
            return True

        def clear_content():
            while content_layout.count():
                item = content_layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.setParent(None)
            for card in section_cards:
                card.deleteLater()
            section_cards.clear()

        # Основные свойства доступны сразу, не дожидаясь анализа потоков.
        try:
            if path.is_file():
                st = path.stat()
                add_section("Общие сведения", [
                    ("Имя", path.name),
                    ("Полный путь", str(path.resolve(strict=False))),
                    ("Расширение", path.suffix or "Без расширения"),
                    ("Размер", _property_measure("filesize", st.st_size)),
                    ("Изменён", datetime.datetime.fromtimestamp(st.st_mtime).astimezone().strftime("%d.%m.%Y %H:%M:%S")),
                    ("MIME-тип по расширению", mimetypes.guess_type(str(path), strict=False)[0] or "Неизвестно"),
                ])
            else:
                add_section("Состояние", [("Файл", "Отсутствует или был перемещён")])
        except OSError as exc:
            add_section("Состояние", [("Ошибка чтения", str(exc))])

        actions = QHBoxLayout()
        actions.addStretch(1)
        close_footer = QPushButton("Закрыть")
        close_footer.clicked.connect(dialog.close)
        actions.addWidget(close_footer)
        outer.addLayout(actions)

        # Синхронизируем заголовок с палитрой активной темы прямо при открытии.
        title_bg = _THEME.get("bg", "#151923")
        title_border = _THEME.get("border", "#303747")
        title_fg = _THEME.get("fg", "#e9edf5")
        title_bar.setStyleSheet(
            f"QFrame#windowTitleBar {{ background:{title_bg}; border-bottom:1px solid {title_bg}; }}"
            f"QLabel#windowTitleLabel {{ color:{title_fg}; background:transparent; font-weight:600; }}"
            f"QPushButton#windowMinButton {{ background:transparent; color:{title_fg}; border:0; border-radius:5px; font-size:16px; }}"
            f"QPushButton#windowMinButton:hover {{ background:{title_border}; }}"
            "QPushButton#windowCloseButton { background:transparent; color:#ffffff; border:0; border-radius:5px; font-size:20px; }"
            "QPushButton#windowCloseButton:hover { background:#d93658; }"
        )

        signals = FilePropertiesSignals(dialog)
        dialog._file_properties_signals = signals
        current_metadata = None

        def render_metadata():
            """Перерисовывает только видимые значения из кеша метаданных."""
            if current_metadata is None:
                return
            clear_content()
            data = current_metadata
            if data.get("error"):
                add_section("Состояние", [("Результат", data["error"])])
            else:
                for section_title, rows in data.get("sections", []):
                    add_section(section_title, rows)
                for i, warning in enumerate(data.get("warnings", []), 1):
                    add_section(f"Предупреждение {i}", [("Информация", warning)])
                if not section_cards:
                    add_section("Состояние анализа", [("Результат", "Метаданные не найдены.")])
            reflow_sections()

        def apply_metadata(data):
            # Результат анализа кэшируется. Смена единиц ниже не запускает анализ заново.
            nonlocal current_metadata
            current_metadata = data
            status.hide()
            render_metadata()

        duration_format_combo.currentIndexChanged.connect(lambda _index: render_metadata())
        bitrate_format_combo.currentIndexChanged.connect(lambda _index: render_metadata())
        filesize_format_combo.currentIndexChanged.connect(lambda _index: render_metadata())
        signals.completed.connect(apply_metadata)

        probe_cancel = threading.Event()
        dialog.finished.connect(lambda _result: probe_cancel.set())
        def worker():
            _PROBE_CONTEXT.cancel_event = probe_cancel
            try:
                data = collect_file_properties(path)
            except Exception as exc:
                data = {"error": f"Непредвиденная ошибка анализа: {exc}"}
            if probe_cancel.is_set():
                return
            try:
                signals.completed.emit(data)
            except RuntimeError:
                # Окно могло быть закрыто до окончания фонового анализа.
                pass

        thread = threading.Thread(target=worker, name="FilePropertiesProbe", daemon=True)
        dialog._file_properties_thread = thread
        self._property_threads = [t for t in getattr(self, "_property_threads", []) if t.is_alive()]
        self._property_threads.append(thread)
        thread.start()
        self._track_properties_dialogs = getattr(self, "_track_properties_dialogs", [])
        self._track_properties_dialogs.append(dialog)
        dialog.finished.connect(lambda _=0, d=dialog: self._track_properties_dialogs.remove(d) if d in self._track_properties_dialogs else None)
        dialog._chrome = AuxiliaryChrome(dialog, title_bar, title_label, maximizable=False)
        dialog.show()

    @staticmethod
    def _format_file_size(size: int) -> str:
        value = float(size)
        for unit in ("Б", "КБ", "МБ", "ГБ", "ТБ"):
            if value < 1024 or unit == "ТБ":
                return f"{value:.0f} {unit}" if unit == "Б" else f"{value:.1f} {unit}"
            value /= 1024

    def track_context_menu(self, position):
        item = self.track_list.itemAt(position)
        if item is None:
            return
        raw_path = item.data(Qt.ItemDataRole.UserRole)
        path = Path(str(raw_path)) if raw_path else None
        if path is None or not path.exists():
            return
        menu = QMenu(self.window())
        menu.addAction("Свойства", lambda p=path: self.show_track_properties(p))
        menu.addSeparator()
        menu.addAction("Открыть папку с файлом", lambda: self.open_file_folder(path))
        menu.addAction("Переименовать", lambda: self.rename_track(path))
        menu.addAction("Удалить файл…", lambda: self.delete_track(path))
        menu.addSeparator()
        menu.addAction("Скопировать ссылку / путь", lambda: self.copy_track_link(path))
        menu.exec(self.track_list.viewport().mapToGlobal(position))

    def copy_track_link(self, path: Path):
        parsed = parse_name(path.stem)
        if parsed:
            QApplication.clipboard().setText(f"https://www.youtube.com/watch?v={parsed[1]}")
        else:
            QApplication.clipboard().setText(QUrl.fromLocalFile(str(path)).toString())

    def open_file_folder(self, path: Path):
        try:
            if os.name == "nt":
                os.startfile(str(path.parent))
            else:
                subprocess.Popen(["xdg-open", str(path.parent)])
        except (OSError, AttributeError) as exc:
            self.show_message("NOP", f"Не удалось открыть папку:\n{exc}")

    def rename_track(self, path: Path):
        return self.prompt_input("Переименовать файл", "Новое имя:", lambda name: self._rename_track(path, name),
                                 value=path.stem)

    def _rename_track(self, path: Path, new_name):
        new_name = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", new_name).strip(" .")
        if not new_name or new_name == path.stem:
            return
        target = path.with_name(new_name + path.suffix)
        if target.exists():
            self.show_message("NOP", "Файл с таким именем уже существует.")
            return
        try:
            was_current = self.current == path
            resume_pos = int(self.player.position()) if was_current else 0
            old_resume_key = str(path.resolve())
            if was_current:
                self.player.stop()
            path.rename(target)
            if was_current:
                self.current = target
                self._resume_positions.pop(old_resume_key, None)
                if resume_pos > 1000:
                    self._resume_positions[str(target.resolve())] = resume_pos
            self.refresh_files()
            if was_current:
                self.play_file(target)
                if resume_pos > 1000:
                    QTimer.singleShot(500, lambda p=resume_pos: self.player.setPosition(p) if self.current == target else None)
        except OSError as exc:
            self.show_message("NOP", f"Не удалось переименовать файл:\n{exc}")

    def delete_track(self, path: Path):
        if not self.cfg.get("confirm_delete", True):
            return self._delete_track(path)
        confirmation_ru = "Вы уверены, что хотите удалить этот файл?\nЭто действие нельзя отменить."
        confirmation_en = "Are you sure you want to delete this file?\nThis action cannot be undone."
        return self.show_message("Удалить файл?", ui_text(confirmation_ru, confirmation_en),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No,
            on_finished=lambda answer: self._delete_track(path) if answer == QMessageBox.StandardButton.Yes else None,
            compact_message=(confirmation_ru, confirmation_en))

    def _delete_track(self, path: Path):
        try:
            if self.current == path:
                self.player.stop()
                self.current = None
            path.unlink()
            self._resume_positions.pop(str(path.resolve()), None)
            self.refresh_files()
        except OSError as exc:
            self.show_message("NOP", f"Не удалось удалить файл:\\n{exc}")

    # ---------- окно ----------
    # ---------- единая логика раскладки окна и панелей ----------

    def adjust_window_size(self):
        """Совместимость: любое изменение панелей / режима сводится к одному пересчёту."""
        self.schedule_relayout()

    def schedule_relayout(self):
        if getattr(self, "_closing", False):
            return
        """Coalesce content changes; panel actions themselves remain atomic."""
        if (getattr(self, '_layout_busy', False) or getattr(self, '_applying_panel_profile', False) or getattr(self, '_video_only_snapshot', None) is not None or (getattr(self, '_video_fullscreen_window', None) is not None)):
            return
        if not self._relayout_timer.isActive():
            self._relayout_timer.start(0)

    def _suspend_panel_layouts(self):
        if getattr(self, "_suspended_panel_layouts", None) is not None:
            return
        # Only suspend the structural containers that can move the video.
        # Tool internals, item views and standalone dialogs keep their own layouts.
        layouts = [self.layout()]
        for name in ("content_row", "main_content", "video_col", "video_area", "profile_row",
                     "side_slot", "side_widgets_row", "lower_w", "right_col"):
            widget = getattr(self, name, None)
            if widget is not None:
                layouts.append(widget.layout())
        layouts.extend(getattr(self, name, None) for name in ("top_layout", "left_layout", "bottom_layout"))
        if hasattr(self, "work_area"):
            layouts.append(self.work_area.layout())
        suspended, seen = [], set()
        for layout in layouts:
            if layout is not None and id(layout) not in seen:
                seen.add(id(layout))
                if layout.isEnabled():
                    layout.setEnabled(False)
                    suspended.append(layout)
        self._suspended_panel_layouts = suspended

    def _resume_panel_layouts(self):
        layouts = getattr(self, "_suspended_panel_layouts", None)
        if layouts is None:
            return
        self._suspended_panel_layouts = None
        for layout in reversed(layouts):
            layout.setEnabled(True)

    def _begin_panel_layout(self, key):
        """Stop intermediate layout activation, never painting or video output."""
        if (not self.isVisible() or self.layout() is None or getattr(self, '_layout_busy', False)):
            return
        self._panel_change_depth = getattr(self, "_panel_change_depth", 0) + 1
        self._suspend_panel_layouts()
        if not self._is_fullscreen_layout():
            if getattr(self, "_panel_video_anchor", None) is None:
                actual = self._video_layout_anchor()
                preferred = getattr(self, "_preferred_video_anchor", actual)
                self._panel_video_anchor = (preferred if actual == getattr(self, "_last_layout_video_anchor", None)
                                            else actual)
            self._panel_layout_key = key
        self.layout().setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
        self.setMinimumSize(0, 0)
        self.setMaximumSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX)

    def _finish_panel_layout(self):
        depth = max(0, getattr(self, "_panel_change_depth", 0) - 1)
        self._panel_change_depth = depth
        if depth or getattr(self, "_applying_panel_profile", False):
            return
        if self.isVisible():
            self.relayout()
        else:
            self.schedule_relayout()

    def _sync_video_control_gaps(self):
        # A QSpacerItem remains in the layout when its neighboring control hides.
        # Keep only gaps belonging to visible rows below the video.
        for index in range(self.left_layout.count() - 1):
            spacer = self.left_layout.itemAt(index).spacerItem()
            following = self.left_layout.itemAt(index + 1).widget()
            if spacer is not None and following is not None:
                spacer.changeSize(0, 0 if following.isHidden() else 6,
                                  QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Fixed)

    def _sync_rounded_window(self):
        if getattr(self, "_closing", False):
            return
        wide = self.isMaximized() or self.isFullScreen() or bool(getattr(self, "_fullscreen_layout_active", False))
        key = (self.width(), self.height(), wide, self.devicePixelRatioF())
        if key != getattr(self, "_window_rounding_key", None):
            self._window_rounding_key = key
            if wide:
                self.clearMask()
            else:
                self.setMask(rounded_widget_region(self.size(), WINDOW_CORNER_RADIUS))
        video = getattr(self, "video", None)
        if video is not None:
            video.sync_mpv_surfaces()

    def showEvent(self, event):
        super().showEvent(event)
        self._sync_rounded_window()

    def changeEvent(self, event):
        super().changeEvent(event)
        if event.type() == QEvent.Type.WindowStateChange:
            self._sync_rounded_window()
            if event.oldState() & Qt.WindowState.WindowMinimized and not self.isMinimized():
                fullscreen = getattr(self, "_video_fullscreen_window", None)
                if fullscreen is not None and fullscreen.isMinimized():
                    fullscreen.showFullScreen()
                    fullscreen.show_controls()


    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._sync_rounded_window()
        if (self.isVisible() and hasattr(self, 'interface_scroll') and (not getattr(self, '_layout_busy', False)) and (not getattr(self, '_panel_change_depth', 0)) and (not self._is_fullscreen_layout()) and (not self.isMaximized()) and (getattr(self, '_video_only_snapshot', None) is None) and (getattr(self, '_last_panel_window_size', None) is not None)):
            # A user's smaller window limits the viewport, never the panels.
            self._window_size_limit = event.size()
            self.schedule_relayout()


    def relayout(self):
        if getattr(self, "_closing", False):
            return
        if getattr(self, "_layout_busy", False):
            return
        if getattr(self, "_video_fullscreen_window", None) is not None:
            # The same video is temporarily in the fullscreen window. Keep the
            # underlying canvas intact until exit_video_fullscreen returns it.
            self._resume_panel_layouts()
            return
        if getattr(self, "_video_only_snapshot", None) is not None:
            self._resume_panel_layouts()
            self._panel_video_anchor = None
            self._panel_layout_key = None
            return
        if not hasattr(self, "interface_scroll"):
            return
        self._layout_busy = True
        focused = QApplication.focusWidget()
        try:
            self._relayout_timer.stop()
            self._suspend_panel_layouts()
            self.right_col.setVisible(self.equalizer_visible or self.converter_visible)
            self.lower_w.setVisible(self.downloads_visible or self.equalizer_visible or self.converter_visible)
            self._sync_video_control_gaps()
            self._adapt_panel_widths_to_screen()
            full = self._is_fullscreen_layout() or self.isMaximized()
            request = (self.size_mode, *self.video_target_size())
            if not full and request != getattr(self, "_last_video_layout_request", None):
                self.fit_video_to_screen()
            self._last_video_layout_request = request
            self._sync_video_area_to_video()
            self._sync_sidebar_height_to_video()
            anchor = getattr(self, "_panel_video_anchor", None)
            self._fit_interface(anchor)
            self._last_layout_video_anchor = self._video_layout_anchor()
            self._preferred_video_anchor = anchor if anchor is not None else self._last_layout_video_anchor
            if self._video_fullscreen_window is None:
                self.video.sync_mpv_surfaces()
            if focused is not None and focused.isVisible() and QApplication.focusWidget() is not focused:
                focused.setFocus(Qt.FocusReason.OtherFocusReason)
        finally:
            self._resume_panel_layouts()
            self._panel_video_anchor = None
            self._panel_layout_key = None
            self._layout_busy = False

    def _video_layout_anchor(self):
        # Stay in Qt logical coordinates. Native mapToGlobal() can round by a
        # physical pixel at 125% DPI and otherwise accumulate a one-pixel drift.
        if self._video_fullscreen_window is not None:
            return getattr(self, "_last_layout_video_anchor", self.pos())
        return self.pos() + self.video.mapTo(self, QPoint())

    def _activate_work_layouts(self):
        """Activate descendants even when a taller neighbor keeps the canvas size.

        Activating only the outer layout skips unchanged container rectangles;
        a newly opened profile row would then move the video on the next event.
        """
        def activate(layout):
            if layout is None:
                return
            layout.activate()
            for index in range(layout.count()):
                item = layout.itemAt(index)
                if item.layout() is not None:
                    activate(item.layout())
                child = item.widget()
                if child is not None and not child.isHidden():
                    activate(child.layout())
        activate(self.work_area.layout())

    def _fit_interface(self, anchor=None):
        """Fit the outer window; the original inner layout is never rearranged."""
        root = self.layout()
        root.setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
        self.setMinimumSize(0, 0)
        self.setMaximumSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX)
        screen = QApplication.screenAt(self.frameGeometry().center()) or self.screen()
        area = screen.availableGeometry()
        full = self._is_fullscreen_layout() or self.isMaximized()
        self._invalidate_layout_hierarchy()
        body = self.work_area.layout()
        natural = body.sizeHint().expandedTo(body.minimumSize())
        if body.hasHeightForWidth():
            natural.setHeight(max(body.minimumSize().height(), body.totalHeightForWidth(natural.width())))
        margins = root.contentsMargins()
        chrome = QSize(margins.left() + margins.right(), margins.top() + margins.bottom())
        if not self.title_bar.isHidden():
            chrome.setHeight(chrome.height() + self.title_bar.height() + root.spacing())
        # Scroll bars can be reached with a 256x144 viewport even on small screens.
        bar_w = self.interface_scroll.verticalScrollBar().sizeHint().width()
        bar_h = self.interface_scroll.horizontalScrollBar().sizeHint().height()
        minimum = QSize(VIDEO_MIN_WIDTH + bar_w, VIDEO_MIN_HEIGHT + bar_h) + chrome
        minimum = minimum.boundedTo(area.size())
        if not full and self.work_area.size() != natural:
            self.work_area.setFixedSize(natural)
        self._resume_panel_layouts()
        self._activate_work_layouts()
        if full:
            position = area.topLeft()
        elif self._restore_fullscreen_pos_pending and self._pre_full_pos is not None:
            position = self._pre_full_pos
            self._restore_fullscreen_pos_pending = False
        elif anchor is not None:
            local = self.video.mapTo(self.work_area, QPoint())
            offset = QPoint(margins.left(), chrome.height() - margins.bottom()) + local
            position = anchor - offset
        else:
            position = self.pos()
        cap = area.size()
        panel_action = (getattr(self, '_panel_layout_key', None) is not None)
        if panel_action:
            # A panel action may expand/move the viewport over the entire work
            # area. A preceding manual resize is not an automatic screen limit.
            self._window_size_limit = None
        limit = getattr(self, "_window_size_limit", None)
        if not full and limit is not None:
            cap = cap.boundedTo(limit.expandedTo(minimum))
        budget = QSize(max(1, cap.width() - chrome.width()), max(1, cap.height() - chrome.height()))
        if full:
            size = area.size()
            self.interface_scroll.fitted_size(natural, budget)
            bar_space = QSize(bar_w if self.interface_scroll.verticalScrollBarPolicy() == Qt.ScrollBarPolicy.ScrollBarAlwaysOn else 0,
                              bar_h if self.interface_scroll.horizontalScrollBarPolicy() == Qt.ScrollBarPolicy.ScrollBarAlwaysOn else 0)
            canvas_size = natural.expandedTo(budget - bar_space)
        else:
            size = (self.interface_scroll.fitted_size(natural, budget) + chrome).expandedTo(minimum).boundedTo(cap)
            canvas_size = natural
        if self.work_area.size() != canvas_size:
            self.work_area.setFixedSize(canvas_size)
        # Lay out the canvas before calculating the video anchor. No event-loop
        # delay, temporary hiding, adjustSize() or video reparent is involved.
        self._resume_panel_layouts()
        self._activate_work_layouts()
        x = min(max(position.x(), area.left()), area.right() - size.width() + 1)
        y = min(max(position.y(), area.top()), area.bottom() - size.height() + 1)
        if self.geometry() != QRectF(x, y, size.width(), size.height()).toRect():
            self.setGeometry(x, y, size.width(), size.height())
        self.setMinimumSize(minimum)
        root.activate()
        # After Qt establishes the viewport and both scroll ranges, preserve
        # the on-screen video anchor whenever those ranges permit it.
        if anchor is not None and not full:
            local = self.video.mapTo(self.work_area, QPoint())
            origin = self.pos() + self.interface_scroll.viewport().mapTo(self, QPoint())
            desired = origin + local - anchor
            self.interface_scroll.horizontalScrollBar().setValue(desired.x())
            self.interface_scroll.verticalScrollBar().setValue(desired.y())
        self._last_panel_window_size = self.size()
        self._last_panel_area = area

    def _invalidate_layout_hierarchy(self):
        """Refresh child size hints before their cached QWidgetItems/parents."""
        root = self.layout()
        if root is None:
            return
        seen = set()

        def visit(layout):
            if layout is None or id(layout) in seen:
                return
            seen.add(id(layout))
            for index in range(layout.count()):
                item = layout.itemAt(index)
                child_layout = item.layout()
                if child_layout is not None:
                    visit(child_layout)
                child = item.widget()
                if child is not None and not child.isHidden():
                    nested = child.layout()
                    if nested is not None:
                        visit(nested)
                        # invalidate() alone does not clear the parent's cached
                        # QWidgetItem size hint. Notify it after the child layout.
                        child.updateGeometry()
            layout.invalidate()

        # QScrollArea's content is not a QLayoutItem of its outer layout.
        # Invalidate that subtree explicitly, before measuring the canvas.
        if hasattr(self, "work_area"):
            visit(self.work_area.layout())
            self.work_area.updateGeometry()
        visit(root)
        self.updateGeometry()

    def _adapt_panel_widths_to_screen(self, area=None):
        """Keep ordinary panel dimensions independent of the viewport/screen."""
        screen_area = area if area is not None else (self.screen() or QApplication.primaryScreen()).availableGeometry()
        track_width = min(480, max(340, int(screen_area.width() * .35)))
        for name, width in (("transcode_panel", min(560, max(280, screen_area.width()-430))), ("color_panel", self.COLOR_PANEL_WIDTH),
                            ("tracks_panel", track_width), ("download_info_panel", 238),
                            ("settings_panel", 330), ("about_panel", 390)):
            panel = getattr(self, name, None)
            if panel is not None:
                panel.setFixedWidth(width)
        for name in ("settings_panel", "about_panel"):
            panel = getattr(self, name, None)
            if panel is not None:
                panel.setFixedHeight(560)
        if hasattr(self, "dl_panel"):
            self.dl_panel.setMinimumWidth(500)
            self.dl_panel.setMaximumWidth(QWIDGETSIZE_MAX)


    def _sync_video_area_to_video(self, _size=None):
        """В обычном режиме высота области кадра всегда равна высоте самого видео.

        Раскладка профилей учитывается отдельным верхним отступом в side_slot, поэтому
        раскрытие верхней панели не растягивает видеоповерхность и не меняет высоту ручки.
        """
        if not hasattr(self, "video_area") or not hasattr(self, "video"):
            return
        if self._is_fullscreen_layout():
            self.video_area.setMinimumHeight(VIDEO_MIN_HEIGHT)
            self.video_area.setMaximumHeight(QWIDGETSIZE_MAX)
            self.video_area.setSizePolicy(
                QSizePolicy.Policy.Expanding,
                QSizePolicy.Policy.Expanding,
            )
            target_h = max(1, self.video.height())
            if (self.btn_handle.minimumHeight() != target_h
                    or self.btn_handle.maximumHeight() != target_h):
                self.btn_handle.setFixedHeight(target_h)
            self.btn_handle.setSizePolicy(
                QSizePolicy.Policy.Fixed,
                QSizePolicy.Policy.Fixed,
            )
            if hasattr(self, "side_video_offset") and hasattr(self, "profile_row"):
                profile_h = max(0, self.profile_row.sizeHint().height())
                if self.side_video_offset.height() != profile_h:
                    self.side_video_offset.setFixedHeight(profile_h)
        else:
            target_h = max(1, self.video.height())
            if (self.video_area.minimumHeight() != target_h
                    or self.video_area.maximumHeight() != target_h):
                self.video_area.setFixedHeight(target_h)
            self.video_area.setSizePolicy(
                QSizePolicy.Policy.Expanding,
                QSizePolicy.Policy.Fixed,
            )
            if (self.btn_handle.minimumHeight() != target_h
                    or self.btn_handle.maximumHeight() != target_h):
                self.btn_handle.setFixedHeight(target_h)
            self.btn_handle.setSizePolicy(
                QSizePolicy.Policy.Fixed,
                QSizePolicy.Policy.Fixed,
            )
            if hasattr(self, "side_video_offset") and hasattr(self, "profile_row"):
                profile_h = max(0, self.profile_row.sizeHint().height())
                if self.side_video_offset.height() != profile_h:
                    self.side_video_offset.setFixedHeight(profile_h)
        self.video_area.updateGeometry()
        self.video_col.updateGeometry()
        if hasattr(self, "side_slot"):
            self.side_slot.updateGeometry()
        if hasattr(self, "side_w"):
            self._sync_sidebar_height_to_video()

    def _sync_sidebar_height_to_video(self):
        """Привязывает боковую ручку к прямоугольнику видео, не к высоте всего окна."""
        if not all(hasattr(self, name) for name in
                   ("side_w", "btn_handle", "video", "video_col", "profile_row")):
            return

        if self._is_fullscreen_layout():
            target_height = max(1, self.video.height())
            if (self.btn_handle.minimumHeight() != target_height
                    or self.btn_handle.maximumHeight() != target_height):
                self.btn_handle.setFixedHeight(target_height)
            self.btn_handle.setSizePolicy(
                QSizePolicy.Policy.Fixed,
                QSizePolicy.Policy.Fixed,
            )
            if hasattr(self, "side_video_offset"):
                profile_h = max(0, self.profile_row.sizeHint().height())
                if self.side_video_offset.height() != profile_h:
                    self.side_video_offset.setFixedHeight(profile_h)
        else:
            target_height = max(1, self.video.height())
            if (self.btn_handle.minimumHeight() != target_height
                    or self.btn_handle.maximumHeight() != target_height):
                self.btn_handle.setFixedHeight(target_height)
            self.btn_handle.setSizePolicy(
                QSizePolicy.Policy.Fixed,
                QSizePolicy.Policy.Fixed,
            )
            # Не обрезаем саму панель кнопок: она сохраняет естественную высоту,
            # а узкая ручка всегда равна высоте видео.
            self.side_w.setMinimumHeight(0)
            self.side_w.setMaximumHeight(QWIDGETSIZE_MAX)
            self.side_w.setSizePolicy(
                QSizePolicy.Policy.Fixed,
                QSizePolicy.Policy.Preferred,
            )
            profile_h = max(0, self.profile_row.sizeHint().height())
            if hasattr(self, "side_video_offset") and self.side_video_offset.height() != profile_h:
                self.side_video_offset.setFixedHeight(profile_h)
        if hasattr(self, "side_slot"):
            self.side_slot.updateGeometry()

    def update_lower_cap(self):
        """Нижние панели цельные; общая прокрутка принадлежит interface_scroll."""
        if not hasattr(self, "lower_w"):
            return
        self.lower_w.updateGeometry()

    def fit_to_video(self):
        """Режим «Авто»: размер окна следует за размером самого видео."""
        if self.size_mode == "auto":
            self.schedule_relayout()

    def build_size_panel(self) -> QWidget:
        panel = QWidget()
        panel.setObjectName("panel")
        panel.setMinimumWidth(340)

        lbl = QLabel("Размер видео")
        lbl.setObjectName("title")
        lbl.setToolTip("Авто — по размеру самого видео")

        grid = QGridLayout()
        grid.setSpacing(4)
        self.size_buttons: dict[str, QPushButton] = {}
        for i, (key, label, _) in enumerate(SIZE_PRESETS):
            b = QPushButton(label)
            b.setObjectName("chip")
            b.setCheckable(True)
            b.setFixedHeight(30)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _checked, k=key: self.set_size_mode(k))
            grid.addWidget(b, i // 4, i % 4)
            self.size_buttons[key] = b

        lay = QVBoxLayout(panel)
        lay.setContentsMargins(10, 8, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(lbl)
        lay.addLayout(grid)
        return panel

    def video_target_size(self) -> tuple[int, int]:
        """Желаемый размер области видео для текущего режима (в «full» - для режима до полного экрана)."""
        mode = self.prev_mode if self.size_mode == "full" else self.size_mode
        if mode == "auto":
            s = self.video.native_size()
            if s.isValid() and s.width() > 0 and s.height() > 0:
                return s.width() * VIDEO_SCALE, s.height() * VIDEO_SCALE
            return 320, 180
        return next(size for key, _, size in SIZE_PRESETS if key == mode and size)

    def fit_video_to_screen(self):
        if self._is_fullscreen_layout():
            return
        target_w, target_h = self.video_target_size()
        size = QSize(max(VIDEO_MIN_WIDTH, int(target_w)), max(VIDEO_MIN_HEIGHT, int(target_h)))
        if self.video.size() != size or self.video.minimumSize() != size or self.video.maximumSize() != size:
            self.video.setFixedSize(size)
        self._invalidate_layout_hierarchy()

    def apply_size(self):
        self._last_video_layout_request = None
        if self.size_mode == "full":
            self.enter_fullscreen()
            return
        if self._is_fullscreen_layout():
            self.leave_fullscreen()
        self.schedule_relayout()

    def _collapse_panels_to_fit(self, layout, available, keys, prefer_hint=True):
        """Compatibility: overflow is laid out by relayout; no panel flag is changed."""
        self.schedule_relayout()

    def keep_window_on_screen(self):
        if self._is_fullscreen_layout() or self.isMinimized():
            return
        self.relayout()

    def arrange_top(self, fullscreen: bool):
        """Порядок виджетов верхней и нижней строки. Меняются только виджеты (removeWidget/addWidget),
        никаких takeAt()/del: раньше удаление элементов раскладки ломало её при смене режима."""
        top = self.top_layout
        top_align = Qt.AlignmentFlag.AlignTop
        everything = (
            self.color_panel, self.video_col, self.side_slot,
            self.tracks_panel, self.download_info_panel, self.settings_panel, self.about_panel,
            self.top_spacer,
        )
        for wdg in everything:
            top.removeWidget(wdg)
        if fullscreen:
            # Боковые панели остаются прижаты к верхнему краю.
            # Колонку видео добавляем БЕЗ AlignTop: она должна растянуться
            # по высоте доступной области экрана. AlignTop здесь сжимал её
            # до sizeHint, из-за чего видеоповерхность исчезала, оставляя
            # большую чёрную пустую область под панелями.
            order = (
                (self.color_panel, 0, top_align), (self.side_slot, 0, top_align),
                (self.tracks_panel, 0, top_align),
                (self.download_info_panel, 0, top_align),
                (self.settings_panel, 0, top_align), (self.about_panel, 0, top_align),
                (self.video_col, 1, None),
            )
        else:
            order = (
                (self.color_panel, 0, top_align), 
                (self.video_col, 0, top_align),
                (self.side_slot, 0, top_align), (self.tracks_panel, 0, top_align),
                (self.download_info_panel, 0, top_align),
                (self.settings_panel, 0, top_align), (self.about_panel, 0, top_align),
                (self.top_spacer, 1, None),
            )
        for wdg, stretch, align in order:
            if align is None:
                top.addWidget(wdg, stretch)
            else:
                top.addWidget(wdg, stretch, align)
        self.top_spacer.setVisible(not fullscreen)
        self.arrange_bottom(fullscreen)

    def arrange_bottom(self, fullscreen: bool):
        """Нижняя строка: «Настройки загрузки» слева, эквалайзер - справа от неё.
        В окне настройки загрузки занимают всё свободное место, в полном экране держатся слева."""
        row = self.bottom_layout
        top_align = Qt.AlignmentFlag.AlignTop
        for wdg in (self.dl_panel, self.right_col, self.bottom_spacer):
            row.removeWidget(wdg)
        row.addWidget(self.dl_panel, 0 if fullscreen else 1, top_align)
        row.addWidget(self.right_col, 0, top_align)
        row.addWidget(self.bottom_spacer, 1 if fullscreen else 0)
        self.bottom_spacer.setVisible(fullscreen)

    def _is_fullscreen_layout(self) -> bool:
        """True for the full-screen size preset, including the frameless geometry mode."""
        return bool(QWidget.isFullScreen(self) or self._fullscreen_layout_active)

    def _sync_fullscreen_video_layout(self):
        """After expanding the frameless window, re-activate layouts and sync the native mpv surface."""
        if not self._is_fullscreen_layout():
            return
        self._invalidate_layout_hierarchy()
        layout = self.layout()
        if layout is not None:
            layout.activate()
        for name in ("main_content", "top_layout", "left_layout"):
            obj = getattr(self, name, None)
            if obj is not None:
                if name == "main_content":
                    child_layout = obj.layout()
                else:
                    child_layout = obj
                if child_layout is not None:
                    child_layout.invalidate()
                    child_layout.activate()
        video_area_layout = self.video_area.layout() if hasattr(self, "video_area") else None
        if video_area_layout is not None:
            video_area_layout.invalidate()
            video_area_layout.activate()
        self.video.show()
        self.video.sync_mpv_surfaces()

    def enter_fullscreen(self):
        if self._is_fullscreen_layout():
            return
        self._pre_full_pos = self.pos()
        self._fullscreen_layout_active = True
        self._sync_rounded_window()
        if hasattr(self, "title_bar"):
            self.title_bar.hide()
        self._restore_fullscreen_pos_pending = False
        # Окно уже без рамки, поэтому растягиваем его геометрией на весь экран,
        # не переключая Qt.WindowState. Это сохраняет HWND видеоповерхности mpv:
        # при showFullScreen() Windows/Qt может пересоздать нативный handle и оставить mpv чёрным.
        self.layout().setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
        self.setMinimumSize(0, 0)
        self.setMaximumSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX)
        self.video.setMinimumSize(VIDEO_MIN_WIDTH, VIDEO_MIN_HEIGHT)
        self.video.setMaximumSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX)
        self.video.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.video_area.setMinimumHeight(VIDEO_MIN_HEIGHT)
        self.video_area.setMaximumHeight(QWIDGETSIZE_MAX)
        self.video_area.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.video_col.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding)
        self.arrange_top(True)
        screen = (QApplication.screenAt(self.frameGeometry().center())
                  or self.screen() or QApplication.primaryScreen())
        if screen is not None:
            self.setGeometry(screen.availableGeometry())
        self.show()
        self.raise_()
        self.activateWindow()
        self._sync_video_area_to_video()
        self._sync_fullscreen_video_layout()
        self.schedule_relayout()
        QTimer.singleShot(0, self._sync_fullscreen_video_layout)
        QTimer.singleShot(150, self.refresh_panels_paint)

    def leave_fullscreen(self):
        was_native_fullscreen = QWidget.isFullScreen(self)
        self._fullscreen_layout_active = False
        self._sync_rounded_window()
        if hasattr(self, "title_bar") and self._video_only_snapshot is None:
            self.title_bar.show()
        self._restore_fullscreen_pos_pending = self._pre_full_pos is not None
        self.arrange_top(False)
        self.video.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self.video_col.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)
        self.video_area.setFixedHeight(max(1, self.video.height()))
        self.video_area.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        # Возвращаем «размер = содержимое» до пересчёта обычного оконного режима.
        self.layout().setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
        self._last_video_layout_request = None
        if was_native_fullscreen:
            self.showNormal()
        else:
            self.show()
        self.schedule_relayout()
        # На Windows после выхода обновляем содержимое панелей и видеоповерхность.
        QTimer.singleShot(150, self.refresh_panels_paint)
        QTimer.singleShot(350, self.refresh_panels_paint)

    def refresh_panels_paint(self):
        """Пересчитывает раскладку и обновляет все панели (в т.ч. viewport прокрутки)."""
        for panel in (self.dl_panel, self.download_info_panel, self.equalizer_panel,
                      self.tracks_panel, self.size_panel, self.converter_panel,
                      self.transcode_panel):
            panel.updateGeometry()
            panel.update()
        if hasattr(self, "transcode_scroll"):
            self.transcode_content.updateGeometry()
            self.transcode_scroll.updateGeometry()
            self.transcode_scroll.viewport().update()
        if getattr(self, "downloads_scroll", None) is not None:
            content_layout = self.downloads_content.layout()
            if content_layout is not None:
                content_layout.invalidate()
                content_layout.activate()
            self.downloads_content.updateGeometry()
            self.downloads_scroll.updateGeometry()
            self.downloads_scroll.viewport().update()
        self.layout().invalidate()
        self.layout().activate()
        self.update()

    def set_size_mode(self, mode: str, save: bool = True):
        self.size_mode = mode
        if mode != "full":
            self.prev_mode = mode
        for key, btn in self.size_buttons.items():
            btn.setChecked(key == mode)
        self.apply_size()
        if save:
            self.save_settings()

    def set_size_visible(self, visible: bool, save: bool = True):
        self.set_panel_visible("size", visible, save)

    def on_escape(self):
        if self._video_only_snapshot is not None:
            self._restore_video_only_mode()
        elif self._video_fullscreen_window is not None:
            self.exit_video_fullscreen()
        elif self._is_fullscreen_layout():
            self.set_size_mode(self.prev_mode)
        else:
            self.close()

    def toggle_fullscreen(self):
        # Режим «Только видео» не является полноэкранным режимом и не переключается F11.
        if self._video_only_snapshot is not None:
            return
        self.set_size_mode(self.prev_mode if self._is_fullscreen_layout() else "full")

    def bring_to_front(self):
        """Показывает окно из свёрнутого или фонового состояния, не меняя его размеров."""
        if getattr(self, "_closing", False):
            return
        if self.isMinimized():
            self.setWindowState((self.windowState() & ~Qt.WindowState.WindowMinimized) | Qt.WindowState.WindowActive)
        self.show()
        self.raise_()
        self.activateWindow()
        fullscreen = getattr(self, "_video_fullscreen_window", None)
        if fullscreen is not None:
            if fullscreen.isMinimized():
                fullscreen.showFullScreen()
            fullscreen.raise_()
            fullscreen.activateWindow()
        if os.name == "nt":
            try:
                ctypes.windll.user32.SetForegroundWindow(int(self.winId()))
            except (OSError, AttributeError):
                pass
        QApplication.alert(self, 1500)

    def open_external_file(self, path: Path):
        """Файл, переданный другим запуском NOP (режим «В текущем окне»)."""
        path = Path(path)
        self.bring_to_front()
        if getattr(self, "current", None) is not None and _media_key(self.current) == _media_key(path):
            return
        self.play_file(path)

    def on_open_mode_changed(self, *_args):
        self.cfg["open_mode"] = self.cmb_open_mode.currentData() or "current"
        self.save_settings()

    # ---------- центрирование при запуске ----------
    def center_on_startup(self):
        """Один раз при запуске ставит окно в центр рабочей области монитора (без панели задач),
        не меняя размеров и настроек. Раскладка панелей досчитывается отложенно, поэтому несколько
        проходов; любое действие пользователя с окном (перетаскивание, свёртывание) их прекращает."""
        self._startup_center_active = True
        self._startup_screen = QApplication.screenAt(QCursor.pos()) or QApplication.primaryScreen()
        for delay in (0, 80, 250, 600, 1200):
            QTimer.singleShot(delay, self._startup_center_step)

    def _startup_center_step(self):
        if (not getattr(self, "_startup_center_active", False) or getattr(self, "_closing", False)
                or self.isMinimized() or self.isMaximized() or self._is_fullscreen_layout()
                or getattr(self, "_video_only_snapshot", None) is not None):
            return
        self._center_in_work_area(self._startup_screen)

    def _center_in_work_area(self, screen=None):
        if self.layout() is not None:
            self.layout().activate()
        screen = screen or QApplication.screenAt(self.frameGeometry().center()) or self.screen() or QApplication.primaryScreen()
        if screen is None:
            return
        area = screen.availableGeometry()  # рабочая область: без панели задач, в логических (DPI-независимых) координатах
        frame = self.frameGeometry()
        x = area.x() + (area.width() - frame.width()) // 2
        y = area.y() + (area.height() - frame.height()) // 2
        x = max(area.left(), min(x, area.right() - frame.width() + 1))
        y = max(area.top(), min(y, area.bottom() - frame.height() + 1))
        if (x, y) != (frame.x(), frame.y()):
            self.move(self.x() + x - frame.x(), self.y() + y - frame.y())

    def center_window(self):
        """Ctrl+M: вернуть плеер в центр активного экрана с видео 256×144."""
        if self.isMinimized():
            self.showNormal()
        self.set_size_mode("256x144", save=False)   # выходит из fullscreen и подгоняет окно
        QTimer.singleShot(60, self._center_now)      # после отложенного пересчёта раскладки

    def _center_now(self):
        if self._is_fullscreen_layout():
            return
        self.layout().activate()
        frame = self.frameGeometry()
        screen = QApplication.screenAt(frame.center()) or self.screen() or QApplication.primaryScreen()
        if screen is None:
            return
        area = screen.availableGeometry()
        # Центрируем именно внешнюю рамку окна, не включая панель задач.
        self.move(area.x() + (area.width() - frame.width()) // 2,
                  area.y() + (area.height() - frame.height()) // 2)
        self.raise_()
        self.activateWindow()


    def on_dl_source_changed(self, _index=None, save: bool = True):
        """Подстраивает панель под выбранный сервис загрузки."""
        if not hasattr(self, "cmb_source"):
            return
        source = self.cmb_source.currentData() or "youtube"
        previous_source = getattr(self, "_last_dl_source", source)
        if previous_source != source and hasattr(self, "channel_edit"):
            self._dl_source_urls[previous_source] = self.channel_edit.text().strip()
            self.channel_edit.setText(self._dl_source_urls.get(source, ""))
            self._last_dl_source = source
        elif not hasattr(self, "_last_dl_source"):
            self._last_dl_source = source
        spotify = source == "spotify"
        direct = source == "direct"
        self.direct_help_row.setVisible(direct)
        self.spotify_source_note.setVisible(spotify)
        self.spotify_source_note.setText(ui_text(
            "Spotify: только метаданные. Аудио ищется отдельно в SpotiSaver, YouTube или SoundCloud; это не прямая загрузка из Spotify и версия записи может отличаться.",
            "Spotify provides metadata only. Audio is matched separately via SpotiSaver, YouTube or SoundCloud; this is not a direct Spotify download and the recording may differ."))
        # Режимы у сервисов разные: у Instagram нет плейлистов, у Spotify - одна ссылка на трек/альбом/плейлист.
        labels = self.DL_KIND_LABELS.get(source, self.DL_KIND_LABELS["youtube"])
        for key, button in self.kind_buttons.items():
            text = labels.get(key)
            button.setVisible(bool(text) and not spotify and not direct)
            if text:
                button.setText(T(text))
        if not labels.get(self.dl_kind):
            self.dl_kind = "channel"
        for key, button in self.kind_buttons.items():
            button.setChecked(key == self.dl_kind)
        self.update_dl_fields()
        # У Spotify свои настройки аудио, у остальных площадок - профиль yt-dlp и cookies.
        for label_widget, control_widget in self._dl_quality_controls.values():
            label_widget.setVisible(not spotify)
            control_widget.setVisible(not spotify)
        for widget in self._dl_spotify_widgets:
            widget.setVisible(spotify)
        self.cookies_row_w.setVisible(not spotify)
        self.on_dl_options_changed(save=False)
        if hasattr(self, "_relayout_timer"):
            self.schedule_relayout()
        if save:
            self.save_settings()

    def authorize_spotify(self):
        if getattr(self, "_closing", False):
            return
        client_id = self.spotify_client_id_edit.text().strip()
        if not client_id:
            self.lbl_spotify_auth.setText("Сначала введи Spotify Client ID из Developer Dashboard.")
            return
        old_client_id = str(self.cfg.get("spotify_client_id", "")).strip()
        if old_client_id and old_client_id != client_id:
            self.cfg["spotify_access_token"] = ""
            self.cfg["spotify_refresh_token"] = ""
            self.cfg["spotify_token_expires_at"] = 0
        self.cfg["spotify_client_id"] = client_id
        self.save_settings()
        thread = getattr(self, "spotify_auth_thread", None)
        if thread is not None and thread.isRunning():
            return
        self.btn_spotify_auth.setEnabled(False)
        self.lbl_spotify_auth.setText("Открой браузер и подтверди доступ к Spotify…")
        previous = getattr(self, "spotify_auth_thread", None)
        if previous is not None and not previous.isRunning():
            previous.deleteLater()
        self.spotify_auth_thread = SpotifyAuthThread(client_id, self)
        self.spotify_auth_thread.status.connect(self.on_spotify_auth_status)
        self.spotify_auth_thread.result.connect(self.on_spotify_auth_result)
        self.spotify_auth_thread.finished.connect(lambda: self.btn_spotify_auth.setEnabled(not getattr(self, "_closing", False)))
        self.spotify_auth_thread.start()

    def on_spotify_auth_status(self, text: str):
        self.lbl_spotify_auth.setText(text)

    def on_spotify_auth_result(self, result: dict):
        if getattr(self, "_closing", False):
            return
        if not result.get("ok"):
            self.lbl_spotify_auth.setText("Ошибка Spotify: " + str(result.get("error", "неизвестная ошибка")))
            self.lbl_spotify_auth.setToolTip(str(result.get("error", "")))
            return
        self.cfg["spotify_client_id"] = str(result.get("client_id", self.spotify_client_id_edit.text().strip()))
        self.cfg["spotify_access_token"] = str(result.get("access_token", ""))
        self.cfg["spotify_refresh_token"] = str(result.get("refresh_token", ""))
        self.cfg["spotify_token_expires_at"] = float(result.get("expires_at", 0) or 0)
        self.lbl_spotify_auth.setText("Spotify авторизован — можно экспортировать альбомы и доступные плейлисты")
        self.save_settings()

    def on_spotify_tokens_updated(self, tokens: dict):
        self.cfg["spotify_access_token"] = str(tokens.get("access_token", self.cfg.get("spotify_access_token", "")))
        self.cfg["spotify_refresh_token"] = str(tokens.get("refresh_token", self.cfg.get("spotify_refresh_token", "")))
        self.cfg["spotify_token_expires_at"] = float(tokens.get("expires_at", self.cfg.get("spotify_token_expires_at", 0)) or 0)
        self.save_settings()

    def on_dl_options_changed(self, _index=None, save: bool = True):
        mode = self.cmb_mode.currentData()
        source = self.cmb_source.currentData() if hasattr(self, "cmb_source") else "youtube"
        is_spotify = source == "spotify"
        video_active = not is_spotify and mode in ("both", "video")
        audio_active = not is_spotify and mode in ("both", "audio")
        # Ненужные параметры не прячем (панель не должна «прыгать»), а серым отключаем.
        for key, active in (("fps", video_active), ("audio", audio_active),
                            ("container", video_active), ("vcodec", video_active), ("resolution", video_active)):
            if key in self._dl_quality_controls:
                label_widget, control_widget = self._dl_quality_controls[key]
                label_widget.setEnabled(active)
                control_widget.setEnabled(active)
        if hasattr(self, "cmb_vbitrate"):
            self.vbitrate_input.setVisible(self.cmb_vbitrate.currentData() == "manual" and not is_spotify)
            self.vbitrate_input.setEnabled(video_active)
            self.vbitrate_hint.setVisible(False)
        if hasattr(self, "clip_start_edit"):
            clip_ok = (not is_spotify) and self._dl_clip_available()
            for _w in self._dl_clip_widgets:
                _w.setVisible(not is_spotify)
            for _w in (self.clip_start_label, self.clip_start_edit, self.clip_end_label, self.clip_end_edit):
                _w.setEnabled(clip_ok)
        if hasattr(self, "cmb_spotify_bitrate"):
            is_mp3 = self.cmb_spotify_format.currentData() == "mp3"
            self.cmb_spotify_bitrate.setEnabled(is_spotify and is_mp3)
            self.spotify_bitrate_label.setEnabled(is_spotify and is_mp3)
        if hasattr(self, "cmb_sample_rate"):
            # Частота дискретизации относится только к обычным загрузкам.
            # Скрываем обе части строки для Spotify, но сохраняем общее значение настройки.
            sample_rate_visible = not is_spotify
            sample_rate_enabled = sample_rate_visible and mode in ("audio", "both")
            self.cmb_sample_rate.setVisible(sample_rate_visible)
            self.sample_rate_label.setVisible(sample_rate_visible)
            self.cmb_sample_rate.setEnabled(sample_rate_enabled)
            self.sample_rate_label.setEnabled(sample_rate_enabled)
        self.update_download_state()
        self._invalidate_dl_resolutions()
        if save:
            self.save_settings()

    def set_pinned(self, on: bool, initial: bool = False):
        self.pinned = on
        pos = self.pos()
        self.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, on)
        if not initial:
            self.show()   # смена флага скрывает окно - показываем снова
            self.move(pos)
            self.save_settings()
        self.tint(self.btn_pin, "pin", on)
        self.btn_pin.setToolTip(
            T("Закреплено поверх всех окон (Ctrl+P - открепить)" if on
              else "Закрепить поверх всех окон (Ctrl+P)")
        )

    # ---------- показ / скрытие панелей: одна логика для всех ----------
    def _panel_spec(self, key: str):
        """ключ -> (атрибут-флаг, виджеты панели, кнопка-переключатель, иконка кнопки)."""
        return {
            "profile": ("profile_bar_visible", (self.profile_bar,), None, None),
            "controls": ("controls_visible", (self.side_w, self.volume_w), None, None),
            "seek": ("seek_visible", (self.seek_w,), self.btn_seek, "seek"),
            "tracks": ("tracks_visible", (self.tracks_panel,), self.btn_tracks, "list"),
            "size": ("size_visible", (self.size_panel,), self.btn_size, "frame"),
            "equalizer": ("equalizer_visible", (self.equalizer_panel,), self.btn_equalizer, "eq"),
            "color": ("color_visible", (self.color_panel,), self.btn_color, "palette"),
            "downloads": ("downloads_visible", (self.dl_panel,), self.btn_panel, "sliders"),
            "converter": ("converter_visible", (self.converter_panel,), self.btn_converter, "convert"),
            "transcode": ("transcode_visible", (self.transcode_panel,), self.btn_transcode, "film"),
            "download_info": ("download_info_visible", (self.download_info_panel,),
                              self.btn_download_info, "activity"),
            "settings": ("settings_visible", (self.settings_panel,), self.btn_settings, "settings"),
            "about": ("about_visible", (self.about_panel,), self.btn_about, "info"),
        }[key]

    def set_panel_visible(self, key: str, visible: bool, save: bool = True):
        if key == "profile":
            self.set_profile_bar_visible(visible, save)
            return
        """Единственная точка, где панель показывается или скрывается: флаг -> виджеты -> кнопка ->
        один отложенный пересчёт раскладки. Размер окна здесь НЕ трогаем (это делает relayout)."""
        self._begin_panel_layout(key)
        visible = bool(visible)
        attr, widgets, button, icon = self._panel_spec(key)
        if save and key not in ("settings", "about") and not getattr(self, "_applying_panel_profile", False):
            self.panel_profile = "custom"
            self._profile_restore = None
            self._sync_profile_buttons()
        setattr(self, attr, visible)
        for wdg in widgets:
            wdg.setVisible(visible)
        if button is not None:
            self.tint(button, icon, visible)
        if key == "controls":
            self.btn_handle.setIcon(make_icon("chev_r" if visible else "chev_l", ICON_MUTED))
            self.btn_handle.setToolTip(
                T("Скрыть панель кнопок (Ctrl+H)" if visible else "Показать панель кнопок (Ctrl+H)")
            )
        if visible and save and key in ("downloads", "tracks"):
            self.refresh_files()
        if hasattr(self, "right_col"):
            self.right_col.setVisible(bool(self.equalizer_visible or self.converter_visible))
        if hasattr(self, "lower_scroll"):
            self.lower_scroll.setVisible(bool(
                self.downloads_visible or self.equalizer_visible or self.converter_visible))
        self._finish_panel_layout()
        if save:
            self.save_settings()

    def set_controls_visible(self, visible: bool, save: bool = True):
        self.set_panel_visible("controls", visible, save)

    def set_downloads_visible(self, visible: bool, save: bool = True):
        self.set_panel_visible("downloads", visible, save)

    def toggle_download_info(self):
        self.set_panel_visible("download_info", not self.download_info_visible)

    def set_download_info_visible(self, visible: bool, save: bool = True):
        """Показывает или скрывает встроенную панель очереди загрузок."""
        self.set_panel_visible("download_info", visible, save)

    def tint(self, btn: QPushButton, kind: str | None, on: bool):
        """Обновляет активное состояние, иконку и тематический цвет обводки."""
        role = btn.property("themeRole")
        if role:
            on = bool(on and btn.property("themeStateful") and not btn.property("themeInactive"))
        is_special = btn.objectName() == "special" or role in {"special", "information"}
        outline_color = SPECIAL if is_special else ACCENT
        white_icons = _THEME["name"] in {"jet_black_orchid", "wine_ash_turquoise"}
        quiet = bool(btn.property("themeSpecial")) and _THEME["name"] != "classic"
        btn.setProperty("quietOutline", quiet)
        if btn.property("instruction"):
            color = SPECIAL
        elif white_icons and role == "information":
            color = ACCENT
        elif white_icons:
            color = "#FFFFFF"
        elif is_special:
            color = (ACCENT if quiet else ON_SPECIAL) if on else "#FFFFFF"
        else:
            color = ACCENT if on else "#FFFFFF"
        if kind is not None:
            info = _ICON_REG.get(btn.icon().cacheKey())
            size = info[2] if info and info[0] == kind else 64
            icon = make_icon(kind, color, size)
            if role:
                disabled = make_icon(kind, _mixc(color, ICON_MUTED, .55), size)
                icon.addPixmap(disabled.pixmap(size, size), QIcon.Mode.Disabled)
                _ICON_REG[icon.cacheKey()] = (kind, _icon_role(color), size)
            btn.setIcon(icon)
        btn.setProperty("outlineColor", outline_color)
        btn.setProperty("on", bool(on))
        btn.style().unpolish(btn)
        btn.style().polish(btn)
        btn.update()

    def set_seek_visible(self, visible: bool, save: bool = True):
        self.set_panel_visible("seek", visible, save)

    def set_tracks_visible(self, visible: bool, save: bool = True):
        self.set_panel_visible('tracks', visible, save)

    def show_video_context_menu(self, global_pos):
        """Контекстное меню видеоплеера с реальными дорожками текущего mpv-файла."""
        menu = QMenu(self)
        current_path = str(getattr(getattr(self, "player", None), "path", "") or "")
        props_action = menu.addAction("Свойства…")
        props_action.setEnabled(bool(current_path and Path(current_path).is_file()))
        if props_action.isEnabled():
            props_action.triggered.connect(lambda _checked=False, p=Path(current_path): self.show_track_properties(p))
        menu.addSeparator()

        facade = getattr(self, "player", None)
        mpv = getattr(facade, "mpv", None)
        using_mpv = bool(facade is not None and getattr(facade, "active", "") == "mpv"
                         and mpv is not None and mpv.available)
        tracks = mpv.get_tracks() if using_mpv else []
        labels = {"audio": "Аудиодорожка", "video": "Видеодорожка", "sub": "Дорожка субтитров"}
        for kind in ("audio", "video", "sub"):
            submenu = menu.addMenu(labels[kind])
            matching = [t for t in tracks if t["type"] == kind]
            if kind == "sub":
                disable = submenu.addAction("Отключить субтитры")
                disable.setCheckable(True)
                disable.setChecked(not any(t["selected"] for t in matching))
                disable.triggered.connect(lambda _checked=False, m=mpv: m.select_track("sub", None) if m and m.available else None)
                if matching:
                    submenu.addSeparator()
            if not using_mpv:
                unavailable = submenu.addAction("Доступно только при воспроизведении через libmpv")
                unavailable.setEnabled(False)
                continue
            if not matching:
                empty = submenu.addAction("Нет доступных дорожек")
                empty.setEnabled(False)
                continue
            for track in matching:
                pieces = []
                title = track.get("title", "").strip()
                lang = track.get("lang", "").strip()
                codec = track.get("codec", "").strip()
                if title:
                    pieces.append(title)
                elif lang:
                    pieces.append(lang)
                else:
                    pieces.append({"audio": "Аудио", "video": "Видео", "sub": "Субтитры"}[kind])
                if lang and lang.casefold() not in " ".join(pieces).casefold():
                    pieces.append(lang)
                if codec:
                    pieces.append(codec)
                if track.get("external"):
                    pieces.append("внешняя")
                text = f"{track['id']}: " + " · ".join(pieces)
                action = submenu.addAction(text)
                action.setCheckable(True)
                action.setChecked(bool(track.get("selected")))
                action.triggered.connect(
                    lambda _checked=False, k=kind, tid=track["id"], m=mpv:
                    m.select_track(k, tid) if m and m.available else None
                )

        menu.addSeparator()
        is_playing = bool(facade is not None and facade.playbackState() == QMediaPlayer.PlaybackState.PlayingState)
        play_action = menu.addAction("Пауза" if is_playing else "Продолжить")
        play_action.triggered.connect(lambda _checked=False: self.toggle_play())
        has_tracks = bool(self._playback_tracks())
        for text, delta in (("Следующий трек", 1), ("Предыдущий трек", -1)):
            action = menu.addAction(T(text))
            action.setEnabled(has_tracks)
            action.triggered.connect(lambda _checked=False, d=delta: self.step(d))
        copy_path = menu.addAction("Скопировать путь к файлу")
        copy_path.setEnabled(bool(current_path))
        copy_path.triggered.connect(lambda _checked=False, p=current_path: QApplication.clipboard().setText(p))
        menu.addSeparator()
        menu.addAction(T("Свернуть"), self.minimize_player)
        menu.addAction(T("Закрыть"), self.close)
        menu.exec(global_pos)

    def minimize_player(self):
        """Minimize both player windows while keeping playback and video intact."""
        fullscreen = self._video_fullscreen_window
        if fullscreen is not None:
            fullscreen.show_controls()
            fullscreen._hide_timer.stop()
            fullscreen.showMinimized()
        self.showMinimized()

    def eventFilter(self, watched, event):
        if watched is getattr(self, "transcode_panel", None) and event.type() == QEvent.Type.Resize:
            self._layout_transcode_settings(event.size().width())
        if (watched is getattr(self, "title_label", None)
                and event.type() in (QEvent.Type.Resize, QEvent.Type.FontChange, QEvent.Type.ApplicationFontChange)):
            self._update_app_title()
        # Глобальное сопровождение перетаскивания бокового блока: события
        # продолжают поступать, даже когда указатель ушёл с разделителя.
        if getattr(self, "_side_separator_dragging", False):
            etype = event.type()
            if etype == QEvent.Type.MouseMove:
                if event.buttons() & Qt.MouseButton.LeftButton:
                    global_pos = event.globalPosition().toPoint()
                    self._move_side_dragged_block(global_pos)
                    self._update_side_separator_drop_target(global_pos)
                    return True
            elif etype == QEvent.Type.MouseButtonRelease and event.button() == Qt.MouseButton.LeftButton:
                self._finish_side_separator_drag(event.globalPosition().toPoint())
                return True
            elif etype == QEvent.Type.KeyPress and event.key() == Qt.Key.Key_Escape:
                self._cancel_side_separator_drag()
                return True

        # У отдельного окна свойств такой же перетаскиваемый заголовок, как у главного окна.
        if (watched.objectName() in ("windowTitleBar", "windowTitleLabel")
                and watched is not getattr(self, "title_bar", None)
                and watched is not getattr(self, "title_label", None)
                and event.type() == QEvent.Type.MouseButtonPress
                and event.button() == Qt.MouseButton.LeftButton):
            property_dialog = watched.window()
            handle = property_dialog.windowHandle() if property_dialog is not None else None
            if handle is not None and handle.isTopLevel():
                handle.startSystemMove()
            return True

        # Строка заголовка ведёт себя как системная: перетаскивание и двойной щелчок.
        if watched in (getattr(self, "title_bar", None), getattr(self, "title_label", None)):
            if event.type() == QEvent.Type.MouseButtonPress and event.button() == Qt.MouseButton.LeftButton:
                handle = self.windowHandle()
                if handle is not None and not self._is_fullscreen_layout():
                    handle.startSystemMove()
                return True

        # Контекстное меню видео должно работать как на QWidget, так и на native HWND libmpv.
        video_targets = (getattr(self, "video", None),
                         self.video.mpv_surface() if hasattr(self, "video") else None)
        if (watched in video_targets and event.type() == QEvent.Type.MouseButtonPress
                and event.button() == Qt.MouseButton.RightButton):
            self.show_video_context_menu(event.globalPosition().toPoint())
            event.accept()
            return True

        # Среднее нажатие по видео переключает отдельный режим «Только видео».
        # Обрабатываем и QWidget, и нативную поверхность mpv, чтобы не зависеть от backend.
        if (watched in video_targets and event.type() == QEvent.Type.MouseButtonPress
                and event.button() == Qt.MouseButton.MiddleButton
                and self._video_fullscreen_window is None):
            self.toggle_video_only_mode()
            return True

        # mpv выводит видео в нативный дочерний HWND, поэтому двойной щелчок
        # в этой поверхности не всегда доходит до VideoFrameWidget.
        if (hasattr(self, "video") and watched is self.video.mpv_surface()
                and event.type() == QEvent.Type.MouseButtonDblClick
                and event.button() == Qt.MouseButton.LeftButton):
            if self._video_fullscreen_window is not None:
                self.exit_video_fullscreen()
            else:
                self.enter_video_fullscreen()
            return True
        return super().eventFilter(watched, event)


    def _restore_windowed_geometry(self):
        if self._is_fullscreen_layout() or self.isMaximized():
            return
        self.relayout()

    def toggle_video_only_mode(self):
        """Скрывает всё, кроме видеоповерхности, сохраняя точное состояние интерфейса."""
        if self._video_only_snapshot is not None:
            self._restore_video_only_mode()
            return
        if self._video_fullscreen_window is not None:
            return

        descendants = self.findChildren(QWidget)
        video_global = self.video.mapToGlobal(QPoint(0, 0))
        was_maximized = self.isMaximized()
        normal_geometry = (self._titlebar_restore_geometry
                           if was_maximized and self._titlebar_restore_geometry is not None
                           else self.geometry())
        self._video_only_snapshot = {
            "geometry": normal_geometry if was_maximized else self.geometry(),
            "was_maximized": was_maximized,
            "normal_geometry": normal_geometry,
            "pinned": bool(self.pinned),
            "hidden": [(widget, widget.isHidden()) for widget in descendants],
            "layout_constraint": self.layout().sizeConstraint() if self.layout() else None,
            "window_minimum": self.minimumSize(),
            "window_maximum": self.maximumSize(),
            "video_size": self.video.size(),
            "video_minimum": self.video.minimumSize(),
            "video_maximum": self.video.maximumSize(),
            "video_policy": self.video.sizePolicy(),
            "area_minimum": self.video_area.minimumSize(),
            "area_maximum": self.video_area.maximumSize(),
            "area_policy": self.video_area.sizePolicy(),
            "area_height_min": self.video_area.minimumHeight(),
            "area_height_max": self.video_area.maximumHeight(),
            "col_policy": self.video_col.sizePolicy(),
            "col_minimum": self.video_col.minimumSize(),
            "col_maximum": self.video_col.maximumSize(),
            "root_margins": self.layout().contentsMargins() if self.layout() else None,
            "root_spacing": self.layout().spacing() if self.layout() else -1,
            "video_global": video_global,
            "canvas_size": self.work_area.size(),
            "scroll": (self.interface_scroll.horizontalScrollBar().value(), self.interface_scroll.verticalScrollBar().value()),
            "window_limit": self._window_size_limit,
        }
        if not self.pinned:
            self.set_pinned(True)
        if was_maximized:
            self.showNormal()
            self.setGeometry(normal_geometry)

        # Оставляем видимыми только предков видеовиджета и само видео/mpv-поверхность.
        keep = set()
        node = self.video
        while node is not None and node is not self:
            keep.add(node)
            node = node.parentWidget()
        keep.add(self)
        keep.add(self.video.mpv_surface())
        for widget in descendants:
            # Hide each off-video branch once. Hiding its descendants as well
            # collapses scroll-content hints; showing the parent first then
            # caches that collapsed hint in the color panel's outer layout.
            if widget not in keep and widget.parentWidget() in keep:
                widget.hide()

        self.title_bar.hide()
        root_layout = self.layout()
        if root_layout is not None:
            root_layout.setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
            # В video-only режиме никаких полей/отступов: внешнее окно и сама
            # поверхность видео должны быть ровно 256×144, а не sizeHint всей формы.
            root_layout.setContentsMargins(0, 0, 0, 0)
            root_layout.setSpacing(0)
        self.setMinimumSize(256, 144)
        self.setMaximumSize(256, 144)
        self.video.setFixedSize(256, 144)
        self.video_area.setFixedSize(256, 144)
        self.video_area.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self.video_col.setFixedSize(256, 144)
        self.video_col.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self._sync_video_control_gaps()
        self.work_area.setFixedSize(256, 144)
        self.interface_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.interface_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.interface_scroll.horizontalScrollBar().setValue(0)
        self.interface_scroll.verticalScrollBar().setValue(0)
        self._invalidate_layout_hierarchy()
        self.work_area.layout().activate()
        if root_layout is not None:
            root_layout.activate()
        self.resize(256, 144)
        if root_layout is not None:
            root_layout.activate()
        current_video_global = self.video.mapToGlobal(QPoint(0, 0))
        delta = video_global - current_video_global
        self.move(self.x() + delta.x(), self.y() + delta.y())
        self.video.sync_mpv_surfaces()
        self.video.mpv_surface().raise_()
        self.video.update()

    def _restore_video_only_mode(self):
        snapshot = self._video_only_snapshot
        if snapshot is None:
            return
        self._video_only_snapshot = None

        # Сначала восстановить флаг окна, затем точную видимость каждого виджета.
        if bool(self.pinned) != snapshot["pinned"]:
            self.set_pinned(snapshot["pinned"])
        for widget, was_hidden in snapshot["hidden"]:
            if widget is not None:
                widget.setVisible(not was_hidden)
        hidden_map = {widget: was_hidden for widget, was_hidden in snapshot["hidden"]}
        if self.title_bar in hidden_map:
            self.title_bar.setVisible(not hidden_map[self.title_bar])
        self.setMinimumSize(snapshot["window_minimum"])
        self.setMaximumSize(snapshot["window_maximum"])
        self.video.setMinimumSize(snapshot["video_minimum"])
        self.video.setMaximumSize(snapshot["video_maximum"])
        self.video.setSizePolicy(snapshot["video_policy"])
        self.video_area.setMinimumSize(snapshot["area_minimum"])
        self.video_area.setMaximumSize(snapshot["area_maximum"])
        self.video_area.setSizePolicy(snapshot["area_policy"])
        self.video_col.setMinimumSize(snapshot["col_minimum"])
        self.video_col.setMaximumSize(snapshot["col_maximum"])
        self.video_col.setSizePolicy(snapshot["col_policy"])
        self.work_area.setFixedSize(snapshot["canvas_size"])
        self.interface_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.interface_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        if self.layout() is not None and snapshot.get("root_margins") is not None:
            self.layout().setContentsMargins(snapshot["root_margins"])
            if snapshot.get("root_spacing", -1) >= 0:
                self.layout().setSpacing(snapshot["root_spacing"])
        if snapshot["was_maximized"]:
            self._titlebar_restore_geometry = snapshot["normal_geometry"]
            self.layout().setSizeConstraint(QLayout.SizeConstraint.SetDefaultConstraint)
            self.setGeometry(snapshot["normal_geometry"])
            self.showMaximized()
        else:
            self.layout().setSizeConstraint(snapshot["layout_constraint"] or QLayout.SizeConstraint.SetFixedSize)
            self.setGeometry(snapshot["geometry"])
        self.layout().invalidate()
        self.layout().activate()
        self._sync_video_area_to_video()
        self._sync_fullscreen_video_layout()
        self.video.sync_mpv_surfaces()
        self.video.mpv_surface().raise_()
        self._window_size_limit = snapshot["window_limit"]
        self.interface_scroll.horizontalScrollBar().setValue(snapshot["scroll"][0])
        self.interface_scroll.verticalScrollBar().setValue(snapshot["scroll"][1])
        self.schedule_relayout()
        self.save_settings()

    def enter_video_fullscreen(self):
        if self._video_fullscreen_window is not None:
            self._video_fullscreen_window.show_controls()
            return
        # Видео находится внутри video_area, а не является прямым элементом
        # left_layout. Удаляем его из правильной раскладки перед переносом в fullscreen,
        # чтобы при возврате не нарушить порядок profile_row -> video_area.
        video_area_layout = self.video_area.layout()
        if video_area_layout is not None:
            video_area_layout.removeWidget(self.video)
        self._video_fullscreen_window = VideoFullscreenWindow(self, self.video)
        self._video_fullscreen_window.update_position(self.player.position())
        self._video_fullscreen_window.update_duration(self.player.duration())
        self._video_fullscreen_window.update_state(
            self.player.playbackState() == QMediaPlayer.PlaybackState.PlayingState
        )
        self._video_fullscreen_window.activate()

    def exit_video_fullscreen(self):
        window = self._video_fullscreen_window
        if window is None:
            return
        window.detach()
        self._video_fullscreen_window = None

        # Возвращаем видео именно в video_area. Если вставить его в индекс 0
        # left_layout, оно окажется выше profile_row и панель раскладки визуально
        # «переедет» вниз относительно видео после выхода из полноэкранного режима.
        # ВАЖНО: режим размера «Весь экран» может оставаться активным и после выхода
        # из отдельного fullscreen-видеорежима. В этом случае нельзя переводить video
        # обратно в Fixed: это блокирует растяжение video_area/video_col и оставляет
        # верхнюю раскладку без видимой видеоповерхности до следующего переключения режима.
        keep_fullscreen_layout = self._is_fullscreen_layout()
        self.video.setParent(self.video_area)
        self.video.setMinimumSize(VIDEO_MIN_WIDTH, VIDEO_MIN_HEIGHT)
        self.video.setMaximumSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX)

        video_area_layout = self.video_area.layout()
        if video_area_layout is not None:
            video_area_layout.addWidget(self.video, 1)
            video_area_layout.invalidate()

        if keep_fullscreen_layout:
            self.layout().setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
            self.video.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding
            )
            self.video_area.setMinimumHeight(VIDEO_MIN_HEIGHT)
            self.video_area.setMaximumHeight(QWIDGETSIZE_MAX)
            self.video_area.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding
            )
            self.video_col.setSizePolicy(
                QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding
            )
        else:
            self.video.setSizePolicy(
                QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed
            )
            self.video_area.setFixedHeight(max(1, self.video.height()))
            self.video_area.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed
            )

        if video_area_layout is not None:
            video_area_layout.activate()
        self.left_layout.invalidate()
        self.left_layout.activate()
        self.video.show()
        self.schedule_relayout()
        window.deleteLater()

        # setParent() / переукладка может прийтись на несколько циклов Qt. В обычном
        # режиме выполняем стандартную подгонку размера; в режиме «Весь экран» её
        # fit_video_to_screen() намеренно пропускает, поэтому явно восстанавливаем
        # полноэкранную раскладку и HWND mpv после завершения reparent/layout.
        if not keep_fullscreen_layout:
            self.fit_video_to_screen()
        QTimer.singleShot(0, self._restore_video_after_fullscreen)
        QTimer.singleShot(90, self._restore_video_after_fullscreen)
        QTimer.singleShot(60, self.refresh_panels_paint)

    def _restore_video_after_fullscreen(self):
        """Восстанавливает размер и нативную поверхность видео после возврата из video-only fullscreen."""
        if getattr(self, "_video_fullscreen_window", None) is not None:
            return
        if not hasattr(self, "video") or self.video.parentWidget() is not self.video_area:
            return

        if self._is_fullscreen_layout():
            layout = self.layout()
            if layout is not None:
                layout.setSizeConstraint(QLayout.SizeConstraint.SetNoConstraint)
            self.video.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding
            )
            self.video_area.setMinimumHeight(VIDEO_MIN_HEIGHT)
            self.video_area.setMaximumHeight(QWIDGETSIZE_MAX)
            self.video_area.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding
            )
            self.video_col.setSizePolicy(
                QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding
            )
            self._sync_fullscreen_video_layout()
        else:
            self.video.setSizePolicy(
                QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed
            )
            self.video_area.setFixedHeight(max(1, self.video.height()))
            self.video_area.setSizePolicy(
                QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed
            )
            self.left_layout.invalidate()
            self.left_layout.activate()
            layout = self.layout()
            if layout is not None:
                layout.invalidate()
                layout.activate()

        self.video.show()
        self.video.sync_mpv_surfaces()
        self.video.mpv_surface().raise_()
        self.video.update()

    def mousePressEvent(self, e):
        if (e.button() == Qt.MouseButton.LeftButton and self.windowHandle()
                and not self._is_fullscreen_layout()):
            start_window_move(self)  # перетаскивание без рамки

    def contextMenuEvent(self, e):
        menu = QMenu(self)
        for text, checked, slot in (
            ("Поверх всех окон", self.pinned, self.set_pinned),
            ("Панель кнопок и громкости", self.controls_visible, self.set_controls_visible),
            ("Ползунок перемотки", self.seek_visible, self.set_seek_visible),
            ("Список треков", self.tracks_visible, self.set_tracks_visible),
            ("Панель размера окна", self.size_visible, self.set_size_visible),
            ("Эквалайзер", self.equalizer_visible, self.set_equalizer_visible),
            ("Настройки загрузки", self.downloads_visible, self.set_downloads_visible),
            ("Информация о загрузках", self.download_info_visible, self.set_download_info_visible),
            ("Конвертация файлов", self.converter_visible,
             lambda state: self.set_panel_visible("converter", state)),
            ("Перекодирование видео", self.transcode_visible,
             lambda state: self.set_panel_visible("transcode", state)),
            ("Настройки приложения", self.settings_visible,
             lambda state: self.set_panel_visible("settings", state)),
            ("О приложении", self.about_visible,
             lambda state: self.set_panel_visible("about", state)),
        ):
            act = menu.addAction(T(text))
            act.setCheckable(True)
            act.setChecked(checked)
            act.triggered.connect(lambda state, s=slot: s(state))
        menu.addSeparator()
        menu.addAction(T("Во весь экран / обратно (F11)"), self.toggle_fullscreen)
        menu.addAction(T("Свернуть"), self.showMinimized)
        menu.addAction(T("Закрыть"), self.close)
        menu.exec(e.globalPos())

    def closeEvent(self, event):
        if getattr(self, "_shutdown_complete", False):
            super().closeEvent(event)
            return
        event.ignore()
        if getattr(self, "_closing", False):
            return
        self._closing = True
        instance = getattr(self, "_instance", None)
        if instance is not None:
            instance.stop()
        self.transcode_preview.shutdown()
        self._shutdown_started_at = time.monotonic()
        for backend in (self.player.ff, self.player.mpv):
            backend._closing_lut = True
            timer = getattr(backend, "_grade_timer", None)
            if timer is not None:
                timer.stop()
            future = getattr(backend, "_lut_future", None)
            if future is not None:
                future.cancel()
        for timer in self.findChildren(QTimer):
            if timer.parent() is self:
                timer.stop()
        self.save_resume_position()
        self.save_settings()
        if self._video_fullscreen_window is not None:
            self.exit_video_fullscreen()
        system_eq_dialog = getattr(self, "_system_eq_dialog", None)
        if system_eq_dialog is not None: system_eq_dialog.close()
        for dialog in list(getattr(self, "_information_dialogs", {}).values()):
            dialog.close()
        for dialog in list(getattr(self, "_track_properties_dialogs", [])):
            dialog.close()
        for dialog in list(self.findChildren(QDialog)):
            dialog.close()
        for worker in (self.worker, getattr(self, "spotify_auth_thread", None),
                       getattr(self, "_compat_thread", None), getattr(self, "_media_probe_thread", None),
                       getattr(self, "converter_worker", None), getattr(self, "transcode_worker", None),
                       getattr(self, "_resolution_probe", None), getattr(self, "_transcode_probe", None),
                       getattr(self, "_conversion_capability_probe", None)):
            if worker is not None and worker.isRunning():
                stop = getattr(worker, "request_stop", worker.requestInterruption)
                stop()
        for worker in self.findChildren(EqualizerAudioThread):
            worker.stop_audio()
        if self.video._worker is not None:
            self.video._worker.request_stop()
        self.player.stop()
        self.player._watch.stop()
        self.btn_window_close.setEnabled(False)
        self.content_row.setEnabled(False)
        for shortcut in self.findChildren(QShortcut):
            shortcut.setEnabled(False)
        self._shutdown_notice = QLabel(T("Завершение фоновых операций…"), self)
        self._shutdown_notice.setObjectName("panel")
        self._shutdown_notice.setMargin(18)
        self._shutdown_notice.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._shutdown_notice.adjustSize()
        self._shutdown_notice.move(max(0, (self.width()-self._shutdown_notice.width())//2), max(0, self.height()//2-30))
        self._shutdown_notice.show()
        self._shutdown_notice.raise_()
        self._shutdown_timer = QTimer(self)
        self._shutdown_timer.setInterval(50)
        self._shutdown_timer.timeout.connect(self._poll_shutdown)
        self._shutdown_timer.start()
        self._poll_shutdown()


    def save_settings(self):
        active_dl_source = self.cmb_source.currentData() if hasattr(self, "cmb_source") else "youtube"
        if hasattr(self, "channel_edit") and hasattr(self, "_dl_source_urls"):
            self._dl_source_urls[active_dl_source] = self.channel_edit.text().strip()
        youtube_channel = (self._dl_source_urls.get("youtube") if hasattr(self, "_dl_source_urls") else None)
        self.cfg.update({
            "channel": normalize_channel(str(youtube_channel or DEFAULT_CHANNEL)),
            "dl_source_urls": dict(self._dl_source_urls) if hasattr(self, "_dl_source_urls") else self.cfg.get("dl_source_urls", {}),
            "folder": str(self.download_dir),
            "sources": [str(p) for p in self.sources],
            "source_folders": [str(p) for p in self.source_folders],
            "excluded_source_folders": [str(p) for p in sorted(self.excluded_source_folders, key=lambda p: str(p).casefold())],
            "playback_mode": self.playback_mode,
            "panel_profile": self.panel_profile,
            "panel_profile_restore": dict(self._profile_restore) if self._profile_restore else {},
            "playback_rate": self.playback_rate,
            "resume_positions": dict(self._resume_positions),
            "download_rate_limit": self.cmb_download_rate.currentData() if hasattr(self, "cmb_download_rate") else self.cfg.get("download_rate_limit", "0"),
            "count": self.count.value(),
            "volume": self.volume.value(),
            "pinned": self.pinned,
            "show_controls": self.controls_visible,
            "show_profile_bar": self.profile_bar_visible,
            "show_downloads": self.downloads_visible,
            "show_download_info": self.download_info_visible,
            "show_converter": self.converter_visible,
            "converter_folder": self.converter_folder_edit.text().strip() if hasattr(self, "converter_folder_edit") else self.cfg.get("converter_folder", str(self.download_dir)),
            "show_transcode": self.transcode_visible,
            "transcode_folder": self.transcode_folder_edit.text().strip() if hasattr(self, "transcode_folder_edit") else self.cfg.get("transcode_folder", str(self.download_dir)),
            "show_seek": self.seek_visible,
            "show_tracks": self.tracks_visible,
            "show_size": self.size_visible,
            "show_equalizer": self.equalizer_visible,
            "equalizer_enabled": self.equalizer_enabled,
            "equalizer_preset": self.equalizer_preset,
            "equalizer_values": list(self.equalizer_values),
            "equalizer_frequencies": list(self.eq_frequencies),
            "equalizer_custom_presets": self.eq_custom_presets,
            "equalizer_scope": self.eq_scope,
            "equalizer_apo_endpoint": self._apo_endpoint,
            "equalizer_apo_endpoint_name": self._apo_endpoint_name,
            "equalizer_apo_directory": self._apo_directory,
            "equalizer_apo_linked": self._apo_linked or self._apo_uncertain,
            "show_color_panel": self.color_visible,
            "color_enabled": self.color_enabled,
            "color_params": dict(self.color_params),
            "color_preset": self.color_preset,
            "color_amount": self.color_amount,
            "color_user_presets": self.color_user_presets,
            "size_mode": self.prev_mode if self.size_mode == "full" else self.size_mode,
            "dl_source": self.cmb_source.currentData(),
            "dl_kind": self.dl_kind if hasattr(self, "dl_kind") else self.cfg.get("dl_kind", "channel"),
            "dl_mode": self.cmb_mode.currentData(),
            "dl_vq": self._dl_profile_value(),
            "dl_video_profile": self._dl_profile_value(),
            "dl_fps": self.cmb_fps.currentData() or "max",
            "dl_video_resolution": self._dl_resolution,
            "dl_aq": self.cmb_aq.currentData(),
            "dl_sample_rate": self.cmb_sample_rate.currentData() if hasattr(self, "cmb_sample_rate") else str(self.cfg.get("dl_sample_rate", "0")),
            "spotify_format": self.cmb_spotify_format.currentData() if hasattr(self, "cmb_spotify_format") else self.cfg.get("spotify_format", "mp3"),
            "spotify_bitrate": self.cmb_spotify_bitrate.currentData() if hasattr(self, "cmb_spotify_bitrate") else self.cfg.get("spotify_bitrate", "192"),
            "dl_container": self.cmb_container.currentData(),
            "dl_vcodec": self.cmb_vcodec.currentData(),
            "dl_cookies_browser": self.cmb_cookies.currentData(),
            "dl_cookies_priority": self.cmb_cookies_priority.currentData() or "browser",
            "dl_tbitrate_mode": self.cmb_vbitrate.currentData() or "auto",
            "dl_tbitrate_kbps": self.vbitrate_input.kbps(),
            "dl_tbitrate_unit": self.vbitrate_input.units.currentData() or "kbps",
            "dl_cookies_file": self.cookies_file_edit.text().strip(),
            "spotify_client_id": self.spotify_client_id_edit.text().strip() if hasattr(self, "spotify_client_id_edit") else self.cfg.get("spotify_client_id", ""),
            "spotify_access_token": self.cfg.get("spotify_access_token", ""),
            "spotify_refresh_token": self.cfg.get("spotify_refresh_token", ""),
            "spotify_token_expires_at": self.cfg.get("spotify_token_expires_at", 0),
        })
